{
  "name": "LunchRun: Workplace Food Coordinator",
  "description": "A collaborative app for workplace food runs. Runners can announce their departure, and colleagues can join in by sharing their orders and Cibus codes. Includes a creative Image Studio for food-related imagery powered by Gemini.",
  "requestFramePermissions": [
    "camera"
  ]
}

export enum UserRole {
  RUNNER = 'RUNNER',
  ORDERER = 'ORDERER'
}

export interface Order {
  id: string;
  userName: string;
  itemDescription: string;
  cibusCode: string;
  timestamp: number;
}

export interface FoodRun {
  id: string;
  runnerName: string;
  destination: string;
  departureTime: number; // timestamp
  minutesUntilDeparture: number;
  orders: Order[];
  status: 'active' | 'completed' | 'cancelled';
}

export interface ImageGenerationConfig {
  aspectRatio: "1:1" | "3:4" | "4:3" | "9:16" | "16:9";
  imageSize: "1K" | "2K" | "4K";
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { ImageGenerationConfig } from "../types";

/**
 * Checks if the user has selected an API key. 
 * Required for gemini-3-pro-image-preview.
 */
export const checkApiKey = async (): Promise<boolean> => {
  if (typeof (window as any).aistudio?.hasSelectedApiKey === 'function') {
    return await (window as any).aistudio.hasSelectedApiKey();
  }
  return !!process.env.API_KEY;
};

/**
 * Opens the API key selection dialog.
 */
export const openApiKeyDialog = async (): Promise<void> => {
  if (typeof (window as any).aistudio?.openSelectKey === 'function') {
    await (window as any).aistudio.openSelectKey();
  } else {
    alert("API Key selection is only available in the AI Studio environment.");
  }
};

/**
 * Generates an image using gemini-3-pro-image-preview.
 */
export const generateFoodImage = async (prompt: string, config: ImageGenerationConfig): Promise<string> => {
  // Always create a new instance to get latest API Key
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: [{ text: prompt }],
      },
      config: {
        imageConfig: {
          aspectRatio: config.aspectRatio,
          imageSize: config.imageSize
        }
      },
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
    }
    throw new Error("No image data found in response");
  } catch (error: any) {
    if (error.message?.includes("Requested entity was not found")) {
      await openApiKeyDialog();
    }
    throw error;
  }
};

/**
 * Edits an image using gemini-2.5-flash-image.
 */
export const editFoodImage = async (base64Image: string, mimeType: string, prompt: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Strip data: prefix if present
  const data = base64Image.split(',')[1] || base64Image;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        {
          inlineData: {
            data: data,
            mimeType: mimeType,
          },
        },
        {
          text: prompt,
        },
      ],
    },
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
  }
  throw new Error("No edited image data found in response");
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "px-4 py-2 rounded-lg font-semibold transition-all duration-200 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed";

  const variants = {
    primary: "bg-orange-600 text-white hover:bg-orange-700 active:scale-95",
    secondary: "bg-white border-2 border-orange-600 text-orange-600 hover:bg-orange-50 active:scale-95",
    danger: "bg-red-500 text-white hover:bg-red-600 active:scale-95",
    ghost: "text-slate-600 hover:bg-slate-100"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${className}`} 
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading ? <i className="fas fa-spinner fa-spin"></i> : children}
    </button>
  );
};

import React, { useState } from 'react';
import { Button } from './Button';
import { generateFoodImage, editFoodImage, checkApiKey, openApiKeyDialog } from '../services/geminiService';
import { ImageGenerationConfig } from '../types';

export const ImageStudio: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'generate' | 'edit'>('generate');
  const [prompt, setPrompt] = useState('');
  const [resultImage, setResultImage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [config, setConfig] = useState<ImageGenerationConfig>({
    aspectRatio: '1:1',
    imageSize: '1K'
  });
  const [sourceImage, setSourceImage] = useState<{data: string, type: string} | null>(null);

  const handleGenerate = async () => {
    if (!prompt) return;
    setLoading(true);
    try {
      const hasKey = await checkApiKey();
      if (!hasKey) {
        await openApiKeyDialog();
        // Proceeding assuming success as per guidelines
      }
      const img = await generateFoodImage(prompt, config);
      setResultImage(img);
    } catch (err) {
      console.error(err);
      alert("Failed to generate image. Please check your API key and connection.");
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = async () => {
    if (!sourceImage || !prompt) return;
    setLoading(true);
    try {
      const img = await editFoodImage(sourceImage.data, sourceImage.type, prompt);
      setResultImage(img);
    } catch (err) {
      console.error(err);
      alert("Failed to edit image.");
    } finally {
      setLoading(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = () => {
        setSourceImage({
          data: reader.result as string,
          type: file.type
        });
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
      <div className="flex border-b">
        <button 
          onClick={() => setActiveTab('generate')}
          className={`flex-1 py-4 font-bold ${activeTab === 'generate' ? 'text-orange-600 border-b-2 border-orange-600 bg-orange-50' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <i className="fas fa-magic mr-2"></i> Generate AI Lunch
        </button>
        <button 
          onClick={() => setActiveTab('edit')}
          className={`flex-1 py-4 font-bold ${activeTab === 'edit' ? 'text-orange-600 border-b-2 border-orange-600 bg-orange-50' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <i className="fas fa-edit mr-2"></i> AI Photo Editor
        </button>
      </div>

      <div className="p-6">
        {activeTab === 'generate' ? (
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-1">What are you craving?</label>
              <textarea 
                className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-orange-500 outline-none"
                placeholder="e.g., A gourmet burger with melting cheese and golden fries on a marble table..."
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                rows={3}
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1">Size</label>
                <select 
                  className="w-full p-2 border rounded-lg"
                  value={config.imageSize}
                  onChange={(e) => setConfig(prev => ({ ...prev, imageSize: e.target.value as any }))}
                >
                  <option value="1K">1K Resolution</option>
                  <option value="2K">2K Resolution (High)</option>
                  <option value="4K">4K Resolution (Ultra)</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1">Ratio</label>
                <select 
                  className="w-full p-2 border rounded-lg"
                  value={config.aspectRatio}
                  onChange={(e) => setConfig(prev => ({ ...prev, aspectRatio: e.target.value as any }))}
                >
                  <option value="1:1">Square (1:1)</option>
                  <option value="16:9">Wide (16:9)</option>
                  <option value="4:3">Standard (4:3)</option>
                  <option value="9:16">Portrait (9:16)</option>
                </select>
              </div>
            </div>

            <Button onClick={handleGenerate} isLoading={loading} className="w-full">
              Generate Masterpiece
            </Button>
          </div>
        ) : (
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-1">Upload Photo</label>
              <input type="file" accept="image/*" onChange={handleFileChange} className="w-full" />
              {sourceImage && (
                <div className="mt-2 relative h-40 w-full rounded-lg overflow-hidden border">
                  <img src={sourceImage.data} alt="source" className="w-full h-full object-cover" />
                </div>
              )}
            </div>
            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-1">Edit Instruction</label>
              <input 
                className="w-full p-3 border rounded-lg focus:ring-2 focus:ring-orange-500 outline-none"
                placeholder="e.g., Add a retro filter, Make it look like a drawing, Remove the napkin..."
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
              />
            </div>
            <Button onClick={handleEdit} isLoading={loading} className="w-full">
              Apply AI Magic
            </Button>
          </div>
        )}

        {resultImage && (
          <div className="mt-8 border-t pt-6 text-center">
            <h3 className="font-bold text-slate-800 mb-4">Your AI Result:</h3>
            <div className="inline-block relative rounded-xl shadow-2xl overflow-hidden bg-slate-100 max-w-full">
              <img src={resultImage} alt="result" className="max-w-full h-auto" />
              <div className="absolute top-2 right-2 flex gap-2">
                <a 
                  href={resultImage} 
                  download="lunch-ai.png"
                  className="bg-white/80 backdrop-blur p-2 rounded-full hover:bg-white transition-colors shadow-sm"
                >
                  <i className="fas fa-download text-orange-600"></i>
                </a>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { FoodRun, Order, UserRole } from './types';
import { Button } from './components/Button';
import { ImageStudio } from './components/ImageStudio';

const App: React.FC = () => {
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [userName, setUserName] = useState('');
  const [isJoined, setIsJoined] = useState(false);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [showJoinForm, setShowJoinForm] = useState<string | null>(null);

  // Form states
  const [newRunDest, setNewRunDest] = useState('');
  const [newRunTime, setNewRunTime] = useState(20);
  const [newOrderItem, setNewOrderItem] = useState('');
  const [newOrderCibus, setNewOrderCibus] = useState('');

  // Mock initial data
  useEffect(() => {
    const mockRuns: FoodRun[] = [
      {
        id: '1',
        runnerName: 'Sarah',
        destination: 'Pasta Place',
        departureTime: Date.now() + 15 * 60000,
        minutesUntilDeparture: 15,
        status: 'active',
        orders: [
          { id: 'o1', userName: 'John', itemDescription: 'Carbonara', cibusCode: '1234', timestamp: Date.now() }
        ]
      }
    ];
    setRuns(mockRuns);
  }, []);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (userName.trim()) setIsJoined(true);
  };

  const createRun = (e: React.FormEvent) => {
    e.preventDefault();
    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: userName,
      destination: newRunDest,
      departureTime: Date.now() + newRunTime * 60000,
      minutesUntilDeparture: newRunTime,
      status: 'active',
      orders: []
    };
    setRuns([newRun, ...runs]);
    setShowCreateForm(false);
    setNewRunDest('');
  };

  const joinRun = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run) return;

    const newOrder: Order = {
      id: Math.random().toString(36).substr(2, 9),
      userName,
      itemDescription: newOrderItem,
      cibusCode: newOrderCibus,
      timestamp: Date.now()
    };

    setRuns(runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, newOrder] } : r));
    setShowJoinForm(null);
    setNewOrderItem('');
    setNewOrderCibus('');
  };

  if (!isJoined) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-orange-400 to-rose-500 p-4">
        <div className="bg-white p-8 rounded-2xl shadow-2xl w-full max-w-md animate-in fade-in zoom-in duration-300">
          <div className="text-center mb-8">
            <div className="w-20 h-20 bg-orange-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <i className="fas fa-hamburger text-orange-600 text-3xl"></i>
            </div>
            <h1 className="text-3xl font-bold text-slate-800">LunchRun</h1>
            <p className="text-slate-500">Who's bringing food today?</p>
          </div>
          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-1">Your Name</label>
              <input 
                autoFocus
                type="text" 
                required
                className="w-full p-3 border-2 border-slate-200 rounded-xl focus:border-orange-500 outline-none transition-all"
                placeholder="Enter your name..."
                value={userName}
                onChange={(e) => setUserName(e.target.value)}
              />
            </div>
            <Button type="submit" className="w-full h-12 text-lg">
              Get Started
            </Button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen pb-20">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 px-4 py-3 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-2">
          <i className="fas fa-hamburger text-orange-600 text-2xl"></i>
          <span className="text-xl font-black text-slate-800 tracking-tight">LUNCHRUN</span>
        </div>
        <div className="flex items-center gap-3">
          <span className="text-slate-600 font-medium hidden sm:inline">Hi, {userName}</span>
          <div className="w-10 h-10 bg-orange-100 rounded-full flex items-center justify-center text-orange-700 font-bold border-2 border-orange-200">
            {userName.charAt(0).toUpperCase()}
          </div>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 sm:p-6 space-y-8">
        {/* Actions Bar */}
        <section className="flex flex-col sm:flex-row gap-4 items-center justify-between bg-white p-4 rounded-xl shadow-sm border border-slate-100">
          <div className="text-center sm:text-left">
            <h2 className="text-xl font-bold text-slate-800">Active Lunch Runs</h2>
            <p className="text-sm text-slate-500">Join a colleague or start your own run</p>
          </div>
          <Button onClick={() => setShowCreateForm(true)}>
            <i className="fas fa-plus"></i> I'm going to bring food
          </Button>
        </section>

        {/* Create Run Modal Overlay */}
        {showCreateForm && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md p-6 animate-in slide-in-from-bottom-4 duration-300">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-2xl font-bold">Announce Your Run</h3>
                <button onClick={() => setShowCreateForm(false)} className="text-slate-400 hover:text-slate-600 text-xl">
                  <i className="fas fa-times"></i>
                </button>
              </div>
              <form onSubmit={createRun} className="space-y-4">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-1">Where are you going?</label>
                  <input 
                    required
                    type="text"
                    className="w-full p-3 border rounded-xl focus:ring-2 focus:ring-orange-500 outline-none"
                    placeholder="McDonalds, Local Salad Bar, etc."
                    value={newRunDest}
                    onChange={(e) => setNewRunDest(e.target.value)}
                  />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-1">Leaving in (minutes)</label>
                  <input 
                    required
                    type="number"
                    min="1"
                    className="w-full p-3 border rounded-xl focus:ring-2 focus:ring-orange-500 outline-none"
                    value={newRunTime}
                    onChange={(e) => setNewRunTime(parseInt(e.target.value))}
                  />
                </div>
                <Button type="submit" className="w-full h-12">Broadcast Run</Button>
              </form>
            </div>
          </div>
        )}

        {/* Food Run List */}
        <div className="grid gap-6">
          {runs.length === 0 ? (
            <div className="text-center py-20 bg-white rounded-2xl border-2 border-dashed border-slate-200">
              <div className="text-slate-300 text-6xl mb-4">
                <i className="fas fa-motorcycle"></i>
              </div>
              <h3 className="text-lg font-medium text-slate-500">No active runs right now. Be the hero!</h3>
            </div>
          ) : (
            runs.map(run => (
              <div key={run.id} className="bg-white rounded-2xl shadow-md border border-slate-200 overflow-hidden hover:shadow-lg transition-shadow">
                <div className="p-6">
                  <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 bg-rose-50 rounded-xl flex items-center justify-center text-rose-600 text-2xl">
                        <i className="fas fa-store"></i>
                      </div>
                      <div>
                        <h4 className="text-xl font-bold text-slate-800">{run.destination}</h4>
                        <p className="text-slate-500">Run by <span className="font-semibold">{run.runnerName}</span></p>
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="text-right">
                        <span className="block text-xs font-bold text-slate-400 uppercase tracking-wider">Departure</span>
                        <span className="text-lg font-black text-orange-600">{run.minutesUntilDeparture}m</span>
                      </div>
                      <Button variant="secondary" onClick={() => setShowJoinForm(run.id)}>
                        Join Run
                      </Button>
                    </div>
                  </div>

                  {/* Orders List */}
                  <div className="space-y-3">
                    <h5 className="text-sm font-bold text-slate-400 uppercase tracking-widest">Order Group ({run.orders.length})</h5>
                    {run.orders.length === 0 ? (
                      <p className="text-slate-400 italic text-sm">No orders yet. Be the first!</p>
                    ) : (
                      <div className="grid gap-2">
                        {run.orders.map(order => (
                          <div key={order.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-xl border border-slate-100">
                            <div className="flex items-center gap-3">
                              <div className="w-8 h-8 rounded-full bg-slate-200 flex items-center justify-center text-xs font-bold">
                                {order.userName.charAt(0)}
                              </div>
                              <div>
                                <span className="font-bold text-slate-700">{order.userName}</span>
                                <span className="mx-2 text-slate-300">|</span>
                                <span className="text-slate-600">{order.itemDescription}</span>
                              </div>
                            </div>
                            <div className="bg-orange-100 px-2 py-1 rounded text-xs font-mono text-orange-700 border border-orange-200">
                              Cibus: {order.cibusCode}
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>

                {/* Join Run Modal */}
                {showJoinForm === run.id && (
                  <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md p-6 animate-in slide-in-from-bottom-4 duration-300">
                      <div className="flex justify-between items-center mb-6">
                        <h3 className="text-2xl font-bold">Join {run.runnerName}'s Run</h3>
                        <button onClick={() => setShowJoinForm(null)} className="text-slate-400 hover:text-slate-600 text-xl">
                          <i className="fas fa-times"></i>
                        </button>
                      </div>
                      <form onSubmit={(e) => { e.preventDefault(); joinRun(run.id); }} className="space-y-4">
                        <div>
                          <label className="block text-sm font-semibold text-slate-700 mb-1">What do you want to eat?</label>
                          <textarea 
                            required
                            className="w-full p-3 border rounded-xl focus:ring-2 focus:ring-orange-500 outline-none"
                            placeholder="Double Cheeseburger, no pickles..."
                            value={newOrderItem}
                            onChange={(e) => setNewOrderItem(e.target.value)}
                            rows={2}
                          />
                        </div>
                        <div>
                          <label className="block text-sm font-semibold text-slate-700 mb-1">Cibus Payment Code</label>
                          <input 
                            required
                            type="text"
                            className="w-full p-3 border rounded-xl focus:ring-2 focus:ring-orange-500 outline-none"
                            placeholder="e.g. 123456"
                            value={newOrderCibus}
                            onChange={(e) => setNewOrderCibus(e.target.value)}
                          />
                        </div>
                        <Button type="submit" className="w-full h-12">Add My Order</Button>
                      </form>
                    </div>
                  </div>
                )}
              </div>
            ))
          )}
        </div>

        {/* Gemini Image Section */}
        <section className="mt-16 space-y-6">
          <div className="border-t pt-12">
            <h2 className="text-2xl font-black text-slate-800 mb-2">Lunch Inspiration Studio</h2>
            <p className="text-slate-500 mb-8 italic">Can't decide what to eat? Let AI visualize your cravings or edit your food photos!</p>
            <ImageStudio />
          </div>
        </section>
      </main>

      {/* Persistent Mobile Action */}
      <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/80 backdrop-blur-md border-t border-slate-200 sm:hidden z-40">
        <Button onClick={() => setShowCreateForm(true)} className="w-full shadow-lg">
          <i className="fas fa-plus"></i> New Food Run
        </Button>
      </div>
    </div>
  );
};

export default App;

{
  "name": "LunchRun: Workplace Food Coordinator",
  "description": "A collaborative app for workplace food runs. Runners can announce departure, set capacity, and notify colleagues upon arrival.",
  "requestFramePermissions": []
}

export enum UserRole {
  RUNNER = 'RUNNER',
  ORDERER = 'ORDERER'
}

export interface Order {
  id: string;
  userName: string;
  itemDescription: string;
  cibusCode: string;
  floor: string;
  timestamp: number;
}

export interface FoodRun {
  id: string;
  runnerName: string;
  destination: string;
  departureTime: number; 
  minutesUntilDeparture: number;
