                          <div key={order.id} className="flex justify-between items-center bg-slate-50 p-3 rounded-xl border border-slate-200">
                            <div className="text-sm">
                              <span className="font-bold text-slate-700">{order.userName}</span>
                              <span className="text-slate-400 mx-2">|</span>
                              <span className="text-slate-600">{order.itemDescription}</span>
                            </div>
                            <div className="flex gap-2">
                               <span className="bg-blue-50 text-blue-700 text-[10px] px-2 py-0.5 rounded border border-blue-100">Floor {order.floor}</span>
                               <span className="bg-amber-50 text-amber-700 text-[10px] px-2 py-0.5 rounded border border-amber-100">Cibus: {order.cibusCode}</span>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>

                  {/* Actions */}
                  <div className="flex gap-3">
                    {run.status === 'active' && !isFull && !isRunner && (
                      <Button variant="primary" className="flex-1 bg-blue-600" onClick={() => setShowJoinForm(run.id)}>
                        Join Run
                      </Button>
                    )}
                    {run.status === 'active' && isFull && !isRunner && (
                      <Button disabled className="flex-1 bg-slate-200 text-slate-500">Run Full</Button>
                    )}
                    {run.status === 'active' && isRunner && (
                      <Button className="flex-1 bg-green-600 hover:bg-green-700" onClick={() => setShowArriveForm(run.id)}>
                        I've Arrived with Food
                      </Button>
                    )}
                  </div>
                </div>

                {/* Join Modal */}
                {showJoinForm === run.id && (
                  <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md p-6">
                      <div className="flex justify-between items-center mb-6">
                        <h3 className="text-2xl font-bold">Join Run</h3>
                        <button onClick={() => setShowJoinForm(null)} className="text-slate-400"><i className="fas fa-times"></i></button>
                      </div>
                      <form onSubmit={(e) => { e.preventDefault(); joinRun(run.id); }} className="space-y-4">
                        <div>
                          <label className="block text-sm font-semibold text-slate-700 mb-1">What do you want?</label>
                          <input required className="w-full p-3 border rounded-xl" placeholder="e.g. Salad with extra egg" value={newOrderItem} onChange={(e) => setNewOrderItem(e.target.value)} />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                          <div>
                            <label className="block text-sm font-semibold text-slate-700 mb-1">Cibus Code</label>
                            <input required className="w-full p-3 border rounded-xl" placeholder="123456" value={newOrderCibus} onChange={(e) => setNewOrderCibus(e.target.value)} />
                          </div>
                          <div>
                            <label className="block text-sm font-semibold text-slate-700 mb-1">Your Floor</label>
                            <input required className="w-full p-3 border rounded-xl" placeholder="e.g. 5th" value={newOrderFloor} onChange={(e) => setNewOrderFloor(e.target.value)} />
                          </div>
                        </div>
                        <Button type="submit" className="w-full h-12 bg-blue-600">Submit Order</Button>
                      </form>
                    </div>
                  </div>
                )}

                {/* Arrive Modal */}
                {showArriveForm === run.id && (
                  <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md p-6">
                      <h3 className="text-2xl font-bold mb-4">Where are you?</h3>
                      <p className="text-slate-500 mb-6">Tell everyone where to pick up their food.</p>
                      <div className="space-y-4">
                        <input autoFocus className="w-full p-3 border rounded-xl" placeholder="e.g. Kitchen, Floor 3 Lobby, My Desk..." value={arrivalLoc} onChange={(e) => setArrivalLoc(e.target.value)} />
                        <div className="flex gap-2">
                          <Button className="flex-1 bg-slate-200 text-slate-700" onClick={() => setShowArriveForm(null)}>Cancel</Button>
                          <Button className="flex-1 bg-green-600" onClick={() => markAsArrived(run.id)}>Notify Everyone</Button>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </main>
    </div>
  );
};

