import React, { useState, useEffect } from 'react';
import { FoodRun, Order } from './types';
import { Button } from './components/Button';

// התאם את הדומיין של החברה שלך כאן
const ALLOWED_DOMAIN = 'company.com'; 
// הזן כאן את ה-Client ID שקיבלת מ-Google Cloud Console
const GOOGLE_CLIENT_ID = 'YOUR_GOOGLE_CLIENT_ID.apps.googleusercontent.com';

const App: React.FC = () => {
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [user, setUser] = useState<{ name: string; email: string; picture?: string } | null>(null);
  const [isJoined, setIsJoined] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [showJoinForm, setShowJoinForm] = useState<string | null>(null);
  const [showArriveForm, setShowArriveForm] = useState<string | null>(null);

  // Form states
  const [newRunDest, setNewRunDest] = useState('');
  const [newRunTime, setNewRunTime] = useState(25);
  const [newRunMax, setNewRunMax] = useState(5);
  const [newOrderItem, setNewOrderItem] = useState('');
  const [newOrderCibus, setNewOrderCibus] = useState('');
  const [newOrderFloor, setNewOrderFloor] = useState('');
  const [arrivalLoc, setArrivalLoc] = useState('');

  useEffect(() => {
    // טעינת ריצות דוגמה
    const mockRuns: FoodRun[] = [
      {
        id: '1',
        runnerName: 'Sarah',
        destination: 'Pasta Place',
        departureTime: Date.now() + 15 * 60000,
        minutesUntilDeparture: 15,
        maxOrders: 3,
        status: 'active',
        orders: [
          { id: 'o1', userName: 'John', itemDescription: 'Carbonara', cibusCode: '1234', floor: '4th', timestamp: Date.now() }
        ]
      }
    ];
    setRuns(mockRuns);

    // אתחול כפתור גוגל
    /* global google */
    if (typeof window !== 'undefined' && (window as any).google) {
      (window as any).google.accounts.id.initialize({
        client_id: GOOGLE_CLIENT_ID,
        callback: handleGoogleResponse,
      });
      (window as any).google.accounts.id.renderButton(
        document.getElementById("googleBtn"),
        { theme: "outline", size: "large", width: "100%" }
      );
    }
  }, [isJoined]);

  const decodeJwt = (token: string) => {
    const base64Url = token.split('.')[1];
    const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
    const jsonPayload = decodeURIComponent(atob(base64).split('').map(function(c) {
        return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
    }).join(''));
    return JSON.parse(jsonPayload);
  };

  const handleGoogleResponse = (response: any) => {
    const payload = decodeJwt(response.credential);
    const email = payload.email;
    const name = payload.name;
    const picture = payload.picture;

    // בדיקת דומיין ארגוני
    if (ALLOWED_DOMAIN && !email.endsWith(`@${ALLOWED_DOMAIN}`)) {
      setLoginError(`Access denied. Please use your @${ALLOWED_DOMAIN} email.`);
      return;
    }

    setUser({ name, email, picture });
    setIsJoined(true);
    setLoginError(null);
  };

  const handleLogout = () => {
    setUser(null);
    setIsJoined(false);
  };

  const createRun = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: user.name,
      destination: newRunDest,
      departureTime: Date.now() + newRunTime * 60000,
      minutesUntilDeparture: newRunTime,
      maxOrders: newRunMax,
      status: 'active',
      orders: []
    };
    setRuns([newRun, ...runs]);
    setShowCreateForm(false);
    setNewRunDest('');
  };

  const joinRun = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run || !user || run.orders.length >= run.maxOrders) return;

    const newOrder: Order = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      itemDescription: newOrderItem,
      cibusCode: newOrderCibus,
      floor: newOrderFloor,
      timestamp: Date.now()
    };

    setRuns(runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, newOrder] } : r));
    setShowJoinForm(null);
    setNewOrderItem('');
    setNewOrderCibus('');
    setNewOrderFloor('');
  };

  const markAsArrived = (runId: string) => {
    setRuns(runs.map(r => r.id === runId ? { 
      ...r, 
      status: 'arrived', 
      arrivalLocation: arrivalLoc, 
      arrivalTime: Date.now() 
    } : r));
    setShowArriveForm(null);
    setArrivalLoc('');
  };

  if (!isJoined) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-slate-800 to-slate-900 p-4 font-sans">
        <div className="bg-white p-8 rounded-2xl shadow-2xl w-full max-w-md animate-in fade-in zoom-in duration-300">
          <div className="text-center mb-8">
            <div className="w-20 h-20 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <i className="fas fa-bicycle text-blue-600 text-3xl"></i>
            </div>
            <h1 className="text-3xl font-bold text-slate-800 tracking-tight">LunchRun</h1>
            <p className="text-slate-500 mt-2">Internal Workplace Tool</p>
          </div>

          <div className="space-y-6">
            <div className="bg-slate-50 p-4 rounded-xl border border-slate-100 text-center">
              <p className="text-sm text-slate-600 mb-4">Please sign in with your corporate account to continue</p>
              <div id="googleBtn" className="w-full"></div>
            </div>

            {loginError && (
              <div className="p-3 bg-red-50 text-red-600 text-sm rounded-lg border border-red-100 flex items-center gap-2">
                <i className="fas fa-exclamation-circle"></i>
                {loginError}
              </div>
            )}

            <p className="text-[10px] text-center text-slate-400 uppercase tracking-widest">
              Secured by Google Identity
            </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen pb-20 bg-slate-50">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 px-4 py-3 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-2">
          <i className="fas fa-bicycle text-blue-600 text-2xl"></i>
          <span className="text-xl font-black text-slate-800 tracking-tight">LUNCHRUN</span>
        </div>
        <div className="flex items-center gap-3">
          <div className="text-right hidden sm:block">
            <p className="text-xs font-bold text-slate-800 leading-none">{user?.name}</p>
            <p className="text-[10px] text-slate-500">{user?.email}</p>
          </div>
          <button onClick={handleLogout} className="group relative">
            {user?.picture ? (
              <img src={user.picture} className="w-10 h-10 rounded-full border-2 border-blue-100" alt="profile" />
            ) : (
              <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center text-blue-700 font-bold border-2 border-blue-200">
                {user?.name.charAt(0)}
              </div>
            )}
            <div className="absolute top-full right-0 mt-2 hidden group-hover:block bg-white border shadow-xl rounded-lg p-2 z-50">
                <button onClick={handleLogout} className="text-xs text-red-600 whitespace-nowrap px-2 py-1 hover:bg-red-50 rounded w-full text-left">
                    Sign Out
                </button>
            </div>
          </button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 sm:p-6 space-y-6">
        <section className="flex flex-col sm:flex-row gap-4 items-center justify-between bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <div>
            <h2 className="text-2xl font-bold text-slate-800">Active Runs</h2>
            <p className="text-slate-500 text-sm">Welcome back, {user?.name.split(' ')[0]}!</p>
          </div>
          <Button onClick={() => setShowCreateForm(true)} className="bg-blue-600 hover:bg-blue-700 h-12 px-6">
            <i className="fas fa-plus"></i> I'm picking up food
          </Button>
        </section>

        {/* Create Run Modal */}
        {showCreateForm && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md p-6 animate-in slide-in-from-bottom-4">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-2xl font-bold">New Food Run</h3>
                <button onClick={() => setShowCreateForm(false)} className="text-slate-400 hover:text-slate-600">
                  <i className="fas fa-times text-xl"></i>
                </button>
              </div>
              <form onSubmit={createRun} className="space-y-4">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-1">Destination</label>
                  <input required type="text" className="w-full p-3 border rounded-xl" placeholder="Sushi, Burgers, etc." value={newRunDest} onChange={(e) => setNewRunDest(e.target.value)} />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-semibold text-slate-700 mb-1">Leaving in (min)</label>
                    <input required type="number" min="1" className="w-full p-3 border rounded-xl" value={newRunTime} onChange={(e) => setNewRunTime(parseInt(e.target.value))} />
                  </div>
                  <div>
                    <label className="block text-sm font-semibold text-slate-700 mb-1">Max Orders</label>
                    <input required type="number" min="1" max="20" className="w-full p-3 border rounded-xl" value={newRunMax} onChange={(e) => setNewRunMax(parseInt(e.target.value))} />
                  </div>
                </div>
                <Button type="submit" className="w-full h-12 bg-blue-600">Broadcast</Button>
              </form>
            </div>
          </div>
        )}

        {/* Runs List */}
        <div className="space-y-4">
          {runs.map(run => {
            const isFull = run.orders.length >= run.maxOrders;
            const isRunner = user && run.runnerName === user.name;

            return (
              <div key={run.id} className={`bg-white rounded-2xl border-2 transition-all ${run.status === 'arrived' ? 'border-green-200 bg-green-50/30' : 'border-slate-100 shadow-sm'}`}>
                <div className="p-6">
                  {/* Header */}
                  <div className="flex flex-col sm:flex-row justify-between items-start gap-4 mb-6">
                    <div className="flex gap-4">
                      <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-2xl ${run.status === 'arrived' ? 'bg-green-100 text-green-600' : 'bg-blue-100 text-blue-600'}`}>
                        <i className={`fas ${run.status === 'arrived' ? 'fa-check-circle' : 'fa-store'}`}></i>
                      </div>
                      <div>
                        <h4 className="text-xl font-bold text-slate-800">{run.destination}</h4>
                        <p className="text-slate-500">Runner: <span className="font-semibold">{run.runnerName}</span></p>
                      </div>
                    </div>

                    <div className="flex flex-wrap gap-2">
                      <div className="bg-slate-100 px-3 py-1 rounded-full text-xs font-bold text-slate-600 uppercase tracking-tight">
                        {run.orders.length} / {run.maxOrders} Spots
                      </div>
                      {run.status === 'active' && (
                        <div className="bg-orange-100 px-3 py-1 rounded-full text-xs font-bold text-orange-600 uppercase">
                          Leaves in {run.minutesUntilDeparture}m
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Arrival Banner */}
                  {run.status === 'arrived' && (
                    <div className="mb-6 bg-green-100 text-green-800 p-4 rounded-xl flex items-center gap-3 animate-pulse">
                      <i className="fas fa-bell text-xl"></i>
                      <div>
                        <p className="font-bold">FOOD HAS ARRIVED!</p>
                        <p className="text-sm">Location: <span className="underline">{run.arrivalLocation || 'Kitchen'}</span></p>
                      </div>
                    </div>
                  )}

                  {/* Orders */}
                  <div className="space-y-2 mb-6">
                    <p className="text-xs font-bold text-slate-400 uppercase">Orders</p>
                    {run.orders.length === 0 ? (
                      <p className="text-sm text-slate-400 italic">No orders yet.</p>
                    ) : (
                      <div className="grid gap-2">
                        {run.orders.map(order => (
                          <div key={order.id} className="flex justify-between items-center bg-slate-50 p-3 rounded-xl border border-slate-200">
                            <div className="text-sm">
                              <span className="font-bold text-slate-700">{order.userName}</span>
                              <span className="text-slate-400 mx-2">|</span>
                              <span className="text-slate-600">{order.itemDescription}</span>
                            </div>
                            <div className="flex gap-2">
                               <span className="bg-blue-50 text-blue-700 text-[10px] px-2 py-0.5 rounded border border-blue-100">Floor {order.floor}</span>
                               <span className="bg-amber-50 text-amber-700 text-[10px] px-2 py-0.5 rounded border border-amber-100">Cibus: {order.cibusCode}</span>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>

                  {/* Actions */}
                  <div className="flex gap-3">
                    {run.status === 'active' && !isFull && !isRunner && (
                      <Button variant="primary" className="flex-1 bg-blue-600" onClick={() => setShowJoinForm(run.id)}>
                        Join Run
                      </Button>
                    )}
                    {run.status === 'active' && isFull && !isRunner && (
                      <Button disabled className="flex-1 bg-slate-200 text-slate-500">Run Full</Button>
                    )}
                    {run.status === 'active' && isRunner && (
                      <Button className="flex-1 bg-green-600 hover:bg-green-700" onClick={() => setShowArriveForm(run.id)}>
                        I've Arrived with Food
                      </Button>
                    )}
                  </div>
                </div>

                {/* Join Modal */}
                {showJoinForm === run.id && (
                  <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md p-6">
                      <div className="flex justify-between items-center mb-6">
                        <h3 className="text-2xl font-bold">Join Run</h3>
                        <button onClick={() => setShowJoinForm(null)} className="text-slate-400"><i className="fas fa-times"></i></button>
                      </div>
                      <form onSubmit={(e) => { e.preventDefault(); joinRun(run.id); }} className="space-y-4">
                        <div>
                          <label className="block text-sm font-semibold text-slate-700 mb-1">What do you want?</label>
                          <input required className="w-full p-3 border rounded-xl" placeholder="e.g. Salad with extra egg" value={newOrderItem} onChange={(e) => setNewOrderItem(e.target.value)} />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                          <div>
                            <label className="block text-sm font-semibold text-slate-700 mb-1">Cibus Code</label>
                            <input required className="w-full p-3 border rounded-xl" placeholder="123456" value={newOrderCibus} onChange={(e) => setNewOrderCibus(e.target.value)} />
                          </div>
                          <div>
                            <label className="block text-sm font-semibold text-slate-700 mb-1">Your Floor</label>
                            <input required className="w-full p-3 border rounded-xl" placeholder="e.g. 5th" value={newOrderFloor} onChange={(e) => setNewOrderFloor(e.target.value)} />
                          </div>
                        </div>
                        <Button type="submit" className="w-full h-12 bg-blue-600">Submit Order</Button>
                      </form>
                    </div>
                  </div>
                )}

                {/* Arrive Modal */}
                {showArriveForm === run.id && (
                  <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md p-6">
                      <h3 className="text-2xl font-bold mb-4">Where are you?</h3>
                      <p className="text-slate-500 mb-6">Tell everyone where to pick up their food.</p>
                      <div className="space-y-4">
                        <input autoFocus className="w-full p-3 border rounded-xl" placeholder="e.g. Kitchen, Floor 3 Lobby, My Desk..." value={arrivalLoc} onChange={(e) => setArrivalLoc(e.target.value)} />
                        <div className="flex gap-2">
                          <Button className="flex-1 bg-slate-200 text-slate-700" onClick={() => setShowArriveForm(null)}>Cancel</Button>
                          <Button className="flex-1 bg-green-600" onClick={() => markAsArrived(run.id)}>Notify Everyone</Button>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { FoodRun, Order } from './types';
import { Button } from './components/Button';

// התאם את הדומיין של החברה שלך כאן
const ALLOWED_DOMAIN = 'company.com'; 
// הזן כאן את ה-Client ID שקיבלת מ-Google Cloud Console
const GOOGLE_CLIENT_ID = 'YOUR_GOOGLE_CLIENT_ID.apps.googleusercontent.com';

const App: React.FC = () => {
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [user, setUser] = useState<{ name: string; email: string; picture?: string; isGuest?: boolean } | null>(null);
  const [isJoined, setIsJoined] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [showJoinForm, setShowJoinForm] = useState<string | null>(null);
  const [showArriveForm, setShowArriveForm] = useState<string | null>(null);

  // Guest mode states
  const [isGuestForm, setIsGuestForm] = useState(false);
  const [guestNameInput, setGuestNameInput] = useState('');

  // Form states
  const [newRunDest, setNewRunDest] = useState('');
  const [newRunTime, setNewRunTime] = useState(25);
  const [newRunMax, setNewRunMax] = useState(5);
  const [newOrderItem, setNewOrderItem] = useState('');
  const [newOrderCibus, setNewOrderCibus] = useState('');
  const [newOrderFloor, setNewOrderFloor] = useState('');
  const [arrivalLoc, setArrivalLoc] = useState('');

  useEffect(() => {
    // טעינת ריצות דוגמה
    const mockRuns: FoodRun[] = [
      {
        id: '1',
        runnerName: 'Sarah',
        destination: 'Pasta Place',
        departureTime: Date.now() + 15 * 60000,
        minutesUntilDeparture: 15,
        maxOrders: 3,
        status: 'active',
        orders: [
          { id: 'o1', userName: 'John', itemDescription: 'Carbonara', cibusCode: '1234', floor: '4th', timestamp: Date.now() }
        ]
      }
    ];
    setRuns(mockRuns);

    // אתחול כפתור גוגל
    /* global google */
    if (!isJoined && typeof window !== 'undefined' && (window as any).google) {
      try {
        (window as any).google.accounts.id.initialize({
          client_id: GOOGLE_CLIENT_ID,
          callback: handleGoogleResponse,
        });
        const btnContainer = document.getElementById("googleBtn");
        if (btnContainer) {
          (window as any).google.accounts.id.renderButton(
            btnContainer,
            { theme: "outline", size: "large", width: "100%" }
          );
        }
      } catch (e) {
        console.error("Google Auth failed to initialize", e);
      }
    }
  }, [isJoined, isGuestForm]);

  const decodeJwt = (token: string) => {
    try {
      const base64Url = token.split('.')[1];
      const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
      const jsonPayload = decodeURIComponent(atob(base64).split('').map(function(c) {
          return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
      }).join(''));
      return JSON.parse(jsonPayload);
    } catch (e) {
      return null;
    }
  };

  const handleGoogleResponse = (response: any) => {
    const payload = decodeJwt(response.credential);
    if (!payload) {
      setLoginError("Failed to verify Google identity.");
      return;
    }

    const email = payload.email;
    const name = payload.name;
    const picture = payload.picture;

    // בדיקת דומיין ארגוני - רק אם הדומיין הוגדר (לא ריק)
    if (ALLOWED_DOMAIN && ALLOWED_DOMAIN !== 'company.com' && !email.endsWith(`@${ALLOWED_DOMAIN}`)) {
      setLoginError(`Access denied. Please use your @${ALLOWED_DOMAIN} email.`);
      return;
    }

    setUser({ name, email, picture, isGuest: false });
    setIsJoined(true);
    setLoginError(null);
  };

  const handleGuestLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (guestNameInput.trim()) {
      setUser({ 
        name: guestNameInput.trim(), 
        email: 'guest@internal', 
        isGuest: true 
      });
      setIsJoined(true);
      setLoginError(null);
    }
  };

  const handleLogout = () => {
    setUser(null);
    setIsJoined(false);
    setIsGuestForm(false);
    setGuestNameInput('');
  };

  const createRun = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: user.name,
      destination: newRunDest,
      departureTime: Date.now() + newRunTime * 60000,
      minutesUntilDeparture: newRunTime,
      maxOrders: newRunMax,
      status: 'active',
      orders: []
    };
    setRuns([newRun, ...runs]);
    setShowCreateForm(false);
    setNewRunDest('');
  };

  const joinRun = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run || !user || run.orders.length >= run.maxOrders) return;

    const newOrder: Order = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      itemDescription: newOrderItem,
      cibusCode: newOrderCibus,
      floor: newOrderFloor,
      timestamp: Date.now()
    };

    setRuns(runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, newOrder] } : r));
    setShowJoinForm(null);
    setNewOrderItem('');
    setNewOrderCibus('');
    setNewOrderFloor('');
  };

  const markAsArrived = (runId: string) => {
    setRuns(runs.map(r => r.id === runId ? { 
      ...r, 
      status: 'arrived', 
      arrivalLocation: arrivalLoc, 
      arrivalTime: Date.now() 
    } : r));
    setShowArriveForm(null);
    setArrivalLoc('');
  };

  if (!isJoined) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-slate-800 to-slate-900 p-4 font-sans">
        <div className="bg-white p-8 rounded-3xl shadow-2xl w-full max-w-md animate-in fade-in zoom-in duration-300">
          <div className="text-center mb-8">
            <div className="w-20 h-20 bg-blue-50 rounded-2xl flex items-center justify-center mx-auto mb-4 rotate-3 shadow-inner">
              <i className="fas fa-bicycle text-blue-600 text-3xl"></i>
            </div>
            <h1 className="text-3xl font-black text-slate-800 tracking-tight">LunchRun</h1>
            <p className="text-slate-500 mt-2 font-medium">Internal Coordination Tool</p>
          </div>

          <div className="space-y-6">
            {!isGuestForm ? (
              <>
                <div className="bg-slate-50 p-6 rounded-2xl border border-slate-100 text-center space-y-4">
                  <p className="text-sm text-slate-600 font-semibold uppercase tracking-wider">Secure Access</p>
                  <div id="googleBtn" className="w-full flex justify-center"></div>
                </div>

                <div className="relative">
                  <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-200"></div></div>
                  <div className="relative flex justify-center text-xs uppercase"><span className="bg-white px-2 text-slate-400 font-bold tracking-widest">Or</span></div>
                </div>

                <Button 
                  onClick={() => setIsGuestForm(true)} 
                  variant="secondary" 
                  className="w-full h-12 border-slate-200 text-slate-700 hover:bg-slate-50"
                >
                  <i className="fas fa-user-clock mr-2"></i> Continue as Guest
                </Button>
              </>
            ) : (
              <form onSubmit={handleGuestLogin} className="animate-in slide-in-from-right-4 duration-200 space-y-4">
                <div>
                  <label className="block text-sm font-bold text-slate-700 mb-2">Display Name</label>
                  <input 
                    autoFocus
                    required
                    type="text"
                    className="w-full p-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 focus:bg-white rounded-xl transition-all outline-none font-medium"
                    placeholder="e.g. Michael G."
                    value={guestNameInput}
                    onChange={(e) => setGuestNameInput(e.target.value)}
                  />
                </div>
                <div className="flex gap-2">
                  <Button 
                    type="button" 
                    onClick={() => setIsGuestForm(false)} 
                    variant="ghost" 
                    className="flex-1"
                  >
                    Back
                  </Button>
                  <Button 
                    type="submit" 
                    className="flex-[2] bg-blue-600 hover:bg-blue-700 h-12"
                  >
                    Start Ordering
                  </Button>
                </div>
              </form>
            )}

            {loginError && (
              <div className="p-4 bg-red-50 text-red-600 text-sm rounded-xl border border-red-100 flex items-center gap-3 animate-shake">
                <i className="fas fa-exclamation-circle text-lg"></i>
                <span className="font-medium">{loginError}</span>
              </div>
            )}

            <p className="text-[10px] text-center text-slate-400 uppercase tracking-widest font-bold">
              Beta Access • 2024
            </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen pb-20 bg-slate-50">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 px-4 py-3 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-2">
          <i className="fas fa-bicycle text-blue-600 text-2xl"></i>
          <span className="text-xl font-black text-slate-800 tracking-tight">LUNCHRUN</span>
        </div>
        <div className="flex items-center gap-3">
          <div className="text-right hidden sm:block">
            <p className="text-xs font-bold text-slate-800 leading-none flex items-center gap-1 justify-end">
              {user?.isGuest && <span className="bg-slate-100 text-[8px] px-1 rounded uppercase tracking-tighter">Guest</span>}
              {user?.name}
            </p>
            <p className="text-[10px] text-slate-500">{user?.email}</p>
          </div>
          <button onClick={handleLogout} className="group relative">
            {user?.picture ? (
              <img src={user.picture} className="w-10 h-10 rounded-full border-2 border-blue-100 object-cover" alt="profile" />
            ) : (
              <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center text-blue-700 font-bold border-2 border-blue-200">
                {user?.name.charAt(0)}
              </div>
            )}
            <div className="absolute top-full right-0 mt-2 hidden group-hover:block bg-white border shadow-2xl rounded-xl p-2 z-50 min-w-[120px]">
                <button onClick={handleLogout} className="text-xs font-bold text-red-600 whitespace-nowrap px-3 py-2 hover:bg-red-50 rounded-lg w-full text-left flex items-center gap-2">
                    <i className="fas fa-sign-out-alt"></i> Sign Out
                </button>
            </div>
          </button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 sm:p-6 space-y-6">
        <section className="flex flex-col sm:flex-row gap-4 items-center justify-between bg-white p-6 rounded-3xl shadow-sm border border-slate-200">
          <div>
            <h2 className="text-2xl font-bold text-slate-800">Active Runs</h2>
            <p className="text-slate-500 text-sm">Hi {user?.name.split(' ')[0]}, hungry for a run?</p>
          </div>
          <Button onClick={() => setShowCreateForm(true)} className="bg-blue-600 hover:bg-blue-700 h-12 px-6 rounded-xl shadow-lg shadow-blue-200 active:scale-95 transition-transform">
            <i className="fas fa-plus"></i> I'm picking up food
          </Button>
        </section>

        {/* Create Run Modal */}
        {showCreateForm && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md p-6 animate-in slide-in-from-bottom-4">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-2xl font-bold">New Food Run</h3>
                <button onClick={() => setShowCreateForm(false)} className="text-slate-400 hover:text-slate-600">
                  <i className="fas fa-times text-xl"></i>
                </button>
              </div>
              <form onSubmit={createRun} className="space-y-4">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-1">Destination</label>
                  <input required type="text" className="w-full p-3 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl outline-none" placeholder="Sushi, Burgers, etc." value={newRunDest} onChange={(e) => setNewRunDest(e.target.value)} />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-semibold text-slate-700 mb-1">Leaving in (min)</label>
                    <input required type="number" min="1" className="w-full p-3 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl outline-none" value={newRunTime} onChange={(e) => setNewRunTime(parseInt(e.target.value))} />
                  </div>
                  <div>
                    <label className="block text-sm font-semibold text-slate-700 mb-1">Max Orders</label>
                    <input required type="number" min="1" max="20" className="w-full p-3 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl outline-none" value={newRunMax} onChange={(e) => setNewRunMax(parseInt(e.target.value))} />
                  </div>
                </div>
                <Button type="submit" className="w-full h-12 bg-blue-600 rounded-xl">Broadcast Run</Button>
              </form>
            </div>
          </div>
        )}

        {/* Runs List */}
        <div className="space-y-4">
          {runs.map(run => {
            const isFull = run.orders.length >= run.maxOrders;
            const isRunner = user && run.runnerName === user.name;

            return (
              <div key={run.id} className={`bg-white rounded-3xl border-2 transition-all ${run.status === 'arrived' ? 'border-green-200 bg-green-50/30' : 'border-slate-100 shadow-sm'}`}>
                <div className="p-6">
                  {/* Header */}
                  <div className="flex flex-col sm:flex-row justify-between items-start gap-4 mb-6">
                    <div className="flex gap-4">
                      <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-2xl ${run.status === 'arrived' ? 'bg-green-100 text-green-600' : 'bg-blue-100 text-blue-600'}`}>
                        <i className={`fas ${run.status === 'arrived' ? 'fa-check-circle' : 'fa-store'}`}></i>
                      </div>
                      <div>
                        <h4 className="text-xl font-bold text-slate-800 tracking-tight">{run.destination}</h4>
                        <p className="text-slate-500 text-sm">Runner: <span className="font-semibold text-slate-700">{run.runnerName}</span></p>
                      </div>
                    </div>

                    <div className="flex flex-wrap gap-2">
                      <div className="bg-slate-100 px-3 py-1 rounded-full text-xs font-bold text-slate-600 uppercase tracking-tight">
                        {run.orders.length} / {run.maxOrders} Spots
                      </div>
                      {run.status === 'active' && (
                        <div className="bg-orange-100 px-3 py-1 rounded-full text-xs font-bold text-orange-600 uppercase">
                          Leaves in {run.minutesUntilDeparture}m
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Arrival Banner */}
                  {run.status === 'arrived' && (
                    <div className="mb-6 bg-green-100 text-green-800 p-4 rounded-2xl flex items-center gap-3 animate-pulse">
                      <i className="fas fa-bell text-xl"></i>
                      <div>
                        <p className="font-bold">FOOD HAS ARRIVED!</p>
                        <p className="text-sm">Location: <span className="font-black underline">{run.arrivalLocation || 'Kitchen'}</span></p>
                      </div>
                    </div>
                  )}

                  {/* Orders */}
                  <div className="space-y-2 mb-6">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Order Queue</p>
                    {run.orders.length === 0 ? (
                      <div className="p-8 text-center bg-slate-50 rounded-2xl border border-dashed border-slate-200">
                        <p className="text-sm text-slate-400 font-medium">No passengers yet.</p>
                      </div>
                    ) : (
                      <div className="grid gap-2">
                        {run.orders.map(order => (
                          <div key={order.id} className="flex justify-between items-center bg-slate-50 p-3 rounded-xl border border-slate-200 hover:border-blue-200 transition-colors">
                            <div className="text-sm">
                              <span className="font-bold text-slate-800">{order.userName}</span>
                              <span className="text-slate-300 mx-2">/</span>
                              <span className="text-slate-600 italic">"{order.itemDescription}"</span>
                            </div>
                            <div className="flex gap-2">
                               <span className="bg-blue-50 text-blue-700 text-[10px] font-bold px-2 py-0.5 rounded-lg border border-blue-100 uppercase">Floor {order.floor}</span>
                               <span className="bg-amber-50 text-amber-700 text-[10px] font-mono px-2 py-0.5 rounded-lg border border-amber-100">Cibus: {order.cibusCode}</span>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>

                  {/* Actions */}
                  <div className="flex gap-3">
                    {run.status === 'active' && !isFull && !isRunner && (
                      <Button variant="primary" className="flex-1 bg-blue-600 rounded-xl" onClick={() => setShowJoinForm(run.id)}>
                        <i className="fas fa-hand-holding-heart mr-1"></i> Join Run
                      </Button>
                    )}
                    {run.status === 'active' && isFull && !isRunner && (
                      <Button disabled className="flex-1 bg-slate-100 text-slate-400 rounded-xl">Run is Full</Button>
                    )}
                    {run.status === 'active' && isRunner && (
                      <Button className="flex-1 bg-green-600 hover:bg-green-700 rounded-xl shadow-lg shadow-green-100" onClick={() => setShowArriveForm(run.id)}>
                        <i className="fas fa-flag-checkered mr-1"></i> I've Arrived with Food
                      </Button>
                    )}
                  </div>
                </div>

                {/* Join Modal */}
                {showJoinForm === run.id && (
                  <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md p-6">
                      <div className="flex justify-between items-center mb-6">
                        <h3 className="text-2xl font-bold">Join {run.runnerName}'s Run</h3>
                        <button onClick={() => setShowJoinForm(null)} className="text-slate-400"><i className="fas fa-times"></i></button>
                      </div>
                      <form onSubmit={(e) => { e.preventDefault(); joinRun(run.id); }} className="space-y-4">
                        <div>
                          <label className="block text-sm font-semibold text-slate-700 mb-1">What's your order?</label>
                          <input required className="w-full p-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl outline-none" placeholder="e.g. Greek Salad + Water" value={newOrderItem} onChange={(e) => setNewOrderItem(e.target.value)} />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                          <div>
                            <label className="block text-sm font-semibold text-slate-700 mb-1">Cibus Code</label>
                            <input required className="w-full p-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl outline-none" placeholder="123456" value={newOrderCibus} onChange={(e) => setNewOrderCibus(e.target.value)} />
                          </div>
                          <div>
                            <label className="block text-sm font-semibold text-slate-700 mb-1">Your Floor</label>
                            <input required className="w-full p-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl outline-none" placeholder="e.g. 5" value={newOrderFloor} onChange={(e) => setNewOrderFloor(e.target.value)} />
                          </div>
                        </div>
                        <Button type="submit" className="w-full h-14 bg-blue-600 rounded-xl shadow-lg shadow-blue-100">Submit My Order</Button>
                      </form>
                    </div>
                  </div>
                )}

                {/* Arrive Modal */}
                {showArriveForm === run.id && (
                  <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md p-6">
                      <h3 className="text-2xl font-bold mb-4">You're here!</h3>
                      <p className="text-slate-500 mb-6">Let the team know where to find their lunch.</p>
                      <div className="space-y-4">
                        <input autoFocus className="w-full p-4 bg-slate-50 border-2 border-transparent focus:border-green-500 rounded-xl outline-none" placeholder="e.g. Kitchen counter, Floor 4 Lobby..." value={arrivalLoc} onChange={(e) => setArrivalLoc(e.target.value)} />
                        <div className="flex gap-2">
                          <Button className="flex-1 bg-slate-100 text-slate-700 rounded-xl" onClick={() => setShowArriveForm(null)}>Cancel</Button>
                          <Button className="flex-1 bg-green-600 rounded-xl shadow-lg shadow-green-100" onClick={() => markAsArrived(run.id)}>Notify Team</Button>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { FoodRun, Order } from './types';
import { Button } from './components/Button';

/** 
 * SECURITY CONFIGURATION
 * 1. Change ALLOWED_DOMAIN to your company's domain (e.g., 'acme.com')
 * 2. Create a Client ID in Google Cloud Console (https://console.cloud.google.com)
 * 3. Add your app's URL to "Authorized JavaScript origins" in the Google Console.
 */
const ALLOWED_DOMAIN = 'yourcompany.com'; 
const GOOGLE_CLIENT_ID = 'YOUR_GOOGLE_CLIENT_ID.apps.googleusercontent.com';

const App: React.FC = () => {
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [user, setUser] = useState<{ name: string; email: string; picture?: string; isGuest?: boolean } | null>(null);
  const [isJoined, setIsJoined] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [showJoinForm, setShowJoinForm] = useState<string | null>(null);
  const [showArriveForm, setShowArriveForm] = useState<string | null>(null);

  const [isGuestForm, setIsGuestForm] = useState(false);
  const [guestNameInput, setGuestNameInput] = useState('');

  const [newRunDest, setNewRunDest] = useState('');
  const [newRunTime, setNewRunTime] = useState(25);
  const [newRunMax, setNewRunMax] = useState(5);
  const [newOrderItem, setNewOrderItem] = useState('');
  const [newOrderCibus, setNewOrderCibus] = useState('');
  const [newOrderFloor, setNewOrderFloor] = useState('');
  const [arrivalLoc, setArrivalLoc] = useState('');

  useEffect(() => {
    // Initial mock data
    const mockRuns: FoodRun[] = [
      {
        id: '1',
        runnerName: 'Sarah',
        destination: 'Pasta Place',
        departureTime: Date.now() + 15 * 60000,
        minutesUntilDeparture: 15,
        maxOrders: 3,
        status: 'active',
        orders: [
          { id: 'o1', userName: 'John', itemDescription: 'Carbonara', cibusCode: '1234', floor: '4th', timestamp: Date.now() }
        ]
      }
    ];
    setRuns(mockRuns);

    // Initialize Google Login with Security Parameters
    if (!isJoined && typeof window !== 'undefined' && (window as any).google) {
      try {
        (window as any).google.accounts.id.initialize({
          client_id: GOOGLE_CLIENT_ID,
          callback: handleGoogleResponse,
          // SECURITY: The 'hd' parameter restricts the account picker to only this domain
          hd: ALLOWED_DOMAIN === 'yourcompany.com' ? undefined : ALLOWED_DOMAIN, 
          auto_select: false,
          context: 'signin'
        });

        const btnContainer = document.getElementById("googleBtn");
        if (btnContainer) {
          (window as any).google.accounts.id.renderButton(
            btnContainer,
            { 
              theme: "filled_blue", 
              size: "large", 
              width: "100%",
              shape: "pill",
              text: "signin_with"
            }
          );
        }
      } catch (e) {
        console.error("Google Auth failed to initialize", e);
      }
    }
  }, [isJoined, isGuestForm]);

  const decodeJwt = (token: string) => {
    try {
      const base64Url = token.split('.')[1];
      const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
      const jsonPayload = decodeURIComponent(atob(base64).split('').map(function(c) {
          return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
      }).join(''));
      return JSON.parse(jsonPayload);
    } catch (e) {
      return null;
    }
  };

  const handleGoogleResponse = (response: any) => {
    const payload = decodeJwt(response.credential);
    if (!payload) {
      setLoginError("Invalid login response.");
      return;
    }

    /**
     * SECURITY VERIFICATION
     * Google includes the 'hd' (Hosted Domain) claim in the JWT.
     * We verify it here to ensure the token actually belongs to the organization.
     */
    const userDomain = payload.hd;
    const email = payload.email;

    if (ALLOWED_DOMAIN !== 'yourcompany.com' && userDomain !== ALLOWED_DOMAIN) {
      setLoginError(`Security Violation: Access is restricted to @${ALLOWED_DOMAIN} accounts only.`);
      // Sign out immediately to clear the session
      (window as any).google.accounts.id.disableAutoSelect();
      return;
    }

    setUser({ 
      name: payload.name, 
      email: payload.email, 
      picture: payload.picture, 
      isGuest: false 
    });
    setIsJoined(true);
    setLoginError(null);
  };

  const handleGuestLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (guestNameInput.trim()) {
      setUser({ 
        name: guestNameInput.trim(), 
        email: 'guest@internal', 
        isGuest: true 
      });
      setIsJoined(true);
      setLoginError(null);
    }
  };

  const handleLogout = () => {
    if (typeof (window as any).google !== 'undefined') {
      (window as any).google.accounts.id.disableAutoSelect();
    }
    setUser(null);
    setIsJoined(false);
    setIsGuestForm(false);
    setGuestNameInput('');
  };

  const createRun = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: user.name,
      destination: newRunDest,
      departureTime: Date.now() + newRunTime * 60000,
      minutesUntilDeparture: newRunTime,
      maxOrders: newRunMax,
      status: 'active',
      orders: []
    };
    setRuns([newRun, ...runs]);
    setShowCreateForm(false);
    setNewRunDest('');
  };

  const joinRun = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run || !user || run.orders.length >= run.maxOrders) return;

    const newOrder: Order = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      itemDescription: newOrderItem,
      cibusCode: newOrderCibus,
      floor: newOrderFloor,
      timestamp: Date.now()
    };

    setRuns(runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, newOrder] } : r));
    setShowJoinForm(null);
    setNewOrderItem('');
    setNewOrderCibus('');
    setNewOrderFloor('');
  };

  const markAsArrived = (runId: string) => {
    setRuns(runs.map(r => r.id === runId ? { 
      ...r, 
      status: 'arrived', 
      arrivalLocation: arrivalLoc, 
      arrivalTime: Date.now() 
    } : r));
    setShowArriveForm(null);
    setArrivalLoc('');
  };

  if (!isJoined) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-slate-900 via-slate-800 to-indigo-950 p-4 font-sans">
        <div className="bg-white p-8 rounded-[2rem] shadow-2xl w-full max-w-md animate-in fade-in zoom-in duration-500">
          <div className="text-center mb-8">
            <div className="w-24 h-24 bg-indigo-50 rounded-3xl flex items-center justify-center mx-auto mb-6 rotate-3 shadow-inner group hover:rotate-0 transition-transform duration-300">
              <i className="fas fa-bicycle text-indigo-600 text-4xl"></i>
            </div>
            <h1 className="text-4xl font-black text-slate-800 tracking-tight">LunchRun</h1>
            <p className="text-slate-500 mt-2 font-medium">Organization Resource</p>
          </div>

          <div className="space-y-6">
            {!isGuestForm ? (
              <>
                <div className="bg-indigo-50/50 p-6 rounded-3xl border border-indigo-100 text-center space-y-4">
                  <div className="flex items-center justify-center gap-2 text-indigo-700 font-bold text-xs uppercase tracking-widest mb-2">
                    <i className="fas fa-shield-alt"></i> Corporate SSO
                  </div>
                  <div id="googleBtn" className="w-full flex justify-center min-h-[40px]"></div>
                  <p className="text-[10px] text-indigo-400 font-medium">
                    Limited to <b>@{ALLOWED_DOMAIN}</b> employees
                  </p>
                </div>

                <div className="relative">
                  <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-100"></div></div>
                  <div className="relative flex justify-center text-[10px] uppercase font-bold text-slate-300 tracking-tighter"><span className="bg-white px-3">Temporary Access</span></div>
                </div>

                <button 
                  onClick={() => setIsGuestForm(true)} 
                  className="w-full py-3 text-slate-400 text-sm font-semibold hover:text-indigo-600 transition-colors flex items-center justify-center gap-2"
                >
                  <i className="fas fa-user-secret"></i> Continue as Guest
                </button>
              </>
            ) : (
              <form onSubmit={handleGuestLogin} className="animate-in slide-in-from-right-8 duration-300 space-y-4">
                <div className="bg-amber-50 border border-amber-100 p-3 rounded-xl flex items-start gap-3 mb-4">
                  <i className="fas fa-info-circle text-amber-500 mt-1"></i>
                  <p className="text-[11px] text-amber-800 leading-tight">
                    <b>Guest Mode:</b> Use this only if SSO is currently unavailable for your team.
                  </p>
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Your Full Name</label>
                  <input 
                    autoFocus
                    required
                    type="text"
                    className="w-full p-4 bg-slate-50 border-2 border-slate-100 focus:border-indigo-500 focus:bg-white rounded-2xl transition-all outline-none font-bold text-slate-700 shadow-sm"
                    placeholder="e.g. David Levi"
                    value={guestNameInput}
                    onChange={(e) => setGuestNameInput(e.target.value)}
                  />
                </div>
                <div className="flex gap-2 pt-2">
                  <Button 
                    type="button" 
                    onClick={() => setIsGuestForm(false)} 
                    variant="ghost" 
                    className="flex-1 text-slate-400"
                  >
                    Back
                  </Button>
                  <Button 
                    type="submit" 
                    className="flex-[2] bg-indigo-600 hover:bg-indigo-700 h-14 rounded-2xl shadow-lg shadow-indigo-100"
                  >
                    Enter System
                  </Button>
                </div>
              </form>
            )}

            {loginError && (
              <div className="p-4 bg-red-50 text-red-700 text-xs rounded-2xl border border-red-100 flex items-start gap-3 animate-bounce">
                <i className="fas fa-lock text-sm mt-0.5"></i>
                <span className="font-bold leading-tight">{loginError}</span>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen pb-20 bg-slate-50">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 px-6 py-4 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-3">
          <div className="bg-indigo-600 p-2 rounded-xl">
             <i className="fas fa-bicycle text-white text-xl"></i>
          </div>
          <span className="text-2xl font-black text-slate-800 tracking-tighter">LUNCHRUN</span>
        </div>
        <div className="flex items-center gap-4">
          <div className="text-right hidden sm:block">
            <p className="text-sm font-black text-slate-800 leading-none flex items-center gap-2 justify-end">
              {user?.isGuest && <span className="bg-amber-100 text-amber-700 text-[9px] px-1.5 py-0.5 rounded-md font-black uppercase tracking-tighter">Guest</span>}
              {!user?.isGuest && <i className="fas fa-check-circle text-indigo-500 text-[10px]"></i>}
              {user?.name}
            </p>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter">{user?.email}</p>
          </div>
          <button onClick={handleLogout} className="group relative">
            {user?.picture ? (
              <img src={user.picture} className="w-12 h-12 rounded-2xl border-2 border-indigo-100 object-cover shadow-sm group-hover:scale-105 transition-transform" alt="profile" />
            ) : (
              <div className="w-12 h-12 bg-indigo-100 rounded-2xl flex items-center justify-center text-indigo-700 font-black border-2 border-indigo-200 shadow-sm group-hover:scale-105 transition-transform">
                {user?.name.charAt(0)}
              </div>
            )}
            <div className="absolute top-full right-0 mt-3 hidden group-hover:block bg-white border shadow-2xl rounded-2xl p-2 z-50 min-w-[140px] animate-in slide-in-from-top-2">
                <button onClick={handleLogout} className="text-xs font-bold text-red-600 whitespace-nowrap px-4 py-3 hover:bg-red-50 rounded-xl w-full text-left flex items-center gap-3 transition-colors">
                    <i className="fas fa-sign-out-alt"></i> Sign Out
                </button>
            </div>
          </button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 sm:p-8 space-y-8">
        <section className="flex flex-col sm:flex-row gap-6 items-center justify-between bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-200">
          <div>
            <h2 className="text-3xl font-black text-slate-800 tracking-tight">Active Runs</h2>
            <p className="text-slate-400 font-medium">Hello {user?.name.split(' ')[0]}, coordinate with your team.</p>
          </div>
          <Button onClick={() => setShowCreateForm(true)} className="bg-indigo-600 hover:bg-indigo-700 h-14 px-8 rounded-2xl shadow-xl shadow-indigo-200 active:scale-95 transition-all text-lg font-black">
            <i className="fas fa-plus"></i> I'm picking up food
          </Button>
        </section>

        {/* Create Run Modal */}
        {showCreateForm && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-md p-8 animate-in slide-in-from-bottom-8">
              <div className="flex justify-between items-center mb-8">
                <h3 className="text-2xl font-black text-slate-800">New Food Run</h3>
                <button onClick={() => setShowCreateForm(false)} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-slate-100 text-slate-400 transition-colors">
                  <i className="fas fa-times text-xl"></i>
                </button>
              </div>
              <form onSubmit={createRun} className="space-y-6">
                <div>
                  <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Destination Name</label>
                  <input required type="text" className="w-full p-4 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl outline-none font-bold" placeholder="Pasta, Sushi, etc." value={newRunDest} onChange={(e) => setNewRunDest(e.target.value)} />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Leaves In (min)</label>
                    <input required type="number" min="1" className="w-full p-4 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl outline-none font-bold" value={newRunTime} onChange={(e) => setNewRunTime(parseInt(e.target.value))} />
                  </div>
                  <div>
                    <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Capacity</label>
                    <input required type="number" min="1" max="20" className="w-full p-4 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl outline-none font-bold" value={newRunMax} onChange={(e) => setNewRunMax(parseInt(e.target.value))} />
                  </div>
                </div>
                <Button type="submit" className="w-full h-16 bg-indigo-600 rounded-2xl text-xl font-black shadow-lg shadow-indigo-100">Broadcast Now</Button>
              </form>
            </div>
          </div>
        )}

        {/* Runs List */}
        <div className="space-y-6">
          {runs.map(run => {
            const isFull = run.orders.length >= run.maxOrders;
            const isRunner = user && run.runnerName === user.name;

            return (
              <div key={run.id} className={`bg-white rounded-[2rem] border-2 transition-all group ${run.status === 'arrived' ? 'border-green-400 bg-green-50/20' : 'border-slate-100 hover:border-indigo-100 shadow-sm'}`}>
                <div className="p-8">
                  <div className="flex flex-col sm:flex-row justify-between items-start gap-4 mb-8">
                    <div className="flex gap-5">
                      <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-3xl shadow-sm ${run.status === 'arrived' ? 'bg-green-100 text-green-600' : 'bg-indigo-50 text-indigo-600'}`}>
                        <i className={`fas ${run.status === 'arrived' ? 'fa-check-circle' : 'fa-store'}`}></i>
                      </div>
                      <div>
                        <h4 className="text-2xl font-black text-slate-800 tracking-tight">{run.destination}</h4>
                        <p className="text-slate-400 text-sm font-bold">Runner: <span className="text-indigo-600">{run.runnerName}</span></p>
                      </div>
                    </div>

                    <div className="flex flex-wrap gap-2">
                      <div className="bg-slate-100 px-4 py-1.5 rounded-full text-[10px] font-black text-slate-600 uppercase tracking-widest border border-slate-200">
                        {run.orders.length} / {run.maxOrders} Spots Used
                      </div>
                      {run.status === 'active' && (
                        <div className="bg-orange-100 px-4 py-1.5 rounded-full text-[10px] font-black text-orange-600 uppercase tracking-widest border border-orange-200">
                          Leaves in {run.minutesUntilDeparture}m
                        </div>
                      )}
                    </div>
                  </div>

                  {run.status === 'arrived' && (
                    <div className="mb-8 bg-green-500 text-white p-6 rounded-3xl flex items-center gap-5 animate-pulse shadow-lg shadow-green-100">
                      <div className="w-12 h-12 bg-white/20 rounded-full flex items-center justify-center shrink-0">
                        <i className="fas fa-bell text-2xl"></i>
                      </div>
                      <div>
                        <p className="font-black text-xl tracking-tight">DELIVERED!</p>
                        <p className="text-sm font-bold opacity-90">Location: <span className="underline decoration-2 underline-offset-4">{run.arrivalLocation || 'Kitchen'}</span></p>
                      </div>
                    </div>
                  )}

                  <div className="space-y-3 mb-8">
                    <p className="text-[10px] font-black text-slate-300 uppercase tracking-[0.2em] px-1">Order Queue</p>
                    {run.orders.length === 0 ? (
                      <div className="p-10 text-center bg-slate-50 rounded-3xl border-2 border-dashed border-slate-100">
                        <p className="text-sm text-slate-400 font-bold">No orders placed yet.</p>
                      </div>
                    ) : (
                      <div className="grid gap-3">
                        {run.orders.map(order => (
                          <div key={order.id} className="flex justify-between items-center bg-white p-4 rounded-2xl border border-slate-100 group-hover:border-indigo-50 shadow-sm transition-all">
                            <div className="flex items-center gap-3">
                               <div className="w-8 h-8 rounded-lg bg-indigo-50 text-indigo-600 flex items-center justify-center text-xs font-black">
                                 {order.userName.charAt(0)}
                               </div>
                               <div className="text-sm">
                                 <span className="font-black text-slate-800">{order.userName}</span>
                                 <span className="text-slate-300 mx-2">•</span>
                                 <span className="text-slate-500 font-medium">"{order.itemDescription}"</span>
                               </div>
                            </div>
                            <div className="flex gap-2">
                               <span className="bg-indigo-50 text-indigo-700 text-[9px] font-black px-3 py-1 rounded-lg uppercase tracking-tighter">Floor {order.floor}</span>
                               <span className="bg-amber-50 text-amber-700 text-[9px] font-mono font-bold px-3 py-1 rounded-lg tracking-tighter">ID: {order.cibusCode}</span>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>

                  <div className="flex gap-4">
                    {run.status === 'active' && !isFull && !isRunner && (
                      <Button variant="primary" className="flex-1 bg-indigo-600 rounded-2xl h-16 text-lg font-black" onClick={() => setShowJoinForm(run.id)}>
                        <i className="fas fa-plus-circle mr-2"></i> Join this Run
                      </Button>
                    )}
                    {run.status === 'active' && isFull && !isRunner && (
                      <Button disabled className="flex-1 bg-slate-100 text-slate-400 rounded-2xl h-16 font-black uppercase tracking-widest">Run is Full</Button>
                    )}
                    {run.status === 'active' && isRunner && (
                      <Button className="flex-1 bg-green-600 hover:bg-green-700 rounded-2xl h-16 text-lg font-black shadow-lg shadow-green-100" onClick={() => setShowArriveForm(run.id)}>
                        <i className="fas fa-check mr-2"></i> I Have Arrived
                      </Button>
                    )}
                  </div>
                </div>

                {/* Join Modal */}
                {showJoinForm === run.id && (
                  <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md p-8">
                      <div className="flex justify-between items-center mb-8">
                        <div>
                          <h3 className="text-2xl font-black text-slate-800">Add Order</h3>
                          <p className="text-slate-400 text-sm font-bold uppercase tracking-tight">Run by {run.runnerName}</p>
                        </div>
                        <button onClick={() => setShowJoinForm(null)} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-slate-100 text-slate-400 transition-colors"><i className="fas fa-times"></i></button>
                      </div>
                      <form onSubmit={(e) => { e.preventDefault(); joinRun(run.id); }} className="space-y-6">
                        <div>
                          <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">What are you getting?</label>
                          <input required className="w-full p-4 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl outline-none font-bold" placeholder="e.g. Cobb Salad, no onion" value={newOrderItem} onChange={(e) => setNewOrderItem(e.target.value)} />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                          <div>
                            <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Cibus ID</label>
                            <input required className="w-full p-4 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl outline-none font-bold" placeholder="123456" value={newOrderCibus} onChange={(e) => setNewOrderCibus(e.target.value)} />
                          </div>
                          <div>
                            <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Floor #</label>
                            <input required className="w-full p-4 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl outline-none font-bold" placeholder="e.g. 5" value={newOrderFloor} onChange={(e) => setNewOrderFloor(e.target.value)} />
                          </div>
                        </div>
                        <Button type="submit" className="w-full h-16 bg-indigo-600 rounded-2xl text-xl font-black shadow-lg shadow-indigo-100">Submit Order</Button>
                      </form>
                    </div>
                  </div>
                )}

                {/* Arrive Modal */}
                {showArriveForm === run.id && (
                  <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md p-10">
                      <div className="w-16 h-16 bg-green-100 text-green-600 rounded-3xl flex items-center justify-center text-3xl mb-6 mx-auto">
                        <i className="fas fa-map-marker-alt"></i>
                      </div>
                      <h3 className="text-2xl font-black text-slate-800 text-center mb-2">Drop-off point?</h3>
                      <p className="text-slate-400 font-bold text-center mb-8 uppercase text-xs tracking-widest">Notify the entire team</p>
                      <div className="space-y-6">
                        <input autoFocus className="w-full p-5 bg-slate-50 border-2 border-transparent focus:border-green-500 rounded-2xl outline-none font-bold text-lg text-center" placeholder="e.g. Main Kitchen, Floor 3" value={arrivalLoc} onChange={(e) => setArrivalLoc(e.target.value)} />
                        <div className="flex gap-3">
                          <Button className="flex-1 bg-slate-100 text-slate-700 rounded-2xl h-14 font-black" onClick={() => setShowArriveForm(null)}>Cancel</Button>
                          <Button className="flex-1 bg-green-600 rounded-2xl h-14 font-black text-white shadow-lg shadow-green-100" onClick={() => markAsArrived(run.id)}>Confirm Arrival</Button>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { FoodRun, Order } from './types';
import { Button } from './components/Button';

/** 
 * SECURITY CONFIGURATION
 * ----------------------
 * 1. ALLOWED_DOMAIN: Set this to your corporate domain (e.g., 'google.com', 'microsoft.com').
 *    When set, the Google Sign-In UI will restrict the account picker to that domain.
 * 2. GOOGLE_CLIENT_ID: Your unique ID from the Google Cloud Console.
 */
const ALLOWED_DOMAIN = 'yourcompany.com'; 
const GOOGLE_CLIENT_ID = 'YOUR_GOOGLE_CLIENT_ID.apps.googleusercontent.com';

const App: React.FC = () => {
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [user, setUser] = useState<{ name: string; email: string; picture?: string; isGuest?: boolean } | null>(null);
  const [isJoined, setIsJoined] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [showJoinForm, setShowJoinForm] = useState<string | null>(null);
  const [showArriveForm, setShowArriveForm] = useState<string | null>(null);

  const [isGuestForm, setIsGuestForm] = useState(false);
  const [guestNameInput, setGuestNameInput] = useState('');

  const [newRunDest, setNewRunDest] = useState('');
  const [newRunTime, setNewRunTime] = useState(25);
  const [newRunMax, setNewRunMax] = useState(5);
  const [newOrderItem, setNewOrderItem] = useState('');
  const [newOrderCibus, setNewOrderCibus] = useState('');
  const [newOrderFloor, setNewOrderFloor] = useState('');
  const [arrivalLoc, setArrivalLoc] = useState('');

  useEffect(() => {
    // Initial mock data
    const mockRuns: FoodRun[] = [
      {
        id: '1',
        runnerName: 'Sarah',
        destination: 'Pasta Place',
        departureTime: Date.now() + 15 * 60000,
        minutesUntilDeparture: 15,
        maxOrders: 3,
        status: 'active',
        orders: [
          { id: 'o1', userName: 'John', itemDescription: 'Carbonara', cibusCode: '1234', floor: '4th', timestamp: Date.now() }
        ]
      }
    ];
    setRuns(mockRuns);

    // Initialize Google Login with Hosted Domain (hd) restriction
    if (!isJoined && typeof window !== 'undefined' && (window as any).google) {
      try {
        (window as any).google.accounts.id.initialize({
          client_id: GOOGLE_CLIENT_ID,
          callback: handleGoogleResponse,
          // SECURITY: The 'hd' parameter tells Google to only allow accounts from this domain.
          // Note: If ALLOWED_DOMAIN is the placeholder, we don't apply it yet.
          hd: ALLOWED_DOMAIN !== 'yourcompany.com' ? ALLOWED_DOMAIN : undefined,
          auto_select: false,
          context: 'signin'
        });

        const btnContainer = document.getElementById("googleBtn");
        if (btnContainer) {
          (window as any).google.accounts.id.renderButton(
            btnContainer,
            { 
              theme: "filled_blue", 
              size: "large", 
              width: "100%",
              shape: "pill",
              logo_alignment: "left"
            }
          );
        }
      } catch (e) {
        console.error("Google Identity Services failed to initialize", e);
      }
    }
  }, [isJoined, isGuestForm]);

  const decodeJwt = (token: string) => {
    try {
      const base64Url = token.split('.')[1];
      const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
      const jsonPayload = decodeURIComponent(atob(base64).split('').map(function(c) {
          return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
      }).join(''));
      return JSON.parse(jsonPayload);
    } catch (e) {
      return null;
    }
  };

  const handleGoogleResponse = (response: any) => {
    const payload = decodeJwt(response.credential);
    if (!payload) {
      setLoginError("Verification failed. Please try again.");
      return;
    }

    /**
     * SECONDARY SECURITY CHECK
     * Even if the UI filters accounts, we MUST check the 'hd' claim in the token payload.
     * This prevents a malicious user from injecting a token from a personal account.
     */
    if (ALLOWED_DOMAIN !== 'yourcompany.com' && payload.hd !== ALLOWED_DOMAIN) {
      setLoginError(`Security Alert: Only @${ALLOWED_DOMAIN} accounts are permitted to access this tool.`);
      // Ensure the session is cleared
      if ((window as any).google?.accounts?.id) {
        (window as any).google.accounts.id.disableAutoSelect();
      }
      return;
    }

    setUser({ 
      name: payload.name, 
      email: payload.email, 
      picture: payload.picture, 
      isGuest: false 
    });
    setIsJoined(true);
    setLoginError(null);
  };

  const handleGuestLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (guestNameInput.trim()) {
      setUser({ 
        name: guestNameInput.trim(), 
        email: 'guest@internal.local', 
        isGuest: true 
      });
      setIsJoined(true);
      setLoginError(null);
    }
  };

  const handleLogout = () => {
    if (typeof (window as any).google !== 'undefined') {
      (window as any).google.accounts.id.disableAutoSelect();
    }
    setUser(null);
    setIsJoined(false);
    setIsGuestForm(false);
    setGuestNameInput('');
  };

  const createRun = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: user.name,
      destination: newRunDest,
      departureTime: Date.now() + newRunTime * 60000,
      minutesUntilDeparture: newRunTime,
      maxOrders: newRunMax,
      status: 'active',
      orders: []
    };
    setRuns([newRun, ...runs]);
    setShowCreateForm(false);
    setNewRunDest('');
  };

  const joinRun = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run || !user || run.orders.length >= run.maxOrders) return;

    const newOrder: Order = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      itemDescription: newOrderItem,
      cibusCode: newOrderCibus,
      floor: newOrderFloor,
      timestamp: Date.now()
    };

    setRuns(runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, newOrder] } : r));
    setShowJoinForm(null);
    setNewOrderItem('');
    setNewOrderCibus('');
    setNewOrderFloor('');
  };

  const markAsArrived = (runId: string) => {
    setRuns(runs.map(r => r.id === runId ? { 
      ...r, 
      status: 'arrived', 
      arrivalLocation: arrivalLoc, 
      arrivalTime: Date.now() 
    } : r));
    setShowArriveForm(null);
    setArrivalLoc('');
  };

  if (!isJoined) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-slate-900 via-indigo-950 to-slate-900 p-4 font-sans">
        <div className="bg-white p-8 rounded-[2.5rem] shadow-[0_20px_50px_rgba(0,0,0,0.3)] w-full max-w-md animate-in fade-in zoom-in duration-500 border border-white/10">
          <div className="text-center mb-10">
            <div className="w-24 h-24 bg-indigo-600 rounded-[2rem] flex items-center justify-center mx-auto mb-6 shadow-2xl shadow-indigo-500/20 rotate-3 hover:rotate-0 transition-all duration-300">
              <i className="fas fa-bicycle text-white text-4xl"></i>
            </div>
            <h1 className="text-4xl font-black text-slate-800 tracking-tight">LunchRun</h1>
            <p className="text-slate-400 mt-2 font-bold uppercase text-[10px] tracking-[0.2em]">Secure Internal Portal</p>
          </div>

          <div className="space-y-8">
            {!isGuestForm ? (
              <>
                <div className="bg-slate-50 p-7 rounded-[2rem] border border-slate-100 space-y-5 text-center shadow-inner">
                  <div className="flex items-center justify-center gap-2 text-indigo-600 font-black text-[11px] uppercase tracking-widest mb-1">
                    <i className="fas fa-shield-check text-sm"></i> Standard Secure Sign-In
                  </div>
                  <div id="googleBtn" className="w-full flex justify-center min-h-[46px]"></div>
                  {ALLOWED_DOMAIN !== 'yourcompany.com' && (
                    <p className="text-[10px] text-slate-400 font-bold leading-relaxed px-4">
                      Access restricted to registered <span className="text-indigo-500">@{ALLOWED_DOMAIN}</span> employees only.
                    </p>
                  )}
                </div>

                <div className="relative flex items-center">
                  <div className="flex-grow border-t border-slate-100"></div>
                  <span className="flex-shrink mx-4 text-[10px] font-black text-slate-300 uppercase tracking-widest">or bypass</span>
                  <div className="flex-grow border-t border-slate-100"></div>
                </div>

                <button 
                  onClick={() => setIsGuestForm(true)} 
                  className="w-full py-2 text-slate-400 text-[11px] font-black uppercase tracking-widest hover:text-indigo-600 transition-colors flex items-center justify-center gap-2"
                >
                  <i className="fas fa-user-clock"></i> Continue as Guest (Unverified)
                </button>
              </>
            ) : (
              <form onSubmit={handleGuestLogin} className="animate-in slide-in-from-right-12 duration-500 space-y-6">
                <div className="bg-amber-50 border border-amber-100 p-4 rounded-2xl flex items-start gap-3">
                  <i className="fas fa-info-circle text-amber-500 mt-0.5"></i>
                  <p className="text-[11px] text-amber-800 font-medium leading-normal">
                    Guest mode is intended for temporary use or external contractors. SSO is preferred for security.
                  </p>
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Identity Display Name</label>
                  <input 
                    autoFocus
                    required
                    type="text"
                    className="w-full p-4 bg-slate-50 border-2 border-slate-100 focus:border-indigo-600 focus:bg-white rounded-2xl transition-all outline-none font-bold text-slate-700 shadow-sm"
                    placeholder="Michael Cohen"
                    value={guestNameInput}
                    onChange={(e) => setGuestNameInput(e.target.value)}
                  />
                </div>
                <div className="flex gap-3 pt-2">
                  <Button 
                    type="button" 
                    onClick={() => setIsGuestForm(false)} 
                    variant="ghost" 
                    className="flex-1 text-slate-400 text-xs font-black uppercase"
                  >
                    Back
                  </Button>
                  <Button 
                    type="submit" 
                    className="flex-[2] bg-indigo-600 hover:bg-indigo-700 h-14 rounded-2xl shadow-xl shadow-indigo-100 text-sm font-black uppercase tracking-widest"
                  >
                    Enter Portal
                  </Button>
                </div>
              </form>
            )}

            {loginError && (
              <div className="p-4 bg-red-50 text-red-700 text-[11px] rounded-2xl border border-red-100 flex items-start gap-3 animate-shake font-bold leading-normal">
                <i className="fas fa-exclamation-triangle text-sm mt-0.5"></i>
                <span>{loginError}</span>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen pb-20 bg-[#F8FAFC]">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-40 px-6 py-4 flex justify-between items-center backdrop-blur-md bg-white/80">
        <div className="flex items-center gap-3">
          <div className="bg-indigo-600 w-10 h-10 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-200">
             <i className="fas fa-bicycle text-white text-lg"></i>
          </div>
          <span className="text-2xl font-black text-slate-800 tracking-tighter">LUNCHRUN</span>
        </div>

        <div className="flex items-center gap-4">
          <div className="text-right hidden sm:block">
            <p className="text-sm font-black text-slate-800 leading-none flex items-center gap-2 justify-end">
              {user?.isGuest ? (
                <span className="bg-slate-100 text-slate-500 text-[8px] px-1.5 py-0.5 rounded font-black uppercase tracking-tighter">Guest</span>
              ) : (
                <span className="bg-emerald-100 text-emerald-600 text-[8px] px-1.5 py-0.5 rounded font-black uppercase tracking-tighter flex items-center gap-1">
                  <i className="fas fa-badge-check"></i> Verified
                </span>
              )}
              {user?.name}
            </p>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter mt-1">{user?.email}</p>
          </div>

          <button onClick={handleLogout} className="group relative outline-none">
            {user?.picture ? (
              <img src={user.picture} className="w-12 h-12 rounded-2xl border-2 border-indigo-50 object-cover shadow-sm group-hover:scale-105 transition-transform" alt="profile" />
            ) : (
              <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-600 font-black border-2 border-indigo-100 shadow-sm group-hover:scale-105 transition-transform">
                {user?.name.charAt(0)}
              </div>
            )}
            <div className="absolute top-full right-0 mt-3 hidden group-hover:block bg-white border border-slate-100 shadow-[0_15px_30px_rgba(0,0,0,0.1)] rounded-2xl p-2 z-50 min-w-[150px] animate-in slide-in-from-top-2">
                <button onClick={handleLogout} className="text-xs font-black text-red-500 whitespace-nowrap px-4 py-3 hover:bg-red-50 rounded-xl w-full text-left flex items-center gap-3 transition-colors uppercase tracking-widest">
                    <i className="fas fa-sign-out-alt"></i> Sign Out
                </button>
            </div>
          </button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 sm:p-8 space-y-10">
        <section className="flex flex-col sm:flex-row gap-6 items-center justify-between bg-white p-10 rounded-[3rem] shadow-sm border border-slate-100">
          <div>
            <h2 className="text-3xl font-black text-slate-800 tracking-tight">Food Runs</h2>
            <p className="text-slate-400 font-bold text-sm uppercase tracking-widest mt-1">Hello, {user?.name.split(' ')[0]}</p>
          </div>
          <Button onClick={() => setShowCreateForm(true)} className="bg-indigo-600 hover:bg-indigo-700 h-16 px-10 rounded-2xl shadow-2xl shadow-indigo-100 active:scale-95 transition-all text-lg font-black uppercase tracking-wider">
            <i className="fas fa-megaphone mr-2"></i> Start a Run
          </Button>
        </section>

        {/* Create Run Modal */}
        {showCreateForm && (
          <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md p-10 animate-in slide-in-from-bottom-12">
              <div className="flex justify-between items-center mb-10">
                <h3 className="text-2xl font-black text-slate-800">Launch a Run</h3>
                <button onClick={() => setShowCreateForm(false)} className="w-12 h-12 flex items-center justify-center rounded-full hover:bg-slate-50 text-slate-300 transition-colors">
                  <i className="fas fa-times text-2xl"></i>
                </button>
              </div>
              <form onSubmit={createRun} className="space-y-8">
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-3 ml-1">Where are you going?</label>
                  <input required type="text" className="w-full p-5 bg-slate-50 border-2 border-transparent focus:border-indigo-600 rounded-2xl outline-none font-bold text-lg" placeholder="Pasta, Burgers, Aroma..." value={newRunDest} onChange={(e) => setNewRunDest(e.target.value)} />
                </div>
                <div className="grid grid-cols-2 gap-6">
                  <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-3 ml-1">Leaves In (min)</label>
                    <input required type="number" min="1" className="w-full p-5 bg-slate-50 border-2 border-transparent focus:border-indigo-600 rounded-2xl outline-none font-bold text-lg" value={newRunTime} onChange={(e) => setNewRunTime(parseInt(e.target.value))} />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-3 ml-1">Max Orders</label>
                    <input required type="number" min="1" max="20" className="w-full p-5 bg-slate-50 border-2 border-transparent focus:border-indigo-600 rounded-2xl outline-none font-bold text-lg" value={newRunMax} onChange={(e) => setNewRunMax(parseInt(e.target.value))} />
                  </div>
                </div>
                <Button type="submit" className="w-full h-20 bg-indigo-600 rounded-[2rem] text-xl font-black shadow-2xl shadow-indigo-100 uppercase tracking-widest">Broadcast to Team</Button>
              </form>
            </div>
          </div>
        )}

        {/* Runs List */}
        <div className="grid gap-8">
          {runs.map(run => {
            const isFull = run.orders.length >= run.maxOrders;
            const isRunner = user && run.runnerName === user.name;

            return (
              <div key={run.id} className={`bg-white rounded-[3rem] border-2 transition-all duration-300 group ${run.status === 'arrived' ? 'border-emerald-500 bg-emerald-50/20' : 'border-white hover:border-indigo-50 shadow-[0_10px_40px_rgba(0,0,0,0.03)]'}`}>
                <div className="p-10">
                  <div className="flex flex-col sm:flex-row justify-between items-start gap-6 mb-10">
                    <div className="flex gap-6">
                      <div className={`w-20 h-20 rounded-[1.5rem] flex items-center justify-center text-4xl shadow-sm ${run.status === 'arrived' ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}>
                        <i className={`fas ${run.status === 'arrived' ? 'fa-check-circle' : 'fa-utensils'}`}></i>
                      </div>
                      <div>
                        <h4 className="text-3xl font-black text-slate-800 tracking-tight">{run.destination}</h4>
                        <p className="text-slate-400 font-bold text-sm mt-1">Organized by <span className="text-indigo-600">{run.runnerName}</span></p>
                      </div>
                    </div>

                    <div className="flex flex-wrap gap-3">
                      <div className="bg-slate-50 px-5 py-2 rounded-full text-[10px] font-black text-slate-500 uppercase tracking-widest border border-slate-100">
                        {run.orders.length} / {run.maxOrders} capacity
                      </div>
                      {run.status === 'active' && (
                        <div className="bg-orange-50 px-5 py-2 rounded-full text-[10px] font-black text-orange-600 uppercase tracking-widest border border-orange-100">
                          {run.minutesUntilDeparture}m left
                        </div>
                      )}
                    </div>
                  </div>

                  {run.status === 'arrived' && (
                    <div className="mb-10 bg-emerald-600 text-white p-8 rounded-[2rem] flex items-center gap-6 animate-pulse shadow-xl shadow-emerald-100">
                      <div className="w-14 h-14 bg-white/20 rounded-full flex items-center justify-center shrink-0">
                        <i className="fas fa-bell text-2xl"></i>
                      </div>
                      <div>
                        <p className="font-black text-2xl tracking-tighter uppercase">Pick up your food!</p>
                        <p className="text-sm font-bold opacity-90 mt-1">Destination: <span className="underline decoration-2 underline-offset-4">{run.arrivalLocation || 'Kitchen'}</span></p>
                      </div>
                    </div>
                  )}

                  <div className="space-y-4 mb-10">
                    <p className="text-[10px] font-black text-slate-300 uppercase tracking-[0.3em] px-2 mb-4">Confirmed Orders</p>
                    {run.orders.length === 0 ? (
                      <div className="p-12 text-center bg-slate-50/50 rounded-[2.5rem] border-2 border-dashed border-slate-100">
                        <p className="text-sm text-slate-400 font-black uppercase tracking-widest">Queue is currently empty</p>
                      </div>
                    ) : (
                      <div className="grid gap-4">
                        {run.orders.map(order => (
                          <div key={order.id} className="flex justify-between items-center bg-white p-6 rounded-[1.5rem] border border-slate-100 shadow-sm transition-all hover:translate-x-1">
                            <div className="flex items-center gap-4">
                               <div className="w-10 h-10 rounded-xl bg-slate-50 text-slate-400 flex items-center justify-center text-xs font-black border border-slate-100">
                                 {order.userName.charAt(0)}
                               </div>
                               <div>
                                 <p className="font-black text-slate-800 text-sm">{order.userName}</p>
                                 <p className="text-slate-500 text-xs font-medium mt-0.5">"{order.itemDescription}"</p>
                               </div>
                            </div>
                            <div className="flex gap-3">
                               <span className="bg-indigo-50 text-indigo-600 text-[10px] font-black px-4 py-1.5 rounded-full uppercase border border-indigo-100 tracking-tighter">F{order.floor}</span>
                               <span className="bg-slate-50 text-slate-400 text-[10px] font-mono font-bold px-4 py-1.5 rounded-full border border-slate-200 tracking-tighter">#{order.cibusCode}</span>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>

                  <div className="flex gap-5">
                    {run.status === 'active' && !isFull && !isRunner && (
                      <Button variant="primary" className="flex-1 bg-indigo-600 rounded-[1.5rem] h-20 text-lg font-black uppercase tracking-widest shadow-lg shadow-indigo-100" onClick={() => setShowJoinForm(run.id)}>
                        <i className="fas fa-plus-circle mr-2"></i> Join Queue
                      </Button>
                    )}
                    {run.status === 'active' && isFull && !isRunner && (
                      <Button disabled className="flex-1 bg-slate-100 text-slate-300 rounded-[1.5rem] h-20 font-black uppercase tracking-widest">Sold Out</Button>
                    )}
                    {run.status === 'active' && isRunner && (
                      <Button className="flex-1 bg-emerald-600 hover:bg-emerald-700 rounded-[1.5rem] h-20 text-lg font-black shadow-2xl shadow-emerald-100 uppercase tracking-widest" onClick={() => setShowArriveForm(run.id)}>
                        <i className="fas fa-check-double mr-2"></i> I've Returned
                      </Button>
                    )}
                  </div>
                </div>

                {/* Join Modal */}
                {showJoinForm === run.id && (
                  <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md p-10">
                      <div className="flex justify-between items-center mb-10">
                        <div>
                          <h3 className="text-2xl font-black text-slate-800 tracking-tight">Place Order</h3>
                          <p className="text-indigo-600 text-[10px] font-black uppercase tracking-widest mt-1">Run by {run.runnerName}</p>
                        </div>
                        <button onClick={() => setShowJoinForm(null)} className="w-12 h-12 flex items-center justify-center rounded-full hover:bg-slate-50 text-slate-300 transition-colors"><i className="fas fa-times text-2xl"></i></button>
                      </div>
                      <form onSubmit={(e) => { e.preventDefault(); joinRun(run.id); }} className="space-y-8">
                        <div>
                          <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 ml-1">What's your order?</label>
                          <input required className="w-full p-5 bg-slate-50 border-2 border-transparent focus:border-indigo-600 rounded-2xl outline-none font-bold text-lg" placeholder="e.g. Double Espresso, Sandwich..." value={newOrderItem} onChange={(e) => setNewOrderItem(e.target.value)} />
                        </div>
                        <div className="grid grid-cols-2 gap-6">
                          <div>
                            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 ml-1">Cibus Code</label>
                            <input required className="w-full p-5 bg-slate-50 border-2 border-transparent focus:border-indigo-600 rounded-2xl outline-none font-bold text-lg" placeholder="6-digit ID" value={newOrderCibus} onChange={(e) => setNewOrderCibus(e.target.value)} />
                          </div>
                          <div>
                            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 ml-1">Floor #</label>
                            <input required className="w-full p-5 bg-slate-50 border-2 border-transparent focus:border-indigo-600 rounded-2xl outline-none font-bold text-lg" placeholder="e.g. 5" value={newOrderFloor} onChange={(e) => setNewOrderFloor(e.target.value)} />
                          </div>
                        </div>
                        <Button type="submit" className="w-full h-20 bg-indigo-600 rounded-[2rem] text-xl font-black shadow-2xl shadow-indigo-100 uppercase tracking-widest">Confirm & Pay</Button>
                      </form>
                    </div>
                  </div>
                )}

                {/* Arrive Modal */}
                {showArriveForm === run.id && (
                  <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md p-12 text-center">
                      <div className="w-20 h-20 bg-emerald-100 text-emerald-600 rounded-[2rem] flex items-center justify-center text-4xl mb-8 mx-auto shadow-lg shadow-emerald-50">
                        <i className="fas fa-map-pin"></i>
                      </div>
                      <h3 className="text-3xl font-black text-slate-800 tracking-tighter mb-4">You're Back!</h3>
                      <p className="text-slate-400 font-bold uppercase text-[10px] tracking-widest mb-10 leading-relaxed px-6">Broadcast your current drop-off location to the team.</p>
                      <div className="space-y-8">
                        <input autoFocus className="w-full p-6 bg-slate-50 border-2 border-transparent focus:border-emerald-500 rounded-3xl outline-none font-black text-xl text-center" placeholder="e.g. Kitchen Counter, Lobby..." value={arrivalLoc} onChange={(e) => setArrivalLoc(e.target.value)} />
                        <div className="flex gap-4">
                          <Button className="flex-1 bg-slate-100 text-slate-600 rounded-2xl h-16 font-black uppercase tracking-widest" onClick={() => setShowArriveForm(null)}>Cancel</Button>
                          <Button className="flex-1 bg-emerald-600 rounded-2xl h-16 font-black text-white shadow-xl shadow-emerald-100 uppercase tracking-widest" onClick={() => markAsArrived(run.id)}>Broadcast</Button>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </main>
    </div>
  );
};

export default App;

export enum UserRole {
  RUNNER = 'RUNNER',
  ORDERER = 'ORDERER',
  ADMIN = 'ADMIN'
}

export interface Order {
  id: string;
  userName: string;
  itemDescription: string;
  cibusCode: string;
  floor: string;
  timestamp: number;
}

export interface FoodRun {
  id: string;
  runnerName: string;
  destination: string;
  departureTime: number; 
  minutesUntilDeparture: number;
  maxOrders: number;
  orders: Order[];
  status: 'active' | 'arrived' | 'cancelled';
  arrivalLocation?: string;
  arrivalTime?: number;
}

export interface AppEvent {
  id: string;
  type: 'login' | 'create_run' | 'join_run' | 'arrival';
  userEmail: string;
  timestamp: number;
  metadata?: any;
}

/**
 * Configuration for AI image generation, supporting specific ratios and resolutions.
 */
export interface ImageGenerationConfig {
  aspectRatio: '1:1' | '3:4' | '4:3' | '9:16' | '16:9';
  imageSize: '1K' | '2K' | '4K';
}

import React, { useState, useEffect, useMemo } from 'react';
import { FoodRun, Order, AppEvent } from './types';
import { Button } from './components/Button';

const ALLOWED_DOMAIN = 'yourcompany.com'; 
const GOOGLE_CLIENT_ID = 'YOUR_GOOGLE_CLIENT_ID.apps.googleusercontent.com';
// הגדר כאן את האימיילים של המנהלים
const ADMIN_EMAILS = ['admin@yourcompany.com', 'manager@yourcompany.com'];

const App: React.FC = () => {
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [events, setEvents] = useState<AppEvent[]>([]);
  const [user, setUser] = useState<{ name: string; email: string; picture?: string; isGuest?: boolean } | null>(null);
  const [isJoined, setIsJoined] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [view, setView] = useState<'app' | 'admin'>('app');
  const [adminTab, setAdminTab] = useState<'history' | 'analytics'>('history');

  // Modals
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [showJoinForm, setShowJoinForm] = useState<string | null>(null);
  const [showArriveForm, setShowArriveForm] = useState<string | null>(null);

  const [isGuestForm, setIsGuestForm] = useState(false);
  const [guestNameInput, setGuestNameInput] = useState('');

  // Form states
  const [newRunDest, setNewRunDest] = useState('');
  const [newRunTime, setNewRunTime] = useState(25);
  const [newRunMax, setNewRunMax] = useState(5);
  const [newOrderItem, setNewOrderItem] = useState('');
  const [newOrderCibus, setNewOrderCibus] = useState('');
  const [newOrderFloor, setNewOrderFloor] = useState('');
  const [arrivalLoc, setArrivalLoc] = useState('');

  // Persistence Logic
  useEffect(() => {
    const savedHistory = localStorage.getItem('lunchrun_history');
    const savedEvents = localStorage.getItem('lunchrun_events');
    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedEvents) setEvents(JSON.parse(savedEvents));

    const mockRuns: FoodRun[] = [
      {
        id: '1',
        runnerName: 'Sarah',
        destination: 'Pasta Place',
        departureTime: Date.now() + 15 * 60000,
        minutesUntilDeparture: 15,
        maxOrders: 3,
        status: 'active',
        orders: [
          { id: 'o1', userName: 'John', itemDescription: 'Carbonara', cibusCode: '1234', floor: '4th', timestamp: Date.now() }
        ]
      }
    ];
    setRuns(mockRuns);

    if (!isJoined && typeof window !== 'undefined' && (window as any).google) {
      try {
        (window as any).google.accounts.id.initialize({
          client_id: GOOGLE_CLIENT_ID,
          callback: handleGoogleResponse,
          hd: ALLOWED_DOMAIN !== 'yourcompany.com' ? ALLOWED_DOMAIN : undefined,
          auto_select: false,
          context: 'signin'
        });
        const btnContainer = document.getElementById("googleBtn");
        if (btnContainer) {
          (window as any).google.accounts.id.renderButton(btnContainer, { 
            theme: "filled_blue", size: "large", width: "100%", shape: "pill" 
          });
        }
      } catch (e) { console.error(e); }
    }
  }, [isJoined, isGuestForm]);

  const logEvent = (type: AppEvent['type'], metadata?: any) => {
    if (!user) return;
    const newEvent: AppEvent = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      userEmail: user.email,
      timestamp: Date.now(),
      metadata
    };
    const updatedEvents = [newEvent, ...events];
    setEvents(updatedEvents);
    localStorage.setItem('lunchrun_events', JSON.stringify(updatedEvents));
  };

  const decodeJwt = (token: string) => {
    try {
      const base64Url = token.split('.')[1];
      const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
      const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2)).join(''));
      return JSON.parse(jsonPayload);
    } catch (e) { return null; }
  };

  const handleGoogleResponse = (response: any) => {
    const payload = decodeJwt(response.credential);
    if (ALLOWED_DOMAIN !== 'yourcompany.com' && payload.hd !== ALLOWED_DOMAIN) {
      setLoginError(`Only @${ALLOWED_DOMAIN} accounts are permitted.`);
      return;
    }
    const loggedUser = { name: payload.name, email: payload.email, picture: payload.picture, isGuest: false };
    setUser(loggedUser);
    setIsJoined(true);
    logEvent('login');
  };

  const handleGuestLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (guestNameInput.trim()) {
      setUser({ name: guestNameInput.trim(), email: 'guest@internal.local', isGuest: true });
      setIsJoined(true);
      logEvent('login', { method: 'guest' });
    }
  };

  const isAdmin = useMemo(() => user && (ADMIN_EMAILS.includes(user.email) || user.email === 'guest@internal.local'), [user]);

  const createRun = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: user.name,
      destination: newRunDest,
      departureTime: Date.now() + newRunTime * 60000,
      minutesUntilDeparture: newRunTime,
      maxOrders: newRunMax,
      status: 'active',
      orders: []
    };
    setRuns([newRun, ...runs]);
    setShowCreateForm(false);
    setNewRunDest('');
    logEvent('create_run', { destination: newRun.destination });
  };

  const joinRun = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run || !user || run.orders.length >= run.maxOrders) return;
    const newOrder: Order = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      itemDescription: newOrderItem,
      cibusCode: newOrderCibus,
      floor: newOrderFloor,
      timestamp: Date.now()
    };
    setRuns(runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, newOrder] } : r));
    setShowJoinForm(null);
    logEvent('join_run', { runId, destination: run.destination });
  };

  const markAsArrived = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run) return;
    const updatedRun: FoodRun = { ...run, status: 'arrived', arrivalLocation: arrivalLoc, arrivalTime: Date.now() };

    // Move to history
    const updatedHistory = [updatedRun, ...history];
    setHistory(updatedHistory);
    localStorage.setItem('lunchrun_history', JSON.stringify(updatedHistory));

    // Remove from active
    setRuns(runs.filter(r => r.id !== runId));
    setShowArriveForm(null);
    logEvent('arrival', { runId, destination: run.destination });
  };

  // Analytics Calculations
  const analytics = useMemo(() => {
    const totalOrders = history.reduce((sum, run) => sum + run.orders.length, 0);
    const avgOrders = history.length ? (totalOrders / history.length).toFixed(1) : 0;
    const uniqueUsers = new Set(events.map(e => e.userEmail)).size;

    const destinations: Record<string, number> = {};
    history.forEach(run => {
      destinations[run.destination] = (destinations[run.destination] || 0) + 1;
    });
    const topDestinations = Object.entries(destinations).sort((a, b) => b[1] - a[1]).slice(0, 5);

    return { totalOrders, avgOrders, uniqueUsers, topDestinations, totalRuns: history.length };
  }, [history, events]);

  if (!isJoined) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-900 p-4 font-sans">
        <div className="bg-white p-8 rounded-[2.5rem] shadow-2xl w-full max-w-md text-center">
          <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center mx-auto mb-6"><i className="fas fa-bicycle text-white text-3xl"></i></div>
          <h1 className="text-3xl font-black mb-2">LunchRun</h1>
          <p className="text-slate-400 mb-8 font-bold uppercase text-[10px] tracking-widest">Internal Portal</p>

          {!isGuestForm ? (
            <div className="space-y-4">
              <div id="googleBtn"></div>
              <button onClick={() => setIsGuestForm(true)} className="text-xs text-slate-400 font-bold hover:text-indigo-600">Continue as Guest</button>
            </div>
          ) : (
            <form onSubmit={handleGuestLogin} className="space-y-4">
              <input required className="w-full p-4 bg-slate-50 border-2 rounded-2xl outline-none font-bold" placeholder="Your Name" value={guestNameInput} onChange={e => setGuestNameInput(e.target.value)} />
              <Button type="submit" className="w-full h-14 bg-indigo-600 rounded-2xl">Enter</Button>
            </form>
          )}
          {loginError && <p className="mt-4 text-red-500 text-xs font-bold">{loginError}</p>}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC]">
      <header className="bg-white border-b sticky top-0 z-40 px-6 py-4 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-3 cursor-pointer" onClick={() => setView('app')}>
          <div className="bg-indigo-600 p-2 rounded-lg"><i className="fas fa-bicycle text-white"></i></div>
          <span className="text-xl font-black tracking-tighter">LUNCHRUN</span>
        </div>

        <div className="flex items-center gap-4">
          {isAdmin && (
            <button 
              onClick={() => setView(view === 'admin' ? 'app' : 'admin')}
              className={`px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${view === 'admin' ? 'bg-indigo-600 text-white' : 'bg-indigo-50 text-indigo-600 border border-indigo-100'}`}
            >
              <i className={`fas ${view === 'admin' ? 'fa-home' : 'fa-chart-pie'} mr-2`}></i>
              {view === 'admin' ? 'Exit Admin' : 'Admin Panel'}
            </button>
          )}
          <img src={user?.picture || `https://ui-avatars.com/api/?name=${user?.name}`} className="w-10 h-10 rounded-xl border object-cover" alt="user" />
        </div>
      </header>

      {view === 'admin' ? (
        <main className="max-w-6xl mx-auto p-6 space-y-8 animate-in fade-in duration-500">
          <div className="flex flex-col sm:flex-row gap-6 justify-between items-end">
            <div>
              <h2 className="text-3xl font-black text-slate-800">Control Center</h2>
              <p className="text-slate-400 font-bold text-sm uppercase tracking-widest mt-1">System Health & Records</p>
            </div>
            <div className="flex bg-white p-1 rounded-2xl border shadow-sm">
              <button onClick={() => setAdminTab('history')} className={`px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${adminTab === 'history' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'text-slate-400 hover:bg-slate-50'}`}>History</button>
              <button onClick={() => setAdminTab('analytics')} className={`px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${adminTab === 'analytics' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'text-slate-400 hover:bg-slate-50'}`}>Analytics</button>
            </div>
          </div>

          {adminTab === 'analytics' ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              <div className="bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Total Orders</p>
                <p className="text-4xl font-black text-indigo-600">{analytics.totalOrders}</p>
              </div>
              <div className="bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Avg per Run</p>
                <p className="text-4xl font-black text-indigo-600">{analytics.avgOrders}</p>
              </div>
              <div className="bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Unique Users</p>
                <p className="text-4xl font-black text-indigo-600">{analytics.uniqueUsers}</p>
              </div>
              <div className="bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Total Runs</p>
                <p className="text-4xl font-black text-indigo-600">{analytics.totalRuns}</p>
              </div>

              <div className="lg:col-span-2 bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100">
                <h3 className="text-lg font-black mb-6 flex items-center gap-2"><i className="fas fa-medal text-amber-500"></i> Top Destinations</h3>
                <div className="space-y-4">
                  {analytics.topDestinations.map(([dest, count]) => (
                    <div key={dest}>
                      <div className="flex justify-between text-xs font-bold mb-1">
                        <span>{dest}</span>
                        <span className="text-indigo-600">{count} runs</span>
                      </div>
                      <div className="w-full bg-slate-100 h-2 rounded-full overflow-hidden">
                        <div className="bg-indigo-600 h-full" style={{ width: `${(count / analytics.totalRuns) * 100}%` }}></div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <div className="lg:col-span-2 bg-slate-900 text-white p-8 rounded-[2rem] shadow-xl overflow-hidden relative">
                <div className="relative z-10">
                   <h3 className="text-lg font-black mb-2 tracking-tight">System Reliability</h3>
                   <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mb-6">Last 24 Hours</p>
                   <div className="flex items-center gap-4">
                      <div className="text-4xl font-black text-emerald-400">99.9%</div>
                      <div className="text-xs font-bold text-slate-400">All services operational.<br/>No detected latency.</div>
                   </div>
                </div>
                <i className="fas fa-server absolute -bottom-4 -right-4 text-9xl text-white/5 rotate-12"></i>
              </div>
            </div>
          ) : (
            <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden">
              <table className="w-full text-left border-collapse">
                <thead className="bg-slate-50 border-b">
                  <tr>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Date</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Runner</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Destination</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Orders</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {history.length === 0 ? (
                    <tr><td colSpan={5} className="px-8 py-20 text-center text-slate-400 font-bold uppercase tracking-widest">No history recorded yet</td></tr>
                  ) : history.map(run => (
                    <tr key={run.id} className="hover:bg-slate-50/50 transition-colors">
                      <td className="px-8 py-5 text-sm font-bold text-slate-500">{new Date(run.arrivalTime || 0).toLocaleDateString()}</td>
                      <td className="px-8 py-5 font-black text-slate-800 text-sm">{run.runnerName}</td>
                      <td className="px-8 py-5 font-bold text-indigo-600 text-sm">{run.destination}</td>
                      <td className="px-8 py-5">
                         <div className="flex -space-x-2">
                            {run.orders.slice(0, 3).map((o, idx) => (
                              <div key={idx} className="w-8 h-8 rounded-full bg-slate-200 border-2 border-white flex items-center justify-center text-[10px] font-black text-slate-500">{o.userName.charAt(0)}</div>
                            ))}
                            {run.orders.length > 3 && <div className="w-8 h-8 rounded-full bg-indigo-50 border-2 border-white flex items-center justify-center text-[10px] font-black text-indigo-600">+{run.orders.length - 3}</div>}
                         </div>
                      </td>
                      <td className="px-8 py-5">
                        <span className="bg-emerald-50 text-emerald-600 text-[10px] font-black px-3 py-1 rounded-lg uppercase tracking-widest">Completed</span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </main>
      ) : (
        <main className="max-w-4xl mx-auto p-4 sm:p-8 space-y-10 animate-in fade-in duration-500">
          <section className="flex flex-col sm:flex-row gap-6 items-center justify-between bg-white p-10 rounded-[3rem] shadow-sm border border-slate-100">
            <div>
              <h2 className="text-3xl font-black text-slate-800 tracking-tight">Active Runs</h2>
              <p className="text-slate-400 font-bold text-sm uppercase tracking-widest mt-1">Ready to coordinate, {user?.name}?</p>
            </div>
            <Button onClick={() => setShowCreateForm(true)} className="bg-indigo-600 hover:bg-indigo-700 h-16 px-10 rounded-2xl shadow-2xl shadow-indigo-100 text-lg font-black uppercase tracking-wider">
              <i className="fas fa-megaphone mr-2"></i> Start a Run
            </Button>
          </section>

          {/* Active Runs List (Same as before) */}
          <div className="grid gap-8">
            {runs.length === 0 ? (
              <div className="text-center py-20 bg-white rounded-[3rem] border-2 border-dashed">
                <i className="fas fa-cookie-bite text-slate-100 text-6xl mb-4"></i>
                <p className="text-slate-400 font-black uppercase tracking-widest">No active runs right now</p>
              </div>
            ) : runs.map(run => {
              const isFull = run.orders.length >= run.maxOrders;
              const isRunner = user && run.runnerName === user.name;
              return (
                <div key={run.id} className="bg-white rounded-[3rem] border-2 border-white shadow-[0_10px_40px_rgba(0,0,0,0.03)] p-10">
                  <div className="flex justify-between items-start mb-10">
                    <div className="flex gap-6">
                      <div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center text-3xl"><i className="fas fa-utensils"></i></div>
                      <div>
                        <h4 className="text-2xl font-black text-slate-800">{run.destination}</h4>
                        <p className="text-slate-400 font-bold text-xs uppercase tracking-widest">By {run.runnerName}</p>
                      </div>
                    </div>
                    <div className="flex gap-2">
                       <span className="bg-slate-50 px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest border">{run.orders.length}/{run.maxOrders}</span>
                       <span className="bg-orange-50 text-orange-600 px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest border border-orange-100">{run.minutesUntilDeparture}m left</span>
                    </div>
                  </div>

                  <div className="space-y-3 mb-10">
                     {run.orders.map(o => (
                       <div key={o.id} className="flex justify-between p-4 bg-slate-50 rounded-2xl border items-center">
                          <span className="font-black text-sm text-slate-700">{o.userName}: <span className="font-medium opacity-60">"{o.itemDescription}"</span></span>
                          <span className="text-[10px] font-black text-indigo-500 uppercase">Floor {o.floor}</span>
                       </div>
                     ))}
                  </div>

                  <div className="flex gap-4">
                    {isRunner ? (
                      <Button className="flex-1 bg-emerald-600 h-16 rounded-2xl font-black uppercase" onClick={() => setShowArriveForm(run.id)}>Notify Arrival</Button>
                    ) : (
                      <Button disabled={isFull} className="flex-1 bg-indigo-600 h-16 rounded-2xl font-black uppercase" onClick={() => setShowJoinForm(run.id)}>
                        {isFull ? 'Full' : 'Join Run'}
                      </Button>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </main>
      )}

      {/* Forms (Minimal Change) */}
      {showCreateForm && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] p-10 w-full max-w-md shadow-2xl animate-in slide-in-from-bottom-12">
            <h3 className="text-2xl font-black mb-8">New Run</h3>
            <form onSubmit={createRun} className="space-y-6">
              <input required className="w-full p-5 bg-slate-50 border-2 rounded-2xl font-bold" placeholder="Destination" value={newRunDest} onChange={e => setNewRunDest(e.target.value)} />
              <div className="grid grid-cols-2 gap-4">
                <input required type="number" className="p-5 bg-slate-50 border-2 rounded-2xl font-bold" placeholder="Mins" value={newRunTime} onChange={e => setNewRunTime(parseInt(e.target.value))} />
                <input required type="number" className="p-5 bg-slate-50 border-2 rounded-2xl font-bold" placeholder="Max" value={newRunMax} onChange={e => setNewRunMax(parseInt(e.target.value))} />
              </div>
              <Button type="submit" className="w-full h-16 bg-indigo-600 rounded-2xl font-black uppercase">Launch</Button>
              <button onClick={() => setShowCreateForm(false)} className="w-full text-xs font-black text-slate-400 uppercase">Cancel</button>
            </form>
          </div>
        </div>
      )}

      {showJoinForm && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] p-10 w-full max-w-md shadow-2xl animate-in slide-in-from-bottom-12">
            <h3 className="text-2xl font-black mb-8">Join Run</h3>
            <form onSubmit={e => { e.preventDefault(); joinRun(showJoinForm); }} className="space-y-6">
              <input required className="w-full p-5 bg-slate-50 border-2 rounded-2xl font-bold" placeholder="What are you eating?" value={newOrderItem} onChange={e => setNewOrderItem(e.target.value)} />
              <div className="grid grid-cols-2 gap-4">
                <input required className="p-5 bg-slate-50 border-2 rounded-2xl font-bold" placeholder="Cibus ID" value={newOrderCibus} onChange={e => setNewOrderCibus(e.target.value)} />
                <input required className="p-5 bg-slate-50 border-2 rounded-2xl font-bold" placeholder="Floor" value={newOrderFloor} onChange={e => setNewOrderFloor(e.target.value)} />
              </div>
              <Button type="submit" className="w-full h-16 bg-indigo-600 rounded-2xl font-black uppercase">Order</Button>
              <button onClick={() => setShowJoinForm(null)} className="w-full text-xs font-black text-slate-400 uppercase">Cancel</button>
            </form>
          </div>
        </div>
      )}

      {showArriveForm && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] p-12 text-center max-w-md w-full shadow-2xl animate-in zoom-in duration-300">
            <div className="w-20 h-20 bg-emerald-100 text-emerald-600 rounded-[2rem] flex items-center justify-center text-4xl mb-8 mx-auto"><i className="fas fa-map-pin"></i></div>
            <h3 className="text-3xl font-black mb-4 tracking-tighter">You're Back!</h3>
            <p className="text-slate-400 font-bold uppercase text-[10px] tracking-widest mb-10">Where should they pick it up?</p>
            <input autoFocus className="w-full p-6 bg-slate-50 border-2 rounded-3xl font-black text-xl text-center mb-6" placeholder="Kitchen, Desk..." value={arrivalLoc} onChange={e => setArrivalLoc(e.target.value)} />
            <div className="flex gap-4">
               <Button className="flex-1 bg-slate-100 text-slate-600 rounded-2xl h-14 font-black" onClick={() => setShowArriveForm(null)}>Cancel</Button>
               <Button className="flex-1 bg-emerald-600 rounded-2xl h-14 font-black text-white" onClick={() => markAsArrived(showArriveForm)}>Confirm</Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export enum UserRole {
  RUNNER = 'RUNNER',
  ORDERER = 'ORDERER',
  ADMIN = 'ADMIN'
}

export interface Order {
  id: string;
  userName: string;
  userEmail: string;
  itemDescription: string;
  cibusCode: string; // Initially empty, filled after departure
  floor: string;
  timestamp: number;
}

export interface WaitingOrder {
  id: string;
  userName: string;
  userEmail: string;
  destination: string;
  itemDescription: string;
  floor: string;
  timestamp: number;
}

export interface FoodRun {
  id: string;
  runnerName: string;
  runnerEmail: string;
  destination: string;
  departureTime: number; 
  minutesUntilDeparture: number;
  maxOrders: number;
  orders: Order[];
  status: 'active' | 'departed' | 'arrived' | 'cancelled';
  arrivalLocation?: string;
  arrivalTime?: number;
}

export interface AppEvent {
  id: string;
  type: 'login' | 'create_run' | 'join_run' | 'depart' | 'arrival' | 'waitlist_add';
  userEmail: string;
  timestamp: number;
  metadata?: any;
}

export interface ImageGenerationConfig {
  aspectRatio: '1:1' | '3:4' | '4:3' | '9:16' | '16:9';
  imageSize: '1K' | '2K' | '4K';
}

import React, { useState, useEffect, useMemo } from 'react';
import { FoodRun, Order, AppEvent, WaitingOrder } from './types';
import { Button } from './components/Button';

const ALLOWED_DOMAIN = 'yourcompany.com'; 
const GOOGLE_CLIENT_ID = 'YOUR_GOOGLE_CLIENT_ID.apps.googleusercontent.com';
const ADMIN_EMAILS = ['admin@yourcompany.com', 'manager@yourcompany.com'];

const App: React.FC = () => {
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [events, setEvents] = useState<AppEvent[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [user, setUser] = useState<{ name: string; email: string; picture?: string; isGuest?: boolean } | null>(null);
  const [isJoined, setIsJoined] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [view, setView] = useState<'app' | 'admin'>('app');
  const [adminTab, setAdminTab] = useState<'history' | 'analytics'>('history');

  // Modals
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [showJoinForm, setShowJoinForm] = useState<string | null>(null);
  const [showArriveForm, setShowArriveForm] = useState<string | null>(null);
  const [showWaitlistForm, setShowWaitlistForm] = useState(false);
  const [showCibusForm, setShowCibusForm] = useState<{runId: string, orderId: string} | null>(null);

  const [isGuestForm, setIsGuestForm] = useState(false);
  const [guestNameInput, setGuestNameInput] = useState('');

  // Form states
  const [newRunDest, setNewRunDest] = useState('');
  const [newRunTime, setNewRunTime] = useState(25);
  const [newRunMax, setNewRunMax] = useState(5);
  const [newOrderItem, setNewOrderItem] = useState('');
  const [newOrderFloor, setNewOrderFloor] = useState('');
  const [newCibusInput, setNewCibusInput] = useState('');
  const [arrivalLoc, setArrivalLoc] = useState('');

  // Persistence Logic
  useEffect(() => {
    const savedHistory = localStorage.getItem('lunchrun_history');
    const savedEvents = localStorage.getItem('lunchrun_events');
    const savedWaitlist = localStorage.getItem('lunchrun_waitlist');
    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedEvents) setEvents(JSON.parse(savedEvents));
    if (savedWaitlist) setWaitingOrders(JSON.parse(savedWaitlist));

    // Mock Active Run
    setRuns([
      {
        id: '1',
        runnerName: 'Sarah',
        runnerEmail: 'sarah@yourcompany.com',
        destination: 'Pasta Place',
        departureTime: Date.now() + 15 * 60000,
        minutesUntilDeparture: 15,
        maxOrders: 3,
        status: 'active',
        orders: [
          { id: 'o1', userName: 'John', userEmail: 'john@yourcompany.com', itemDescription: 'Carbonara', cibusCode: '', floor: '4th', timestamp: Date.now() }
        ]
      }
    ]);

    if (!isJoined && typeof window !== 'undefined' && (window as any).google) {
      try {
        (window as any).google.accounts.id.initialize({
          client_id: GOOGLE_CLIENT_ID,
          callback: handleGoogleResponse,
          hd: ALLOWED_DOMAIN !== 'yourcompany.com' ? ALLOWED_DOMAIN : undefined,
          auto_select: false,
          context: 'signin'
        });
        const btnContainer = document.getElementById("googleBtn");
        if (btnContainer) {
          (window as any).google.accounts.id.renderButton(btnContainer, { 
            theme: "filled_blue", size: "large", width: "100%", shape: "pill" 
          });
        }
      } catch (e) { console.error(e); }
    }
  }, [isJoined, isGuestForm]);

  const logEvent = (type: AppEvent['type'], metadata?: any) => {
    if (!user) return;
    const newEvent: AppEvent = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      userEmail: user.email,
      timestamp: Date.now(),
      metadata
    };
    const updatedEvents = [newEvent, ...events];
    setEvents(updatedEvents);
    localStorage.setItem('lunchrun_events', JSON.stringify(updatedEvents));
  };

  const decodeJwt = (token: string) => {
    try {
      const base64Url = token.split('.')[1];
      const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
      const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2)).join(''));
      return JSON.parse(jsonPayload);
    } catch (e) { return null; }
  };

  const handleGoogleResponse = (response: any) => {
    const payload = decodeJwt(response.credential);
    if (ALLOWED_DOMAIN !== 'yourcompany.com' && payload.hd !== ALLOWED_DOMAIN) {
      setLoginError(`Only @${ALLOWED_DOMAIN} accounts are permitted.`);
      return;
    }
    setUser({ name: payload.name, email: payload.email, picture: payload.picture, isGuest: false });
    setIsJoined(true);
    logEvent('login');
  };

  const handleGuestLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (guestNameInput.trim()) {
      setUser({ name: guestNameInput.trim(), email: 'guest@internal.local', isGuest: true });
      setIsJoined(true);
      logEvent('login', { method: 'guest' });
    }
  };

  const isAdmin = useMemo(() => user && (ADMIN_EMAILS.includes(user.email) || user.email === 'guest@internal.local'), [user]);

  const createRun = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;

    // Check for matching waitlist orders
    const matchingWaitlist = waitingOrders.filter(wo => wo.destination.toLowerCase().trim() === newRunDest.toLowerCase().trim());
    const initialOrders: Order[] = matchingWaitlist.slice(0, newRunMax).map(wo => ({
      id: Math.random().toString(36).substr(2, 9),
      userName: wo.userName,
      userEmail: wo.userEmail,
      itemDescription: wo.itemDescription,
      floor: wo.floor,
      cibusCode: '',
      timestamp: Date.now()
    }));

    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: user.name,
      runnerEmail: user.email,
      destination: newRunDest,
      departureTime: Date.now() + newRunTime * 60000,
      minutesUntilDeparture: newRunTime,
      maxOrders: newRunMax,
      status: 'active',
      orders: initialOrders
    };

    // Remove added items from waitlist
    const remainingWaitlist = waitingOrders.filter(wo => !initialOrders.some(io => io.userEmail === wo.userEmail && io.itemDescription === wo.itemDescription));
    setWaitingOrders(remainingWaitlist);
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(remainingWaitlist));

    setRuns([newRun, ...runs]);
    setShowCreateForm(false);
    setNewRunDest('');
    logEvent('create_run', { destination: newRun.destination, autoAddedCount: initialOrders.length });
  };

  const addToWaitlist = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newWait: WaitingOrder = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      userEmail: user.email,
      destination: newRunDest,
      itemDescription: newOrderItem,
      floor: newOrderFloor,
      timestamp: Date.now()
    };
    const updated = [...waitingOrders, newWait];
    setWaitingOrders(updated);
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(updated));
    setShowWaitlistForm(false);
    setNewRunDest('');
    setNewOrderItem('');
    logEvent('waitlist_add', { destination: newWait.destination });
  };

  const joinRun = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run || !user || run.orders.length >= run.maxOrders) return;
    const newOrder: Order = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      userEmail: user.email,
      itemDescription: newOrderItem,
      cibusCode: '', // No Cibus code allowed yet
      floor: newOrderFloor,
      timestamp: Date.now()
    };
    setRuns(runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, newOrder] } : r));
    setShowJoinForm(null);
    setNewOrderItem('');
    setNewOrderFloor('');
    logEvent('join_run', { runId, destination: run.destination });
  };

  const departRun = (runId: string) => {
    setRuns(runs.map(r => r.id === runId ? { ...r, status: 'departed' } : r));
    logEvent('depart', { runId });
    // In a real app, this would trigger a push/email to all r.orders
    alert("Run status: DEPARTED. Everyone in this run has been notified to enter their Cibus codes!");
  };

  const submitCibusCode = (e: React.FormEvent) => {
    e.preventDefault();
    if (!showCibusForm) return;
    const { runId, orderId } = showCibusForm;
    setRuns(runs.map(r => r.id === runId ? {
      ...r,
      orders: r.orders.map(o => o.id === orderId ? { ...o, cibusCode: newCibusInput } : o)
    } : r));
    setShowCibusForm(null);
    setNewCibusInput('');
  };

  const markAsArrived = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run) return;
    const updatedRun: FoodRun = { ...run, status: 'arrived', arrivalLocation: arrivalLoc, arrivalTime: Date.now() };
    const updatedHistory = [updatedRun, ...history];
    setHistory(updatedHistory);
    localStorage.setItem('lunchrun_history', JSON.stringify(updatedHistory));
    setRuns(runs.filter(r => r.id !== runId));
    setShowArriveForm(null);
    logEvent('arrival', { runId, destination: run.destination });
  };

  const analytics = useMemo(() => {
    const totalOrders = history.reduce((sum, run) => sum + run.orders.length, 0);
    const avgOrders = history.length ? (totalOrders / history.length).toFixed(1) : 0;
    const uniqueUsers = new Set(events.map(e => e.userEmail)).size;
    const destinations: Record<string, number> = {};
    history.forEach(run => { destinations[run.destination] = (destinations[run.destination] || 0) + 1; });
    const topDestinations = Object.entries(destinations).sort((a, b) => b[1] - a[1]).slice(0, 5);
    return { totalOrders, avgOrders, uniqueUsers, topDestinations, totalRuns: history.length };
  }, [history, events]);

  if (!isJoined) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-900 p-4 font-sans">
        <div className="bg-white p-10 rounded-[2.5rem] shadow-2xl w-full max-w-md text-center">
          <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center mx-auto mb-6"><i className="fas fa-bicycle text-white text-3xl"></i></div>
          <h1 className="text-3xl font-black mb-2">LunchRun</h1>
          <p className="text-slate-400 mb-8 font-bold uppercase text-[10px] tracking-widest">Internal Portal</p>
          {!isGuestForm ? (
            <div className="space-y-4">
              <div id="googleBtn" className="flex justify-center"></div>
              <button onClick={() => setIsGuestForm(true)} className="text-xs text-slate-400 font-bold hover:text-indigo-600 uppercase tracking-widest">Continue as Guest</button>
            </div>
          ) : (
            <form onSubmit={handleGuestLogin} className="space-y-4 text-left">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Full Name</label>
              <input required className="w-full p-4 bg-slate-50 border-2 rounded-2xl outline-none font-bold" placeholder="e.g. David Levi" value={guestNameInput} onChange={e => setGuestNameInput(e.target.value)} />
              <Button type="submit" className="w-full h-14 bg-indigo-600 rounded-2xl shadow-lg">Enter</Button>
              <button type="button" onClick={() => setIsGuestForm(false)} className="w-full text-center text-xs text-slate-400 font-bold">Back</button>
            </form>
          )}
          {loginError && <p className="mt-4 text-red-500 text-xs font-bold bg-red-50 p-3 rounded-xl">{loginError}</p>}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC]">
      <header className="bg-white border-b sticky top-0 z-40 px-6 py-4 flex justify-between items-center shadow-sm backdrop-blur-md bg-white/80">
        <div className="flex items-center gap-3 cursor-pointer" onClick={() => setView('app')}>
          <div className="bg-indigo-600 p-2 rounded-xl shadow-lg shadow-indigo-100"><i className="fas fa-bicycle text-white"></i></div>
          <span className="text-xl font-black tracking-tighter">LUNCHRUN</span>
        </div>
        <div className="flex items-center gap-4">
          {isAdmin && (
            <button onClick={() => setView(view === 'admin' ? 'app' : 'admin')} className={`px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${view === 'admin' ? 'bg-indigo-600 text-white' : 'bg-indigo-50 text-indigo-600'}`}>
              <i className={`fas ${view === 'admin' ? 'fa-home' : 'fa-chart-pie'} mr-2`}></i>
              {view === 'admin' ? 'App' : 'Admin'}
            </button>
          )}
          <img src={user?.picture || `https://ui-avatars.com/api/?name=${user?.name}`} className="w-10 h-10 rounded-xl border-2 border-white shadow-sm object-cover" alt="user" />
        </div>
      </header>

      {view === 'admin' ? (
        <main className="max-w-6xl mx-auto p-6 space-y-8 animate-in fade-in duration-500">
          <div className="flex justify-between items-end">
            <h2 className="text-3xl font-black text-slate-800">Control Center</h2>
            <div className="flex bg-white p-1 rounded-2xl border shadow-sm">
              <button onClick={() => setAdminTab('history')} className={`px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest ${adminTab === 'history' ? 'bg-indigo-600 text-white' : 'text-slate-400'}`}>History</button>
              <button onClick={() => setAdminTab('analytics')} className={`px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest ${adminTab === 'analytics' ? 'bg-indigo-600 text-white' : 'text-slate-400'}`}>Analytics</button>
            </div>
          </div>

          {adminTab === 'analytics' ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              {[
                { label: 'Total Orders', val: analytics.totalOrders },
                { label: 'Avg / Run', val: analytics.avgOrders },
                { label: 'Unique Users', val: analytics.uniqueUsers },
                { label: 'Total Runs', val: analytics.totalRuns }
              ].map(stat => (
                <div key={stat.label} className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">{stat.label}</p>
                  <p className="text-4xl font-black text-indigo-600">{stat.val}</p>
                </div>
              ))}
            </div>
          ) : (
            <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden">
              <table className="w-full text-left">
                <thead className="bg-slate-50 border-b">
                  <tr>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Date</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Runner</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Destination</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Orders</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 font-bold text-sm text-slate-600">
                  {history.map(run => (
                    <tr key={run.id} className="hover:bg-slate-50/50">
                      <td className="px-8 py-5">{new Date(run.arrivalTime || 0).toLocaleDateString()}</td>
                      <td className="px-8 py-5 font-black text-slate-800">{run.runnerName}</td>
                      <td className="px-8 py-5 text-indigo-600">{run.destination}</td>
                      <td className="px-8 py-5">{run.orders.length} items</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </main>
      ) : (
        <main className="max-w-4xl mx-auto p-4 sm:p-8 space-y-12 animate-in fade-in duration-500">
          <section className="bg-white p-10 rounded-[3rem] shadow-sm border border-slate-100 flex flex-col sm:flex-row justify-between items-center gap-6">
            <div>
              <h2 className="text-3xl font-black text-slate-800 tracking-tight">Active Runs</h2>
              <p className="text-slate-400 font-bold text-xs uppercase tracking-widest mt-1">Ready to go, {user?.name}?</p>
            </div>
            <div className="flex gap-4">
              <Button onClick={() => setShowWaitlistForm(true)} variant="secondary" className="h-16 px-8 rounded-2xl border-indigo-100 text-indigo-600 font-black uppercase text-xs tracking-widest">
                <i className="fas fa-list-ul mr-2"></i> Join Waitlist
              </Button>
              <Button onClick={() => setShowCreateForm(true)} className="bg-indigo-600 hover:bg-indigo-700 h-16 px-8 rounded-2xl shadow-xl shadow-indigo-100 text-sm font-black uppercase tracking-wider">
                <i className="fas fa-megaphone mr-2"></i> Start Run
              </Button>
            </div>
          </section>

          {/* Runs Grid */}
          <div className="grid gap-8">
            {runs.map(run => {
              const isRunner = user && run.runnerEmail === user.email;
              const myOrder = run.orders.find(o => o.userEmail === user?.email);

              return (
                <div key={run.id} className={`bg-white rounded-[3rem] border-2 shadow-[0_10px_40px_rgba(0,0,0,0.03)] p-10 transition-all ${run.status === 'departed' ? 'border-orange-400 ring-4 ring-orange-50' : 'border-white'}`}>
                  <div className="flex justify-between items-start mb-8">
                    <div className="flex gap-6">
                      <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-3xl ${run.status === 'departed' ? 'bg-orange-100 text-orange-600' : 'bg-indigo-50 text-indigo-600'}`}>
                        <i className={`fas ${run.status === 'departed' ? 'fa-running' : 'fa-utensils'}`}></i>
                      </div>
                      <div>
                        <h4 className="text-2xl font-black text-slate-800">{run.destination}</h4>
                        <p className="text-slate-400 font-bold text-[10px] uppercase tracking-[0.2em] mt-1">Runner: {run.runnerName}</p>
                      </div>
                    </div>
                    <div className="text-right">
                       <span className={`px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest border ${run.status === 'departed' ? 'bg-orange-600 text-white border-orange-700' : 'bg-slate-50 border-slate-200 text-slate-500'}`}>
                         {run.status === 'departed' ? 'Departed - Enter Codes' : `Leaves in ${run.minutesUntilDeparture}m`}
                       </span>
                    </div>
                  </div>

                  {run.status === 'departed' && (
                    <div className="mb-8 p-6 bg-orange-50 border-2 border-orange-100 rounded-3xl flex items-center gap-5">
                       <div className="w-10 h-10 bg-orange-600 rounded-full flex items-center justify-center text-white shrink-0 shadow-lg shadow-orange-200 animate-pulse">
                         <i className="fas fa-exclamation"></i>
                       </div>
                       <p className="text-xs font-black text-orange-800 uppercase tracking-widest leading-relaxed">
                         The runner is on the way! If you haven't entered your Cibus code yet, do it now. Codes expire in 20 min.
                       </p>
                    </div>
                  )}

                  <div className="space-y-4 mb-8">
                    {run.orders.map(o => {
                      const isMe = user && o.userEmail === user.email;
                      return (
                        <div key={o.id} className={`flex justify-between p-6 rounded-2xl border items-center transition-all ${isMe ? 'bg-indigo-50/50 border-indigo-100' : 'bg-slate-50/50 border-slate-100'}`}>
                           <div className="flex items-center gap-4">
                              <div className="w-8 h-8 rounded-lg bg-white border flex items-center justify-center text-[10px] font-black text-slate-400">{o.userName.charAt(0)}</div>
                              <div>
                                <p className="font-black text-slate-800 text-sm">{o.userName}</p>
                                <p className="text-slate-400 text-xs font-bold italic">"{o.itemDescription}"</p>
                              </div>
                           </div>
                           <div className="flex gap-4 items-center">
                              {o.cibusCode ? (
                                <span className="bg-emerald-100 text-emerald-700 text-[9px] font-black px-3 py-1.5 rounded-lg uppercase border border-emerald-200 flex items-center gap-1">
                                  <i className="fas fa-check-circle"></i> Paid
                                </span>
                              ) : (
                                run.status === 'departed' && isMe ? (
                                  <button onClick={() => setShowCibusForm({runId: run.id, orderId: o.id})} className="bg-indigo-600 text-white text-[9px] font-black px-4 py-1.5 rounded-lg uppercase shadow-lg shadow-indigo-100 hover:scale-105 transition-transform">
                                    Pay with Cibus
                                  </button>
                                ) : (
                                  <span className="text-[9px] font-black text-slate-300 uppercase italic">Pending Departure</span>
                                )
                              )}
                              <span className="bg-slate-100 text-slate-500 text-[10px] font-black px-3 py-1.5 rounded-lg uppercase">Floor {o.floor}</span>
                           </div>
                        </div>
                      );
                    })}
                  </div>

                  <div className="flex gap-4">
                    {isRunner ? (
                      run.status === 'active' ? (
                        <Button className="flex-1 bg-orange-600 hover:bg-orange-700 h-16 rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl shadow-orange-100" onClick={() => departRun(run.id)}>
                          <i className="fas fa-motorcycle mr-2"></i> Departing Now
                        </Button>
                      ) : (
                        <Button className="flex-1 bg-emerald-600 hover:bg-emerald-700 h-16 rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl shadow-emerald-100" onClick={() => setShowArriveForm(run.id)}>
                          <i className="fas fa-check-double mr-2"></i> Mark Arrived
                        </Button>
                      )
                    ) : (
                      !myOrder && run.status === 'active' && run.orders.length < run.maxOrders && (
                        <Button className="flex-1 bg-indigo-600 h-16 rounded-2xl font-black uppercase" onClick={() => setShowJoinForm(run.id)}>
                          Join Run
                        </Button>
                      )
                    )}
                  </div>
                </div>
              );
            })}

            {/* Waitlist View */}
            <div className="bg-slate-900 rounded-[3rem] p-10 text-white overflow-hidden relative">
               <div className="relative z-10">
                 <div className="flex justify-between items-center mb-10">
                    <div>
                      <h3 className="text-2xl font-black tracking-tighter">Waitlist</h3>
                      <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.2em] mt-1">Hoping for a runner...</p>
                    </div>
                    <i className="fas fa-hourglass-half text-white/10 text-6xl"></i>
                 </div>
                 {waitingOrders.length === 0 ? (
                    <div className="text-center py-10 opacity-30">
                       <p className="text-sm font-black uppercase tracking-[0.3em]">Waitlist is empty</p>
                    </div>
                 ) : (
                    <div className="grid gap-4">
                       {waitingOrders.map(wo => (
                         <div key={wo.id} className="bg-white/5 border border-white/10 p-5 rounded-2xl flex justify-between items-center backdrop-blur-sm group hover:bg-white/10 transition-colors">
                            <div>
                               <p className="font-black text-sm">{wo.userName} <span className="text-indigo-400">@ {wo.destination}</span></p>
                               <p className="text-xs text-slate-400 font-medium italic mt-1">"{wo.itemDescription}"</p>
                            </div>
                            <span className="text-[10px] font-black bg-white/10 px-3 py-1 rounded-full uppercase tracking-widest">Floor {wo.floor}</span>
                         </div>
                       ))}
                    </div>
                 )}
               </div>
            </div>
          </div>
        </main>
      )}

      {/* Forms Modals */}
      {showCreateForm && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] p-10 w-full max-w-md shadow-2xl animate-in slide-in-from-bottom-12">
            <h3 className="text-2xl font-black mb-8">Start Food Run</h3>
            <form onSubmit={createRun} className="space-y-6">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Destination</label>
                <input required className="w-full p-5 bg-slate-50 border-2 rounded-2xl font-bold outline-none focus:border-indigo-600 transition-all" placeholder="Pasta, Burgers, etc." value={newRunDest} onChange={e => setNewRunDest(e.target.value)} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Leaves In (min)</label>
                  <input required type="number" className="w-full p-5 bg-slate-50 border-2 rounded-2xl font-bold outline-none" value={newRunTime} onChange={e => setNewRunTime(parseInt(e.target.value))} />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Capacity</label>
                  <input required type="number" className="w-full p-5 bg-slate-50 border-2 rounded-2xl font-bold outline-none" value={newRunMax} onChange={e => setNewRunMax(parseInt(e.target.value))} />
                </div>
              </div>
              <Button type="submit" className="w-full h-18 bg-indigo-600 rounded-[1.5rem] font-black uppercase text-sm tracking-widest shadow-xl shadow-indigo-100">Broadcast Now</Button>
              <button type="button" onClick={() => setShowCreateForm(false)} className="w-full text-xs font-black text-slate-400 uppercase">Cancel</button>
            </form>
          </div>
        </div>
      )}

      {showWaitlistForm && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] p-10 w-full max-w-md shadow-2xl animate-in slide-in-from-bottom-12">
            <h3 className="text-2xl font-black mb-8">Add to Waitlist</h3>
            <form onSubmit={addToWaitlist} className="space-y-6">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Preferred Destination</label>
                <input required className="w-full p-5 bg-slate-50 border-2 rounded-2xl font-bold outline-none focus:border-indigo-600" placeholder="e.g. Pasta Bar" value={newRunDest} onChange={e => setNewRunDest(e.target.value)} />
              </div>
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">What do you want?</label>
                <input required className="w-full p-5 bg-slate-50 border-2 rounded-2xl font-bold outline-none" placeholder="e.g. Greek Salad" value={newOrderItem} onChange={e => setNewOrderItem(e.target.value)} />
              </div>
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Delivery Floor</label>
                <input required className="w-full p-5 bg-slate-50 border-2 rounded-2xl font-bold outline-none" placeholder="e.g. 5" value={newOrderFloor} onChange={e => setNewOrderFloor(e.target.value)} />
              </div>
              <Button type="submit" className="w-full h-18 bg-indigo-600 rounded-[1.5rem] font-black uppercase">Post to Waitlist</Button>
              <button type="button" onClick={() => setShowWaitlistForm(false)} className="w-full text-xs font-black text-slate-400 uppercase">Cancel</button>
            </form>
          </div>
        </div>
      )}

      {showJoinForm && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] p-10 w-full max-w-md shadow-2xl animate-in slide-in-from-bottom-12">
            <h3 className="text-2xl font-black mb-8">Join Food Run</h3>
            <form onSubmit={e => { e.preventDefault(); joinRun(showJoinForm); }} className="space-y-6">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Your Order</label>
                <input required className="w-full p-5 bg-slate-50 border-2 rounded-2xl font-bold outline-none" placeholder="Salad, Burger..." value={newOrderItem} onChange={e => setNewOrderItem(e.target.value)} />
              </div>
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Floor #</label>
                <input required className="w-full p-5 bg-slate-50 border-2 rounded-2xl font-bold outline-none" placeholder="5" value={newOrderFloor} onChange={e => setNewOrderFloor(e.target.value)} />
              </div>
              <Button type="submit" className="w-full h-18 bg-indigo-600 rounded-[1.5rem] font-black uppercase">Join Run</Button>
              <button type="button" onClick={() => setShowJoinForm(null)} className="w-full text-xs font-black text-slate-400 uppercase">Cancel</button>
            </form>
          </div>
        </div>
      )}

      {showCibusForm && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] p-12 text-center max-w-md w-full shadow-2xl animate-in zoom-in duration-300">
            <div className="w-20 h-20 bg-orange-100 text-orange-600 rounded-[2rem] flex items-center justify-center text-4xl mb-8 mx-auto"><i className="fas fa-credit-card"></i></div>
            <h3 className="text-2xl font-black mb-2 tracking-tighter">Enter Cibus Code</h3>
            <p className="text-slate-400 font-bold uppercase text-[10px] tracking-widest mb-8 leading-relaxed">The runner is active. Please provide your Cibus payment ID.</p>
            <form onSubmit={submitCibusCode} className="space-y-6">
              <input required autoFocus className="w-full p-6 bg-slate-50 border-2 border-indigo-100 rounded-3xl font-black text-2xl text-center outline-none focus:border-indigo-600" placeholder="6-digit ID" value={newCibusInput} onChange={e => setNewCibusInput(e.target.value)} />
              <div className="flex gap-4">
                 <Button type="button" className="flex-1 bg-slate-100 text-slate-600 rounded-2xl h-14 font-black" onClick={() => setShowCibusForm(null)}>Close</Button>
                 <Button type="submit" className="flex-1 bg-orange-600 rounded-2xl h-14 font-black text-white shadow-lg shadow-orange-100">Submit Pay</Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showArriveForm && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] p-12 text-center max-w-md w-full shadow-2xl animate-in zoom-in duration-300">
            <div className="w-20 h-20 bg-emerald-100 text-emerald-600 rounded-[2rem] flex items-center justify-center text-4xl mb-8 mx-auto"><i className="fas fa-map-pin"></i></div>
            <h3 className="text-3xl font-black mb-4 tracking-tighter">You're Back!</h3>
            <p className="text-slate-400 font-bold uppercase text-[10px] tracking-widest mb-10">Where should they pick it up?</p>
            <input autoFocus className="w-full p-6 bg-slate-50 border-2 rounded-3xl font-black text-xl text-center mb-6 outline-none" placeholder="Kitchen, Desk..." value={arrivalLoc} onChange={e => setArrivalLoc(e.target.value)} />
            <div className="flex gap-4">
               <Button className="flex-1 bg-slate-100 text-slate-600 rounded-2xl h-14 font-black" onClick={() => setShowArriveForm(null)}>Cancel</Button>
               <Button className="flex-1 bg-emerald-600 rounded-2xl h-14 font-black text-white" onClick={() => markAsArrived(showArriveForm)}>Confirm</Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export enum UserRole {
  RUNNER = 'RUNNER',
  ORDERER = 'ORDERER',
  ADMIN = 'ADMIN'
}

export interface Order {
  id: string;
  userName: string;
  userEmail: string;
  itemDescription: string;
  cibusCode: string;
  floor: string;
  timestamp: number;
}

export interface WaitingOrder {
  id: string;
  userName: string;
  userEmail: string;
  destination: string;
  itemDescription: string;
  floor: string;
  timestamp: number;
}

export interface FoodRun {
  id: string;
  runnerName: string;
  runnerEmail: string;
  destination: string;
  departureTime: number; 
  minutesUntilDeparture: number;
  maxOrders: number;
  orders: Order[];
  status: 'active' | 'departed' | 'arrived' | 'cancelled';
  arrivalLocation?: string;
  arrivalTime?: number;
}

export interface UserNotification {
  id: string;
  type: 'waitlist_promoted' | 'departed' | 'arrived';
  message: string;
  runId: string;
  timestamp: number;
  read: boolean;
}

export interface AppEvent {
  id: string;
  type: 'login' | 'create_run' | 'join_run' | 'depart' | 'arrival' | 'waitlist_add';
  userEmail: string;
  timestamp: number;
  metadata?: any;
}

export interface ImageGenerationConfig {
  aspectRatio: '1:1' | '3:4' | '4:3' | '9:16' | '16:9';
  imageSize: '1K' | '2K' | '4K';
}

import React, { useState, useEffect, useMemo } from 'react';
import { FoodRun, Order, AppEvent, WaitingOrder, UserNotification } from './types';
import { Button } from './components/Button';

const ALLOWED_DOMAIN = 'yourcompany.com'; 
const GOOGLE_CLIENT_ID = 'YOUR_GOOGLE_CLIENT_ID.apps.googleusercontent.com';
const ADMIN_EMAILS = ['admin@yourcompany.com', 'manager@yourcompany.com'];

const App: React.FC = () => {
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [events, setEvents] = useState<AppEvent[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [notifications, setNotifications] = useState<UserNotification[]>([]);
  const [user, setUser] = useState<{ name: string; email: string; picture?: string; isGuest?: boolean } | null>(null);
  const [isJoined, setIsJoined] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [view, setView] = useState<'app' | 'admin'>('app');
  const [adminTab, setAdminTab] = useState<'history' | 'analytics'>('history');

  // Modals
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [showJoinForm, setShowJoinForm] = useState<string | null>(null);
  const [showArriveForm, setShowArriveForm] = useState<string | null>(null);
  const [showWaitlistForm, setShowWaitlistForm] = useState(false);
  const [showCibusForm, setShowCibusForm] = useState<{runId: string, orderId: string} | null>(null);
  const [showNotificationCenter, setShowNotificationCenter] = useState(false);

  const [isGuestForm, setIsGuestForm] = useState(false);
  const [guestNameInput, setGuestNameInput] = useState('');

  // Form states
  const [newRunDest, setNewRunDest] = useState('');
  const [newRunTime, setNewRunTime] = useState(25);
  const [newRunMax, setNewRunMax] = useState(5);
  const [newOrderItem, setNewOrderItem] = useState('');
  const [newOrderFloor, setNewOrderFloor] = useState('');
  const [newCibusInput, setNewCibusInput] = useState('');
  const [arrivalLoc, setArrivalLoc] = useState('');

  // Persistence Logic
  useEffect(() => {
    const savedHistory = localStorage.getItem('lunchrun_history');
    const savedEvents = localStorage.getItem('lunchrun_events');
    const savedWaitlist = localStorage.getItem('lunchrun_waitlist');
    const savedNotifications = localStorage.getItem('lunchrun_notifications');

    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedEvents) setEvents(JSON.parse(savedEvents));
    if (savedWaitlist) setWaitingOrders(JSON.parse(savedWaitlist));
    if (savedNotifications) setNotifications(JSON.parse(savedNotifications));

    // Mock Active Run
    setRuns([
      {
        id: '1',
        runnerName: 'Sarah',
        runnerEmail: 'sarah@yourcompany.com',
        destination: 'Pasta Place',
        departureTime: Date.now() + 15 * 60000,
        minutesUntilDeparture: 15,
        maxOrders: 3,
        status: 'active',
        orders: [
          { id: 'o1', userName: 'John', userEmail: 'john@yourcompany.com', itemDescription: 'Carbonara', cibusCode: '', floor: '4th', timestamp: Date.now() }
        ]
      }
    ]);

    if (!isJoined && typeof window !== 'undefined' && (window as any).google) {
      try {
        (window as any).google.accounts.id.initialize({
          client_id: GOOGLE_CLIENT_ID,
          callback: handleGoogleResponse,
          hd: ALLOWED_DOMAIN !== 'yourcompany.com' ? ALLOWED_DOMAIN : undefined,
          auto_select: false,
          context: 'signin'
        });
        const btnContainer = document.getElementById("googleBtn");
        if (btnContainer) {
          (window as any).google.accounts.id.renderButton(btnContainer, { 
            theme: "filled_blue", size: "large", width: "100%", shape: "pill" 
          });
        }
      } catch (e) { console.error(e); }
    }
  }, [isJoined, isGuestForm]);

  const addNotification = (targetEmail: string, type: UserNotification['type'], message: string, runId: string) => {
    // Only add to state/storage if it's the current user's notification
    // In a multi-user app, this would be a server-side DB write
    const newNotif: UserNotification = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      message,
      runId,
      timestamp: Date.now(),
      read: false
    };

    // We simulate "push" by checking if targetEmail is the current logged in user
    if (targetEmail === user?.email) {
      const updated = [newNotif, ...notifications];
      setNotifications(updated);
      localStorage.setItem('lunchrun_notifications', JSON.stringify(updated));
    }

    // SIMULATED EMAIL LOGGING
    console.log(`[SIMULATED EMAIL] To: ${targetEmail} | Subject: ${type.toUpperCase()} | Body: ${message}`);
  };

  const logEvent = (type: AppEvent['type'], metadata?: any) => {
    if (!user) return;
    const newEvent: AppEvent = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      userEmail: user.email,
      timestamp: Date.now(),
      metadata
    };
    const updatedEvents = [newEvent, ...events];
    setEvents(updatedEvents);
    localStorage.setItem('lunchrun_events', JSON.stringify(updatedEvents));
  };

  const decodeJwt = (token: string) => {
    try {
      const base64Url = token.split('.')[1];
      const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
      const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2)).join(''));
      return JSON.parse(jsonPayload);
    } catch (e) { return null; }
  };

  const handleGoogleResponse = (response: any) => {
    const payload = decodeJwt(response.credential);
    if (ALLOWED_DOMAIN !== 'yourcompany.com' && payload.hd !== ALLOWED_DOMAIN) {
      setLoginError(`Only @${ALLOWED_DOMAIN} accounts are permitted.`);
      return;
    }
    setUser({ name: payload.name, email: payload.email, picture: payload.picture, isGuest: false });
    setIsJoined(true);
    logEvent('login');
  };

  const handleGuestLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (guestNameInput.trim()) {
      setUser({ name: guestNameInput.trim(), email: 'guest@internal.local', isGuest: true });
      setIsJoined(true);
      logEvent('login', { method: 'guest' });
    }
  };

  const isAdmin = useMemo(() => user && (ADMIN_EMAILS.includes(user.email) || user.email === 'guest@internal.local'), [user]);

  const createRun = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;

    // Check for matching waitlist orders
    const matchingWaitlist = waitingOrders.filter(wo => wo.destination.toLowerCase().trim() === newRunDest.toLowerCase().trim());
    const initialOrders: Order[] = matchingWaitlist.slice(0, newRunMax).map(wo => {
        // Notify waitlisted user that they were promoted
        addNotification(wo.userEmail, 'waitlist_promoted', `Great news! Your waitlist request for ${wo.destination} was picked up.`, 'new_run');
        return {
            id: Math.random().toString(36).substr(2, 9),
            userName: wo.userName,
            userEmail: wo.userEmail,
            itemDescription: wo.itemDescription,
            floor: wo.floor,
            cibusCode: '',
            timestamp: Date.now()
        };
    });

    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: user.name,
      runnerEmail: user.email,
      destination: newRunDest,
      departureTime: Date.now() + newRunTime * 60000,
      minutesUntilDeparture: newRunTime,
      maxOrders: newRunMax,
      status: 'active',
      orders: initialOrders
    };

    // Remove added items from waitlist
    const remainingWaitlist = waitingOrders.filter(wo => !initialOrders.some(io => io.userEmail === wo.userEmail && io.itemDescription === wo.itemDescription));
    setWaitingOrders(remainingWaitlist);
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(remainingWaitlist));

    setRuns([newRun, ...runs]);
    setShowCreateForm(false);
    setNewRunDest('');
    logEvent('create_run', { destination: newRun.destination, autoAddedCount: initialOrders.length });
  };

  const addToWaitlist = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newWait: WaitingOrder = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      userEmail: user.email,
      destination: newRunDest,
      itemDescription: newOrderItem,
      floor: newOrderFloor,
      timestamp: Date.now()
    };
    const updated = [...waitingOrders, newWait];
    setWaitingOrders(updated);
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(updated));
    setShowWaitlistForm(false);
    setNewRunDest('');
    setNewOrderItem('');
    logEvent('waitlist_add', { destination: newWait.destination });
  };

  const joinRun = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run || !user || run.orders.length >= run.maxOrders) return;
    const newOrder: Order = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      userEmail: user.email,
      itemDescription: newOrderItem,
      cibusCode: '', 
      floor: newOrderFloor,
      timestamp: Date.now()
    };
    setRuns(runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, newOrder] } : r));
    setShowJoinForm(null);
    setNewOrderItem('');
    setNewOrderFloor('');
    logEvent('join_run', { runId, destination: run.destination });
  };

  const departRun = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run) return;

    setRuns(runs.map(r => r.id === runId ? { ...r, status: 'departed' } : r));

    // NOTIFY PARTICIPANTS
    run.orders.forEach(order => {
        addNotification(
            order.userEmail, 
            'departed', 
            `The runner for ${run.destination} has DEPARTED. Please enter your Cibus code now (active for 20 mins).`, 
            runId
        );
    });

    logEvent('depart', { runId });
  };

  const submitCibusCode = (e: React.FormEvent) => {
    e.preventDefault();
    if (!showCibusForm) return;
    const { runId, orderId } = showCibusForm;
    setRuns(runs.map(r => r.id === runId ? {
      ...r,
      orders: r.orders.map(o => o.id === orderId ? { ...o, cibusCode: newCibusInput } : o)
    } : r));
    setShowCibusForm(null);
    setNewCibusInput('');
  };

  const markAsArrived = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run) return;

    const updatedRun: FoodRun = { ...run, status: 'arrived', arrivalLocation: arrivalLoc, arrivalTime: Date.now() };

    // NOTIFY PARTICIPANTS
    run.orders.forEach(order => {
        addNotification(
            order.userEmail, 
            'arrived', 
            `Your food from ${run.destination} has ARRIVED at ${arrivalLoc || 'the kitchen'}. Come get it!`, 
            runId
        );
    });

    const updatedHistory = [updatedRun, ...history];
    setHistory(updatedHistory);
    localStorage.setItem('lunchrun_history', JSON.stringify(updatedHistory));
    setRuns(runs.filter(r => r.id !== runId));
    setShowArriveForm(null);
    logEvent('arrival', { runId, destination: run.destination });
  };

  const analytics = useMemo(() => {
    const totalOrders = history.reduce((sum, run) => sum + run.orders.length, 0);
    const avgOrders = history.length ? (totalOrders / history.length).toFixed(1) : 0;
    const uniqueUsers = new Set(events.map(e => e.userEmail)).size;
    const destinations: Record<string, number> = {};
    history.forEach(run => { destinations[run.destination] = (destinations[run.destination] || 0) + 1; });
    const topDestinations = Object.entries(destinations).sort((a, b) => b[1] - a[1]).slice(0, 5);
    return { totalOrders, avgOrders, uniqueUsers, topDestinations, totalRuns: history.length };
  }, [history, events]);

  const unreadCount = notifications.filter(n => !n.read).length;

  const markNotifRead = (id: string) => {
      const updated = notifications.map(n => n.id === id ? {...n, read: true} : n);
      setNotifications(updated);
      localStorage.setItem('lunchrun_notifications', JSON.stringify(updated));
  };

  if (!isJoined) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-900 p-4 font-sans">
        <div className="bg-white p-10 rounded-[2.5rem] shadow-2xl w-full max-w-md text-center">
          <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center mx-auto mb-6"><i className="fas fa-bicycle text-white text-3xl"></i></div>
          <h1 className="text-3xl font-black mb-2 tracking-tighter">LunchRun</h1>
          <p className="text-slate-400 mb-8 font-bold uppercase text-[10px] tracking-widest">Internal Logistics Portal</p>
          {!isGuestForm ? (
            <div className="space-y-4">
              <div id="googleBtn" className="flex justify-center"></div>
              <button onClick={() => setIsGuestForm(true)} className="text-xs text-slate-400 font-bold hover:text-indigo-600 uppercase tracking-widest">Continue as Guest</button>
            </div>
          ) : (
            <form onSubmit={handleGuestLogin} className="space-y-4 text-left animate-in slide-in-from-right-8 duration-300">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Full Name</label>
              <input required className="w-full p-4 bg-slate-50 border-2 rounded-2xl outline-none font-bold" placeholder="e.g. David Levi" value={guestNameInput} onChange={e => setGuestNameInput(e.target.value)} />
              <Button type="submit" className="w-full h-14 bg-indigo-600 rounded-2xl shadow-lg">Enter</Button>
              <button type="button" onClick={() => setIsGuestForm(false)} className="w-full text-center text-xs text-slate-400 font-bold">Back</button>
            </form>
          )}
          {loginError && <p className="mt-4 text-red-500 text-xs font-bold bg-red-50 p-3 rounded-xl">{loginError}</p>}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC]">
      <header className="bg-white border-b sticky top-0 z-40 px-6 py-4 flex justify-between items-center shadow-sm backdrop-blur-md bg-white/80">
        <div className="flex items-center gap-3 cursor-pointer" onClick={() => setView('app')}>
          <div className="bg-indigo-600 p-2 rounded-xl shadow-lg shadow-indigo-100"><i className="fas fa-bicycle text-white"></i></div>
          <span className="text-xl font-black tracking-tighter">LUNCHRUN</span>
        </div>
        <div className="flex items-center gap-4">
          <div className="relative">
              <button onClick={() => setShowNotificationCenter(!showNotificationCenter)} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-colors ${unreadCount > 0 ? 'bg-indigo-50 text-indigo-600' : 'bg-slate-50 text-slate-400'}`}>
                <i className="fas fa-bell"></i>
                {unreadCount > 0 && <span className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 text-white rounded-full flex items-center justify-center text-[10px] font-black border-2 border-white animate-bounce">{unreadCount}</span>}
              </button>

              {showNotificationCenter && (
                  <div className="absolute top-full right-0 mt-3 w-80 bg-white border border-slate-100 shadow-2xl rounded-2xl overflow-hidden animate-in slide-in-from-top-4 z-50">
                      <div className="p-4 border-b bg-slate-50/50 flex justify-between items-center">
                          <h4 className="text-xs font-black uppercase tracking-widest text-slate-500">Updates</h4>
                          {unreadCount > 0 && <span className="text-[10px] font-bold text-indigo-600">{unreadCount} New</span>}
                      </div>
                      <div className="max-h-96 overflow-y-auto">
                          {notifications.length === 0 ? (
                              <div className="p-8 text-center text-slate-300 text-xs font-bold">No updates yet.</div>
                          ) : (
                              notifications.map(n => (
                                  <div key={n.id} onClick={() => markNotifRead(n.id)} className={`p-4 border-b last:border-0 hover:bg-slate-50 transition-colors cursor-pointer flex gap-3 ${!n.read ? 'bg-indigo-50/30' : ''}`}>
                                      <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${n.type === 'waitlist_promoted' ? 'bg-emerald-100 text-emerald-600' : n.type === 'departed' ? 'bg-orange-100 text-orange-600' : 'bg-indigo-100 text-indigo-600'}`}>
                                          <i className={`fas ${n.type === 'waitlist_promoted' ? 'fa-check' : n.type === 'departed' ? 'fa-motorcycle' : 'fa-map-pin'} text-xs`}></i>
                                      </div>
                                      <div className="text-xs">
                                          <p className={`leading-snug ${!n.read ? 'font-bold text-slate-800' : 'text-slate-500'}`}>{n.message}</p>
                                          <p className="text-[10px] text-slate-300 mt-1 uppercase font-black">{new Date(n.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                                      </div>
                                  </div>
                              ))
                          )}
                      </div>
                  </div>
              )}
          </div>

          {isAdmin && (
            <button onClick={() => setView(view === 'admin' ? 'app' : 'admin')} className={`px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${view === 'admin' ? 'bg-indigo-600 text-white' : 'bg-indigo-50 text-indigo-600'}`}>
              <i className={`fas ${view === 'admin' ? 'fa-home' : 'fa-chart-pie'} mr-2`}></i>
              {view === 'admin' ? 'App' : 'Admin Panel'}
            </button>
          )}
          <div className="flex items-center gap-3">
              <div className="hidden sm:block text-right">
                <p className="text-[10px] font-black uppercase tracking-tighter text-slate-400">Current Portal User</p>
                <p className="text-xs font-black text-slate-800">{user?.name}</p>
              </div>
              <img src={user?.picture || `https://ui-avatars.com/api/?name=${user?.name}`} className="w-10 h-10 rounded-xl border-2 border-white shadow-sm object-cover" alt="user" />
          </div>
        </div>
      </header>

      {view === 'admin' ? (
        <main className="max-w-6xl mx-auto p-6 space-y-8 animate-in fade-in duration-500">
          <div className="flex flex-col sm:flex-row gap-6 justify-between items-end">
            <div>
              <h2 className="text-3xl font-black text-slate-800 tracking-tight">System Controls</h2>
              <p className="text-slate-400 font-bold text-sm uppercase tracking-widest mt-1">Analytics & Historical Data</p>
            </div>
            <div className="flex bg-white p-1 rounded-2xl border shadow-sm">
              <button onClick={() => setAdminTab('history')} className={`px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${adminTab === 'history' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:bg-slate-50'}`}>History</button>
              <button onClick={() => setAdminTab('analytics')} className={`px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${adminTab === 'analytics' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:bg-slate-50'}`}>Analytics</button>
            </div>
          </div>

          {adminTab === 'analytics' ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              {[
                { label: 'Total Orders', val: analytics.totalOrders, icon: 'fa-box' },
                { label: 'Avg / Run', val: analytics.avgOrders, icon: 'fa-calculator' },
                { label: 'Unique Users', val: analytics.uniqueUsers, icon: 'fa-users' },
                { label: 'Completed Runs', val: analytics.totalRuns, icon: 'fa-check-double' }
              ].map(stat => (
                <div key={stat.label} className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100 flex items-center justify-between">
                  <div>
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">{stat.label}</p>
                    <p className="text-4xl font-black text-indigo-600">{stat.val}</p>
                  </div>
                  <div className="w-12 h-12 bg-indigo-50 text-indigo-400 rounded-full flex items-center justify-center text-xl">
                    <i className={`fas ${stat.icon}`}></i>
                  </div>
                </div>
              ))}
              <div className="lg:col-span-2 bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100">
                <h3 className="text-sm font-black uppercase tracking-widest mb-8 text-slate-400">Popular Destinations</h3>
                <div className="space-y-6">
                  {analytics.topDestinations.map(([dest, count]) => (
                    <div key={dest}>
                      <div className="flex justify-between text-xs font-black mb-2 uppercase tracking-tight">
                        <span>{dest}</span>
                        <span className="text-indigo-600">{count} Runs</span>
                      </div>
                      <div className="w-full bg-slate-50 h-3 rounded-full overflow-hidden border">
                        <div className="bg-indigo-600 h-full rounded-full transition-all duration-1000" style={{ width: `${(count / analytics.totalRuns) * 100}%` }}></div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          ) : (
            <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden">
              <table className="w-full text-left">
                <thead className="bg-slate-50 border-b">
                  <tr>
                    <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Date / Time</th>
                    <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Runner</th>
                    <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Destination</th>
                    <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Orders</th>
                    <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Action</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 font-bold text-sm text-slate-600">
                  {history.map(run => (
                    <tr key={run.id} className="hover:bg-slate-50/50 transition-colors">
                      <td className="px-8 py-6 text-xs text-slate-400">{new Date(run.arrivalTime || 0).toLocaleString()}</td>
                      <td className="px-8 py-6 font-black text-slate-800">{run.runnerName}</td>
                      <td className="px-8 py-6 text-indigo-600">{run.destination}</td>
                      <td className="px-8 py-6">
                         <div className="flex items-center gap-2">
                            <span className="bg-indigo-50 text-indigo-600 text-[10px] px-2 py-0.5 rounded font-black">{run.orders.length}</span>
                         </div>
                      </td>
                      <td className="px-8 py-6 text-right font-black uppercase text-[10px] text-emerald-500">Completed</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </main>
      ) : (
        <main className="max-w-4xl mx-auto p-4 sm:p-8 space-y-12 animate-in fade-in duration-500">
          <section className="bg-white p-10 rounded-[3rem] shadow-sm border border-slate-100 flex flex-col sm:flex-row justify-between items-center gap-6">
            <div>
              <h2 className="text-3xl font-black text-slate-800 tracking-tight">Current Runs</h2>
              <p className="text-slate-400 font-bold text-xs uppercase tracking-widest mt-1">Hello, {user?.name.split(' ')[0]}</p>
            </div>
            <div className="flex gap-4">
              <Button onClick={() => setShowWaitlistForm(true)} variant="secondary" className="h-16 px-8 rounded-2xl border-indigo-100 text-indigo-600 font-black uppercase text-xs tracking-widest hover:shadow-lg transition-all">
                <i className="fas fa-list-ul mr-2"></i> Waitlist Me
              </Button>
              <Button onClick={() => setShowCreateForm(true)} className="bg-indigo-600 hover:bg-indigo-700 h-16 px-8 rounded-2xl shadow-xl shadow-indigo-100 text-sm font-black uppercase tracking-wider active:scale-95 transition-all">
                <i className="fas fa-megaphone mr-2"></i> Start Run
              </Button>
            </div>
          </section>

          {/* Runs Grid */}
          <div className="grid gap-8">
            {runs.length === 0 && (
                <div className="text-center py-20 bg-white rounded-[3rem] border-2 border-dashed border-slate-100 flex flex-col items-center">
                    <i className="fas fa-search text-slate-100 text-6xl mb-6"></i>
                    <p className="text-slate-400 font-black uppercase tracking-[0.2em] mb-4">No active runs nearby</p>
                    <p className="text-xs text-slate-300 max-w-xs leading-relaxed font-bold">Why not start one yourself or add your request to the waitlist below?</p>
                </div>
            )}

            {runs.map(run => {
              const isRunner = user && run.runnerEmail === user.email;
              const myOrder = run.orders.find(o => o.userEmail === user?.email);

              return (
                <div key={run.id} className={`bg-white rounded-[3rem] border-2 shadow-[0_10px_40px_rgba(0,0,0,0.03)] p-10 transition-all duration-500 group relative overflow-hidden ${run.status === 'departed' ? 'border-orange-400 ring-4 ring-orange-50' : 'border-white hover:border-indigo-100'}`}>
                  {run.status === 'departed' && <div className="absolute top-0 right-0 bg-orange-600 text-white text-[9px] font-black uppercase px-6 py-1.5 rounded-bl-2xl tracking-[0.2em] shadow-lg">In Transit</div>}

                  <div className="flex justify-between items-start mb-8 relative z-10">
                    <div className="flex gap-6">
                      <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-3xl shadow-sm transition-all ${run.status === 'departed' ? 'bg-orange-100 text-orange-600 rotate-3' : 'bg-indigo-50 text-indigo-600 group-hover:-rotate-3'}`}>
                        <i className={`fas ${run.status === 'departed' ? 'fa-running' : 'fa-utensils'}`}></i>
                      </div>
                      <div>
                        <h4 className="text-2xl font-black text-slate-800 tracking-tight">{run.destination}</h4>
                        <p className="text-slate-400 font-bold text-[10px] uppercase tracking-[0.2em] mt-1 flex items-center gap-2">
                            <i className="fas fa-user-circle text-indigo-400"></i> Runner: {run.runnerName}
                        </p>
                      </div>
                    </div>
                    <div className="text-right">
                       <span className={`px-5 py-2.5 rounded-full text-[10px] font-black uppercase tracking-widest border transition-all ${run.status === 'departed' ? 'bg-orange-600 text-white border-orange-700 shadow-lg shadow-orange-100' : 'bg-slate-50 border-slate-200 text-slate-500'}`}>
                         {run.status === 'departed' ? 'TIME TO PAY' : `Leaves in ${run.minutesUntilDeparture}m`}
                       </span>
                    </div>
                  </div>

                  {run.status === 'departed' && (
                    <div className="mb-8 p-6 bg-orange-50/50 border-2 border-orange-100 rounded-3xl flex items-center gap-5 animate-in slide-in-from-top-4">
                       <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-orange-600 shrink-0 shadow-sm border border-orange-100">
                         <i className="fas fa-clock animate-pulse"></i>
                       </div>
                       <div>
                         <p className="text-[11px] font-black text-orange-800 uppercase tracking-widest">Cibus Window Active</p>
                         <p className="text-xs text-orange-700/80 font-bold leading-relaxed mt-0.5">Payment IDs entered now are valid for the next 20 minutes. Don't let your runner wait!</p>
                       </div>
                    </div>
                  )}

                  <div className="space-y-4 mb-8">
                    <p className="text-[9px] font-black uppercase tracking-[0.3em] text-slate-300 ml-2">Manifest</p>
                    {run.orders.map(o => {
                      const isMe = user && o.userEmail === user.email;
                      return (
                        <div key={o.id} className={`flex justify-between p-6 rounded-3xl border items-center transition-all ${isMe ? 'bg-indigo-50/50 border-indigo-200 shadow-sm' : 'bg-slate-50/20 border-slate-100 hover:border-slate-200'}`}>
                           <div className="flex items-center gap-4">
