                <input required className="w-full p-5 bg-slate-50 border-2 rounded-2xl font-bold outline-none focus:border-indigo-600" placeholder="5" value={newOrderFloor} onChange={e => setNewOrderFloor(e.target.value)} />
              </div>
              <div className="pt-6">
                  <Button type="submit" className="w-full h-20 bg-indigo-600 rounded-[2rem] font-black uppercase tracking-widest">Sign Manifest</Button>
                  <button type="button" onClick={() => setShowJoinForm(null)} className="w-full mt-6 text-[10px] font-black text-slate-300 uppercase tracking-widest">Nevermind</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showCibusForm && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-xl z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[3.5rem] p-12 text-center max-w-md w-full shadow-2xl animate-in zoom-in duration-300">
            <div className="w-24 h-24 bg-indigo-50 text-indigo-600 rounded-[2.5rem] flex items-center justify-center text-4xl mb-8 mx-auto shadow-inner border border-indigo-100"><i className="fas fa-credit-card"></i></div>
            <h3 className="text-3xl font-black mb-2 tracking-tighter">Submit Cibus ID</h3>
            <p className="text-slate-400 font-bold uppercase text-[10px] tracking-widest mb-10 leading-relaxed px-4">Runner is in transit. Pay now to ensure your order is processed. Expiring in 20m.</p>
            <form onSubmit={submitCibusCode} className="space-y-8">
              <input required autoFocus className="w-full p-8 bg-slate-50 border-2 border-indigo-100 rounded-[2.5rem] font-black text-3xl text-center outline-none focus:border-indigo-600 shadow-inner" placeholder="6-digit ID" value={newCibusInput} onChange={e => setNewCibusInput(e.target.value)} />
              <div className="flex gap-4">
                 <Button type="button" className="flex-1 bg-slate-100 text-slate-500 rounded-2xl h-16 font-black uppercase text-[10px] tracking-widest" onClick={() => setShowCibusForm(null)}>Close</Button>
                 <Button type="submit" className="flex-[2] bg-indigo-600 rounded-2xl h-16 font-black text-white shadow-xl shadow-indigo-100 uppercase text-[10px] tracking-[0.2em]">Authorize</Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showArriveForm && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-xl z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[3.5rem] p-12 text-center max-w-md w-full shadow-2xl animate-in zoom-in duration-300">
            <div className="w-24 h-24 bg-emerald-50 text-emerald-600 rounded-[2.5rem] flex items-center justify-center text-4xl mb-8 mx-auto shadow-inner border border-emerald-100"><i className="fas fa-map-pin"></i></div>
            <h3 className="text-3xl font-black mb-4 tracking-tighter">Final Step: Dropoff</h3>
            <p className="text-slate-400 font-bold uppercase text-[10px] tracking-widest mb-10 px-6 leading-relaxed">Broadcast the exact location where colleagues can pick up their orders.</p>
            <input autoFocus className="w-full p-8 bg-slate-50 border-2 border-emerald-100 rounded-[2.5rem] font-black text-xl text-center mb-8 outline-none focus:border-emerald-600 shadow-inner" placeholder="e.g. Floor 3 Kitchen Bar" value={arrivalLoc} onChange={e => setArrivalLoc(e.target.value)} />
            <div className="flex gap-4">
               <Button className="flex-1 bg-slate-100 text-slate-500 rounded-2xl h-16 font-black uppercase text-[10px] tracking-widest" onClick={() => setShowArriveForm(null)}>Wait</Button>
               <Button className="flex-[2] bg-emerald-600 rounded-2xl h-16 font-black text-white shadow-2xl shadow-emerald-100 uppercase text-[10px] tracking-[0.2em]" onClick={() => markAsArrived(showArriveForm)}>Broadcast Arrival</Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export enum UserRole {
  RUNNER = 'RUNNER',
  ORDERER = 'ORDERER',
  ADMIN = 'ADMIN'
}

export interface Order {
  id: string;
  userName: string;
  userEmail: string;
  itemDescription: string;
  cibusCode: string;
  floor: string;
  timestamp: number;
}

export interface WaitingOrder {
  id: string;
  userName: string;
  userEmail: string;
  destination: string;
  itemDescription: string;
  floor: string;
  timestamp: number;
}

export interface FoodRun {
  id: string;
  runnerName: string;
  runnerEmail: string;
  destination: string;
  departureTime: number; 
  minutesUntilDeparture: number;
  maxOrders: number;
  orders: Order[];
  status: 'active' | 'departed' | 'arrived' | 'cancelled';
  arrivalLocation?: string;
  arrivalTime?: number;
}

export interface UserNotification {
  id: string;
  type: 'waitlist_promoted' | 'departed' | 'arrived';
  message: string;
  emailBody?: string; // HTML simulation of the email content
  runId: string;
  timestamp: number;
  read: boolean;
}

export interface AppEvent {
  id: string;
  type: 'login' | 'create_run' | 'join_run' | 'depart' | 'arrival' | 'waitlist_add';
  userEmail: string;
  timestamp: number;
  metadata?: any;
}

export interface ImageGenerationConfig {
  aspectRatio: '1:1' | '3:4' | '4:3' | '9:16' | '16:9';
  imageSize: '1K' | '2K' | '4K';
}

import React, { useState, useEffect, useMemo } from 'react';
import { FoodRun, Order, AppEvent, WaitingOrder, UserNotification } from './types';
import { Button } from './components/Button';

const ALLOWED_DOMAIN = 'yourcompany.com'; 
const GOOGLE_CLIENT_ID = 'YOUR_GOOGLE_CLIENT_ID.apps.googleusercontent.com';
const ADMIN_EMAILS = ['admin@yourcompany.com', 'manager@yourcompany.com'];

// --- Email Templates ---
const getEmailTemplate = (type: UserNotification['type'], data: any) => {
  const styles = {
    container: "font-family: sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; border: 1px solid #e2e8f0; border-radius: 12px;",
    header: "background-color: #4f46e5; color: white; padding: 20px; border-radius: 8px 8px 0 0; text-align: center;",
    body: "padding: 30px; line-height: 1.6; color: #1e293b;",
    footer: "padding: 20px; text-align: center; color: #94a3b8; font-size: 12px;",
    button: "display: inline-block; padding: 12px 24px; background-color: #4f46e5; color: white; text-decoration: none; border-radius: 6px; font-weight: bold; margin-top: 20px;"
  };

  const templates = {
    waitlist_promoted: `
      <div style="${styles.container}">
        <div style="${styles.header}"><h2>🍕 LunchRun: You're In!</h2></div>
        <div style="${styles.body}">
          <p>Hi ${data.userName},</p>
          <p>Great news! Your waitlist request for <strong>${data.destination}</strong> has been picked up by <strong>${data.runnerName}</strong>.</p>
          <p>Your order for <em>"${data.itemDescription}"</em> is now on the manifest. We'll notify you when the runner departs.</p>
          <a href="#" style="${styles.button}">View Order Status</a>
        </div>
        <div style="${styles.footer}">© LunchRun Internal Portal • 2025</div>
      </div>
    `,
    departed: `
      <div style="${styles.container}">
        <div style="${styles.header}; background-color: #ea580c;"><h2>🏃 Runner Departed!</h2></div>
        <div style="${styles.body}">
          <p>Hi ${data.userName},</p>
          <p>The runner for <strong>${data.destination}</strong> has officially departed! <strong>Action required:</strong></p>
          <p>Please enter your <strong>Cibus Payment Code</strong> in the app now. Note: These codes are only valid for 20 minutes.</p>
          <a href="#" style="${styles.button}; background-color: #ea580c;">Enter Cibus Code</a>
        </div>
        <div style="${styles.footer}">© LunchRun Internal Portal • 2025</div>
      </div>
    `,
    arrived: `
      <div style="${styles.container}">
        <div style="${styles.header}; background-color: #059669;"><h2>🍱 Food is Here!</h2></div>
        <div style="${styles.body}">
          <p>Hi ${data.userName},</p>
          <p>Your food from <strong>${data.destination}</strong> has arrived!</p>
          <p><strong>Pick up location:</strong> <span style="font-weight: bold; color: #059669;">${data.location}</span></p>
          <p>Please come and collect it while it's fresh.</p>
          <a href="#" style="${styles.button}; background-color: #059669;">I'm On My Way</a>
        </div>
        <div style="${styles.footer}">© LunchRun Internal Portal • 2025</div>
      </div>
    `
  };

  return templates[type];
};

const App: React.FC = () => {
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [events, setEvents] = useState<AppEvent[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [notifications, setNotifications] = useState<UserNotification[]>([]);
  const [activeToast, setActiveToast] = useState<{message: string, type: string} | null>(null);

  const [user, setUser] = useState<{ name: string; email: string; picture?: string; isGuest?: boolean } | null>(null);
  const [isJoined, setIsJoined] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [view, setView] = useState<'app' | 'admin'>('app');
  const [adminTab, setAdminTab] = useState<'history' | 'analytics'>('history');

  // Modals
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [showJoinForm, setShowJoinForm] = useState<string | null>(null);
  const [showArriveForm, setShowArriveForm] = useState<string | null>(null);
  const [showWaitlistForm, setShowWaitlistForm] = useState(false);
  const [showCibusForm, setShowCibusForm] = useState<{runId: string, orderId: string} | null>(null);
  const [showNotificationCenter, setShowNotificationCenter] = useState(false);

  const [isGuestForm, setIsGuestForm] = useState(false);
  const [guestNameInput, setGuestNameInput] = useState('');

  // Form states
  const [newRunDest, setNewRunDest] = useState('');
  const [newRunTime, setNewRunTime] = useState(25);
  const [newRunMax, setNewRunMax] = useState(5);
  const [newOrderItem, setNewOrderItem] = useState('');
  const [newOrderFloor, setNewOrderFloor] = useState('');
  const [newCibusInput, setNewCibusInput] = useState('');
  const [arrivalLoc, setArrivalLoc] = useState('');

  // Persistence Logic
  useEffect(() => {
    const savedHistory = localStorage.getItem('lunchrun_history');
    const savedEvents = localStorage.getItem('lunchrun_events');
    const savedWaitlist = localStorage.getItem('lunchrun_waitlist');
    const savedNotifications = localStorage.getItem('lunchrun_notifications');

    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedEvents) setEvents(JSON.parse(savedEvents));
    if (savedWaitlist) setWaitingOrders(JSON.parse(savedWaitlist));
    if (savedNotifications) setNotifications(JSON.parse(savedNotifications));

    // Initial Mock
    setRuns([{
      id: '1',
      runnerName: 'Sarah',
      runnerEmail: 'sarah@yourcompany.com',
      destination: 'Pasta Place',
      departureTime: Date.now() + 15 * 60000,
      minutesUntilDeparture: 15,
      maxOrders: 3,
      status: 'active',
      orders: [{ id: 'o1', userName: 'John', userEmail: 'john@yourcompany.com', itemDescription: 'Carbonara', cibusCode: '', floor: '4th', timestamp: Date.now() }]
    }]);

    if (!isJoined && typeof window !== 'undefined' && (window as any).google) {
      try {
        (window as any).google.accounts.id.initialize({
          client_id: GOOGLE_CLIENT_ID,
          callback: handleGoogleResponse,
          hd: ALLOWED_DOMAIN !== 'yourcompany.com' ? ALLOWED_DOMAIN : undefined,
          auto_select: false,
          context: 'signin'
        });
        const btnContainer = document.getElementById("googleBtn");
        if (btnContainer) {
          (window as any).google.accounts.id.renderButton(btnContainer, { theme: "filled_blue", size: "large", width: "100%", shape: "pill" });
        }
      } catch (e) { console.error(e); }
    }
  }, [isJoined, isGuestForm]);

  const showToast = (message: string, type: string) => {
      setActiveToast({ message, type });
      setTimeout(() => setActiveToast(null), 5000);
  };

  const addNotification = (targetEmail: string, type: UserNotification['type'], message: string, runId: string, emailData: any) => {
    const emailBody = getEmailTemplate(type, emailData);
    const newNotif: UserNotification = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      message,
      emailBody,
      runId,
      timestamp: Date.now(),
      read: false
    };

    if (targetEmail === user?.email) {
      const updated = [newNotif, ...notifications];
      setNotifications(updated);
      localStorage.setItem('lunchrun_notifications', JSON.stringify(updated));
      showToast(message, type);
    }

    // SIMULATED EMAIL LOGGING IN CONSOLE
    console.group(`📧 Simulation: Email Sent to ${targetEmail}`);
    console.log(`Subject: [LunchRun] ${message}`);
    console.log(`Body (HTML Rendered):`);
    console.log(emailBody);
    console.groupEnd();
  };

  const logEvent = (type: AppEvent['type'], metadata?: any) => {
    if (!user) return;
    const newEvent: AppEvent = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      userEmail: user.email,
      timestamp: Date.now(),
      metadata
    };
    const updatedEvents = [newEvent, ...events];
    setEvents(updatedEvents);
    localStorage.setItem('lunchrun_events', JSON.stringify(updatedEvents));
  };

  const decodeJwt = (token: string) => {
    try {
      const base64Url = token.split('.')[1];
      const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
      const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2)).join(''));
      return JSON.parse(jsonPayload);
    } catch (e) { return null; }
  };

  const handleGoogleResponse = (response: any) => {
    const payload = decodeJwt(response.credential);
    if (ALLOWED_DOMAIN !== 'yourcompany.com' && payload.hd !== ALLOWED_DOMAIN) {
      setLoginError(`Only @${ALLOWED_DOMAIN} accounts are permitted.`);
      return;
    }
    setUser({ name: payload.name, email: payload.email, picture: payload.picture, isGuest: false });
    setIsJoined(true);
    logEvent('login');
  };

  const handleGuestLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (guestNameInput.trim()) {
      setUser({ name: guestNameInput.trim(), email: 'guest@internal.local', isGuest: true });
      setIsJoined(true);
      logEvent('login', { method: 'guest' });
    }
  };

  const isAdmin = useMemo(() => user && (ADMIN_EMAILS.includes(user.email) || user.email === 'guest@internal.local'), [user]);

  const createRun = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;

    const matchingWaitlist = waitingOrders.filter(wo => wo.destination.toLowerCase().trim() === newRunDest.toLowerCase().trim());
    const initialOrders: Order[] = matchingWaitlist.slice(0, newRunMax).map(wo => {
        addNotification(wo.userEmail, 'waitlist_promoted', `You've been added to a run to ${wo.destination}!`, 'new_run', {
            userName: wo.userName,
            destination: wo.destination,
            runnerName: user.name,
            itemDescription: wo.itemDescription
        });
        return {
            id: Math.random().toString(36).substr(2, 9),
            userName: wo.userName,
            userEmail: wo.userEmail,
            itemDescription: wo.itemDescription,
            floor: wo.floor,
            cibusCode: '',
            timestamp: Date.now()
        };
    });

    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: user.name,
      runnerEmail: user.email,
      destination: newRunDest,
      departureTime: Date.now() + newRunTime * 60000,
      minutesUntilDeparture: newRunTime,
      maxOrders: newRunMax,
      status: 'active',
      orders: initialOrders
    };

    const remainingWaitlist = waitingOrders.filter(wo => !initialOrders.some(io => io.userEmail === wo.userEmail && io.itemDescription === wo.itemDescription));
    setWaitingOrders(remainingWaitlist);
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(remainingWaitlist));

    setRuns([newRun, ...runs]);
    setShowCreateForm(false);
    setNewRunDest('');
    logEvent('create_run', { destination: newRun.destination });
  };

  const addToWaitlist = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newWait: WaitingOrder = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      userEmail: user.email,
      destination: newRunDest,
      itemDescription: newOrderItem,
      floor: newOrderFloor,
      timestamp: Date.now()
    };
    const updated = [...waitingOrders, newWait];
    setWaitingOrders(updated);
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(updated));
    setShowWaitlistForm(false);
    setNewRunDest('');
    setNewOrderItem('');
    logEvent('waitlist_add', { destination: newWait.destination });
  };

  const departRun = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run) return;
    setRuns(runs.map(r => r.id === runId ? { ...r, status: 'departed' } : r));

    run.orders.forEach(order => {
        addNotification(order.userEmail, 'departed', `Runner leaving for ${run.destination}! Enter Cibus code.`, runId, {
            userName: order.userName,
            destination: run.destination
        });
    });
    logEvent('depart', { runId });
  };

  const markAsArrived = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run) return;
    const updatedRun: FoodRun = { ...run, status: 'arrived', arrivalLocation: arrivalLoc, arrivalTime: Date.now() };

    run.orders.forEach(order => {
        addNotification(order.userEmail, 'arrived', `Food from ${run.destination} is here!`, runId, {
            userName: order.userName,
            destination: run.destination,
            location: arrivalLoc || 'Kitchen'
        });
    });

    const updatedHistory = [updatedRun, ...history];
    setHistory(updatedHistory);
    localStorage.setItem('lunchrun_history', JSON.stringify(updatedHistory));
    setRuns(runs.filter(r => r.id !== runId));
    setShowArriveForm(null);
    logEvent('arrival', { runId, destination: run.destination });
  };

  const submitCibusCode = (e: React.FormEvent) => {
    e.preventDefault();
    if (!showCibusForm) return;
    const { runId, orderId } = showCibusForm;
    setRuns(runs.map(r => r.id === runId ? {
      ...r,
      orders: r.orders.map(o => o.id === orderId ? { ...o, cibusCode: newCibusInput } : o)
    } : r));
    setShowCibusForm(null);
    setNewCibusInput('');
    showToast("Cibus code submitted successfully!", "success");
  };

  const unreadCount = notifications.filter(n => !n.read).length;

  return (
    <div className="min-h-screen bg-[#F8FAFC] pb-10">
      {/* Toast System */}
      {activeToast && (
