              <div className={`px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-4 backdrop-blur-md border border-white/20 ${activeToast.type === 'arrived' ? 'bg-emerald-600 text-white' : activeToast.type === 'departed' ? 'bg-orange-600 text-white' : 'bg-indigo-600 text-white'}`}>
                  <div className="w-10 h-10 rounded-full bg-white/20 flex items-center justify-center text-lg">
                      <i className={`fas ${activeToast.type === 'arrived' ? 'fa-check-circle' : activeToast.type === 'departed' ? 'fa-bolt' : 'fa-bell'}`}></i>
                  </div>
                  <div className="pr-4">
                      <p className="text-[10px] font-black uppercase tracking-widest opacity-80">Notification</p>
                      <p className="font-bold text-sm tracking-tight">{activeToast.message}</p>
                  </div>
                  <button onClick={() => setActiveToast(null)} className="opacity-50 hover:opacity-100"><i className="fas fa-times"></i></button>
              </div>
          </div>
