        </div>
        <div className="flex items-center gap-4">
          <div className="relative">
              <button onClick={() => setShowNotificationCenter(!showNotificationCenter)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${unreadCount > 0 ? 'bg-indigo-50 text-indigo-600 shadow-sm border border-indigo-100' : 'bg-slate-50 text-slate-400'}`}>
                <i className="fas fa-bell text-lg"></i>
                {unreadCount > 0 && <span className="absolute -top-1 -right-1 w-6 h-6 bg-red-500 text-white rounded-full flex items-center justify-center text-[10px] font-black border-4 border-white animate-bounce">{unreadCount}</span>}
              </button>

              {showNotificationCenter && (
                  <div className="absolute top-full right-0 mt-4 w-96 bg-white border border-slate-100 shadow-[0_20px_60px_rgba(0,0,0,0.15)] rounded-[2rem] overflow-hidden animate-in slide-in-from-top-4 z-50">
                      <div className="p-6 border-b bg-slate-50/50 flex justify-between items-center">
                          <h4 className="text-sm font-black uppercase tracking-[0.2em] text-slate-500">Inbox</h4>
                          <button onClick={() => setShowNotificationCenter(false)} className="text-slate-300 hover:text-slate-500 transition-colors"><i className="fas fa-times"></i></button>
                      </div>
                      <div className="max-h-[500px] overflow-y-auto">
                          {notifications.length === 0 ? (
                              <div className="p-20 text-center text-slate-200">
                                  <i className="fas fa-envelope-open text-6xl mb-4"></i>
                                  <p className="text-xs font-black uppercase tracking-widest">Empty Inbox</p>
                              </div>
                          ) : (
                              notifications.map(n => (
                                  <div key={n.id} onClick={() => { setNotifications(notifications.map(x => x.id === n.id ? {...x, read: true} : x)); }} className={`p-6 border-b last:border-0 hover:bg-slate-50 transition-colors cursor-pointer flex gap-4 ${!n.read ? 'bg-indigo-50/20' : ''}`}>
                                      <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 ${n.type === 'waitlist_promoted' ? 'bg-emerald-100 text-emerald-600' : n.type === 'departed' ? 'bg-orange-100 text-orange-600' : 'bg-indigo-100 text-indigo-600'}`}>
                                          <i className={`fas ${n.type === 'waitlist_promoted' ? 'fa-magic' : n.type === 'departed' ? 'fa-running' : 'fa-map-marker-alt'}`}></i>
                                      </div>
                                      <div className="flex-1">
                                          <p className={`text-sm leading-relaxed mb-1 ${!n.read ? 'font-black text-slate-800' : 'text-slate-500 font-medium'}`}>{n.message}</p>
                                          <p className="text-[10px] text-slate-300 font-black uppercase tracking-widest">{new Date(n.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                                      </div>
                                  </div>
                              ))
