          <div className="flex items-center gap-3 pl-4 border-l">
              <img src={user?.picture || `https://ui-avatars.com/api/?name=${user?.name}`} className="w-12 h-12 rounded-2xl border-2 border-white shadow-md object-cover transition-transform hover:rotate-6" alt="user" />
          </div>
        </div>
      </header>

      {view === 'admin' ? (
        <main className="max-w-6xl mx-auto p-8 space-y-12 animate-in fade-in duration-700">
          <div className="flex flex-col md:flex-row justify-between items-end gap-6">
            <div>
              <h2 className="text-4xl font-black text-slate-800 tracking-tighter">System Analytics</h2>
              <p className="text-slate-400 font-bold text-xs uppercase tracking-widest mt-2 bg-slate-100 inline-block px-3 py-1 rounded-lg">Operational Dashboard</p>
            </div>
            <div className="flex bg-white p-1.5 rounded-3xl border shadow-xl">
              <button onClick={() => setAdminTab('history')} className={`px-8 py-4 rounded-[1.25rem] text-[10px] font-black uppercase tracking-widest transition-all ${adminTab === 'history' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'text-slate-400'}`}>Archives</button>
              <button onClick={() => setAdminTab('analytics')} className={`px-8 py-4 rounded-[1.25rem] text-[10px] font-black uppercase tracking-widest transition-all ${adminTab === 'analytics' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'text-slate-400'}`}>Insights</button>
            </div>
          </div>

          {adminTab === 'analytics' ? (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
                  {[
                      { l: 'Lifetime Orders', v: analytics.totalOrders, i: 'fa-shopping-bag', c: 'text-indigo-600' },
                      { l: 'Efficiency Ratio', v: analytics.avgOrders, i: 'fa-bolt', c: 'text-orange-600' },
                      { l: 'Active Workforce', v: analytics.uniqueUsers, i: 'fa-user-astronaut', c: 'text-emerald-600' },
                      { l: 'Total Missions', v: analytics.totalRuns, i: 'fa-flag-checkered', c: 'text-slate-600' }
                  ].map(s => (
                      <div key={s.l} className="bg-white p-10 rounded-[3rem] shadow-sm border border-slate-100 hover:shadow-xl transition-all group">
                          <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-xl mb-6 shadow-inner ${s.c.replace('text', 'bg').replace('600', '50')} ${s.c}`}>
                              <i className={`fas ${s.i}`}></i>
                          </div>
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">{s.l}</p>
                          <p className={`text-5xl font-black tracking-tighter ${s.c}`}>{s.v}</p>
                      </div>
                  ))}

                  <div className="lg:col-span-2 bg-slate-900 text-white p-12 rounded-[4rem] shadow-2xl relative overflow-hidden">
                      <div className="absolute top-0 right-0 w-full h-full bg-indigo-600/5 rotate-12 blur-3xl"></div>
                      <h3 className="text-xl font-black mb-10 tracking-tight flex items-center gap-3"><i className="fas fa-trophy text-amber-400"></i> Trending Hotspots</h3>
                      <div className="space-y-8 relative z-10">
                          {analytics.topDestinations.map(([d, c]) => (
