// --- Enhanced Email Templates ---
const getEmailTemplate = (type: UserNotification['type'], data: any) => {
  const brandColor = "#4f46e5"; // Indigo 600
  const orangeColor = "#ea580c"; // Orange 600
  const greenColor = "#059669"; // Emerald 600

  const baseStyles = `
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    line-height: 1.6;
    color: #334155;
    background-color: #f8fafc;
    margin: 0;
