  const containerStyles = `
    max-width: 500px;
    margin: 0 auto;
    background-color: #ffffff;
    border-radius: 24px;
    overflow: hidden;
    box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.1);
    border: 1px solid #e2e8f0;
  `;

  const headerStyles = (color: string) => `
    background-color: ${color};
    padding: 40px 20px;
    text-align: center;
    color: #ffffff;
  `;

  const bodyStyles = `
    padding: 40px;
  `;

  const buttonStyles = (color: string) => `
    display: block;
    text-align: center;
    background-color: ${color};
    color: #ffffff;
    padding: 16px 32px;
