    border-radius: 12px;
    font-weight: 800;
    font-size: 14px;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-top: 30px;
  `;

  const footerStyles = `
    padding: 24px;
    text-align: center;
    font-size: 11px;
    color: #94a3b8;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    border-top: 1px solid #f1f5f9;
  `;

  const templates = {
    waitlist_promoted: `
      <div style="${baseStyles}">
        <div style="${containerStyles}">
          <div style="${headerStyles(brandColor)}">
            <h1 style="margin:0; font-size: 24px; font-weight: 900;">LUNCHRUN</h1>
            <p style="margin-top:8px; opacity: 0.8; font-weight: 700;">Waitlist Promotion</p>
          </div>
          <div style="${bodyStyles}">
            <p>Hey <strong>${data.userName}</strong>,</p>
            <p>Good news! <strong>${data.runnerName}</strong> just started a run to <strong>${data.destination}</strong> and you've been automatically promoted from the waitlist.</p>
            <div style="background-color: #f1f5f9; padding: 20px; border-radius: 16px; margin: 20px 0;">
              <p style="margin:0; font-size: 13px; color: #64748b; font-weight: 800; text-transform: uppercase;">Your Order</p>
              <p style="margin:4px 0 0 0; font-weight: 700;">${data.itemDescription}</p>
            </div>
            <p>Stay tuned. We'll ping you when it's time to submit your payment code.</p>
            <a href="https://lunchrun.internal" style="${buttonStyles(brandColor)}">Track Mission</a>
          </div>
          <div style="${footerStyles}">Internal Logistics Portal • Workplace Excellence</div>
        </div>
      </div>
    `,
    departed: `
      <div style="${baseStyles}">
        <div style="${containerStyles}">
          <div style="${headerStyles(orangeColor)}">
            <h1 style="margin:0; font-size: 24px; font-weight: 900;">PAYMENT REQUIRED</h1>
            <p style="margin-top:8px; opacity: 0.8; font-weight: 700;">Runner is En Route</p>
          </div>
          <div style="${bodyStyles}">
            <p>Hi <strong>${data.userName}</strong>,</p>
            <p>The runner for <strong>${data.destination}</strong> has officially departed! 🏃‍♂️</p>
            <p style="color: ${orangeColor}; font-weight: 800;">Action Required: Submit your Cibus Code within the next 20 minutes.</p>
            <p style="font-size: 13px; color: #64748b;">Codes are time-sensitive. Please don't keep the runner waiting at the register.</p>
            <a href="https://lunchrun.internal" style="${buttonStyles(orangeColor)}">Submit Cibus Code</a>
          </div>
