        </div>
      </div>
    `,
    arrived: `
      <div style="${baseStyles}">
        <div style="${containerStyles}">
          <div style="${headerStyles(greenColor)}">
            <h1 style="margin:0; font-size: 24px; font-weight: 900;">FOOD ARRIVED</h1>
