  // Input states
  const [newRunDest, setNewRunDest] = useState('');
  const [newRunTime, setNewRunTime] = useState(25);
  const [newRunMax, setNewRunMax] = useState(5);
  const [newOrderItem, setNewOrderItem] = useState('');
  const [newOrderFloor, setNewOrderFloor] = useState('');
  const [newCibusInput, setNewCibusInput] = useState('');
  const [arrivalLoc, setArrivalLoc] = useState('');

  useEffect(() => {
    const savedHistory = localStorage.getItem('lunchrun_history');
    const savedEvents = localStorage.getItem('lunchrun_events');
    const savedWaitlist = localStorage.getItem('lunchrun_waitlist');
    const savedNotifications = localStorage.getItem('lunchrun_notifications');

    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedEvents) setEvents(JSON.parse(savedEvents));
    if (savedWaitlist) setWaitingOrders(JSON.parse(savedWaitlist));
    if (savedNotifications) setNotifications(JSON.parse(savedNotifications));

    if (!isJoined && typeof window !== 'undefined' && (window as any).google) {
      try {
        (window as any).google.accounts.id.initialize({
          client_id: GOOGLE_CLIENT_ID,
          callback: handleGoogleResponse,
          hd: ALLOWED_DOMAIN !== 'yourcompany.com' ? ALLOWED_DOMAIN : undefined,
          auto_select: false,
          context: 'signin'
        });
        const btnContainer = document.getElementById("googleBtn");
        if (btnContainer) {
          (window as any).google.accounts.id.renderButton(btnContainer, { theme: "filled_blue", size: "large", width: "100%", shape: "pill" });
        }
      } catch (e) { console.error(e); }
    }
  }, [isJoined, isGuestForm]);

  const showToast = (message: string, type: string) => {
    setActiveToast({ message, type });
    setTimeout(() => setActiveToast(null), 6000);
  };

  const sendNotification = (targetEmail: string, type: UserNotification['type'], message: string, runId: string, emailData: any) => {
    const emailBody = getEmailTemplate(type, emailData);
    const newNotif: UserNotification = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      message,
      emailBody,
      runId,
      timestamp: Date.now(),
      read: false
    };

    // Simulate real-time arrival for the current user
    if (targetEmail === user?.email) {
      const updated = [newNotif, ...notifications];
      setNotifications(updated);
      localStorage.setItem('lunchrun_notifications', JSON.stringify(updated));
      showToast(message, type);
    }

    // Console simulation of email transport
    console.group(`%c EMAIL SENT TO: ${targetEmail} `, 'background: #4f46e5; color: #fff; font-weight: bold;');
    console.log(`Type: ${type.toUpperCase()}`);
    console.log(`Subject: [LunchRun] ${message}`);
    console.log(`HTML Preview:`);
    console.log(emailBody);
    console.groupEnd();
  };

  const handleGoogleResponse = (response: any) => {
    const payload = decodeJwt(response.credential);
    if (ALLOWED_DOMAIN !== 'yourcompany.com' && payload.hd !== ALLOWED_DOMAIN) {
      setLoginError(`Only @${ALLOWED_DOMAIN} accounts are permitted.`);
      return;
    }
    setUser({ name: payload.name, email: payload.email, picture: payload.picture, isGuest: false });
    setIsJoined(true);
    logEvent('login');
  };

  const handleGuestLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (guestNameInput.trim()) {
      setUser({ name: guestNameInput.trim(), email: 'guest@internal.local', isGuest: true });
      setIsJoined(true);
      logEvent('login', { method: 'guest' });
    }
  };

  const decodeJwt = (token: string) => {
    try {
      const base64Url = token.split('.')[1];
      const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
      const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2)).join(''));
      return JSON.parse(jsonPayload);
    } catch (e) { return null; }
  };

  const logEvent = (type: AppEvent['type'], metadata?: any) => {
    if (!user) return;
    const newEvent: AppEvent = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      userEmail: user.email,
      timestamp: Date.now(),
      metadata
    };
    const updatedEvents = [newEvent, ...events];
    setEvents(updatedEvents);
    localStorage.setItem('lunchrun_events', JSON.stringify(updatedEvents));
  };

  const createRun = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;

    // Promotion logic
    const matchingWaitlist = waitingOrders.filter(wo => wo.destination.toLowerCase().trim() === newRunDest.toLowerCase().trim());
    const initialOrders: Order[] = matchingWaitlist.slice(0, newRunMax).map(wo => {
        sendNotification(wo.userEmail, 'waitlist_promoted', `Waitlist Match! You're in for ${wo.destination}`, 'new_run', {
            userName: wo.userName,
            destination: wo.destination,
            runnerName: user.name,
            itemDescription: wo.itemDescription
        });
        return {
            id: Math.random().toString(36).substr(2, 9),
            userName: wo.userName,
            userEmail: wo.userEmail,
            itemDescription: wo.itemDescription,
            floor: wo.floor,
            cibusCode: '',
            timestamp: Date.now()
        };
    });

    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: user.name,
      runnerEmail: user.email,
      destination: newRunDest,
      departureTime: Date.now() + newRunTime * 60000,
      minutesUntilDeparture: newRunTime,
      maxOrders: newRunMax,
      status: 'active',
      orders: initialOrders
    };

    const remainingWaitlist = waitingOrders.filter(wo => !initialOrders.some(io => io.userEmail === wo.userEmail && io.itemDescription === wo.itemDescription));
    setWaitingOrders(remainingWaitlist);
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(remainingWaitlist));

    setRuns([newRun, ...runs]);
    setShowCreateForm(false);
    setNewRunDest('');
    logEvent('create_run', { destination: newRun.destination });
  };

  const departRun = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run) return;
    setRuns(runs.map(r => r.id === runId ? { ...r, status: 'departed' } : r));

    run.orders.forEach(order => {
        sendNotification(order.userEmail, 'departed', `Time to pay! Runner leaving for ${run.destination}`, runId, {
            userName: order.userName,
            destination: run.destination
        });
    });
    logEvent('depart', { runId });
  };

  const markAsArrived = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run) return;
    const updatedRun: FoodRun = { ...run, status: 'arrived', arrivalLocation: arrivalLoc, arrivalTime: Date.now() };

    run.orders.forEach(order => {
        sendNotification(order.userEmail, 'arrived', `Food is here! Pick up at ${arrivalLoc || 'Kitchen'}`, runId, {
            userName: order.userName,
            destination: run.destination,
            location: arrivalLoc || 'Kitchen'
        });
    });

    const updatedHistory = [updatedRun, ...history];
    setHistory(updatedHistory);
    localStorage.setItem('lunchrun_history', JSON.stringify(updatedHistory));
    setRuns(runs.filter(r => r.id !== runId));
    setShowArriveForm(null);
    logEvent('arrival', { runId, destination: run.destination });
  };

  const addToWaitlist = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newWait: WaitingOrder = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      userEmail: user.email,
      destination: newRunDest,
      itemDescription: newOrderItem,
      floor: newOrderFloor,
      timestamp: Date.now()
    };
    const updated = [...waitingOrders, newWait];
    setWaitingOrders(updated);
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(updated));
    setShowWaitlistForm(false);
    setNewRunDest('');
    setNewOrderItem('');
    logEvent('waitlist_add', { destination: newWait.destination });
  };

  const joinRun = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run || !user || run.orders.length >= run.maxOrders) return;
    const newOrder: Order = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      userEmail: user.email,
      itemDescription: newOrderItem,
      cibusCode: '', 
      floor: newOrderFloor,
      timestamp: Date.now()
    };
    setRuns(runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, newOrder] } : r));
    setShowJoinForm(null);
    setNewOrderItem('');
    setNewOrderFloor('');
    logEvent('join_run', { runId, destination: run.destination });
  };

  const isAdmin = useMemo(() => user && (ADMIN_EMAILS.includes(user.email) || user.email === 'guest@internal.local'), [user]);
  const unreadCount = notifications.filter(n => !n.read).length;

  const analytics = useMemo(() => {
    const totalOrders = history.reduce((sum, run) => sum + run.orders.length, 0);
    const avgOrders = history.length ? (totalOrders / history.length).toFixed(1) : 0;
    const uniqueUsers = new Set(events.map(e => e.userEmail)).size;
    const destinations: Record<string, number> = {};
    history.forEach(run => { destinations[run.destination] = (destinations[run.destination] || 0) + 1; });
    const topDestinations = Object.entries(destinations).sort((a, b) => b[1] - a[1]).slice(0, 5);
    return { totalOrders, avgOrders, uniqueUsers, topDestinations, totalRuns: history.length };
  }, [history, events]);

  if (!isJoined) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-900 p-4 font-sans">
        <div className="bg-white p-12 rounded-[3.5rem] shadow-2xl w-full max-w-md text-center border border-white/20">
          <div className="w-24 h-24 bg-indigo-600 rounded-[2.5rem] flex items-center justify-center mx-auto mb-8 shadow-2xl shadow-indigo-200">
            <i className="fas fa-bicycle text-white text-4xl"></i>
          </div>
          <h1 className="text-4xl font-black mb-2 tracking-tighter text-slate-900">LunchRun</h1>
          <p className="text-slate-400 mb-12 font-bold uppercase text-[10px] tracking-[0.3em]">Corporate Logistics</p>
          {!isGuestForm ? (
            <div className="space-y-6">
              <div id="googleBtn" className="flex justify-center"></div>
              <button onClick={() => setIsGuestForm(true)} className="text-[11px] text-slate-400 font-black uppercase tracking-widest hover:text-indigo-600 transition-colors">Internal Guest Access</button>
            </div>
          ) : (
            <form onSubmit={handleGuestLogin} className="space-y-6 text-left animate-in slide-in-from-right-10 duration-500">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-2 block">Display Name</label>
                <input required className="w-full p-5 bg-slate-50 border-2 rounded-2xl outline-none font-bold text-lg" placeholder="e.g. David Levi" value={guestNameInput} onChange={e => setGuestNameInput(e.target.value)} />
              </div>
              <Button type="submit" className="w-full h-18 bg-indigo-600 rounded-2xl shadow-xl shadow-indigo-100 text-sm font-black uppercase">Authenticate</Button>
              <button type="button" onClick={() => setIsGuestForm(false)} className="w-full text-center text-[10px] font-black text-slate-400 uppercase">Back to SSO</button>
            </form>
          )}
          {loginError && <p className="mt-6 text-red-500 text-xs font-bold bg-red-50 p-4 rounded-2xl">{loginError}</p>}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC]">
      {/* Dynamic Toast System */}
      {activeToast && (
          <div className="fixed top-8 left-1/2 -translate-x-1/2 z-[100] animate-in slide-in-from-top-16 duration-500">
              <div className={`px-8 py-5 rounded-3xl shadow-[0_20px_50px_rgba(0,0,0,0.15)] flex items-center gap-5 backdrop-blur-xl border border-white/20 min-w-[320px] ${activeToast.type === 'arrived' ? 'bg-emerald-600 text-white' : activeToast.type === 'departed' ? 'bg-orange-600 text-white' : 'bg-slate-900 text-white'}`}>
                  <div className="w-12 h-12 rounded-2xl bg-white/20 flex items-center justify-center text-xl shrink-0">
                      <i className={`fas ${activeToast.type === 'arrived' ? 'fa-check-circle' : activeToast.type === 'departed' ? 'fa-running' : 'fa-bell'}`}></i>
                  </div>
                  <div className="flex-1 pr-4">
                      <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-60">System Notification</p>
                      <p className="font-bold text-sm tracking-tight leading-snug">{activeToast.message}</p>
                  </div>
                  <button onClick={() => setActiveToast(null)} className="opacity-40 hover:opacity-100 transition-opacity"><i className="fas fa-times text-lg"></i></button>
              </div>
          </div>
      )}

      <header className="bg-white border-b sticky top-0 z-40 px-8 py-5 flex justify-between items-center shadow-sm backdrop-blur-lg bg-white/80">
        <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setView('app')}>
          <div className="bg-indigo-600 p-2.5 rounded-2xl shadow-lg shadow-indigo-100 transition-transform group-hover:scale-110"><i className="fas fa-bicycle text-white"></i></div>
          <span className="text-2xl font-black tracking-tighter">LUNCHRUN</span>
        </div>

        <div className="flex items-center gap-6">
          <div className="relative">
              <button onClick={() => setShowNotificationCenter(!showNotificationCenter)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${unreadCount > 0 ? 'bg-indigo-50 text-indigo-600 shadow-sm border border-indigo-100' : 'bg-slate-50 text-slate-400'}`}>
                <i className="fas fa-bell text-xl"></i>
                {unreadCount > 0 && <span className="absolute -top-1.5 -right-1.5 w-7 h-7 bg-red-500 text-white rounded-full flex items-center justify-center text-[11px] font-black border-4 border-white animate-bounce">{unreadCount}</span>}
              </button>

              {showNotificationCenter && (
                  <div className="absolute top-full right-0 mt-5 w-[400px] bg-white border border-slate-100 shadow-[0_30px_70px_rgba(0,0,0,0.2)] rounded-[2.5rem] overflow-hidden animate-in slide-in-from-top-6 z-50">
                      <div className="p-7 border-b bg-slate-50/50 flex justify-between items-center">
                          <h4 className="text-xs font-black uppercase tracking-[0.3em] text-slate-500">Notifications</h4>
                          <button onClick={() => setShowNotificationCenter(false)} className="text-slate-300 hover:text-slate-500"><i className="fas fa-times-circle text-xl"></i></button>
                      </div>
                      <div className="max-h-[500px] overflow-y-auto">
                          {notifications.length === 0 ? (
                              <div className="p-20 text-center opacity-20">
                                  <i className="fas fa-inbox text-7xl mb-6"></i>
                                  <p className="text-[10px] font-black uppercase tracking-[0.4em]">All caught up</p>
                              </div>
                          ) : (
                              notifications.map(n => (
                                  <div key={n.id} onClick={() => { setNotifications(notifications.map(x => x.id === n.id ? {...x, read: true} : x)); }} className={`p-7 border-b last:border-0 hover:bg-slate-50 transition-colors cursor-pointer flex gap-5 ${!n.read ? 'bg-indigo-50/20' : ''}`}>
                                      <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 shadow-sm ${n.type === 'waitlist_promoted' ? 'bg-emerald-100 text-emerald-600' : n.type === 'departed' ? 'bg-orange-100 text-orange-600' : 'bg-indigo-100 text-indigo-600'}`}>
                                          <i className={`fas ${n.type === 'waitlist_promoted' ? 'fa-magic' : n.type === 'departed' ? 'fa-running' : 'fa-map-pin'} text-lg`}></i>
                                      </div>
                                      <div className="flex-1">
                                          <p className={`text-sm leading-relaxed mb-2 ${!n.read ? 'font-black text-slate-800' : 'text-slate-500 font-medium'}`}>{n.message}</p>
                                          <div className="flex justify-between items-center">
                                            <p className="text-[10px] text-slate-300 font-black uppercase tracking-widest">{new Date(n.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                                            {!n.read && <span className="w-2 h-2 bg-indigo-600 rounded-full"></span>}
                                          </div>
                                      </div>
                                  </div>
                              ))
                          )}
                      </div>
                  </div>
              )}
          </div>

          {isAdmin && (
            <button onClick={() => setView(view === 'admin' ? 'app' : 'admin')} className={`h-12 px-6 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all shadow-sm ${view === 'admin' ? 'bg-slate-900 text-white' : 'bg-white border-2 text-indigo-600 border-indigo-50'}`}>
              <i className={`fas ${view === 'admin' ? 'fa-home' : 'fa-chart-line'} mr-2`}></i>
              {view === 'admin' ? 'Portal' : 'Admin'}
            </button>
          )}

          <img src={user?.picture || `https://ui-avatars.com/api/?name=${user?.name}`} className="w-12 h-12 rounded-2xl border-2 border-white shadow-md object-cover" alt="u" />
        </div>
      </header>

      {view === 'admin' ? (
        <main className="max-w-6xl mx-auto p-10 space-y-12 animate-in fade-in duration-700">
          <div className="flex justify-between items-end">
            <div>
              <h2 className="text-4xl font-black text-slate-800 tracking-tighter">System Health</h2>
              <p className="text-slate-400 font-bold text-xs uppercase tracking-widest mt-2">Historical Analytics Hub</p>
            </div>
            <div className="flex bg-white p-2 rounded-[2rem] border shadow-xl">
              <button onClick={() => setAdminTab('history')} className={`px-8 py-4 rounded-3xl text-[10px] font-black uppercase tracking-widest ${adminTab === 'history' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'text-slate-400'}`}>Archives</button>
              <button onClick={() => setAdminTab('analytics')} className={`px-8 py-4 rounded-3xl text-[10px] font-black uppercase tracking-widest ${adminTab === 'analytics' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'text-slate-400'}`}>Analytics</button>
            </div>
          </div>

          {adminTab === 'analytics' ? (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                  {[
                      { l: 'Total Orders', v: analytics.totalOrders, i: 'fa-box-open', c: 'text-indigo-600' },
                      { l: 'Avg Per Run', v: analytics.avgOrders, i: 'fa-bolt', c: 'text-orange-600' },
                      { l: 'Active Staff', v: analytics.uniqueUsers, i: 'fa-users', c: 'text-emerald-600' },
                      { l: 'Lifetime Runs', v: analytics.totalRuns, i: 'fa-flag', c: 'text-slate-600' }
                  ].map(s => (
                      <div key={s.l} className="bg-white p-10 rounded-[3rem] shadow-sm border border-slate-100">
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">{s.l}</p>
                          <p className={`text-5xl font-black tracking-tighter ${s.c}`}>{s.v}</p>
                      </div>
                  ))}

                  <div className="lg:col-span-2 bg-slate-900 text-white p-12 rounded-[4rem] shadow-2xl overflow-hidden relative">
                      <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/10 blur-[100px] rounded-full"></div>
                      <h3 className="text-lg font-black mb-10 tracking-tight"><i className="fas fa-chart-bar text-indigo-400 mr-3"></i> Top Hotspots</h3>
                      <div className="space-y-8 relative z-10">
                          {analytics.topDestinations.map(([d, c]) => (
                              <div key={d}>
                                  <div className="flex justify-between text-xs font-black uppercase mb-3 tracking-widest"><span>{d}</span><span className="text-indigo-400">{c} Hits</span></div>
                                  <div className="w-full h-3 bg-white/5 rounded-full overflow-hidden">
                                      <div className="h-full bg-indigo-500 rounded-full transition-all duration-1000" style={{ width: `${(c / Math.max(...analytics.topDestinations.map(x => x[1]))) * 100}%` }}></div>
                                  </div>
                              </div>
                          ))}
                      </div>
                  </div>
              </div>
          ) : (
              <div className="bg-white rounded-[3.5rem] shadow-2xl border border-slate-100 overflow-hidden">
                  <table className="w-full text-left">
                      <thead>
                          <tr className="bg-slate-50/50">
                              <th className="px-10 py-8 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">Completed</th>
                              <th className="px-10 py-8 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">Runner</th>
                              <th className="px-10 py-8 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">Target</th>
                              <th className="px-10 py-8 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">Load</th>
                          </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100 font-bold text-sm text-slate-600">
                          {history.map(r => (
                              <tr key={r.id} className="hover:bg-slate-50 transition-colors">
                                  <td className="px-10 py-8 text-xs text-slate-400 font-black">{new Date(r.arrivalTime || 0).toLocaleDateString()}</td>
                                  <td className="px-10 py-8 font-black text-slate-800">{r.runnerName}</td>
                                  <td className="px-10 py-8 text-indigo-600 font-black tracking-tight">{r.destination}</td>
                                  <td className="px-10 py-8">{r.orders.length} items</td>
                              </tr>
                          ))}
                      </tbody>
                  </table>
              </div>
          )}
        </main>
      ) : (
        <main className="max-w-4xl mx-auto p-12 space-y-16 animate-in fade-in duration-500">
          <section className="bg-white p-12 rounded-[4.5rem] shadow-sm border border-slate-100 flex flex-col sm:flex-row justify-between items-center gap-10">
              <div className="text-center sm:text-left">
                  <h2 className="text-4xl font-black text-slate-800 tracking-tighter">Mission Control</h2>
                  <p className="text-slate-400 font-bold text-sm uppercase tracking-[0.2em] mt-2">Real-time team feed</p>
              </div>
              <div className="flex gap-4">
                  <Button onClick={() => setShowWaitlistForm(true)} variant="secondary" className="h-20 px-12 rounded-[2.5rem] text-[11px] font-black uppercase tracking-widest shadow-sm">
                      <i className="fas fa-list-check mr-3"></i> Waitlist
                  </Button>
                  <Button onClick={() => setShowCreateForm(true)} className="bg-indigo-600 hover:bg-indigo-700 h-20 px-12 rounded-[2.5rem] shadow-2xl shadow-indigo-100 text-[11px] font-black uppercase tracking-widest active:scale-95">
                      <i className="fas fa-rocket mr-3"></i> Start Mission
                  </Button>
              </div>
          </section>

          <div className="grid gap-16">
            {runs.length === 0 && (
                <div className="text-center py-40 bg-white rounded-[5rem] border-4 border-dashed border-slate-100 flex flex-col items-center">
                    <div className="w-24 h-24 bg-slate-50 rounded-[2.5rem] flex items-center justify-center text-slate-200 text-5xl mb-10"><i className="fas fa-radar"></i></div>
                    <p className="text-slate-400 font-black uppercase tracking-[0.4em] mb-4">Radar Clear</p>
                    <p className="text-[13px] text-slate-300 max-w-xs leading-relaxed font-bold">Waiting for an active runner. Submit a request to the waitlist to be picked up automatically.</p>
                </div>
            )}

            {runs.map(run => {
              const isRunner = user && run.runnerEmail === user.email;
              const myOrder = run.orders.find(o => o.userEmail === user?.email);

              return (
                <div key={run.id} className={`bg-white rounded-[5rem] border-2 shadow-[0_40px_80px_rgba(0,0,0,0.05)] p-14 transition-all duration-700 group relative overflow-hidden ${run.status === 'departed' ? 'border-orange-500 ring-[12px] ring-orange-50' : 'border-white hover:border-indigo-100'}`}>
                  {run.status === 'departed' && <div className="absolute top-0 right-0 bg-orange-600 text-white text-[11px] font-black uppercase px-10 py-4 rounded-bl-[2.5rem] tracking-[0.4em] shadow-2xl animate-pulse z-10">Active Mission</div>}

                  <div className="flex justify-between items-start mb-16 relative z-10">
                    <div className="flex gap-10">
                      <div className={`w-24 h-24 rounded-[3rem] flex items-center justify-center text-5xl shadow-sm transition-all duration-700 ${run.status === 'departed' ? 'bg-orange-100 text-orange-600 rotate-6 scale-110' : 'bg-indigo-50 text-indigo-600 group-hover:-rotate-6 group-hover:scale-110'}`}>
                        <i className={`fas ${run.status === 'departed' ? 'fa-motorcycle' : 'fa-pizza-slice'}`}></i>
                      </div>
                      <div>
                        <h4 className="text-4xl font-black text-slate-800 tracking-tighter">{run.destination}</h4>
                        <p className="text-slate-400 font-black text-[11px] uppercase tracking-[0.3em] mt-3 flex items-center gap-3">
                            <span className="w-2 h-2 bg-indigo-500 rounded-full"></span> Lead: {run.runnerName}
                        </p>
                      </div>
                    </div>
                    <div className="text-right">
                       <span className={`px-8 py-4 rounded-[2rem] text-[11px] font-black uppercase tracking-[0.3em] border transition-all ${run.status === 'departed' ? 'bg-orange-600 text-white border-orange-700 shadow-2xl shadow-orange-100' : 'bg-slate-50 border-slate-200 text-slate-400'}`}>
                         {run.status === 'departed' ? 'Submit Codes' : `${run.minutesUntilDeparture}m Window`}
                       </span>
                    </div>
                  </div>

                  {run.status === 'departed' && (
                    <div className="mb-14 p-10 bg-orange-50/50 border-2 border-orange-100 rounded-[3.5rem] flex items-center gap-10 animate-in slide-in-from-top-6">
                       <div className="w-20 h-20 bg-white rounded-[2rem] flex items-center justify-center text-orange-600 shrink-0 shadow-sm border border-orange-100 text-2xl">
                         <i className="fas fa-clock animate-spin-slow"></i>
                       </div>
                       <div>
                         <p className="text-[11px] font-black text-orange-800 uppercase tracking-[0.3em] mb-2">Cibus Protocol Active</p>
                         <p className="text-[15px] text-orange-700/80 font-bold leading-relaxed">Payment codes provided now are valid for the next 20 minutes. Please synchronize immediately.</p>
                       </div>
                    </div>
                  )}

                  <div className="space-y-6 mb-16">
