              <div className="pt-10">
                  <Button type="submit" className="w-full h-28 bg-slate-900 text-white rounded-[3.5rem] font-black uppercase tracking-[0.5em] shadow-2xl">Publish To Feed</Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showJoinForm && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-3xl z-[60] flex items-center justify-center p-6 overflow-y-auto">
          <div className="bg-white rounded-[5rem] p-16 w-full max-w-xl shadow-2xl animate-in zoom-in-95 duration-500 relative">
            <button onClick={() => setShowJoinForm(null)} className="absolute top-12 right-12 w-14 h-14 rounded-full hover:bg-slate-50 flex items-center justify-center text-slate-300"><i className="fas fa-times text-2xl"></i></button>
