      {showArriveForm && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-3xl z-[70] flex items-center justify-center p-6 overflow-y-auto">
          <div className="bg-white rounded-[6rem] p-20 text-center max-w-xl w-full shadow-2xl animate-in zoom-in-95 duration-300">
            <div className="w-32 h-32 bg-emerald-50 text-emerald-600 rounded-[3.5rem] flex items-center justify-center text-6xl mb-14 mx-auto shadow-inner border border-emerald-100"><i className="fas fa-map-marker-alt"></i></div>
            <h3 className="text-4xl font-black mb-6 tracking-tighter">Deliver Complete</h3>
            <p className="text-slate-400 font-bold uppercase text-[11px] tracking-[0.4em] mb-14 px-12 leading-relaxed">Broadcast the final pickup coordinates for your teammates.</p>
            <input autoFocus className="w-full p-10 bg-slate-50 border-2 border-emerald-100 rounded-[3.5rem] font-black text-3xl text-center mb-12 outline-none focus:border-emerald-600 shadow-inner" placeholder="e.g. Kitchen Counter" value={arrivalLoc} onChange={e => setArrivalLoc(e.target.value)} />
            <div className="flex gap-8">
               <Button className="flex-1 bg-slate-100 text-slate-500 rounded-[2.5rem] h-24 font-black uppercase text-[11px] tracking-[0.4em]" onClick={() => setShowArriveForm(null)}>Abort</Button>
               <Button className="flex-[2] bg-emerald-600 rounded-[2.5rem] h-24 font-black text-white shadow-2xl shadow-emerald-100 uppercase text-[11px] tracking-[0.4em]" onClick={() => markAsArrived(showArriveForm)}>Broadcast Signal</Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export enum UserRole {
  RUNNER = 'RUNNER',
  ORDERER = 'ORDERER',
  ADMIN = 'ADMIN'
}

export interface Order {
  id: string;
  userName: string;
  userEmail: string;
  itemDescription: string;
  cibusCode: string;
  floor: string;
  timestamp: number;
}

export interface WaitingOrder {
  id: string;
  userName: string;
  userEmail: string;
  destination: string;
  itemDescription: string;
  floor: string;
  timestamp: number;
}

export interface FoodRun {
  id: string;
  runnerName: string;
  runnerEmail: string;
  destination: string;
  departureTime: number; 
  minutesUntilDeparture: number;
  maxOrders: number;
  orders: Order[];
  status: 'active' | 'departed' | 'arrived' | 'cancelled';
  arrivalLocation?: string;
  arrivalTime?: number;
}

export interface UserNotification {
  id: string;
  type: 'waitlist_promoted' | 'departed' | 'arrived';
  message: string;
  chatMessageBody?: string; // HTML simulation of a Google Chat Card
  runId: string;
  timestamp: number;
  read: boolean;
}

export interface AppEvent {
  id: string;
  type: 'login' | 'create_run' | 'join_run' | 'depart' | 'arrival' | 'waitlist_add';
  userEmail: string;
  timestamp: number;
  metadata?: any;
}

export interface ImageGenerationConfig {
  aspectRatio: '1:1' | '3:4' | '4:3' | '9:16' | '16:9';
  imageSize: '1K' | '2K' | '4K';
}

import React, { useState, useEffect, useMemo } from 'react';
import { FoodRun, Order, AppEvent, WaitingOrder, UserNotification } from './types';
import { Button } from './components/Button';
import { ImageStudio } from './components/ImageStudio';

const ALLOWED_DOMAIN = 'yourcompany.com'; 
const GOOGLE_CLIENT_ID = 'YOUR_GOOGLE_CLIENT_ID.apps.googleusercontent.com';
const ADMIN_EMAILS = ['admin@yourcompany.com', 'manager@yourcompany.com'];

// --- Google Chat Card Templates ---
const getChatTemplate = (type: UserNotification['type'], data: any) => {
  const chatGreen = "#0b6623";
  const chatBlue = "#1a73e8";

  const containerStyle = "max-width: 450px; margin: 0 auto; background: #ffffff; border: 1px solid #dadce0; border-radius: 8px; font-family: 'Roboto', arial, sans-serif; overflow: hidden; box-shadow: 0 1px 2px 0 rgba(60,64,67,.3), 0 1px 3px 1px rgba(60,64,67,.15);";
  const headerStyle = "padding: 12px 16px; border-bottom: 1px solid #f1f3f4; display: flex; align-items: center; gap: 12px; background: #f8f9fa;";
  const bodyStyle = "padding: 16px;";
  const sectionStyle = "margin-bottom: 12px; padding: 12px; background: #f8f9fa; border-radius: 4px; border-left: 4px solid #1a73e8;";
  const btnStyle = (color: string) => `display: inline-block; padding: 8px 16px; background: ${color}; color: white; border-radius: 4px; text-decoration: none; font-size: 13px; font-weight: 500; margin-top: 8px;`;

  const templates = {
    waitlist_promoted: `
      <div style="${containerStyle}">
        <div style="${headerStyle}">
          <div style="width: 24px; height: 24px; background: #1a73e8; color: white; border-radius: 4px; display: flex; align-items: center; justify-content: center; font-size: 12px;">LR</div>
          <div style="font-size: 14px; font-weight: 500; color: #3c4043;">LunchRun Space</div>
        </div>
        <div style="${bodyStyle}">
          <div style="font-size: 14px; font-weight: 400; color: #202124; margin-bottom: 12px;">
            Hey <b>${data.userName}</b>, you've been promoted from the waitlist!
          </div>
          <div style="${sectionStyle}">
            <div style="font-size: 12px; color: #5f6368; text-transform: uppercase; font-weight: 700;">Active Run</div>
            <div style="font-size: 15px; font-weight: 500; color: #202124;">${data.destination}</div>
            <div style="font-size: 13px; color: #5f6368;">Item: ${data.itemDescription}</div>
          </div>
          <p style="font-size: 12px; color: #5f6368;">We'll notify you here when the runner departs.</p>
        </div>
      </div>
    `,
    departed: `
      <div style="${containerStyle}">
        <div style="${headerStyle}">
          <div style="width: 24px; height: 24px; background: #ea8600; color: white; border-radius: 4px; display: flex; align-items: center; justify-content: center; font-size: 12px;">!</div>
          <div style="font-size: 14px; font-weight: 500; color: #3c4043;">LunchRun Alert</div>
        </div>
        <div style="${bodyStyle}">
          <div style="font-size: 16px; font-weight: 500; color: #d93025; margin-bottom: 8px;">🚀 Runner is leaving for ${data.destination}!</div>
          <div style="font-size: 14px; color: #202124; margin-bottom: 16px;">
            Please submit your <b>Cibus Code</b> now. The runner needs it for the register.
          </div>
          <div style="text-align: center;">
            <a href="#" style="${btnStyle('#1a73e8')}">SUBMIT PAYMENT CODE</a>
          </div>
        </div>
      </div>
    `,
    arrived: `
      <div style="${containerStyle}">
        <div style="${headerStyle}">
          <div style="width: 24px; height: 24px; background: #188038; color: white; border-radius: 4px; display: flex; align-items: center; justify-content: center; font-size: 12px;">✓</div>
          <div style="font-size: 14px; font-weight: 500; color: #3c4043;">Food Arrived</div>
        </div>
        <div style="${bodyStyle}">
          <div style="font-size: 14px; color: #202124; margin-bottom: 12px;">
            Your order from <b>${data.destination}</b> has arrived and is ready for pickup!
          </div>
          <div style="padding: 12px; background: #e6f4ea; border-radius: 8px; border: 1px solid #34a853; text-align: center;">
            <div style="font-size: 11px; font-weight: 700; color: #137333; text-transform: uppercase;">Location</div>
            <div style="font-size: 18px; font-weight: 700; color: #137333;">${data.location}</div>
          </div>
          <div style="text-align: center;">
             <a href="#" style="${btnStyle('#188038')}">PICKED UP</a>
          </div>
        </div>
      </div>
    `
  };

  return templates[type] || '';
};

const App: React.FC = () => {
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [events, setEvents] = useState<AppEvent[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [notifications, setNotifications] = useState<UserNotification[]>([]);
  const [activeToast, setActiveToast] = useState<{message: string, type: string} | null>(null);

  const [user, setUser] = useState<{ name: string; email: string; picture?: string; isGuest?: boolean } | null>(null);
  const [isJoined, setIsJoined] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [view, setView] = useState<'app' | 'admin' | 'studio'>('app');
  const [adminTab, setAdminTab] = useState<'history' | 'analytics'>('history');

  // Modal States
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [showJoinForm, setShowJoinForm] = useState<string | null>(null);
  const [showArriveForm, setShowArriveForm] = useState<string | null>(null);
  const [showWaitlistForm, setShowWaitlistForm] = useState(false);
  const [showCibusForm, setShowCibusForm] = useState<{runId: string, orderId: string} | null>(null);
  const [showNotificationCenter, setShowNotificationCenter] = useState(false);
  const [previewChat, setPreviewChat] = useState<UserNotification | null>(null);

  const [isGuestForm, setIsGuestForm] = useState(false);
  const [guestNameInput, setGuestNameInput] = useState('');

  // Input states
  const [newRunDest, setNewRunDest] = useState('');
  const [newRunTime, setNewRunTime] = useState(25);
  const [newRunMax, setNewRunMax] = useState(5);
  const [newOrderItem, setNewOrderItem] = useState('');
  const [newOrderFloor, setNewOrderFloor] = useState('');
  const [newCibusInput, setNewCibusInput] = useState('');
  const [arrivalLoc, setArrivalLoc] = useState('');

  useEffect(() => {
    const savedHistory = localStorage.getItem('lunchrun_history');
    const savedEvents = localStorage.getItem('lunchrun_events');
    const savedWaitlist = localStorage.getItem('lunchrun_waitlist');
    const savedNotifications = localStorage.getItem('lunchrun_notifications');

    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedEvents) setEvents(JSON.parse(savedEvents));
    if (savedWaitlist) setWaitingOrders(JSON.parse(savedWaitlist));
    if (savedNotifications) setNotifications(JSON.parse(savedNotifications));

    if (!isJoined && typeof window !== 'undefined' && (window as any).google) {
      try {
        (window as any).google.accounts.id.initialize({
          client_id: GOOGLE_CLIENT_ID,
          callback: handleGoogleResponse,
          hd: ALLOWED_DOMAIN !== 'yourcompany.com' ? ALLOWED_DOMAIN : undefined,
          auto_select: false,
          context: 'signin'
        });
        const btnContainer = document.getElementById("googleBtn");
        if (btnContainer) {
          (window as any).google.accounts.id.renderButton(btnContainer, { theme: "filled_blue", size: "large", width: "100%", shape: "pill" });
        }
      } catch (e) { console.error(e); }
    }
  }, [isJoined, isGuestForm]);

  const showToast = (message: string, type: string) => {
    setActiveToast({ message, type });
    setTimeout(() => setActiveToast(null), 6000);
  };

  const sendNotification = (targetEmail: string, type: UserNotification['type'], message: string, runId: string, data: any) => {
    const chatBody = getChatTemplate(type, data);
    const newNotif: UserNotification = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      message,
      chatMessageBody: chatBody,
      runId,
      timestamp: Date.now(),
      read: false
    };

    if (targetEmail === user?.email) {
      const updated = [newNotif, ...notifications];
      setNotifications(updated);
      localStorage.setItem('lunchrun_notifications', JSON.stringify(updated));
      showToast(message, type);
    }

    console.group(`%c GOOGLE CHAT MESSAGE SENT: ${targetEmail} `, 'background: #0b6623; color: #fff; font-weight: bold;');
    console.log(`Context: Space Message / Direct Message`);
    console.log(`Alert: ${message}`);
    console.groupEnd();
  };

  const handleGoogleResponse = (response: any) => {
    const payload = decodeJwt(response.credential);
    if (ALLOWED_DOMAIN !== 'yourcompany.com' && payload.hd !== ALLOWED_DOMAIN) {
      setLoginError(`Only @${ALLOWED_DOMAIN} accounts are permitted.`);
      return;
    }
    setUser({ name: payload.name, email: payload.email, picture: payload.picture, isGuest: false });
    setIsJoined(true);
    logEvent('login');
  };

  const handleGuestLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (guestNameInput.trim()) {
      setUser({ name: guestNameInput.trim(), email: 'guest@internal.local', isGuest: true });
      setIsJoined(true);
      logEvent('login', { method: 'guest' });
    }
  };

  const decodeJwt = (token: string) => {
    try {
      const base64Url = token.split('.')[1];
      const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
      const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2)).join(''));
      return JSON.parse(jsonPayload);
    } catch (e) { return null; }
  };

  const logEvent = (type: AppEvent['type'], metadata?: any) => {
    if (!user) return;
    const newEvent: AppEvent = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      userEmail: user.email,
      timestamp: Date.now(),
      metadata
    };
    const updatedEvents = [newEvent, ...events];
    setEvents(updatedEvents);
    localStorage.setItem('lunchrun_events', JSON.stringify(updatedEvents));
  };

  const createRun = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;

    const matchingWaitlist = waitingOrders.filter(wo => wo.destination.toLowerCase().trim() === newRunDest.toLowerCase().trim());
    const initialOrders: Order[] = matchingWaitlist.slice(0, newRunMax).map(wo => {
        sendNotification(wo.userEmail, 'waitlist_promoted', `You've been added to a run to ${wo.destination}`, 'new_run', {
            userName: wo.userName,
            destination: wo.destination,
            runnerName: user.name,
            itemDescription: wo.itemDescription
        });
        return {
            id: Math.random().toString(36).substr(2, 9),
            userName: wo.userName,
            userEmail: wo.userEmail,
            itemDescription: wo.itemDescription,
            floor: wo.floor,
            cibusCode: '',
            timestamp: Date.now()
        };
    });

    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: user.name,
      runnerEmail: user.email,
      destination: newRunDest,
      departureTime: Date.now() + newRunTime * 60000,
      minutesUntilDeparture: newRunTime,
      maxOrders: newRunMax,
      status: 'active',
      orders: initialOrders
    };

    const remainingWaitlist = waitingOrders.filter(wo => !initialOrders.some(io => io.userEmail === wo.userEmail && io.itemDescription === wo.itemDescription));
    setWaitingOrders(remainingWaitlist);
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(remainingWaitlist));

    setRuns([newRun, ...runs]);
    setShowCreateForm(false);
    setNewRunDest('');
    logEvent('create_run', { destination: newRun.destination });
  };

  const departRun = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run) return;
    setRuns(runs.map(r => r.id === runId ? { ...r, status: 'departed' } : r));

    run.orders.forEach(order => {
        sendNotification(order.userEmail, 'departed', `Google Chat: Runner leaving for ${run.destination}`, runId, {
            userName: order.userName,
            destination: run.destination
        });
    });
    logEvent('depart', { runId });
  };

  const markAsArrived = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run) return;
    const updatedRun: FoodRun = { ...run, status: 'arrived', arrivalLocation: arrivalLoc, arrivalTime: Date.now() };

    run.orders.forEach(order => {
        sendNotification(order.userEmail, 'arrived', `Google Chat: Food from ${run.destination} is here!`, runId, {
            userName: order.userName,
            destination: run.destination,
            location: arrivalLoc || 'Kitchen'
        });
    });

    const updatedHistory = [updatedRun, ...history];
    setHistory(updatedHistory);
    localStorage.setItem('lunchrun_history', JSON.stringify(updatedHistory));
    setRuns(runs.filter(r => r.id !== runId));
    setShowArriveForm(null);
    logEvent('arrival', { runId, destination: run.destination });
  };

  const addToWaitlist = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newWait: WaitingOrder = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      userEmail: user.email,
      destination: newRunDest,
      itemDescription: newOrderItem,
      floor: newOrderFloor,
      timestamp: Date.now()
    };
    const updated = [...waitingOrders, newWait];
    setWaitingOrders(updated);
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(updated));
    setShowWaitlistForm(false);
    setNewRunDest('');
    setNewOrderItem('');
    logEvent('waitlist_add', { destination: newWait.destination });
  };

  const joinRun = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run || !user || run.orders.length >= run.maxOrders) return;
    const newOrder: Order = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      userEmail: user.email,
      itemDescription: newOrderItem,
      cibusCode: '', 
      floor: newOrderFloor,
      timestamp: Date.now()
    };
    setRuns(runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, newOrder] } : r));
    setShowJoinForm(null);
    setNewOrderItem('');
    setNewOrderFloor('');
    logEvent('join_run', { runId, destination: run.destination });
  };

  const submitCibusCode = (e: React.FormEvent) => {
    e.preventDefault();
    if (!showCibusForm || !newCibusInput.trim()) return;

    const { runId, orderId } = showCibusForm;

    setRuns(prevRuns => prevRuns.map(run => {
      if (run.id === runId) {
        return {
          ...run,
          orders: run.orders.map(order => 
            order.id === orderId ? { ...order, cibusCode: newCibusInput } : order
          )
        };
      }
      return run;
    }));

    setNewCibusInput('');
    setShowCibusForm(null);
    logEvent('join_run', { runId, orderId, method: 'cibus_submission' });
  };

  const isAdmin = useMemo(() => user && (ADMIN_EMAILS.includes(user.email) || user.email === 'guest@internal.local'), [user]);
  const unreadCount = notifications.filter(n => !n.read).length;

  const analytics = useMemo(() => {
    const totalOrders = history.reduce((sum, run) => sum + run.orders.length, 0);
    const avgOrders = history.length ? (totalOrders / history.length).toFixed(1) : 0;
    const uniqueUsers = new Set(events.map(e => e.userEmail)).size;
    const destinations: Record<string, number> = {};
    history.forEach(run => { destinations[run.destination] = (destinations[run.destination] || 0) + 1; });
    const topDestinations = Object.entries(destinations).sort((a, b) => b[1] - a[1]).slice(0, 5);
    return { totalOrders, avgOrders, uniqueUsers, topDestinations, totalRuns: history.length };
  }, [history, events]);

  if (!isJoined) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-900 p-4 font-sans">
        <div className="bg-white p-12 rounded-[3.5rem] shadow-2xl w-full max-w-md text-center border border-white/20">
          <div className="w-24 h-24 bg-indigo-600 rounded-[2.5rem] flex items-center justify-center mx-auto mb-8 shadow-2xl shadow-indigo-100">
            <i className="fas fa-bicycle text-white text-4xl"></i>
          </div>
          <h1 className="text-4xl font-black mb-2 tracking-tighter text-slate-900">LunchRun</h1>
          <p className="text-slate-400 mb-12 font-bold uppercase text-[10px] tracking-[0.3em]">Corporate Logistics</p>
          {!isGuestForm ? (
            <div className="space-y-6">
              <div id="googleBtn" className="flex justify-center"></div>
              <button onClick={() => setIsGuestForm(true)} className="text-[11px] text-slate-400 font-black uppercase tracking-widest hover:text-indigo-600 transition-colors">Internal Guest Access</button>
            </div>
          ) : (
            <form onSubmit={handleGuestLogin} className="space-y-6 text-left animate-in slide-in-from-right-10 duration-500">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-2 block">Display Name</label>
                <input required className="w-full p-5 bg-slate-50 border-2 rounded-2xl outline-none font-bold text-lg" placeholder="e.g. David Levi" value={guestNameInput} onChange={e => setGuestNameInput(e.target.value)} />
              </div>
              <Button type="submit" className="w-full h-18 bg-indigo-600 rounded-2xl shadow-xl shadow-indigo-100 text-sm font-black uppercase">Authenticate</Button>
              <button type="button" onClick={() => setIsGuestForm(false)} className="w-full text-center text-[10px] font-black text-slate-400 uppercase">Back to SSO</button>
            </form>
          )}
          {loginError && <p className="mt-6 text-red-500 text-xs font-bold bg-red-50 p-4 rounded-2xl">{loginError}</p>}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC]">
      {/* Toast System */}
      {activeToast && (
          <div className="fixed top-8 left-1/2 -translate-x-1/2 z-[100] animate-in slide-in-from-top-16 duration-500">
              <div className={`px-8 py-5 rounded-3xl shadow-[0_20px_50px_rgba(0,0,0,0.15)] flex items-center gap-5 backdrop-blur-xl border border-white/20 min-w-[320px] bg-slate-900 text-white`}>
                  <div className="w-12 h-12 rounded-2xl bg-white/20 flex items-center justify-center text-xl shrink-0">
                      <i className="fas fa-comment-dots text-green-400"></i>
                  </div>
                  <div className="flex-1 pr-4">
                      <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-60">Google Chat Notification</p>
                      <p className="font-bold text-sm tracking-tight leading-snug">{activeToast.message}</p>
                  </div>
                  <button onClick={() => setActiveToast(null)} className="opacity-40 hover:opacity-100 transition-opacity"><i className="fas fa-times text-lg"></i></button>
              </div>
          </div>
      )}

      {/* Preview Chat Modal */}
      {previewChat && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-xl z-[100] flex items-center justify-center p-4">
           <div className="max-w-xl w-full bg-[#f1f3f4] rounded-[2rem] overflow-hidden shadow-2xl animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]">
              <div className="p-5 bg-white border-b flex justify-between items-center">
                 <div className="flex items-center gap-3">
                    <div className="w-8 h-8 bg-green-700 rounded-lg flex items-center justify-center text-white text-xs"><i className="fas fa-comments"></i></div>
                    <div>
                      <h3 className="font-bold text-slate-800 text-sm">Google Chat Space</h3>
                      <p className="text-[10px] font-medium text-slate-400">LunchRun Internal Bot</p>
                    </div>
                 </div>
                 <button onClick={() => setPreviewChat(null)} className="w-8 h-8 rounded-full hover:bg-slate-100 transition-colors flex items-center justify-center text-slate-400"><i className="fas fa-times"></i></button>
              </div>
              <div className="flex-1 overflow-y-auto p-10 flex items-start justify-center">
                 <div dangerouslySetInnerHTML={{ __html: previewChat.chatMessageBody || '' }} className="w-full" />
              </div>
              <div className="p-6 bg-white border-t text-center">
                 <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4 italic">This simulates a message received in your company's Google Chat Space.</p>
                 <Button onClick={() => setPreviewChat(null)} className="mx-auto h-12 px-8 rounded-xl bg-green-700 text-white font-bold text-xs uppercase tracking-widest">Back to Portal</Button>
              </div>
           </div>
        </div>
      )}

