              <div>
                <label className="block text-[11px] font-black text-slate-400 uppercase tracking-[0.4em] mb-4 ml-4">Specific Order</label>
                <input required className="w-full p-8 bg-slate-50 border-2 rounded-[3rem] font-black outline-none text-2xl shadow-inner" placeholder="e.g. Caesar Salad" value={newOrderItem} onChange={e => setNewOrderItem(e.target.value)} />
              </div>
              <div>
                <label className="block text-[11px] font-black text-slate-400 uppercase tracking-[0.4em] mb-4 ml-4">Floor</label>
                <input required className="w-full p-8 bg-slate-50 border-2 rounded-[3rem] font-black outline-none text-2xl shadow-inner" placeholder="5" value={newOrderFloor} onChange={e => setNewOrderFloor(e.target.value)} />
