export interface ImageGenerationConfig {
  aspectRatio: '1:1' | '3:4' | '4:3' | '9:16' | '16:9';
  imageSize: '1K' | '2K' | '4K';
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { FoodRun, Order, AppEvent, WaitingOrder, UserNotification } from './types';
import { Button } from './components/Button';

// --- Compact Google Chat Templates ---
const getChatTemplate = (type: UserNotification['type'], data: any) => {
  const containerStyle = "max-width: 300px; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 12px; font-family: sans-serif; overflow: hidden; box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1); text-align: left;";
  const headerStyle = "padding: 8px 12px; border-bottom: 1px solid #f1f3f4; display: flex; align-items: center; gap: 8px; background: #f8fafc; font-size: 11px; font-weight: 700; color: #64748b; text-transform: uppercase;";
  const bodyStyle = "padding: 12px; font-size: 13px; color: #1e293b; line-height: 1.4;";
  const highlightStyle = "margin: 8px 0; padding: 8px; background: #f1f5f9; border-radius: 6px; font-weight: 600; border-left: 3px solid #6366f1; font-size: 12px;";
  const btnStyle = (color: string) => `display: inline-block; padding: 6px 12px; background: ${color}; color: white; border-radius: 6px; text-decoration: none; font-size: 10px; font-weight: 800; margin-top: 8px; text-transform: uppercase; letter-spacing: 0.05em;`;

  const templates = {
    waitlist_promoted: `
      <div style="${containerStyle}">
        <div style="${headerStyle}"><i class="fas fa-robot"></i> LunchRun Bot</div>
        <div style="${bodyStyle}">
          Great news! <b>${data.runnerName}</b> added you to the run to <b>${data.destination}</b>.
          <div style="${highlightStyle}">${data.itemDescription}</div>
        </div>
      </div>
    `,
    departed: `
      <div style="${containerStyle}">
        <div style="${headerStyle}"><i class="fas fa-bolt"></i> Departure Alert</div>
        <div style="${bodyStyle}">
          Mission to <b>${data.destination}</b> is departing! Please provide payment code now.
          <div style="text-align: center;"><a href="#" style="${btnStyle('#4f46e5')}">Provide Code</a></div>
        </div>
      </div>
    `,
    arrived: `
      <div style="${containerStyle}">
        <div style="${headerStyle}"><i class="fas fa-map-marker-alt"></i> Delivery Ready</div>
        <div style="${bodyStyle}">
          Your meal is waiting at: <br/><b>${data.location}</b>
          <div style="text-align: center;"><a href="#" style="${btnStyle('#059669')}">I'm on my way</a></div>
        </div>
      </div>
    `
  };
  return templates[type] || '';
};

const App: React.FC = () => {
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [notifications, setNotifications] = useState<UserNotification[]>([]);
  const [simulatorMode, setSimulatorMode] = useState(false);

  useEffect(() => {
    const savedHistory = localStorage.getItem('lunchrun_history');
    const savedWaitlist = localStorage.getItem('lunchrun_waitlist');
    const savedNotifications = localStorage.getItem('lunchrun_notifications');
    const savedRuns = localStorage.getItem('lunchrun_active_runs');

    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedWaitlist) setWaitingOrders(JSON.parse(savedWaitlist));
    if (savedNotifications) setNotifications(JSON.parse(savedNotifications));
    if (savedRuns) setRuns(JSON.parse(savedRuns));
  }, []);

  // Sync to localstorage for persistence even in simulation
  useEffect(() => {
    localStorage.setItem('lunchrun_active_runs', JSON.stringify(runs));
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(waitingOrders));
    localStorage.setItem('lunchrun_notifications', JSON.stringify(notifications));
    localStorage.setItem('lunchrun_history', JSON.stringify(history));
  }, [runs, waitingOrders, notifications, history]);

  const sharedActions = {
    runs, setRuns,
    history, setHistory,
    waitingOrders, setWaitingOrders,
    notifications, setNotifications,
  };

  return (
    <div className={`min-h-screen bg-slate-50 transition-all duration-500 ${simulatorMode ? 'p-2 sm:p-4 bg-slate-200' : ''}`}>
      {/* QA Toolbar - Always visible but discreet */}
      <div className="bg-slate-900 text-white/70 px-6 py-2 flex justify-between items-center text-[10px] font-black uppercase tracking-[0.2em] shadow-xl sticky top-0 z-[100] rounded-b-xl sm:mx-4">
        <div className="flex items-center gap-4">
          <div className="w-2 h-2 bg-indigo-400 rounded-full animate-pulse"></div>
          <span>Environment: Internal QA</span>
        </div>
        <div className="flex gap-4">
           <button onClick={() => setSimulatorMode(!simulatorMode)} className={`px-4 py-1.5 rounded-full border transition-all ${simulatorMode ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'border-slate-700 hover:text-white hover:border-slate-500'}`}>
             {simulatorMode ? 'Close Simulator' : 'Split-Screen QA'}
           </button>
           <button onClick={() => { localStorage.clear(); window.location.reload(); }} className="px-4 py-1.5 rounded-full border border-red-900/50 text-red-400/80 hover:text-red-400 hover:bg-red-900/20">
             Wipe State
           </button>
        </div>
      </div>

      {simulatorMode ? (
        <div className="flex flex-col md:flex-row h-[calc(100vh-80px)] gap-4 mt-4 overflow-hidden">
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-indigo-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Instance A: Avi (Runner)</div>
             <AppInstance userOverride={{ name: 'Avi', email: 'avi@office.com' }} {...sharedActions} />
          </div>
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-emerald-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Instance B: Dana (Orderer)</div>
             <AppInstance userOverride={{ name: 'Dana', email: 'dana@office.com' }} {...sharedActions} />
          </div>
        </div>
      ) : (
        <div className="max-w-4xl mx-auto mt-6">
          <AppInstance {...sharedActions} />
        </div>
      )}
    </div>
  );
};

const AppInstance: React.FC<any> = ({ 
  userOverride, 
  runs, setRuns, 
  history, setHistory, 
  waitingOrders, setWaitingOrders, 
  notifications, setNotifications 
}) => {
  const [user, setUser] = useState<{ name: string; email: string; isGuest?: boolean } | null>(userOverride || null);
  const [activeToast, setActiveToast] = useState<{message: string, type: string} | null>(null);
  const lastNotifId = useRef<string | null>(null);

  // Modal States
  const [modals, setModals] = useState<{ [key: string]: boolean | any }>({
    create: false, waitlist: false, join: null, cibus: null, arrive: null, notifs: false, preview: null
  });

  // Inputs
  const [inputs, setInputs] = useState({ dest: '', time: 20, max: 5, item: '', floor: '', cibus: '', loc: '' });

  // Handle Incoming Notifications (Simulation logic)
  useEffect(() => {
    if (!user) return;
    const userNotifs = notifications.filter((n: UserNotification) => n.targetEmail === user.email);
    const newest = userNotifs[0];

    if (newest && newest.id !== lastNotifId.current) {
       lastNotifId.current = newest.id;
       setActiveToast({ message: newest.message, type: newest.type });
       setTimeout(() => setActiveToast(null), 4000);
    }
  }, [notifications, user]);

  const triggerBroadcast = (targetEmail: string, type: UserNotification['type'], message: string, data: any) => {
    const chatBody = getChatTemplate(type, data);
    const newNotif: UserNotification = {
      id: Math.random().toString(36).substr(2, 9),
      targetEmail, type, message, chatMessageBody: chatBody, runId: 'sys', timestamp: Date.now(), read: false
    };
    setNotifications((prev: any) => [newNotif, ...prev]);
  };

  const actions = {
    createRun: (e: React.FormEvent) => {
      e.preventDefault();
      const match = waitingOrders.filter(wo => wo.destination.toLowerCase() === inputs.dest.toLowerCase());
      const selected = match.slice(0, inputs.max);

      const orders: Order[] = selected.map(wo => {
        triggerBroadcast(wo.userEmail, 'waitlist_promoted', `You're in! Run to ${wo.destination} started`, {
          runnerName: user?.name, destination: wo.destination, itemDescription: wo.itemDescription
        });
        return { id: wo.id, userName: wo.userName, userEmail: wo.userEmail, itemDescription: wo.itemDescription, floor: wo.floor, cibusCode: '', timestamp: Date.now() };
      });

      const newRun: FoodRun = {
        id: Math.random().toString(36).substr(2, 9), runnerName: user?.name || '', runnerEmail: user?.email || '',
        destination: inputs.dest, departureTime: Date.now() + inputs.time * 60000, minutesUntilDeparture: inputs.time,
        maxOrders: inputs.max, status: 'active', orders
      };

      setWaitingOrders((prev: any) => prev.filter((wo: any) => !orders.some(o => o.userEmail === wo.userEmail)));
      setRuns((prev: any) => [newRun, ...prev]);
      setModals({ ...modals, create: false });
      setInputs({ ...inputs, dest: '' });
    },
    depart: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, status: 'departed' } : r));
      run.orders.forEach((o: any) => triggerBroadcast(o.userEmail, 'departed', `Payment required for ${run.destination}`, { destination: run.destination }));
    },
    arrive: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      const updatedRun = { ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() };
      run.orders.forEach((o: any) => triggerBroadcast(o.userEmail, 'arrived', `Food is here! Pick up at ${inputs.loc}`, { destination: run.destination, location: inputs.loc }));
      setHistory((prev: any) => [updatedRun, ...prev]);
      setRuns(runs.filter((r: any) => r.id !== runId));
      setModals({ ...modals, arrive: null });
      setInputs({ ...inputs, loc: '' });
    },
    join: (runId: string) => {
      const order: Order = { id: Math.random().toString(36).substr(2, 9), userName: user?.name || '', userEmail: user?.email || '', itemDescription: inputs.item, floor: inputs.floor, cibusCode: '', timestamp: Date.now() };
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: [...r.orders, order] } : r));
      setModals({ ...modals, join: null });
      setInputs({ ...inputs, item: '', floor: '' });
    },
    waitlist: (e: React.FormEvent) => {
      e.preventDefault();
      const wo: WaitingOrder = { id: Math.random().toString(36).substr(2, 9), userName: user?.name || '', userEmail: user?.email || '', destination: inputs.dest, itemDescription: inputs.item, floor: inputs.floor, timestamp: Date.now() };
      setWaitingOrders((prev: any) => [...prev, wo]);
      setModals({ ...modals, waitlist: false });
      setInputs({ ...inputs, dest: '', item: '', floor: '' });
    },
    pay: (e: React.FormEvent) => {
      e.preventDefault();
      const { runId, orderId } = modals.cibus;
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: r.orders.map((o: any) => o.id === orderId ? { ...o, cibusCode: inputs.cibus } : o) } : r));
      setModals({ ...modals, cibus: null });
      setInputs({ ...inputs, cibus: '' });
    }
  };

  const userNotifs = notifications.filter((n: any) => n.targetEmail === user?.email);
  const unreadCount = userNotifs.filter((n: any) => !n.read).length;

  if (!user) return <div className="h-full flex items-center justify-center"><Button onClick={() => setUser({name: 'Tester', email: 'test@office.com'})}>Sign In</Button></div>;

  return (
    <div className="h-full flex flex-col bg-slate-50 relative">
      {/* Mini Toast */}
      {activeToast && (
        <div className="absolute top-16 left-1/2 -translate-x-1/2 z-[100] animate-in slide-in-from-top-4 duration-300">
          <div className="bg-slate-900 text-white px-4 py-2 rounded-xl shadow-2xl flex items-center gap-3 border border-indigo-500/30">
             <i className="fas fa-comment-dots text-indigo-400"></i>
             <div className="text-[10px] font-black uppercase tracking-widest">{activeToast.message}</div>
          </div>
        </div>
      )}

      {/* Internal Preview Modal */}
      {modals.preview && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[150] flex items-center justify-center p-4" onClick={() => setModals({...modals, preview: null})}>
           <div className="animate-in zoom-in-95 duration-200" onClick={e => e.stopPropagation()}>
              <div dangerouslySetInnerHTML={{ __html: modals.preview.chatMessageBody || '' }} />
              <button onClick={() => setModals({...modals, preview: null})} className="mt-4 w-full py-2 bg-white/20 text-white rounded-lg text-[10px] font-black uppercase tracking-widest hover:bg-white/30 transition-colors">Dismiss</button>
           </div>
        </div>
      )}

      {/* Instance Header */}
      <header className="bg-white px-6 py-4 flex justify-between items-center border-b border-slate-100">
        <div className="flex items-center gap-3">
           <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white text-sm"><i className="fas fa-rocket"></i></div>
           <span className="font-black text-sm tracking-tighter text-slate-800">LUNCHRUN</span>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setModals({...modals, notifs: !modals.notifs})} className="relative w-8 h-8 rounded-lg bg-slate-50 flex items-center justify-center text-slate-400 hover:text-indigo-600 transition-colors">
             <i className="fas fa-bell text-xs"></i>
             {unreadCount > 0 && <span className="absolute -top-1 -right-1 w-4 h-4 bg-indigo-600 text-white rounded-full text-[8px] flex items-center justify-center font-bold border-2 border-white">{unreadCount}</span>}
          </button>
          <img src={`https://ui-avatars.com/api/?name=${user.name}&background=6366f1&color=fff`} className="w-8 h-8 rounded-lg border shadow-sm" alt="u" />
        </div>
      </header>

      {/* Notification Center Popover */}
      {modals.notifs && (
        <div className="absolute right-4 top-16 w-64 bg-white border border-slate-200 shadow-2xl rounded-2xl overflow-hidden z-[90] animate-in slide-in-from-top-2">
           <div className="p-3 bg-slate-50 text-[9px] font-black uppercase tracking-widest text-slate-400 border-b flex justify-between items-center">
             <span>Recent Activity</span>
             <button onClick={() => setModals({...modals, notifs: false})}><i className="fas fa-times"></i></button>
           </div>
           <div className="max-h-60 overflow-y-auto">
             {userNotifs.length === 0 ? <p className="p-8 text-center text-[10px] text-slate-300 font-bold uppercase">Inbox Empty</p> : 
               userNotifs.map((n: any) => (
                 <div key={n.id} onClick={() => { setNotifications(notifications.map((x: any) => x.id === n.id ? {...x, read: true} : x)); setModals({...modals, preview: n, notifs: false}); }} className={`p-3 border-b last:border-0 cursor-pointer hover:bg-slate-50 flex gap-3 ${!n.read ? 'bg-indigo-50/30' : ''}`}>
                    <div className="w-6 h-6 rounded bg-indigo-100 text-indigo-600 flex items-center justify-center text-[10px] shrink-0"><i className="fas fa-envelope-open"></i></div>
                    <div>
                      <p className="text-[10px] font-bold text-slate-600 leading-tight">{n.message}</p>
                      <p className="text-[8px] text-slate-300 mt-1 uppercase font-black">{new Date(n.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</p>
                    </div>
                 </div>
               ))
             }
           </div>
        </div>
      )}

      {/* Main Content Area */}
      <main className="flex-1 overflow-y-auto p-4 space-y-4">
        {/* Compact Action Bar */}
        <div className="bg-white p-3 rounded-2xl shadow-sm border border-slate-100 flex justify-between items-center">
           <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Team Mission Control</span>
           <div className="flex gap-2">
             <Button onClick={() => setModals({...modals, waitlist: true})} variant="ghost" className="h-9 px-4 text-[9px] font-black uppercase rounded-lg border border-slate-100">Waitlist</Button>
             <Button onClick={() => setModals({...modals, create: true})} className="h-9 px-4 text-[9px] font-black uppercase rounded-lg bg-indigo-600">Start Run</Button>
           </div>
        </div>

        {/* Runs Feed */}
        <div className="grid gap-4">
           {runs.length === 0 && (
             <div className="text-center py-16 opacity-30">
                <i className="fas fa-pizza-slice text-3xl mb-4 text-slate-200"></i>
                <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">No active runs nearby</p>
             </div>
           )}

           {runs.map((run: FoodRun) => {
             const isRunner = user.email === run.runnerEmail;
             const myOrder = run.orders.find(o => o.userEmail === user.email);
