               <div key={run.id} className={`bg-white rounded-2xl p-5 shadow-sm border-2 transition-all ${run.status === 'departed' ? 'border-indigo-500 shadow-indigo-100 shadow-xl' : 'border-white hover:border-slate-100'}`}>
                 <div className="flex justify-between items-start mb-4">
                    <div className="flex gap-3">
                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-lg ${run.status === 'departed' ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-400'}`}>
                         <i className={`fas ${run.status === 'departed' ? 'fa-running' : 'fa-store'}`}></i>
                      </div>
                      <div>
                        <h4 className="text-sm font-black text-slate-800">{run.destination}</h4>
                        <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Lead: {run.runnerName} • {run.minutesUntilDeparture}m window</p>
                      </div>
