    background: '#f8fafc',
    fontSize: '11px',
    fontWeight: '700',
    color: '#64748b',
    textTransform: 'uppercase'
  };

  const bodyStyle: React.CSSProperties = {
    padding: '12px',
    fontSize: '13px',
    color: '#1e293b',
    lineHeight: '1.4'
