    borderRadius: '8px',
    fontSize: '10px',
    fontWeight: '900',
    textTransform: 'uppercase',
    letterSpacing: '0.05em',
    transition: 'all 0.2s ease',
    boxShadow: '0 1px 2px 0 rgba(0, 0, 0, 0.05)',
    border: 'none',
    cursor: 'pointer'
  };

  return (
    <div className="animate-in zoom-in-95 duration-200" style={{ pointerEvents: 'auto' }}>
      <div style={containerStyle}>
        <div style={headerStyle}>
          <i className={`fas ${type === 'departed' ? 'fa-bolt text-amber-500' : type === 'arrived' ? 'fa-map-marker-alt text-emerald-500' : 'fa-robot text-indigo-500'}`}></i>
          <span>LunchRun Bot</span>
        </div>
        <div style={bodyStyle}>
          <p className="font-medium">{message}</p>

          {type === 'departed' && (
            <button 
              onClick={() => onAction('open_pay')} 
              style={{ ...btnBaseStyle, backgroundColor: '#4f46e5' }}
              className="hover:brightness-110 active:scale-95"
            >
              Provide Payment Code
            </button>
          )}

          {type === 'arrived' && (
            <button 
              onClick={() => onAction('close')} 
              style={{ ...btnBaseStyle, backgroundColor: '#059669' }}
              className="hover:brightness-110 active:scale-95"
            >
              I'm on my way!
            </button>
          )}

          {type === 'waitlist_promoted' && (
             <button 
               onClick={() => onAction('close')} 
               style={{ ...btnBaseStyle, backgroundColor: '#475569' }}
               className="hover:brightness-110 active:scale-95"
             >
              Got it
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [notifications, setNotifications] = useState<UserNotification[]>([]);
  const [simulatorMode, setSimulatorMode] = useState(false);
  const [webhookUrl, setWebhookUrl] = useState<string>(localStorage.getItem('lunchrun_webhook') || '');
  const [isSimulatorAdmin, setIsSimulatorAdmin] = useState(false);

  useEffect(() => {
    const savedHistory = localStorage.getItem('lunchrun_history');
    const savedWaitlist = localStorage.getItem('lunchrun_waitlist');
    const savedNotifications = localStorage.getItem('lunchrun_notifications');
    const savedRuns = localStorage.getItem('lunchrun_active_runs');

    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedWaitlist) setWaitingOrders(JSON.parse(savedWaitlist));
    if (savedNotifications) setNotifications(JSON.parse(savedNotifications));
    if (savedRuns) setRuns(JSON.parse(savedRuns));
  }, []);

  useEffect(() => {
    localStorage.setItem('lunchrun_active_runs', JSON.stringify(runs));
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(waitingOrders));
    localStorage.setItem('lunchrun_notifications', JSON.stringify(notifications));
    localStorage.setItem('lunchrun_history', JSON.stringify(history));
    localStorage.setItem('lunchrun_webhook', webhookUrl);
  }, [runs, waitingOrders, notifications, history, webhookUrl]);

  const sharedActions = {
    runs, setRuns,
    history, setHistory,
    waitingOrders, setWaitingOrders,
    notifications, setNotifications,
    webhookUrl, setWebhookUrl,
    isSimulatorAdmin
  };

  return (
    <div className={`min-h-screen bg-slate-50 transition-all duration-500 ${simulatorMode ? 'p-2 sm:p-4 bg-slate-200' : ''}`}>
      {/* QA Toolbar */}
      <div className="bg-slate-900 text-white/70 px-6 py-2 flex justify-between items-center text-[10px] font-black uppercase tracking-[0.2em] shadow-xl sticky top-0 z-[100] rounded-b-xl sm:mx-4">
        <div className="flex items-center gap-4">
          <div className="w-2 h-2 bg-indigo-400 rounded-full animate-pulse"></div>
          <span>LunchRun Network</span>
        </div>
        <div className="flex gap-4">
           {simulatorMode && (
             <button 
               onClick={() => setIsSimulatorAdmin(!isSimulatorAdmin)} 
               className={`px-4 py-1.5 rounded-full border transition-all ${isSimulatorAdmin ? 'bg-amber-500 border-amber-400 text-slate-900 shadow-lg' : 'border-slate-700 hover:text-white'}`}
             >
               {isSimulatorAdmin ? 'Admin: ON' : 'Become Admin'}
             </button>
           )}
           <button onClick={() => setSimulatorMode(!simulatorMode)} className={`px-4 py-1.5 rounded-full border transition-all ${simulatorMode ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'border-slate-700 hover:text-white hover:border-slate-500'}`}>
             {simulatorMode ? 'Exit QA' : 'Split-Screen QA'}
           </button>
           <button onClick={() => { localStorage.clear(); window.location.reload(); }} className="px-4 py-1.5 rounded-full border border-red-900/50 text-red-400/80 hover:text-red-400 hover:bg-red-900/20">
             Reset
           </button>
        </div>
      </div>

      {simulatorMode ? (
        <div className="flex flex-col md:flex-row h-[calc(100vh-80px)] gap-4 mt-4 overflow-hidden">
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-indigo-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Persona: Avi (Runner)</div>
             <AppInstance userOverride={{ name: 'Avi', email: `avi@${ALLOWED_DOMAIN}` }} {...sharedActions} />
          </div>
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-emerald-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Persona: Dana (Orderer)</div>
             <AppInstance userOverride={{ name: 'Dana', email: `dana@${ALLOWED_DOMAIN}` }} {...sharedActions} />
          </div>
        </div>
      ) : (
        <div className="max-w-4xl mx-auto mt-6">
          <AppInstance {...sharedActions} />
        </div>
      )}
    </div>
  );
};

const AppInstance: React.FC<any> = ({ 
  userOverride, 
  runs, setRuns, 
  history, setHistory, 
  waitingOrders, setWaitingOrders, 
  notifications, setNotifications,
  webhookUrl, setWebhookUrl,
  isSimulatorAdmin
}) => {
  const [user, setUser] = useState<{ name: string; email: string; isAdmin?: boolean } | null>(userOverride || null);
  const [activeToast, setActiveToast] = useState<{message: string, type: string} | null>(null);
  const [authError, setAuthError] = useState<string | null>(null);
  const lastNotifId = useRef<string | null>(null);

  const [modals, setModals] = useState<{ [key: string]: boolean | any }>({
    create: false, waitlist: false, join: null, cibus: null, arrive: null, notifs: false, preview: null, admin: false
  });

  const [inputs, setInputs] = useState({ dest: '', time: 20, max: 5, item: '', floor: '', cibus: '', loc: '' });

  useEffect(() => {
    if (userOverride || user) return;

    const handleCredentialResponse = (response: any) => {
      try {
        const payload = JSON.parse(atob(response.credential.split('.')[1]));
        const email = payload.email;
        const domain = email.split('@')[1];

        if (domain !== ALLOWED_DOMAIN) {
          setAuthError(`Only @${ALLOWED_DOMAIN} accounts are allowed.`);
          return;
        }

        setUser({
          name: payload.name,
          email: email,
          isAdmin: email === ADMIN_EMAIL
        });
        setAuthError(null);
      } catch (e) {
        setAuthError("Auth failed. Please try again.");
      }
    };

    if ((window as any).google) {
      (window as any).google.accounts.id.initialize({
        client_id: "YOUR_GOOGLE_CLIENT_ID.apps.googleusercontent.com",
        callback: handleCredentialResponse
      });
      (window as any).google.accounts.id.renderButton(
        document.getElementById("googleBtn"),
        { theme: "outline", size: "large", width: "320" }
      );
    }
  }, [user, userOverride]);

  useEffect(() => {
    if (!user) return;
    const userNotifs = notifications.filter((n: UserNotification) => n.targetEmail === user.email);
    const newest = userNotifs[0];

    if (newest && newest.id !== lastNotifId.current) {
       lastNotifId.current = newest.id;
       setActiveToast({ message: newest.message, type: newest.type });
       setTimeout(() => setActiveToast(null), 5000);
    }
  }, [notifications, user]);

  const triggerBroadcast = (targetEmail: string, type: UserNotification['type'], message: string) => {
    const newNotif: UserNotification = {
      id: Math.random().toString(36).substr(2, 9),
      targetEmail, type, message, runId: 'sys', timestamp: Date.now(), read: false
    };
    setNotifications((prev: any) => [newNotif, ...prev]);
  };

  const actions = {
    createRun: (e: React.FormEvent) => {
      e.preventDefault();
      const match = waitingOrders.filter(wo => wo.destination.toLowerCase() === inputs.dest.toLowerCase());
      const selected = match.slice(0, inputs.max);

      const orders: Order[] = selected.map(wo => {
        triggerBroadcast(wo.userEmail, 'waitlist_promoted', `Added to run: ${wo.destination} by ${user?.name}`);
        return { id: wo.id, userName: wo.userName, userEmail: wo.userEmail, itemDescription: wo.itemDescription, floor: wo.floor, cibusCode: '', timestamp: Date.now() };
      });

      const newRun: FoodRun = {
        id: Math.random().toString(36).substr(2, 9), runnerName: user?.name || '', runnerEmail: user?.email || '',
        destination: inputs.dest, departureTime: Date.now() + inputs.time * 60000, minutesUntilDeparture: inputs.time,
        maxOrders: inputs.max, status: 'active', orders
      };

      setWaitingOrders((prev: any) => prev.filter((wo: any) => !orders.some(o => o.userEmail === wo.userEmail)));
      setRuns((prev: any) => [newRun, ...prev]);
      setModals({ ...modals, create: false });

      // BROADCAST TO GOOGLE CHAT
      if (webhookUrl) {
        sendToGoogleChat(webhookUrl, {
          title: "New Run Initiated!",
          subtitle: `Destination: ${inputs.dest}`,
          details: `Lead by <b>${user?.name}</b>. Departing in ${inputs.time} mins. Slots: ${inputs.max}.`,
          buttonText: "Join Manifest",
          buttonUrl: window.location.href
        });
      }

      setInputs({ ...inputs, dest: '' });
    },
    depart: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, status: 'departed' } : r));
      run.orders.forEach((o: any) => triggerBroadcast(o.userEmail, 'departed', `Runner leaving for ${run.destination}! Pay now.`));

      if (webhookUrl) {
        sendToGoogleChat(webhookUrl, {
          title: "Run Departed!",
          subtitle: `En route to ${run.destination}`,
          details: `Mission lead by ${run.runnerName}. Members should provide payment codes now.`,
          buttonText: "Pay with Cibus",
          buttonUrl: window.location.href
        });
      }
    },
    arrive: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      const updatedRun = { ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() };
      run.orders.forEach((o: any) => triggerBroadcast(o.userEmail, 'arrived', `Food is at ${inputs.loc}!`));
      setHistory((prev: any) => [updatedRun, ...prev]);
      setRuns(runs.filter((r: any) => r.id !== runId));
      setModals({ ...modals, arrive: null });

      if (webhookUrl) {
        sendToGoogleChat(webhookUrl, {
          title: "Delivery Arrived!",
          subtitle: `Food from ${run.destination} is here`,
          details: `Pick up your order at: <b>${inputs.loc}</b>.`,
          buttonText: "View My Order",
          buttonUrl: window.location.href
        });
      }
    },
    join: (runId: string) => {
      const order: Order = { id: Math.random().toString(36).substr(2, 9), userName: user?.name || '', userEmail: user?.email || '', itemDescription: inputs.item, floor: inputs.floor, cibusCode: '', timestamp: Date.now() };
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: [...r.orders, order] } : r));
      setModals({ ...modals, join: null });
    },
    waitlist: (e: React.FormEvent) => {
      e.preventDefault();
      const wo: WaitingOrder = { id: Math.random().toString(36).substr(2, 9), userName: user?.name || '', userEmail: user?.email || '', destination: inputs.dest, itemDescription: inputs.item, floor: inputs.floor, timestamp: Date.now() };
      setWaitingOrders((prev: any) => [...prev, wo]);
      setModals({ ...modals, waitlist: false });
    },
    pay: (e: React.FormEvent) => {
      e.preventDefault();
      const { runId, orderId } = modals.cibus;
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: r.orders.map((o: any) => o.id === orderId ? { ...o, cibusCode: inputs.cibus } : o) } : r));
      setModals({ ...modals, cibus: null });
      setInputs({ ...inputs, cibus: '' });
    },
    handleNotifAction: (action: string) => {
      if (action === 'open_pay') {
        const myActiveRun = runs.find(r => r.orders.some(o => o.userEmail === user?.email));
        const myOrder = myActiveRun?.orders.find(o => o.userEmail === user?.email);
        if (myActiveRun && myOrder) {
          setModals({ ...modals, preview: null, cibus: { runId: myActiveRun.id, orderId: myOrder.id } });
        } else {
          setModals({ ...modals, preview: null });
        }
      } else {
        setModals({ ...modals, preview: null });
      }
    }
  };

  const userNotifs = notifications.filter((n: any) => n.targetEmail === user?.email);
  const unreadCount = userNotifs.filter((n: any) => !n.read).length;

  // Final admin check: real login OR simulator override
  const isAdmin = user?.isAdmin || isSimulatorAdmin;

  if (!user) {
    return (
      <div className="h-full flex flex-col items-center justify-center p-8 bg-white">
        <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-3xl mb-6 shadow-xl"><i className="fas fa-bicycle"></i></div>
        <h1 className="text-2xl font-black tracking-tighter mb-2 text-slate-800">Welcome to LunchRun</h1>
        <p className="text-slate-400 text-sm mb-8 text-center max-w-xs">Coordinate food runs with your colleagues. <br/>Limited to <b>@{ALLOWED_DOMAIN}</b></p>
        <div id="googleBtn" className="mb-4"></div>
        {authError && <p className="text-red-500 text-xs font-bold mt-2 bg-red-50 px-3 py-1 rounded-full animate-bounce">{authError}</p>}
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col bg-slate-50 relative">
      {/* Simulation Toasts */}
      {activeToast && (
        <div className="absolute top-16 left-1/2 -translate-x-1/2 z-[100] animate-in slide-in-from-top-4 duration-300">
          <div onClick={() => setModals({...modals, notifs: true})} className="cursor-pointer bg-slate-900 text-white px-4 py-3 rounded-2xl shadow-2xl flex items-center gap-4 border border-indigo-500/50">
             <div className="w-8 h-8 rounded-xl bg-indigo-500 flex items-center justify-center text-xs"><i className="fas fa-comment"></i></div>
             <div>
                <p className="text-[9px] font-black uppercase text-indigo-400">Incoming Message</p>
                <p className="text-[11px] font-bold">{activeToast.message}</p>
             </div>
          </div>
        </div>
      )}

      {/* Notification Modal */}
      {modals.preview && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[150] flex items-center justify-center p-4">
           <ChatPreviewContent notification={modals.preview} onAction={actions.handleNotifAction} />
        </div>
      )}

      <header className="bg-white px-6 py-4 flex justify-between items-center border-b border-slate-100">
        <div className="flex items-center gap-3">
           <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white text-sm shadow-indigo-200 shadow-lg"><i className="fas fa-rocket"></i></div>
           <div>
             <span className="font-black text-sm tracking-tighter text-slate-800 block leading-none">LUNCHRUN</span>
             {isAdmin && (
               <button 
                 onClick={() => setModals({...modals, admin: true})} 
                 className="text-[8px] font-black text-indigo-600 uppercase tracking-widest mt-0.5 hover:bg-indigo-50 px-1 rounded transition-colors"
               >
                 Admin Setup <i className="fas fa-cog ml-1"></i>
               </button>
             )}
           </div>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setModals({...modals, notifs: !modals.notifs})} className="relative w-8 h-8 rounded-xl bg-slate-50 flex items-center justify-center text-slate-400 hover:text-indigo-600 transition-colors">
             <i className="fas fa-bell text-xs"></i>
             {unreadCount > 0 && <span className="absolute -top-1 -right-1 w-4 h-4 bg-indigo-600 text-white rounded-full text-[8px] flex items-center justify-center font-bold border-2 border-white">{unreadCount}</span>}
          </button>
          <img src={`https://ui-avatars.com/api/?name=${user.name}&background=6366f1&color=fff`} className="w-8 h-8 rounded-xl border-2 border-white shadow-sm" alt="u" />
        </div>
      </header>

      {modals.notifs && (
        <div className="absolute right-4 top-16 w-72 bg-white border border-slate-200 shadow-2xl rounded-2xl overflow-hidden z-[90] animate-in slide-in-from-top-2">
           <div className="p-4 bg-slate-50 text-[9px] font-black uppercase tracking-[0.2em] text-slate-400 border-b flex justify-between items-center">
             <span>Live Activity</span>
             <button onClick={() => setModals({...modals, notifs: false})} className="text-slate-400 hover:text-slate-600"><i className="fas fa-times"></i></button>
           </div>
           <div className="max-h-80 overflow-y-auto">
             {userNotifs.length === 0 ? <p className="p-12 text-center text-[10px] text-slate-300 font-black uppercase">No Recent Alerts</p> : 
               userNotifs.map((n: any) => (
                 <div key={n.id} onClick={() => { setNotifications(notifications.map((x: any) => x.id === n.id ? {...x, read: true} : x)); setModals({...modals, preview: n, notifs: false}); }} className={`p-4 border-b last:border-0 cursor-pointer hover:bg-slate-50 flex gap-4 transition-all ${!n.read ? 'bg-indigo-50/40' : ''}`}>
                    <div className="w-8 h-8 rounded-xl bg-indigo-100 text-indigo-600 flex items-center justify-center text-xs shrink-0"><i className="fas fa-envelope-open-text"></i></div>
                    <div className="flex-1">
                      <p className="text-[11px] font-bold text-slate-700 leading-snug">{n.message}</p>
                      <p className="text-[8px] text-slate-300 mt-1 uppercase font-black">{new Date(n.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</p>
                    </div>
                 </div>
               ))
             }
           </div>
        </div>
      )}

      <main className="flex-1 overflow-y-auto p-4 space-y-4">
        {webhookUrl && (
          <div className="bg-emerald-50 text-emerald-700 px-4 py-2 rounded-xl border border-emerald-100 flex items-center gap-3 text-[10px] font-bold">
            <i className="fas fa-link text-emerald-500"></i>
            Broadcast connected to Google Chat
          </div>
        )}

        {/* Actions Bar */}
        <div className="bg-white p-3 rounded-2xl shadow-sm border border-slate-100 flex justify-between items-center">
           <div className="flex -space-x-2 ml-2">
              {[1,2,3].map(i => <div key={i} className="w-6 h-6 rounded-full border-2 border-white bg-slate-200 flex items-center justify-center text-[8px] font-black text-slate-400"><i className="fas fa-user"></i></div>)}
              <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest pl-4 self-center">Team Online</span>
           </div>
           <div className="flex gap-2">
             <Button onClick={() => setModals({...modals, waitlist: true})} variant="ghost" className="h-9 px-4 text-[9px] font-black uppercase rounded-xl border border-slate-100">Waitlist</Button>
             <Button onClick={() => setModals({...modals, create: true})} className="h-9 px-4 text-[9px] font-black uppercase rounded-xl bg-indigo-600 shadow-md">Start Run</Button>
           </div>
        </div>

        {/* Runs Feed */}
        <div className="grid gap-4">
           {runs.length === 0 && (
             <div className="text-center py-20 opacity-40">
                <div className="w-20 h-20 bg-slate-100 rounded-full mx-auto flex items-center justify-center mb-4"><i className="fas fa-utensils text-2xl text-slate-300"></i></div>
                <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Waiting for a hero to go for food</p>
             </div>
           )}

           {runs.map((run: FoodRun) => {
             const isRunner = user.email === run.runnerEmail;
             const myOrder = run.orders.find(o => o.userEmail === user.email);
             return (
               <div key={run.id} className={`bg-white rounded-[2rem] p-6 shadow-sm border-2 transition-all duration-300 ${run.status === 'departed' ? 'border-indigo-500 shadow-indigo-100 shadow-2xl' : 'border-white hover:border-slate-100'}`}>
                 <div className="flex justify-between items-start mb-6">
                    <div className="flex gap-4">
                      <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xl ${run.status === 'departed' ? 'bg-indigo-600 text-white' : 'bg-slate-50 text-slate-400'}`}>
                         <i className={`fas ${run.status === 'departed' ? 'fa-shipping-fast' : 'fa-hamburger'}`}></i>
                      </div>
                      <div>
                        <h4 className="text-lg font-black text-slate-800 tracking-tight">{run.destination}</h4>
                        <p className="text-[9px] font-black text-slate-400 uppercase tracking-[0.1em]">Lead: {run.runnerName} • {run.minutesUntilDeparture}m left</p>
                      </div>
                    </div>
                 </div>

                 <div className="space-y-2 mb-6">
                   {run.orders.map(o => (
                     <div key={o.id} className={`flex justify-between items-center p-3 rounded-2xl border text-xs ${o.userEmail === user.email ? 'bg-indigo-50 border-indigo-100' : 'bg-slate-50/50 border-slate-100'}`}>
                        <div className="flex items-center gap-3">
                           <div className="w-6 h-6 rounded-lg bg-white border flex items-center justify-center text-[9px] font-black text-slate-400">{o.userName.charAt(0)}</div>
                           <span className="font-bold text-slate-700">{o.userName}</span>
                           <span className="text-slate-400 italic">"{o.itemDescription}"</span>
                        </div>
                        <div className="flex gap-2">
                          {o.userEmail === user.email && run.status === 'departed' && !o.cibusCode && (
                            <button onClick={() => setModals({...modals, cibus: {runId: run.id, orderId: o.id}})} className="text-[9px] font-black bg-indigo-600 text-white px-3 py-1 rounded-lg shadow-sm hover:scale-105 transition-transform">PAY</button>
                          )}
                          {o.cibusCode && <div className="flex items-center gap-1.5 text-indigo-600 font-black text-[9px] uppercase"><i className="fas fa-check-circle"></i> Paid</div>}
                        </div>
                     </div>
                   ))}
                 </div>

                 <div className="flex gap-3">
                   {isRunner ? (
                     run.status === 'active' ? (
                       <Button onClick={() => actions.depart(run.id)} className="flex-1 h-12 bg-indigo-600 font-black uppercase text-[10px] rounded-2xl">Broadcast Departure</Button>
                     ) : (
                       <Button onClick={() => setModals({...modals, arrive: run.id})} className="flex-1 h-12 bg-emerald-600 font-black uppercase text-[10px] rounded-2xl">Mark as Arrived</Button>
                     )
                   ) : !myOrder && run.status === 'active' && run.orders.length < run.maxOrders && (
                     <Button onClick={() => setModals({...modals, join: run.id})} className="flex-1 h-12 bg-indigo-600 font-black uppercase text-[10px] rounded-2xl">Join Manifest</Button>
                   )}
                 </div>
               </div>
             );
           })}
        </div>
      </main>

      {/* Admin Setup Modal */}
      {modals.admin && (
        <Overlay title="Chat Integration" onClose={() => setModals({...modals, admin: false})}>
           <div className="space-y-4">
              <div className="flex items-center gap-3 p-3 bg-indigo-50 rounded-2xl">
                <i className="fas fa-shield-alt text-indigo-600"></i>
                <p className="text-[9px] font-black text-indigo-900 uppercase tracking-widest">Admin Control Panel</p>
              </div>
              <p className="text-[10px] text-slate-500 leading-relaxed font-medium">To send messages to Google Chat, create a Webhook in your Space settings and paste the URL here.</p>
              <input 
                className="w-full p-4 bg-slate-50 border-0 rounded-2xl font-bold text-xs focus:ring-2 focus:ring-indigo-500 outline-none" 
                placeholder="https://chat.googleapis.com/v1/spaces/..." 
                value={webhookUrl} 
                onChange={e => setWebhookUrl(e.target.value)} 
              />
              <Button onClick={() => setModals({...modals, admin: false})} className="w-full h-12 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl">Save Configuration</Button>
           </div>
        </Overlay>
      )}

      {/* Other Modals */}
      {modals.create && (
        <Overlay title="Mission Config" onClose={() => setModals({...modals, create: false})}>
           <form onSubmit={actions.createRun} className="space-y-4">
              <input required className="w-full p-4 bg-slate-50 border-0 rounded-2xl font-bold text-sm focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="Target Destination" value={inputs.dest} onChange={e => setInputs({...inputs, dest: e.target.value})} />
              <div className="grid grid-cols-2 gap-4">
                <input required type="number" className="w-full p-4 bg-slate-50 border-0 rounded-2xl font-bold text-sm" placeholder="Wait (m)" value={inputs.time} onChange={e => setInputs({...inputs, time: parseInt(e.target.value)})} />
                <input required type="number" className="w-full p-4 bg-slate-50 border-0 rounded-2xl font-bold text-sm" placeholder="Slots" value={inputs.max} onChange={e => setInputs({...inputs, max: parseInt(e.target.value)})} />
              </div>
              <Button type="submit" className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl">Establish Mission</Button>
           </form>
        </Overlay>
      )}

      {modals.cibus && (
        <Overlay title="Cibus Payload" onClose={() => setModals({...modals, cibus: null})}>
           <form onSubmit={actions.pay} className="space-y-6 text-center">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Enter 6-Digit Payment Code</p>
              <input required autoFocus className="w-full p-6 bg-slate-50 border-0 rounded-2xl font-black text-5xl text-center tracking-[0.3em] focus:ring-2 focus:ring-indigo-500 outline-none text-slate-700" placeholder="000000" maxLength={6} value={inputs.cibus} onChange={e => setInputs({...inputs, cibus: e.target.value})} />
              <Button type="submit" className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl">Send to Runner</Button>
           </form>
        </Overlay>
      )}

      {modals.arrive && (
        <Overlay title="Delivery Signal" onClose={() => setModals({...modals, arrive: null})}>
           <form onSubmit={(e) => { e.preventDefault(); actions.arrive(modals.arrive); }} className="space-y-4">
              <input required autoFocus className="w-full p-4 bg-slate-50 border-0 rounded-2xl font-bold text-center text-sm" placeholder="Drop-off point" value={inputs.loc} onChange={e => setInputs({...inputs, loc: e.target.value})} />
              <Button type="submit" className="w-full h-14 bg-emerald-600 font-black uppercase text-[11px] rounded-2xl">Broadcast Arrival</Button>
           </form>
        </Overlay>
      )}

      {modals.join && (
        <Overlay title="Join Manifest" onClose={() => setModals({...modals, join: null})}>
           <form onSubmit={e => { e.preventDefault(); actions.join(modals.join); }} className="space-y-4">
              <input required className="w-full p-4 bg-slate-50 border-0 rounded-2xl font-bold text-sm" placeholder="Your Order Detail" value={inputs.item} onChange={e => setInputs({...inputs, item: e.target.value})} />
              <input required className="w-full p-4 bg-slate-50 border-0 rounded-2xl font-bold text-sm" placeholder="Pickup Floor" value={inputs.floor} onChange={e => setInputs({...inputs, floor: e.target.value})} />
              <Button type="submit" className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl">Confirm Join</Button>
           </form>
        </Overlay>
      )}

      {modals.waitlist && (
        <Overlay title="Post Request" onClose={() => setModals({...modals, waitlist: false})}>
           <form onSubmit={actions.waitlist} className="space-y-4">
              <input required className="w-full p-4 bg-slate-50 border-0 rounded-2xl font-bold text-sm" placeholder="Where from?" value={inputs.dest} onChange={e => setInputs({...inputs, dest: e.target.value})} />
              <input required className="w-full p-4 bg-slate-50 border-0 rounded-2xl font-bold text-sm" placeholder="What exactly?" value={inputs.item} onChange={e => setInputs({...inputs, item: e.target.value})} />
              <input required className="w-full p-4 bg-slate-50 border-0 rounded-2xl font-bold text-sm" placeholder="Floor" value={inputs.floor} onChange={e => setInputs({...inputs, floor: e.target.value})} />
              <Button type="submit" className="w-full h-14 bg-slate-900 text-white font-black uppercase text-[11px] rounded-2xl">Broadcast to Team</Button>
           </form>
        </Overlay>
      )}
    </div>
  );
};

const Overlay: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
  <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md z-[110] flex items-center justify-center p-6">
    <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-[340px] shadow-2xl animate-in zoom-in-95 duration-300 relative">
      <div className="flex justify-between items-center mb-8">
         <h3 className="text-[11px] font-black uppercase tracking-[0.3em] text-indigo-600">{title}</h3>
         <button onClick={onClose} className="w-8 h-8 rounded-full bg-slate-50 text-slate-300 hover:text-slate-500 transition-colors flex items-center justify-center"><i className="fas fa-times"></i></button>
      </div>
      {children}
    </div>
  </div>
);

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { FoodRun, Order, AppEvent, WaitingOrder, UserNotification } from './types';
import { Button } from './components/Button';
import { sendToGoogleChat } from './services/googleChatService';

/** 
 * ADMIN CONFIGURATION
 * Change this to your real Google email to get admin rights in production.
 */
const ADMIN_EMAIL = 'admin@yourcompany.com'; 
const ALLOWED_DOMAIN = 'yourcompany.com';

const ChatPreviewContent: React.FC<{ 
  notification: UserNotification, 
  onAction: (actionType: string) => void 
}> = ({ notification, onAction }) => {
  const { type, message } = notification;

  const containerStyle: React.CSSProperties = {
    maxWidth: '300px',
    background: '#ffffff',
    border: '1px solid #e2e8f0',
    borderRadius: '12px',
    fontFamily: 'sans-serif',
    overflow: 'hidden',
    boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)',
    textAlign: 'left'
  };

  const headerStyle: React.CSSProperties = {
    padding: '8px 12px',
    borderBottom: '1px solid #f1f3f4',
    display: 'flex',
    alignItems: 'center',
    gap: '8px',
    background: '#f8fafc',
    fontSize: '11px',
    fontWeight: '700',
    color: '#64748b',
    textTransform: 'uppercase'
  };

  const bodyStyle: React.CSSProperties = {
    padding: '12px',
    fontSize: '13px',
    color: '#1e293b',
    lineHeight: '1.4'
  };

  const btnBaseStyle: React.CSSProperties = {
    width: '100%',
    marginTop: '12px',
    padding: '8px 16px',
    color: 'white',
    borderRadius: '8px',
    fontSize: '10px',
    fontWeight: '900',
    textTransform: 'uppercase',
    letterSpacing: '0.05em',
    transition: 'all 0.2s ease',
    boxShadow: '0 1px 2px 0 rgba(0, 0, 0, 0.05)',
    border: 'none',
    cursor: 'pointer'
  };

  return (
    <div className="animate-in zoom-in-95 duration-200" style={{ pointerEvents: 'auto' }}>
      <div style={containerStyle}>
        <div style={headerStyle}>
          <i className={`fas ${type === 'departed' ? 'fa-bolt text-amber-500' : type === 'arrived' ? 'fa-map-marker-alt text-emerald-500' : 'fa-robot text-indigo-500'}`}></i>
          <span>LunchRun Bot</span>
        </div>
        <div style={bodyStyle}>
          <p className="font-medium">{message}</p>

          {type === 'departed' && (
            <button 
              onClick={() => onAction('open_pay')} 
              style={{ ...btnBaseStyle, backgroundColor: '#4f46e5' }}
              className="hover:brightness-110 active:scale-95"
            >
              Provide Payment Code
            </button>
          )}

          {type === 'arrived' && (
            <button 
              onClick={() => onAction('close')} 
              style={{ ...btnBaseStyle, backgroundColor: '#059669' }}
              className="hover:brightness-110 active:scale-95"
            >
              I'm on my way!
            </button>
          )}

          {type === 'waitlist_promoted' && (
             <button 
               onClick={() => onAction('close')} 
               style={{ ...btnBaseStyle, backgroundColor: '#475569' }}
               className="hover:brightness-110 active:scale-95"
             >
              Got it
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [notifications, setNotifications] = useState<UserNotification[]>([]);
  const [simulatorMode, setSimulatorMode] = useState(false);
  const [webhookUrl, setWebhookUrl] = useState<string>(localStorage.getItem('lunchrun_webhook') || '');
  const [isSimulatorAdmin, setIsSimulatorAdmin] = useState(false);

  useEffect(() => {
    const savedHistory = localStorage.getItem('lunchrun_history');
    const savedWaitlist = localStorage.getItem('lunchrun_waitlist');
    const savedNotifications = localStorage.getItem('lunchrun_notifications');
    const savedRuns = localStorage.getItem('lunchrun_active_runs');

    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedWaitlist) setWaitingOrders(JSON.parse(savedWaitlist));
    if (savedNotifications) setNotifications(JSON.parse(savedNotifications));
    if (savedRuns) setRuns(JSON.parse(savedRuns));
  }, []);

  useEffect(() => {
    localStorage.setItem('lunchrun_active_runs', JSON.stringify(runs));
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(waitingOrders));
    localStorage.setItem('lunchrun_notifications', JSON.stringify(notifications));
    localStorage.setItem('lunchrun_history', JSON.stringify(history));
    localStorage.setItem('lunchrun_webhook', webhookUrl);
  }, [runs, waitingOrders, notifications, history, webhookUrl]);

  const sharedActions = {
    runs, setRuns,
    history, setHistory,
    waitingOrders, setWaitingOrders,
    notifications, setNotifications,
    webhookUrl, setWebhookUrl,
    isSimulatorAdmin
  };

  return (
    <div className={`min-h-screen transition-all duration-500 ${simulatorMode ? 'p-2 sm:p-4 bg-slate-200' : 'bg-slate-50'}`}>
      {/* QA Toolbar */}
      <div className="bg-slate-900 text-white/70 px-6 py-2 flex justify-between items-center text-[10px] font-black uppercase tracking-[0.2em] shadow-xl sticky top-0 z-[100] rounded-b-xl sm:mx-4">
        <div className="flex items-center gap-4">
          <div className={`w-2 h-2 rounded-full animate-pulse ${isSimulatorAdmin ? 'bg-amber-400' : 'bg-indigo-400'}`}></div>
          <span>{isSimulatorAdmin ? 'Admin Terminal' : 'LunchRun Network'}</span>
        </div>
        <div className="flex gap-4">
           {simulatorMode && (
             <button 
               onClick={() => setIsSimulatorAdmin(!isSimulatorAdmin)} 
               className={`px-4 py-1.5 rounded-full border transition-all flex items-center gap-2 ${isSimulatorAdmin ? 'bg-amber-500 border-amber-400 text-slate-900 shadow-lg' : 'border-slate-700 hover:text-white'}`}
             >
               <i className={`fas ${isSimulatorAdmin ? 'fa-user-shield' : 'fa-unlock'}`}></i>
               {isSimulatorAdmin ? 'ADMIN MODE: ACTIVE' : 'TOGGLE ADMIN MODE'}
             </button>
           )}
           <button onClick={() => setSimulatorMode(!simulatorMode)} className={`px-4 py-1.5 rounded-full border transition-all ${simulatorMode ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'border-slate-700 hover:text-white hover:border-slate-500'}`}>
             {simulatorMode ? 'Exit Simulator' : 'Split-Screen QA'}
           </button>
           <button onClick={() => { localStorage.clear(); window.location.reload(); }} className="px-4 py-1.5 rounded-full border border-red-900/50 text-red-400/80 hover:text-red-400 hover:bg-red-900/20">
             Reset Data
           </button>
        </div>
      </div>

      {simulatorMode ? (
        <div className="flex flex-col md:flex-row h-[calc(100vh-80px)] gap-4 mt-4 overflow-hidden">
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-indigo-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Persona: Avi (Runner)</div>
             <AppInstance userOverride={{ name: 'Avi', email: `avi@${ALLOWED_DOMAIN}` }} {...sharedActions} />
          </div>
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-emerald-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Persona: Dana (Orderer)</div>
             <AppInstance userOverride={{ name: 'Dana', email: `dana@${ALLOWED_DOMAIN}` }} {...sharedActions} />
          </div>
        </div>
      ) : (
        <div className="max-w-4xl mx-auto mt-6">
          <AppInstance {...sharedActions} />
        </div>
      )}
    </div>
  );
};

const AppInstance: React.FC<any> = ({ 
  userOverride, 
  runs, setRuns, 
  history, setHistory, 
  waitingOrders, setWaitingOrders, 
  notifications, setNotifications,
  webhookUrl, setWebhookUrl,
  isSimulatorAdmin
}) => {
  const [user, setUser] = useState<{ name: string; email: string; isAdmin?: boolean } | null>(userOverride || null);
  const [activeToast, setActiveToast] = useState<{message: string, type: string} | null>(null);
  const [authError, setAuthError] = useState<string | null>(null);
  const lastNotifId = useRef<string | null>(null);

  const [modals, setModals] = useState<{ [key: string]: boolean | any }>({
    create: false, waitlist: false, join: null, cibus: null, arrive: null, notifs: false, preview: null
  });

  const [inputs, setInputs] = useState({ dest: '', time: 20, max: 5, item: '', floor: '', cibus: '', loc: '' });

  useEffect(() => {
    if (userOverride || user) return;

    const handleCredentialResponse = (response: any) => {
      try {
        const payload = JSON.parse(atob(response.credential.split('.')[1]));
        const email = payload.email;
        const domain = email.split('@')[1];

        if (domain !== ALLOWED_DOMAIN) {
          setAuthError(`Only @${ALLOWED_DOMAIN} accounts are allowed.`);
          return;
        }

        setUser({
          name: payload.name,
          email: email,
          isAdmin: email === ADMIN_EMAIL
        });
        setAuthError(null);
      } catch (e) {
        setAuthError("Auth failed. Please try again.");
      }
    };

    if ((window as any).google) {
      (window as any).google.accounts.id.initialize({
        client_id: "YOUR_GOOGLE_CLIENT_ID.apps.googleusercontent.com",
        callback: handleCredentialResponse
      });
      (window as any).google.accounts.id.renderButton(
        document.getElementById("googleBtn"),
        { theme: "outline", size: "large", width: "320" }
      );
    }
  }, [user, userOverride]);

  useEffect(() => {
    if (!user) return;
    const userNotifs = notifications.filter((n: UserNotification) => n.targetEmail === user.email);
    const newest = userNotifs[0];

    if (newest && newest.id !== lastNotifId.current) {
       lastNotifId.current = newest.id;
       setActiveToast({ message: newest.message, type: newest.type });
       setTimeout(() => setActiveToast(null), 5000);
    }
  }, [notifications, user]);

  const triggerBroadcast = (targetEmail: string, type: UserNotification['type'], message: string) => {
    const newNotif: UserNotification = {
      id: Math.random().toString(36).substr(2, 9),
      targetEmail, type, message, runId: 'sys', timestamp: Date.now(), read: false
    };
    setNotifications((prev: any) => [newNotif, ...prev]);
  };

  const actions = {
    createRun: (e: React.FormEvent) => {
      e.preventDefault();
      const match = waitingOrders.filter(wo => wo.destination.toLowerCase() === inputs.dest.toLowerCase());
      const selected = match.slice(0, inputs.max);

      const orders: Order[] = selected.map(wo => {
        triggerBroadcast(wo.userEmail, 'waitlist_promoted', `Added to run: ${wo.destination} by ${user?.name}`);
        return { id: wo.id, userName: wo.userName, userEmail: wo.userEmail, itemDescription: wo.itemDescription, floor: wo.floor, cibusCode: '', timestamp: Date.now() };
      });

      const newRun: FoodRun = {
        id: Math.random().toString(36).substr(2, 9), runnerName: user?.name || '', runnerEmail: user?.email || '',
        destination: inputs.dest, departureTime: Date.now() + inputs.time * 60000, minutesUntilDeparture: inputs.time,
        maxOrders: inputs.max, status: 'active', orders
      };

      setWaitingOrders((prev: any) => prev.filter((wo: any) => !orders.some(o => o.userEmail === wo.userEmail)));
      setRuns((prev: any) => [newRun, ...prev]);
      setModals({ ...modals, create: false });

      if (webhookUrl) {
        sendToGoogleChat(webhookUrl, {
          title: "New Run Initiated!",
          subtitle: `Destination: ${inputs.dest}`,
          details: `Lead by <b>${user?.name}</b>. Departing in ${inputs.time} mins. Slots: ${inputs.max}.`,
          buttonText: "Join Manifest",
          buttonUrl: window.location.href
        });
      }

      setInputs({ ...inputs, dest: '' });
    },
    depart: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, status: 'departed' } : r));
      run.orders.forEach((o: any) => triggerBroadcast(o.userEmail, 'departed', `Runner leaving for ${run.destination}! Pay now.`));

      if (webhookUrl) {
        sendToGoogleChat(webhookUrl, {
          title: "Run Departed!",
          subtitle: `En route to ${run.destination}`,
          details: `Mission lead by ${run.runnerName}. Members should provide payment codes now.`,
          buttonText: "Pay with Cibus",
          buttonUrl: window.location.href
        });
      }
    },
    arrive: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      const updatedRun = { ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() };
      run.orders.forEach((o: any) => triggerBroadcast(o.userEmail, 'arrived', `Food is at ${inputs.loc}!`));
      setHistory((prev: any) => [updatedRun, ...prev]);
      setRuns(runs.filter((r: any) => r.id !== runId));
      setModals({ ...modals, arrive: null });

      if (webhookUrl) {
        sendToGoogleChat(webhookUrl, {
          title: "Delivery Arrived!",
          subtitle: `Food from ${run.destination} is here`,
          details: `Pick up your order at: <b>${inputs.loc}</b>.`,
          buttonText: "View My Order",
          buttonUrl: window.location.href
        });
      }
    },
    join: (runId: string) => {
      const order: Order = { id: Math.random().toString(36).substr(2, 9), userName: user?.name || '', userEmail: user?.email || '', itemDescription: inputs.item, floor: inputs.floor, cibusCode: '', timestamp: Date.now() };
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: [...r.orders, order] } : r));
      setModals({ ...modals, join: null });
    },
    waitlist: (e: React.FormEvent) => {
      e.preventDefault();
      const wo: WaitingOrder = { id: Math.random().toString(36).substr(2, 9), userName: user?.name || '', userEmail: user?.email || '', destination: inputs.dest, itemDescription: inputs.item, floor: inputs.floor, timestamp: Date.now() };
      setWaitingOrders((prev: any) => [...prev, wo]);
      setModals({ ...modals, waitlist: false });
    },
    pay: (e: React.FormEvent) => {
      e.preventDefault();
      const { runId, orderId } = modals.cibus;
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: r.orders.map((o: any) => o.id === orderId ? { ...o, cibusCode: inputs.cibus } : o) } : r));
      setModals({ ...modals, cibus: null });
      setInputs({ ...inputs, cibus: '' });
    },
    handleNotifAction: (action: string) => {
      if (action === 'open_pay') {
        const myActiveRun = runs.find(r => r.orders.some(o => o.userEmail === user?.email));
        const myOrder = myActiveRun?.orders.find(o => o.userEmail === user?.email);
        if (myActiveRun && myOrder) {
          setModals({ ...modals, preview: null, cibus: { runId: myActiveRun.id, orderId: myOrder.id } });
        } else {
          setModals({ ...modals, preview: null });
        }
      } else {
        setModals({ ...modals, preview: null });
      }
    }
  };

  const isAdmin = user?.isAdmin || isSimulatorAdmin;

  if (!user) {
    return (
      <div className="h-full flex flex-col items-center justify-center p-8 bg-white">
        <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-3xl mb-6 shadow-xl"><i className="fas fa-bicycle"></i></div>
        <h1 className="text-2xl font-black tracking-tighter mb-2 text-slate-800">Welcome to LunchRun</h1>
        <p className="text-slate-400 text-sm mb-8 text-center max-w-xs">Coordinate food runs with your colleagues. <br/>Limited to <b>@{ALLOWED_DOMAIN}</b></p>
        <div id="googleBtn" className="mb-4"></div>
        {authError && <p className="text-red-500 text-xs font-bold mt-2 bg-red-50 px-3 py-1 rounded-full animate-bounce">{authError}</p>}
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col bg-slate-50 relative">
      {/* Simulation Toasts */}
      {activeToast && (
        <div className="absolute top-16 left-1/2 -translate-x-1/2 z-[100] animate-in slide-in-from-top-4 duration-300">
          <div onClick={() => setModals({...modals, notifs: true})} className="cursor-pointer bg-slate-900 text-white px-4 py-3 rounded-2xl shadow-2xl flex items-center gap-4 border border-indigo-500/50">
             <div className="w-8 h-8 rounded-xl bg-indigo-500 flex items-center justify-center text-xs"><i className="fas fa-comment"></i></div>
             <div>
                <p className="text-[9px] font-black uppercase text-indigo-400">Incoming Message</p>
                <p className="text-[11px] font-bold">{activeToast.message}</p>
             </div>
          </div>
        </div>
      )}

      {/* Notification Modal */}
      {modals.preview && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[150] flex items-center justify-center p-4">
           <ChatPreviewContent notification={modals.preview} onAction={actions.handleNotifAction} />
        </div>
      )}

      <header className={`px-6 py-4 flex justify-between items-center border-b transition-colors duration-500 ${isAdmin ? 'bg-amber-50 border-amber-100' : 'bg-white border-slate-100'}`}>
        <div className="flex items-center gap-3">
           <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-white text-sm shadow-lg ${isAdmin ? 'bg-amber-500 shadow-amber-200' : 'bg-indigo-600 shadow-indigo-200'}`}><i className={`fas ${isAdmin ? 'fa-user-shield' : 'fa-rocket'}`}></i></div>
           <div>
             <span className="font-black text-sm tracking-tighter text-slate-800 block leading-none">LUNCHRUN</span>
             {isAdmin && <span className="text-[8px] font-black text-amber-600 uppercase tracking-widest mt-0.5">ADMINISTRATOR</span>}
           </div>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setModals({...modals, notifs: !modals.notifs})} className="relative w-8 h-8 rounded-xl bg-slate-100/50 flex items-center justify-center text-slate-400 hover:text-indigo-600 transition-colors">
             <i className="fas fa-bell text-xs"></i>
             {unreadCount > 0 && <span className="absolute -top-1 -right-1 w-4 h-4 bg-indigo-600 text-white rounded-full text-[8px] flex items-center justify-center font-bold border-2 border-white">{unreadCount}</span>}
          </button>
          <img src={`https://ui-avatars.com/api/?name=${user.name}&background=${isAdmin ? 'f59e0b' : '6366f1'}&color=fff`} className="w-8 h-8 rounded-xl border-2 border-white shadow-sm" alt="u" />
        </div>
      </header>

      <main className="flex-1 overflow-y-auto p-4 space-y-4">

        {/* ADMIN DASHBOARD CARD - High Visibility */}
        {isAdmin && (
          <div className="bg-slate-900 rounded-[2rem] p-6 text-white shadow-2xl border-4 border-amber-500/20 relative overflow-hidden animate-in slide-in-from-top-4">
