             <div className="absolute top-0 inset-x-0 bg-indigo-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Persona: Avi (Runner)</div>
             <AppInstance userOverride={{ name: 'Avi', email: `avi@${ALLOWED_DOMAIN}` }} {...sharedActions} />
          </div>
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-emerald-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Persona: Dana (Orderer)</div>
             <AppInstance userOverride={{ name: 'Dana', email: `dana@${ALLOWED_DOMAIN}` }} {...sharedActions} />
          </div>
        </div>
      ) : (
        <div className="max-w-4xl mx-auto mt-6">
          <AppInstance {...sharedActions} />
        </div>
      )}
