export interface GoogleChatCardParams {
  title: string;
  subtitle: string;
  imageIcon?: string;
  sectionHeader?: string;
  details: string;
  buttonText?: string;
  buttonUrl?: string;
  prefix?: string;
}

/**
 * Sends a formatted card message to a Google Chat Webhook.
 * Includes a top-level 'text' field to ensure notifications are visible even if cards fail.
 */
export const sendToGoogleChat = async (webhookUrl: string, params: GoogleChatCardParams) => {
  if (!webhookUrl) return;

  const plainText = `${params.prefix ? params.prefix + ' ' : ''}${params.title}: ${params.subtitle}. ${params.details.replace(/<[^>]*>?/gm, '')}`;

  const card = {
    text: plainText, // Fallback text for notifications and mobile
    cardsV2: [
      {
        cardId: "lunchrun-notification",
        card: {
          header: {
            title: "LunchRun",
            subtitle: params.title,
            imageUrl: "https://fonts.gstatic.com/s/i/short-term/release/googlesymbols/directions_run/default/48px.svg",
            imageType: "CIRCLE",
          },
          sections: [
            {
              header: params.sectionHeader || "LunchRun Activity",
              widgets: [
                {
                  textParagraph: {
                    text: `${params.prefix ? `<b>${params.prefix}</b><br>` : ''}<b>${params.subtitle}</b><br>${params.details}`,
                  },
                },
                params.buttonUrl ? {
                  buttonList: {
                    buttons: [
                      {
                        text: params.buttonText || "Open LunchRun",
                        onClick: {
                          openLink: {
                            url: params.buttonUrl,
                          },
                        },
                      },
                    ],
                  },
                } : null,
              ].filter(Boolean),
            },
          ],
        },
      },
    ],
  };

  try {
    const response = await fetch(webhookUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json; charset=UTF-8' },
      body: JSON.stringify(card),
    });
    return response.ok;
  } catch (error) {
    console.error("Failed to send message to Google Chat", error);
    return false;
  }
};

