           ))}
        </div>
      </main>

      {/* MODALS (Simplified for the demo) */}
      {modals.create && (
        <Overlay title="Launch Run" onClose={() => setModals({...modals, create: false})}>
           <form onSubmit={actions.createRun} className="space-y-4">
              <input required className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Destination" value={inputs.dest} onChange={e => setInputs({...inputs, dest: e.target.value})} />
              <div className="grid grid-cols-2 gap-4">
