  const [defaultWait, setDefaultWait] = useState<number>(Number(localStorage.getItem('lunchrun_def_wait')) || 20);
  const [defaultMax, setDefaultMax] = useState<number>(Number(localStorage.getItem('lunchrun_def_max')) || 5);
  const [isSimulatorAdmin, setIsSimulatorAdmin] = useState(false);

  useEffect(() => {
    const savedHistory = localStorage.getItem('lunchrun_history');
    const savedWaitlist = localStorage.getItem('lunchrun_waitlist');
    const savedNotifications = localStorage.getItem('lunchrun_notifications');
    const savedRuns = localStorage.getItem('lunchrun_active_runs');

    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedWaitlist) setWaitingOrders(JSON.parse(savedWaitlist));
    if (savedNotifications) setNotifications(JSON.parse(savedNotifications));
    if (savedRuns) setRuns(JSON.parse(savedRuns));
  }, []);

  useEffect(() => {
    localStorage.setItem('lunchrun_active_runs', JSON.stringify(runs));
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(waitingOrders));
    localStorage.setItem('lunchrun_notifications', JSON.stringify(notifications));
    localStorage.setItem('lunchrun_history', JSON.stringify(history));
    localStorage.setItem('lunchrun_webhook', webhookUrl);
    localStorage.setItem('lunchrun_prefix', messagePrefix);
    localStorage.setItem('lunchrun_def_wait', defaultWait.toString());
    localStorage.setItem('lunchrun_def_max', defaultMax.toString());
  }, [runs, waitingOrders, notifications, history, webhookUrl, messagePrefix, defaultWait, defaultMax]);

  const sharedActions = {
    runs, setRuns,
    history, setHistory,
    waitingOrders, setWaitingOrders,
    notifications, setNotifications,
    webhookUrl, setWebhookUrl,
    messagePrefix, setMessagePrefix,
    defaultWait, setDefaultWait,
    defaultMax, setDefaultMax,
    isSimulatorAdmin
  };

  return (
    <div className={`min-h-screen transition-all duration-500 ${simulatorMode ? 'p-2 sm:p-4 bg-slate-200' : 'bg-slate-50'}`}>
      <div className="bg-slate-900 text-white/70 px-6 py-2 flex justify-between items-center text-[10px] font-black uppercase tracking-[0.2em] shadow-xl sticky top-0 z-[100] rounded-b-xl sm:mx-4">
        <div className="flex items-center gap-4">
          <div className={`w-2 h-2 rounded-full animate-pulse ${isSimulatorAdmin ? 'bg-amber-400' : 'bg-indigo-400'}`}></div>
          <span>{isSimulatorAdmin ? 'Admin Terminal' : 'LunchRun Network'}</span>
        </div>
        <div className="flex gap-4">
           {simulatorMode && (
             <button 
               onClick={() => setIsSimulatorAdmin(!isSimulatorAdmin)} 
               className={`px-4 py-1.5 rounded-full border transition-all flex items-center gap-2 ${isSimulatorAdmin ? 'bg-amber-500 border-amber-400 text-slate-900 shadow-lg' : 'border-slate-700 hover:text-white'}`}
             >
               <i className={`fas ${isSimulatorAdmin ? 'fa-user-shield' : 'fa-unlock'}`}></i>
               {isSimulatorAdmin ? 'ADMIN MODE' : 'USER MODE'}
             </button>
           )}
           <button onClick={() => setSimulatorMode(!simulatorMode)} className={`px-4 py-1.5 rounded-full border transition-all ${simulatorMode ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'border-slate-700 hover:text-white hover:border-slate-500'}`}>
             {simulatorMode ? 'Exit Simulator' : 'Split-Screen QA'}
           </button>
        </div>
      </div>

      {simulatorMode ? (
        <div className="flex flex-col md:flex-row h-[calc(100vh-80px)] gap-4 mt-4 overflow-hidden">
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-indigo-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">USER 1: RUNNER VIEW</div>
             <AppInstance userOverride={{ name: 'Avi', email: `avi@${ALLOWED_DOMAIN}` }} {...sharedActions} />
          </div>
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-emerald-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">USER 2: ORDERER VIEW</div>
             <AppInstance userOverride={{ name: 'Dana', email: `dana@${ALLOWED_DOMAIN}` }} {...sharedActions} />
          </div>
        </div>
      ) : (
        <div className="max-w-4xl mx-auto mt-6">
          <AppInstance {...sharedActions} />
        </div>
      )}
    </div>
  );
};

const AppInstance: React.FC<any> = ({ 
  userOverride, 
  runs, setRuns, 
  history, setHistory, 
  waitingOrders, setWaitingOrders, 
  notifications, setNotifications,
  webhookUrl, setWebhookUrl,
  messagePrefix, setMessagePrefix,
  defaultWait, setDefaultWait,
  defaultMax, setDefaultMax,
  isSimulatorAdmin
}) => {
  const [user, setUser] = useState<{ name: string; email: string; isAdmin?: boolean } | null>(userOverride || null);
  const [activeToast, setActiveToast] = useState<{message: string, type: string} | null>(null);
  const [authError, setAuthError] = useState<string | null>(null);
  const [testLoading, setTestLoading] = useState(false);
  const lastNotifId = useRef<string | null>(null);

  const [modals, setModals] = useState<{ [key: string]: boolean | any }>({
    create: false, waitlist: false, join: null, cibus: null, arrive: null, preview: null
  });

  const [loginForm, setLoginForm] = useState({ username: '', password: '', visible: false });
  const [inputs, setInputs] = useState({ dest: '', time: defaultWait, max: defaultMax, item: '', floor: '', cibus: '', loc: '' });

  useEffect(() => {
    if (!user) return;
    // Filtering notifications: Only show alerts where targetEmail matches current user
    const userNotifs = notifications.filter((n: UserNotification) => n.targetEmail === user.email);
    const newest = userNotifs[0];

    if (newest && newest.id !== lastNotifId.current) {
       lastNotifId.current = newest.id;
       setActiveToast({ message: newest.message, type: newest.type });
       setTimeout(() => setActiveToast(null), 8000);
    }
  }, [notifications, user]);

  const triggerPrivateAlert = (targetEmail: string, type: UserNotification['type'], message: string) => {
    const newNotif: UserNotification = {
      id: Math.random().toString(36).substr(2, 9),
      targetEmail, type, message, runId: 'sys', timestamp: Date.now(), read: false
    };
    setNotifications((prev: any) => [newNotif, ...prev]);
  };

  const actions = {
    handleManualLogin: (e: React.FormEvent) => {
      e.preventDefault();
      if (loginForm.username === 'admin' && loginForm.password === 'admin') {
        setUser({ name: 'System Admin', email: 'admin@system.local', isAdmin: true });
        setAuthError(null);
      } else {
        setAuthError("Wrong credentials. Try admin/admin");
      }
    },
    createRun: (e: React.FormEvent) => {
      e.preventDefault();
      const newRun: FoodRun = {
        id: Math.random().toString(36).substr(2, 9), runnerName: user?.name || '', runnerEmail: user?.email || '',
        destination: inputs.dest, departureTime: Date.now() + inputs.time * 60000, minutesUntilDeparture: inputs.time,
        maxOrders: inputs.max, status: 'active', orders: []
      };
      setRuns((prev: any) => [newRun, ...prev]);
      setModals({ ...modals, create: false });

      // PUBLIC BROADCAST
      sendToGoogleChat(webhookUrl, {
        title: "New Food Run!",
        subtitle: `Destination: ${inputs.dest}`,
        details: `Departing in <b>${inputs.time} mins</b>. Lead by ${user?.name}.`,
        buttonText: "Open App to Join",
        buttonUrl: window.location.href,
        prefix: messagePrefix
      });
    },
    depart: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, status: 'departed' } : r));

      // PUBLIC BROADCAST (Milestone)
      sendToGoogleChat(webhookUrl, {
        title: "Runner is Leaving!",
        subtitle: `En route to ${run.destination}`,
        details: "The runner has departed. Last chance for orders is over.",
        prefix: messagePrefix
      });

      // PRIVATE ALERTS (To orderers only)
      run.orders.forEach(order => {
        triggerPrivateAlert(order.userEmail, 'departed', `Runner leaving for ${run.destination}! Please provide your payment code now.`);
      });
    },
    arrive: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;

      // PUBLIC BROADCAST (Milestone)
      sendToGoogleChat(webhookUrl, {
        title: "Food has Arrived!",
        subtitle: `From ${run.destination}`,
        details: `Pickup point: <b>${inputs.loc}</b>.`,
        prefix: messagePrefix
      });

      // PRIVATE ALERTS (To orderers only)
      run.orders.forEach(order => {
        triggerPrivateAlert(order.userEmail, 'arrived', `Your food is waiting at ${inputs.loc}!`);
      });

      setHistory((prev: any) => [{ ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() }, ...prev]);
      setRuns(runs.filter((r: any) => r.id !== runId));
      setModals({ ...modals, arrive: null });
    },
    join: (runId: string) => {
      const order: Order = { 
        id: Math.random().toString(36).substr(2, 9), 
        userName: user?.name || '', 
        userEmail: user?.email || '', 
        itemDescription: inputs.item, 
        floor: inputs.floor, 
        cibusCode: '', 
        timestamp: Date.now() 
      };
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: [...r.orders, order] } : r));
      setModals({ ...modals, join: null });
      // Note: Joining is private, no Webhook sent to avoid spamming the channel
    }
  };

  const isAdmin = user?.isAdmin || isSimulatorAdmin;

  return (
    <div className="h-full flex flex-col bg-slate-50 relative">
      {/* PERSONAL TOAST - Only shows for the targeted user */}
      {activeToast && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-[200] animate-in slide-in-from-top-10">
          <div className="bg-slate-900 text-white px-6 py-4 rounded-3xl shadow-2xl flex items-center gap-4 border border-indigo-500/50 min-w-[300px]">
             <div className="w-10 h-10 rounded-2xl bg-indigo-600 flex items-center justify-center text-lg"><i className="fas fa-bell animate-swing"></i></div>
             <div>
                <p className="text-[10px] font-black uppercase text-indigo-400 tracking-widest">Personal Alert</p>
                <p className="text-[13px] font-bold pr-4">{activeToast.message}</p>
             </div>
             <button onClick={() => setActiveToast(null)} className="ml-auto text-white/30 hover:text-white"><i className="fas fa-times"></i></button>
          </div>
        </div>
      )}

      <header className={`px-6 py-4 flex justify-between items-center border-b ${isAdmin ? 'bg-amber-50 border-amber-100' : 'bg-white border-slate-100'}`}>
        <div className="flex items-center gap-3">
           <div className={`w-9 h-9 rounded-xl flex items-center justify-center text-white text-lg shadow-lg ${isAdmin ? 'bg-amber-500' : 'bg-indigo-600'}`}><i className={`fas ${isAdmin ? 'fa-user-shield' : 'fa-bicycle'}`}></i></div>
           <div>
             <span className="font-black text-sm text-slate-800 tracking-tight">LUNCHRUN</span>
             <span className="text-[8px] font-black text-slate-400 uppercase block">{user?.email}</span>
           </div>
        </div>
        <img src={`https://ui-avatars.com/api/?name=${user?.name}&background=${isAdmin ? 'f59e0b' : '6366f1'}&color=fff`} className="w-9 h-9 rounded-2xl border-2 border-white shadow-sm" alt="u" />
      </header>

      <main className="flex-1 overflow-y-auto p-4 space-y-4">
        {isAdmin && (
          <div className="bg-slate-900 rounded-[2.5rem] p-6 text-white shadow-2xl border-4 border-amber-500/20 relative overflow-hidden">
             <div className="flex justify-between items-center mb-6">
                <div>
                   <h3 className="text-amber-400 text-[10px] font-black uppercase tracking-[0.2em]">Channel Configuration</h3>
                   <p className="text-white/40 text-[9px]">Settings shared via browser sync/export.</p>
                </div>
                <div className="flex gap-2">
                   <button onClick={() => actions.exportConfig()} className="bg-white/10 p-2 rounded-xl text-[10px]"><i className="fas fa-share-nodes"></i></button>
                </div>
             </div>
             <div className="space-y-4">
                <div>
                   <label className="text-[9px] font-black uppercase text-white/40 block mb-2 pl-1">Space Webhook (Public Channel)</label>
                   <div className="flex gap-2">
                      <input className="flex-1 p-3 bg-white/5 border border-white/10 rounded-2xl font-bold text-xs outline-none focus:ring-2 focus:ring-amber-500" value={webhookUrl} onChange={e => setWebhookUrl(e.target.value)} placeholder="https://chat.googleapis.com/..." />
                      <Button onClick={() => actions.testWebhook()} isLoading={testLoading} className="h-10 px-6 bg-amber-500 text-slate-900 text-[10px] font-black uppercase">Test</Button>
                   </div>
                </div>
                <div className="p-3 bg-white/5 rounded-2xl border border-white/5">
                   <p className="text-[9px] font-black text-amber-500 uppercase flex items-center gap-2"><i className="fas fa-info-circle"></i> Security Note</p>
                   <p className="text-[10px] text-white/50 leading-relaxed mt-1">Personal alerts (Waitlist, Payment) are private and visible only to the specific user in-app.</p>
                </div>
             </div>
          </div>
        )}

        <div className="flex justify-between items-center bg-white p-3 rounded-2xl border border-slate-100 shadow-sm">
           <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-2">Active Missions</span>
           <div className="flex gap-2">
              <Button onClick={() => setModals({...modals, waitlist: true})} variant="ghost" className="h-9 px-4 text-[10px] font-black uppercase rounded-xl border border-slate-100">Waitlist</Button>
              <Button onClick={() => setModals({...modals, create: true})} className="h-9 px-4 text-[10px] font-black uppercase rounded-xl bg-indigo-600 shadow-lg">Start Run</Button>
           </div>
        </div>

        <div className="space-y-4 pb-20">
           {runs.length === 0 && (
             <div className="py-20 text-center opacity-20">
                <div className="w-20 h-20 bg-slate-200 rounded-full mx-auto flex items-center justify-center mb-4"><i className="fas fa-shopping-basket text-2xl text-slate-400"></i></div>
                <p className="text-[10px] font-black uppercase tracking-widest">No active runs in your sector</p>
             </div>
           )}

           {runs.map((run: FoodRun) => {
             const isRunner = user?.email === run.runnerEmail;
             const myOrder = run.orders.find(o => o.userEmail === user?.email);
             return (
               <div key={run.id} className={`bg-white rounded-[2.5rem] p-6 shadow-xl border-2 transition-all ${run.status === 'departed' ? 'border-indigo-500 shadow-indigo-100' : 'border-white'}`}>
                  <div className="flex justify-between items-start mb-6">
                     <div className="flex gap-4">
                        <div className="w-14 h-14 rounded-2xl bg-slate-50 flex items-center justify-center text-2xl text-slate-400 shadow-inner">
                           <i className={`fas ${run.status === 'departed' ? 'fa-bolt text-indigo-500' : 'fa-hamburger'}`}></i>
                        </div>
                        <div>
                           <h4 className="text-xl font-black text-slate-800 tracking-tight">{run.destination}</h4>
                           <div className="flex items-center gap-2 mt-1">
                              <span className="text-[10px] font-black bg-slate-100 text-slate-500 px-2 py-0.5 rounded-full">{run.status.toUpperCase()}</span>
                              <span className="text-[10px] font-black text-slate-400 uppercase">{run.runnerName} • {run.minutesUntilDeparture}m wait</span>
                           </div>
                        </div>
                     </div>
                  </div>

                  {run.orders.length > 0 && (
                     <div className="space-y-2 mb-6">
                        {run.orders.map(o => (
                           <div key={o.id} className={`flex justify-between items-center p-3 rounded-2xl text-xs border ${o.userEmail === user?.email ? 'bg-indigo-50 border-indigo-200' : 'bg-slate-50/50 border-slate-100'}`}>
                              <div className="flex items-center gap-3">
                                 <span className="font-bold text-slate-700">{o.userName}</span>
                                 <span className="text-slate-400 truncate max-w-[150px]">"{o.itemDescription}"</span>
                              </div>
                              {o.userEmail === user?.email && run.status === 'departed' && !o.cibusCode && (
                                 <button onClick={() => setModals({...modals, cibus: {runId: run.id, orderId: o.id}})} className="bg-indigo-600 text-white px-3 py-1 rounded-lg text-[10px] font-black uppercase animate-pulse">Pay</button>
                              )}
                              {o.cibusCode && <span className="text-[10px] font-black text-emerald-600 uppercase"><i className="fas fa-check-circle"></i> Paid</span>}
                           </div>
                        ))}
                     </div>
                  )}

                  <div className="flex gap-3">
                     {isRunner ? (
                        run.status === 'active' ? (
                           <Button onClick={() => actions.depart(run.id)} className="flex-1 h-14 bg-indigo-600 text-[11px] font-black uppercase rounded-2xl shadow-lg shadow-indigo-100">Broadcast Departure</Button>
                        ) : (
                           <Button onClick={() => setModals({...modals, arrive: run.id})} className="flex-1 h-14 bg-emerald-600 text-[11px] font-black uppercase rounded-2xl shadow-lg shadow-emerald-100">Signal Arrival</Button>
                        )
                     ) : !myOrder && run.status === 'active' && run.orders.length < run.maxOrders && (
                        <Button onClick={() => setModals({...modals, join: run.id})} className="flex-1 h-14 bg-slate-800 text-[11px] font-black uppercase rounded-2xl">Join Manifest</Button>
                     )}
                     {myOrder && <div className="flex-1 text-center py-4 text-[10px] font-black uppercase text-indigo-400 tracking-widest"><i className="fas fa-check mr-2"></i> You are in this run</div>}
                  </div>
               </div>
             );
           })}
        </div>
      </main>

      {/* MODALS */}
      {modals.create && (
        <Overlay title="Mission Config" onClose={() => setModals({...modals, create: false})}>
           <form onSubmit={actions.createRun} className="space-y-4">
              <input required className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Destination Name" value={inputs.dest} onChange={e => setInputs({...inputs, dest: e.target.value})} />
              <div className="grid grid-cols-2 gap-4">
                 <input required type="number" className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Minutes" value={inputs.time} onChange={e => setInputs({...inputs, time: Number(e.target.value)})} />
                 <input required type="number" className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Capacity" value={inputs.max} onChange={e => setInputs({...inputs, max: Number(e.target.value)})} />
              </div>
              <Button type="submit" className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl">Establish Run</Button>
           </form>
        </Overlay>
      )}

      {modals.join && (
        <Overlay title="Join Manifest" onClose={() => setModals({...modals, join: null})}>
           <form onSubmit={(e) => { e.preventDefault(); actions.join(modals.join); }} className="space-y-4">
              <input required className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="What are you eating?" value={inputs.item} onChange={e => setInputs({...inputs, item: e.target.value})} />
              <input required className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Your Floor" value={inputs.floor} onChange={e => setInputs({...inputs, floor: e.target.value})} />
              <Button type="submit" className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl">Confirm Join</Button>
           </form>
        </Overlay>
      )}

      {modals.arrive && (
        <Overlay title="Drop-off Logic" onClose={() => setModals({...modals, arrive: null})}>
           <form onSubmit={(e) => { e.preventDefault(); actions.arrive(modals.arrive); }} className="space-y-4">
              <input required autoFocus className="w-full p-4 bg-slate-50 rounded-2xl font-bold text-center" placeholder="Where is the food?" value={inputs.loc} onChange={e => setInputs({...inputs, loc: e.target.value})} />
              <Button type="submit" className="w-full h-14 bg-emerald-600 font-black uppercase text-[11px] rounded-2xl">Blast Final Alert</Button>
           </form>
        </Overlay>
      )}
    </div>
  );
};

const Overlay: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
  <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md z-[300] flex items-center justify-center p-6 overflow-hidden">
    <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-[340px] shadow-2xl animate-in zoom-in-95 duration-300 relative">
      <div className="flex justify-between items-center mb-8">
         <h3 className="text-[11px] font-black uppercase tracking-[0.3em] text-indigo-600">{title}</h3>
         <button onClick={onClose} className="w-9 h-9 rounded-2xl bg-slate-50 text-slate-300 hover:text-slate-600 transition-colors flex items-center justify-center"><i className="fas fa-times"></i></button>
      </div>
      {children}
    </div>
  </div>
);

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { FoodRun, Order, AppEvent, WaitingOrder, UserNotification } from './types';
import { Button } from './components/Button';
import { sendToGoogleChat } from './services/googleChatService';
import { ImageStudio } from './components/ImageStudio';

const ADMIN_EMAIL = 'admin@yourcompany.com'; 
const ALLOWED_DOMAIN = 'yourcompany.com';

const App: React.FC = () => {
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [notifications, setNotifications] = useState<UserNotification[]>([]);
  const [simulatorMode, setSimulatorMode] = useState(false);
  const [webhookUrl, setWebhookUrl] = useState<string>(localStorage.getItem('lunchrun_webhook') || '');
  const [messagePrefix, setMessagePrefix] = useState<string>(localStorage.getItem('lunchrun_prefix') || '[LunchRun]');
  const [defaultWait, setDefaultWait] = useState<number>(Number(localStorage.getItem('lunchrun_def_wait')) || 20);
  const [defaultMax, setDefaultMax] = useState<number>(Number(localStorage.getItem('lunchrun_def_max')) || 5);
  const [isSimulatorAdmin, setIsSimulatorAdmin] = useState(false);

  useEffect(() => {
    const savedHistory = localStorage.getItem('lunchrun_history');
    const savedWaitlist = localStorage.getItem('lunchrun_waitlist');
    const savedNotifications = localStorage.getItem('lunchrun_notifications');
    const savedRuns = localStorage.getItem('lunchrun_active_runs');

    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedWaitlist) setWaitingOrders(JSON.parse(savedWaitlist));
    if (savedNotifications) setNotifications(JSON.parse(savedNotifications));
    if (savedRuns) setRuns(JSON.parse(savedRuns));
  }, []);

  useEffect(() => {
    localStorage.setItem('lunchrun_active_runs', JSON.stringify(runs));
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(waitingOrders));
    localStorage.setItem('lunchrun_notifications', JSON.stringify(notifications));
    localStorage.setItem('lunchrun_history', JSON.stringify(history));
    localStorage.setItem('lunchrun_webhook', webhookUrl);
    localStorage.setItem('lunchrun_prefix', messagePrefix);
    localStorage.setItem('lunchrun_def_wait', defaultWait.toString());
    localStorage.setItem('lunchrun_def_max', defaultMax.toString());
  }, [runs, waitingOrders, notifications, history, webhookUrl, messagePrefix, defaultWait, defaultMax]);

  const sharedActions = {
    runs, setRuns,
    history, setHistory,
    waitingOrders, setWaitingOrders,
    notifications, setNotifications,
    webhookUrl, setWebhookUrl,
    messagePrefix, setMessagePrefix,
    defaultWait, setDefaultWait,
    defaultMax, setDefaultMax,
    isSimulatorAdmin
  };

  return (
    <div className={`min-h-screen transition-all duration-500 ${simulatorMode ? 'p-2 sm:p-4 bg-slate-200' : 'bg-slate-50'}`}>
      <div className="bg-slate-900 text-white/70 px-6 py-2 flex justify-between items-center text-[10px] font-black uppercase tracking-[0.2em] shadow-xl sticky top-0 z-[100] rounded-b-xl sm:mx-4">
        <div className="flex items-center gap-4">
          <div className={`w-2 h-2 rounded-full animate-pulse ${isSimulatorAdmin ? 'bg-amber-400' : 'bg-indigo-400'}`}></div>
          <span>{isSimulatorAdmin ? 'Admin Terminal' : 'LunchRun Network'}</span>
        </div>
        <div className="flex gap-4">
           {simulatorMode && (
             <button 
               onClick={() => setIsSimulatorAdmin(!isSimulatorAdmin)} 
               className={`px-4 py-1.5 rounded-full border transition-all flex items-center gap-2 ${isSimulatorAdmin ? 'bg-amber-500 border-amber-400 text-slate-900 shadow-lg' : 'border-slate-700 hover:text-white'}`}
             >
               <i className={`fas ${isSimulatorAdmin ? 'fa-user-shield' : 'fa-unlock'}`}></i>
               {isSimulatorAdmin ? 'ADMIN MODE' : 'USER MODE'}
             </button>
           )}
           <button onClick={() => setSimulatorMode(!simulatorMode)} className={`px-4 py-1.5 rounded-full border transition-all ${simulatorMode ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'border-slate-700 hover:text-white hover:border-slate-500'}`}>
             {simulatorMode ? 'Exit Simulator' : 'Split-Screen QA'}
           </button>
        </div>
      </div>

      {simulatorMode ? (
        <div className="flex flex-col md:flex-row h-[calc(100vh-80px)] gap-4 mt-4 overflow-hidden">
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-indigo-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">USER 1: RUNNER VIEW</div>
             <AppInstance userOverride={{ name: 'Avi', email: `avi@${ALLOWED_DOMAIN}` }} {...sharedActions} />
          </div>
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-emerald-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">USER 2: ORDERER VIEW</div>
             <AppInstance userOverride={{ name: 'Dana', email: `dana@${ALLOWED_DOMAIN}` }} {...sharedActions} />
          </div>
        </div>
      ) : (
        <div className="max-w-4xl mx-auto mt-6">
          <AppInstance {...sharedActions} />
        </div>
      )}
    </div>
  );
};

const AppInstance: React.FC<any> = ({ 
  userOverride, 
  runs, setRuns, 
  history, setHistory, 
  waitingOrders, setWaitingOrders, 
  notifications, setNotifications,
  webhookUrl, setWebhookUrl,
  messagePrefix, setMessagePrefix,
  defaultWait, setDefaultWait,
  defaultMax, setDefaultMax,
  isSimulatorAdmin
}) => {
  const [user, setUser] = useState<{ name: string; email: string; isAdmin?: boolean } | null>(userOverride || null);
  const [activeToast, setActiveToast] = useState<{message: string, type: string} | null>(null);
  const [authError, setAuthError] = useState<string | null>(null);
  const [testLoading, setTestLoading] = useState(false);
  const lastNotifId = useRef<string | null>(null);

  const [modals, setModals] = useState<{ [key: string]: boolean | any }>({
    create: false, waitlist: false, join: null, cibus: null, arrive: null, preview: null
  });

  const [loginForm, setLoginForm] = useState({ username: '', password: '', visible: false });
  const [inputs, setInputs] = useState({ dest: '', time: defaultWait, max: defaultMax, item: '', floor: '', cibus: '', loc: '' });

  useEffect(() => {
    if (!user) return;
    // Filtering notifications: Only show alerts where targetEmail matches current user
    const userNotifs = notifications.filter((n: UserNotification) => n.targetEmail === user.email);
    const newest = userNotifs[0];

    if (newest && newest.id !== lastNotifId.current) {
       lastNotifId.current = newest.id;
       setActiveToast({ message: newest.message, type: newest.type });
       setTimeout(() => setActiveToast(null), 8000);
    }
  }, [notifications, user]);

  const triggerPrivateAlert = (targetEmail: string, type: UserNotification['type'], message: string) => {
    const newNotif: UserNotification = {
      id: Math.random().toString(36).substr(2, 9),
      targetEmail, type, message, runId: 'sys', timestamp: Date.now(), read: false
    };
    setNotifications((prev: any) => [newNotif, ...prev]);
  };

  const actions = {
    handleManualLogin: (e: React.FormEvent) => {
      e.preventDefault();
      if (loginForm.username === 'admin' && loginForm.password === 'admin') {
        setUser({ name: 'System Admin', email: 'admin@system.local', isAdmin: true });
        setAuthError(null);
      } else {
        setAuthError("Wrong credentials. Try admin/admin");
      }
    },
    createRun: (e: React.FormEvent) => {
      e.preventDefault();
      const newRun: FoodRun = {
        id: Math.random().toString(36).substr(2, 9), runnerName: user?.name || '', runnerEmail: user?.email || '',
        destination: inputs.dest, departureTime: Date.now() + inputs.time * 60000, minutesUntilDeparture: inputs.time,
        maxOrders: inputs.max, status: 'active', orders: []
      };
      setRuns((prev: any) => [newRun, ...prev]);
      setModals({ ...modals, create: false });

      // PUBLIC BROADCAST
      sendToGoogleChat(webhookUrl, {
        title: "New Food Run!",
        subtitle: `Destination: ${inputs.dest}`,
        details: `Departing in <b>${inputs.time} mins</b>. Lead by ${user?.name}.`,
        buttonText: "Open App to Join",
        buttonUrl: window.location.href,
        prefix: messagePrefix
      });
    },
    depart: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, status: 'departed' } : r));

      // PUBLIC BROADCAST (Milestone)
      sendToGoogleChat(webhookUrl, {
        title: "Runner is Leaving!",
        subtitle: `En route to ${run.destination}`,
        details: "The runner has departed. Last chance for orders is over.",
        prefix: messagePrefix
      });

      // PRIVATE ALERTS (To orderers only)
      run.orders.forEach(order => {
        triggerPrivateAlert(order.userEmail, 'departed', `Runner leaving for ${run.destination}! Please provide your payment code now.`);
      });
    },
    arrive: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;

      // PUBLIC BROADCAST (Milestone)
      sendToGoogleChat(webhookUrl, {
        title: "Food has Arrived!",
        subtitle: `From ${run.destination}`,
        details: `Pickup point: <b>${inputs.loc}</b>.`,
        prefix: messagePrefix
      });

      // PRIVATE ALERTS (To orderers only)
      run.orders.forEach(order => {
        triggerPrivateAlert(order.userEmail, 'arrived', `Your food is waiting at ${inputs.loc}!`);
      });

      setHistory((prev: any) => [{ ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() }, ...prev]);
      setRuns(runs.filter((r: any) => r.id !== runId));
      setModals({ ...modals, arrive: null });
    },
    join: (runId: string) => {
      const order: Order = { 
        id: Math.random().toString(36).substr(2, 9), 
        userName: user?.name || '', 
        userEmail: user?.email || '', 
        itemDescription: inputs.item, 
        floor: inputs.floor, 
        cibusCode: '', 
        timestamp: Date.now() 
      };
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: [...r.orders, order] } : r));
      setModals({ ...modals, join: null });
      // Note: Joining is private, no Webhook sent to avoid spamming the channel
    },
    // Fix: Added missing exportConfig method
    exportConfig: () => {
      const config = { webhookUrl, messagePrefix, defaultWait, defaultMax };
      const configStr = JSON.stringify(config, null, 2);
      navigator.clipboard.writeText(configStr).then(() => {
        alert("Configuration copied to clipboard!");
      }).catch(err => {
        console.error('Failed to copy: ', err);
        alert("Configuration: " + configStr);
      });
    },
    // Fix: Added missing testWebhook method
    testWebhook: async () => {
      if (!webhookUrl) {
        alert("Please enter a webhook URL first.");
        return;
      }
      setTestLoading(true);
      try {
        const success = await sendToGoogleChat(webhookUrl, {
          title: "Test Connection",
          subtitle: "Webhook Verification",
          details: "If you see this, your webhook is working correctly.",
          prefix: messagePrefix
        });
        if (success) {
          alert("Test message sent successfully!");
        } else {
          alert("Failed to send test message. Please verify the Webhook URL.");
        }
      } catch (err) {
        console.error(err);
        alert("An error occurred while testing the webhook.");
      } finally {
        setTestLoading(false);
      }
    }
  };

  const isAdmin = user?.isAdmin || isSimulatorAdmin;

  return (
    <div className="h-full flex flex-col bg-slate-50 relative">
      {/* PERSONAL TOAST - Only shows for the targeted user */}
      {activeToast && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-[200] animate-in slide-in-from-top-10">
          <div className="bg-slate-900 text-white px-6 py-4 rounded-3xl shadow-2xl flex items-center gap-4 border border-indigo-500/50 min-w-[300px]">
             <div className="w-10 h-10 rounded-2xl bg-indigo-600 flex items-center justify-center text-lg"><i className="fas fa-bell animate-swing"></i></div>
             <div>
                <p className="text-[10px] font-black uppercase text-indigo-400 tracking-widest">Personal Alert</p>
                <p className="text-[13px] font-bold pr-4">{activeToast.message}</p>
             </div>
             <button onClick={() => setActiveToast(null)} className="ml-auto text-white/30 hover:text-white"><i className="fas fa-times"></i></button>
          </div>
        </div>
      )}

      <header className={`px-6 py-4 flex justify-between items-center border-b ${isAdmin ? 'bg-amber-50 border-amber-100' : 'bg-white border-slate-100'}`}>
        <div className="flex items-center gap-3">
           <div className={`w-9 h-9 rounded-xl flex items-center justify-center text-white text-lg shadow-lg ${isAdmin ? 'bg-amber-500' : 'bg-indigo-600'}`}><i className={`fas ${isAdmin ? 'fa-user-shield' : 'fa-bicycle'}`}></i></div>
           <div>
             <span className="font-black text-sm text-slate-800 tracking-tight">LUNCHRUN</span>
             <span className="text-[8px] font-black text-slate-400 uppercase block">{user?.email}</span>
           </div>
        </div>
        <img src={`https://ui-avatars.com/api/?name=${user?.name}&background=${isAdmin ? 'f59e0b' : '6366f1'}&color=fff`} className="w-9 h-9 rounded-2xl border-2 border-white shadow-sm" alt="u" />
      </header>

      <main className="flex-1 overflow-y-auto p-4 space-y-4">
        {isAdmin && (
          <div className="bg-slate-900 rounded-[2.5rem] p-6 text-white shadow-2xl border-4 border-amber-500/20 relative overflow-hidden">
             <div className="flex justify-between items-center mb-6">
                <div>
                   <h3 className="text-amber-400 text-[10px] font-black uppercase tracking-[0.2em]">Channel Configuration</h3>
                   <p className="text-white/40 text-[9px]">Settings shared via browser sync/export.</p>
                </div>
                <div className="flex gap-2">
                   <button onClick={() => actions.exportConfig()} className="bg-white/10 p-2 rounded-xl text-[10px]"><i className="fas fa-share-nodes"></i></button>
                </div>
             </div>
             <div className="space-y-4">
                <div>
                   <label className="text-[9px] font-black uppercase text-white/40 block mb-2 pl-1">Space Webhook (Public Channel)</label>
                   <div className="flex gap-2">
                      <input className="flex-1 p-3 bg-white/5 border border-white/10 rounded-2xl font-bold text-xs outline-none focus:ring-2 focus:ring-amber-500" value={webhookUrl} onChange={e => setWebhookUrl(e.target.value)} placeholder="https://chat.googleapis.com/..." />
                      <Button onClick={() => actions.testWebhook()} isLoading={testLoading} className="h-10 px-6 bg-amber-500 text-slate-900 text-[10px] font-black uppercase">Test</Button>
                   </div>
                </div>
                <div className="p-3 bg-white/5 rounded-2xl border border-white/5">
                   <p className="text-[9px] font-black text-amber-500 uppercase flex items-center gap-2"><i className="fas fa-info-circle"></i> Security Note</p>
                   <p className="text-[10px] text-white/50 leading-relaxed mt-1">Personal alerts (Waitlist, Payment) are private and visible only to the specific user in-app.</p>
                </div>
             </div>
          </div>
        )}

        <div className="flex justify-between items-center bg-white p-3 rounded-2xl border border-slate-100 shadow-sm">
           <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-2">Active Missions</span>
           <div className="flex gap-2">
              <Button onClick={() => setModals({...modals, preview: true})} variant="ghost" className="h-9 px-4 text-[10px] font-black uppercase rounded-xl border border-slate-100">
                <i className="fas fa-wand-magic-sparkles mr-1"></i> Studio
              </Button>
              <Button onClick={() => setModals({...modals, waitlist: true})} variant="ghost" className="h-9 px-4 text-[10px] font-black uppercase rounded-xl border border-slate-100">Waitlist</Button>
              <Button onClick={() => setModals({...modals, create: true})} className="h-9 px-4 text-[10px] font-black uppercase rounded-xl bg-indigo-600 shadow-lg">Start Run</Button>
           </div>
        </div>

        <div className="space-y-4 pb-20">
           {runs.length === 0 && (
             <div className="py-20 text-center opacity-20">
                <div className="w-20 h-20 bg-slate-200 rounded-full mx-auto flex items-center justify-center mb-4"><i className="fas fa-shopping-basket text-2xl text-slate-400"></i></div>
                <p className="text-[10px] font-black uppercase tracking-widest">No active runs in your sector</p>
             </div>
           )}

           {runs.map((run: FoodRun) => {
             const isRunner = user?.email === run.runnerEmail;
             const myOrder = run.orders.find(o => o.userEmail === user?.email);
             return (
               <div key={run.id} className={`bg-white rounded-[2.5rem] p-6 shadow-xl border-2 transition-all ${run.status === 'departed' ? 'border-indigo-500 shadow-indigo-100' : 'border-white'}`}>
                  <div className="flex justify-between items-start mb-6">
                     <div className="flex gap-4">
                        <div className="w-14 h-14 rounded-2xl bg-slate-50 flex items-center justify-center text-2xl text-slate-400 shadow-inner">
                           <i className={`fas ${run.status === 'departed' ? 'fa-bolt text-indigo-500' : 'fa-hamburger'}`}></i>
                        </div>
                        <div>
                           <h4 className="text-xl font-black text-slate-800 tracking-tight">{run.destination}</h4>
                           <div className="flex items-center gap-2 mt-1">
                              <span className="text-[10px] font-black bg-slate-100 text-slate-500 px-2 py-0.5 rounded-full">{run.status.toUpperCase()}</span>
                              <span className="text-[10px] font-black text-slate-400 uppercase">{run.runnerName} • {run.minutesUntilDeparture}m wait</span>
                           </div>
                        </div>
                     </div>
                  </div>

                  {run.orders.length > 0 && (
                     <div className="space-y-2 mb-6">
                        {run.orders.map(o => (
                           <div key={o.id} className={`flex justify-between items-center p-3 rounded-2xl text-xs border ${o.userEmail === user?.email ? 'bg-indigo-50 border-indigo-200' : 'bg-slate-50/50 border-slate-100'}`}>
                              <div className="flex items-center gap-3">
                                 <span className="font-bold text-slate-700">{o.userName}</span>
                                 <span className="text-slate-400 truncate max-w-[150px]">"{o.itemDescription}"</span>
                              </div>
                              {o.userEmail === user?.email && run.status === 'departed' && !o.cibusCode && (
                                 <button onClick={() => setModals({...modals, cibus: {runId: run.id, orderId: o.id}})} className="bg-indigo-600 text-white px-3 py-1 rounded-lg text-[10px] font-black uppercase animate-pulse">Pay</button>
                              )}
                              {o.cibusCode && <span className="text-[10px] font-black text-emerald-600 uppercase"><i className="fas fa-check-circle"></i> Paid</span>}
                           </div>
                        ))}
                     </div>
                  )}

                  <div className="flex gap-3">
                     {isRunner ? (
                        run.status === 'active' ? (
                           <Button onClick={() => actions.depart(run.id)} className="flex-1 h-14 bg-indigo-600 text-[11px] font-black uppercase rounded-2xl shadow-lg shadow-indigo-100">Broadcast Departure</Button>
                        ) : (
                           <Button onClick={() => setModals({...modals, arrive: run.id})} className="flex-1 h-14 bg-emerald-600 text-[11px] font-black uppercase rounded-2xl shadow-lg shadow-emerald-100">Signal Arrival</Button>
                        )
                     ) : !myOrder && run.status === 'active' && run.orders.length < run.maxOrders && (
                        <Button onClick={() => setModals({...modals, join: run.id})} className="flex-1 h-14 bg-slate-800 text-[11px] font-black uppercase rounded-2xl">Join Manifest</Button>
                     )}
                     {myOrder && <div className="flex-1 text-center py-4 text-[10px] font-black uppercase text-indigo-400 tracking-widest"><i className="fas fa-check mr-2"></i> You are in this run</div>}
                  </div>
               </div>
             );
           })}
        </div>
      </main>

      {/* MODALS */}
      {modals.create && (
        <Overlay title="Mission Config" onClose={() => setModals({...modals, create: false})}>
           <form onSubmit={actions.createRun} className="space-y-4">
              <input required className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Destination Name" value={inputs.dest} onChange={e => setInputs({...inputs, dest: e.target.value})} />
              <div className="grid grid-cols-2 gap-4">
                 <input required type="number" className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Minutes" value={inputs.time} onChange={e => setInputs({...inputs, time: Number(e.target.value)})} />
                 <input required type="number" className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Capacity" value={inputs.max} onChange={e => setInputs({...inputs, max: Number(e.target.value)})} />
              </div>
              <Button type="submit" className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl">Establish Run</Button>
           </form>
        </Overlay>
      )}

      {modals.join && (
        <Overlay title="Join Manifest" onClose={() => setModals({...modals, join: null})}>
           <form onSubmit={(e) => { e.preventDefault(); actions.join(modals.join); }} className="space-y-4">
              <input required className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="What are you eating?" value={inputs.item} onChange={e => setInputs({...inputs, item: e.target.value})} />
              <input required className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Your Floor" value={inputs.floor} onChange={e => setInputs({...inputs, floor: e.target.value})} />
              <Button type="submit" className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl">Confirm Join</Button>
           </form>
        </Overlay>
      )}

      {modals.arrive && (
        <Overlay title="Drop-off Logic" onClose={() => setModals({...modals, arrive: null})}>
           <form onSubmit={(e) => { e.preventDefault(); actions.arrive(modals.arrive); }} className="space-y-4">
              <input required autoFocus className="w-full p-4 bg-slate-50 rounded-2xl font-bold text-center" placeholder="Where is the food?" value={inputs.loc} onChange={e => setInputs({...inputs, loc: e.target.value})} />
              <Button type="submit" className="w-full h-14 bg-emerald-600 font-black uppercase text-[11px] rounded-2xl">Blast Final Alert</Button>
           </form>
        </Overlay>
      )}

      {modals.waitlist && (
        <Overlay title="Global Waitlist" onClose={() => setModals({...modals, waitlist: false})}>
           <div className="space-y-4 max-h-[400px] overflow-y-auto pr-2">
              {waitingOrders.length === 0 ? (
                <div className="text-center py-8 opacity-40">
                  <i className="fas fa-clock text-2xl mb-2"></i>
                  <p className="text-[10px] font-black uppercase">Waitlist is empty</p>
                </div>
              ) : (
                waitingOrders.map((wo: any) => (
                  <div key={wo.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                    <div className="flex justify-between items-start">
                      <div>
                        <p className="font-bold text-slate-800 text-xs">{wo.userName}</p>
                        <p className="text-[10px] text-slate-400">Craving: {wo.itemDescription}</p>
                      </div>
                      <span className="text-[9px] font-black bg-white px-2 py-0.5 rounded-full shadow-sm">FL {wo.floor}</span>
                    </div>
                  </div>
                ))
              )}
           </div>
        </Overlay>
      )}

      {modals.cibus && (
        <Overlay title="Payment Code" onClose={() => setModals({...modals, cibus: null})}>
           <div className="space-y-4">
              <p className="text-[10px] text-slate-500 font-bold text-center">Enter your Cibus code for the runner.</p>
              <input 
                required 
                className="w-full p-4 bg-slate-50 rounded-2xl font-black text-center text-xl tracking-widest border-2 border-indigo-100" 
                placeholder="XXXXXX" 
                value={inputs.cibus} 
                onChange={e => setInputs({...inputs, cibus: e.target.value})} 
              />
              <Button 
                onClick={() => {
                  const { runId, orderId } = modals.cibus;
                  setRuns(runs.map((r: any) => r.id === runId ? {
                    ...r,
                    orders: r.orders.map((o: any) => o.id === orderId ? { ...o, cibusCode: inputs.cibus } : o)
                  } : r));
                  setModals({...modals, cibus: null});
                  setInputs({...inputs, cibus: ''});
                }} 
                className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl"
              >
                Submit Payment
              </Button>
           </div>
        </Overlay>
      )}

      {modals.preview && (
        <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md z-[400] flex items-center justify-center p-4">
          <div className="w-full max-w-2xl max-h-[90vh] overflow-y-auto">
            <div className="flex justify-end mb-2">
              <button onClick={() => setModals({...modals, preview: false})} className="bg-white/10 hover:bg-white/20 text-white w-10 h-10 rounded-full flex items-center justify-center transition-colors">
                <i className="fas fa-times"></i>
              </button>
            </div>
            <ImageStudio />
          </div>
        </div>
      )}
    </div>
  );
};

const Overlay: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
  <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md z-[300] flex items-center justify-center p-6 overflow-hidden">
    <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-[340px] shadow-2xl animate-in zoom-in-95 duration-300 relative">
      <div className="flex justify-between items-center mb-8">
         <h3 className="text-[11px] font-black uppercase tracking-[0.3em] text-indigo-600">{title}</h3>
         <button onClick={onClose} className="w-9 h-9 rounded-2xl bg-slate-50 text-slate-300 hover:text-slate-600 transition-colors flex items-center justify-center"><i className="fas fa-times"></i></button>
      </div>
      {children}
    </div>
  </div>
);

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { FoodRun, Order, AppEvent, WaitingOrder, UserNotification } from './types';
import { Button } from './components/Button';
import { sendToGoogleChat } from './services/googleChatService';

const ADMIN_EMAIL = 'admin@yourcompany.com'; 
const ALLOWED_DOMAIN = 'yourcompany.com';

/**
 * Normalizes business names for consistent matching.
 * Removes spaces, dashes, and common prefixes to compare strings like "יום טוב" and "יומטוב".
 */
const normalizeBusinessName = (name: string): string => {
  return name.trim().toLowerCase()
    .replace(/\s+/g, '')       // Remove all whitespace
    .replace(/[-_]/g, '')      // Remove dashes/underscores
    .replace(/^ה/g, '');       // Optional: Remove Hebrew 'Ha' prefix if needed
};

const App: React.FC = () => {
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [notifications, setNotifications] = useState<UserNotification[]>([]);
  const [simulatorMode, setSimulatorMode] = useState(false);
  const [webhookUrl, setWebhookUrl] = useState<string>(localStorage.getItem('lunchrun_webhook') || '');
  const [messagePrefix, setMessagePrefix] = useState<string>(localStorage.getItem('lunchrun_prefix') || '[LunchRun]');
  const [defaultWait, setDefaultWait] = useState<number>(Number(localStorage.getItem('lunchrun_def_wait')) || 20);
  const [defaultMax, setDefaultMax] = useState<number>(Number(localStorage.getItem('lunchrun_def_max')) || 5);
  const [isSimulatorAdmin, setIsSimulatorAdmin] = useState(false);

  useEffect(() => {
    const savedHistory = localStorage.getItem('lunchrun_history');
    const savedWaitlist = localStorage.getItem('lunchrun_waitlist');
    const savedNotifications = localStorage.getItem('lunchrun_notifications');
    const savedRuns = localStorage.getItem('lunchrun_active_runs');

    if (savedHistory) setHistory(JSON.parse(savedHistory));
    if (savedWaitlist) setWaitingOrders(JSON.parse(savedWaitlist));
    if (savedNotifications) setNotifications(JSON.parse(savedNotifications));
    if (savedRuns) setRuns(JSON.parse(savedRuns));
  }, []);

  useEffect(() => {
    localStorage.setItem('lunchrun_active_runs', JSON.stringify(runs));
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(waitingOrders));
    localStorage.setItem('lunchrun_notifications', JSON.stringify(notifications));
    localStorage.setItem('lunchrun_history', JSON.stringify(history));
    localStorage.setItem('lunchrun_webhook', webhookUrl);
    localStorage.setItem('lunchrun_prefix', messagePrefix);
    localStorage.setItem('lunchrun_def_wait', defaultWait.toString());
    localStorage.setItem('lunchrun_def_max', defaultMax.toString());
  }, [runs, waitingOrders, notifications, history, webhookUrl, messagePrefix, defaultWait, defaultMax]);

  const sharedActions = {
    runs, setRuns,
    history, setHistory,
    waitingOrders, setWaitingOrders,
    notifications, setNotifications,
    webhookUrl, setWebhookUrl,
    messagePrefix, setMessagePrefix,
    defaultWait, setDefaultWait,
    defaultMax, setDefaultMax,
    isSimulatorAdmin
  };

  return (
    <div className={`min-h-screen transition-all duration-500 ${simulatorMode ? 'p-2 sm:p-4 bg-slate-200' : 'bg-slate-50'}`}>
      <div className="bg-slate-900 text-white/70 px-6 py-2 flex justify-between items-center text-[10px] font-black uppercase tracking-[0.2em] shadow-xl sticky top-0 z-[100] rounded-b-xl sm:mx-4">
        <div className="flex items-center gap-4">
          <div className={`w-2 h-2 rounded-full animate-pulse ${isSimulatorAdmin ? 'bg-amber-400' : 'bg-indigo-400'}`}></div>
          <span>{isSimulatorAdmin ? 'Admin Terminal' : 'LunchRun Network'}</span>
        </div>
        <div className="flex gap-4">
           {simulatorMode && (
             <button 
               onClick={() => setIsSimulatorAdmin(!isSimulatorAdmin)} 
               className={`px-4 py-1.5 rounded-full border transition-all flex items-center gap-2 ${isSimulatorAdmin ? 'bg-amber-500 border-amber-400 text-slate-900 shadow-lg' : 'border-slate-700 hover:text-white'}`}
             >
               <i className={`fas ${isSimulatorAdmin ? 'fa-user-shield' : 'fa-unlock'}`}></i>
               {isSimulatorAdmin ? 'ADMIN MODE' : 'USER MODE'}
             </button>
           )}
           <button onClick={() => setSimulatorMode(!simulatorMode)} className={`px-4 py-1.5 rounded-full border transition-all ${simulatorMode ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'border-slate-700 hover:text-white hover:border-slate-500'}`}>
             {simulatorMode ? 'Exit Simulator' : 'Split-Screen QA'}
           </button>
        </div>
      </div>

      {simulatorMode ? (
        <div className="flex flex-col md:flex-row h-[calc(100vh-80px)] gap-4 mt-4 overflow-hidden">
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-indigo-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">USER 1: RUNNER VIEW</div>
             <AppInstance userOverride={{ name: 'Avi', email: `avi@${ALLOWED_DOMAIN}` }} {...sharedActions} />
          </div>
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-emerald-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">USER 2: ORDERER VIEW</div>
             <AppInstance userOverride={{ name: 'Dana', email: `dana@${ALLOWED_DOMAIN}` }} {...sharedActions} />
          </div>
        </div>
      ) : (
        <div className="max-w-4xl mx-auto mt-6">
          <AppInstance {...sharedActions} />
        </div>
      )}
    </div>
  );
};

const AppInstance: React.FC<any> = ({ 
  userOverride, 
  runs, setRuns, 
  history, setHistory, 
  waitingOrders, setWaitingOrders, 
  notifications, setNotifications,
  webhookUrl, setWebhookUrl,
  messagePrefix, setMessagePrefix,
  defaultWait, setDefaultWait,
  defaultMax, setDefaultMax,
  isSimulatorAdmin
}) => {
  const [user, setUser] = useState<{ name: string; email: string; isAdmin?: boolean } | null>(userOverride || null);
  const [activeToast, setActiveToast] = useState<{message: string, type: string} | null>(null);
  const [authError, setAuthError] = useState<string | null>(null);
  const [testLoading, setTestLoading] = useState(false);
  const lastNotifId = useRef<string | null>(null);

  const [modals, setModals] = useState<{ [key: string]: boolean | any }>({
    create: false, waitlist: false, join: null, cibus: null, arrive: null
  });

  const [loginForm, setLoginForm] = useState({ username: '', password: '', visible: false });
  const [inputs, setInputs] = useState({ dest: '', time: defaultWait, max: defaultMax, item: '', floor: '', cibus: '', loc: '' });

  // Compute unique destinations from history and runs for suggestions
  const destinationSuggestions = useMemo(() => {
    const fromHistory = history.map((r: FoodRun) => r.destination);
    const fromRuns = runs.map((r: FoodRun) => r.destination);
    const fromWaitlist = waitingOrders.map((wo: WaitingOrder) => wo.destination);
    return Array.from(new Set([...fromHistory, ...fromRuns, ...fromWaitlist])).sort();
  }, [history, runs, waitingOrders]);

  useEffect(() => {
    if (!user) return;
    const userNotifs = notifications.filter((n: UserNotification) => n.targetEmail === user.email);
    const newest = userNotifs[0];

    if (newest && newest.id !== lastNotifId.current) {
       lastNotifId.current = newest.id;
       setActiveToast({ message: newest.message, type: newest.type });
       setTimeout(() => setActiveToast(null), 8000);
    }
  }, [notifications, user]);

  const triggerPrivateAlert = (targetEmail: string, type: UserNotification['type'], message: string) => {
    const newNotif: UserNotification = {
      id: Math.random().toString(36).substr(2, 9),
      targetEmail, type, message, runId: 'sys', timestamp: Date.now(), read: false
    };
    setNotifications((prev: any) => [newNotif, ...prev]);
  };

  const actions = {
    handleManualLogin: (e: React.FormEvent) => {
      e.preventDefault();
      if (loginForm.username === 'admin' && loginForm.password === 'admin') {
        setUser({ name: 'System Admin', email: 'admin@system.local', isAdmin: true });
        setAuthError(null);
      } else {
        setAuthError("Wrong credentials. Try admin/admin");
      }
    },
    createRun: (e: React.FormEvent) => {
      e.preventDefault();

      // Matching Logic: Normalize both the new destination and waitlist destinations
      const normalizedNewDest = normalizeBusinessName(inputs.dest);
      const matches = waitingOrders.filter(wo => normalizeBusinessName(wo.destination) === normalizedNewDest);
      const ordersToPull = matches.slice(0, inputs.max);

      const orders: Order[] = ordersToPull.map(wo => {
        triggerPrivateAlert(wo.userEmail, 'waitlist_promoted', `Runner ${user?.name} picked up your request from ${wo.destination}!`);
        return { 
          id: wo.id, 
          userName: wo.userName, 
          userEmail: wo.userEmail, 
          itemDescription: wo.itemDescription, 
          floor: wo.floor, 
          cibusCode: '', 
          timestamp: Date.now() 
        };
      });

      const newRun: FoodRun = {
        id: Math.random().toString(36).substr(2, 9), runnerName: user?.name || '', runnerEmail: user?.email || '',
        destination: inputs.dest, departureTime: Date.now() + inputs.time * 60000, minutesUntilDeparture: inputs.time,
        maxOrders: inputs.max, status: 'active', orders
      };

      setWaitingOrders((prev: any) => prev.filter((wo: any) => !ordersToPull.some(o => o.id === wo.id)));
      setRuns((prev: any) => [newRun, ...prev]);
      setModals({ ...modals, create: false });

      sendToGoogleChat(webhookUrl, {
        title: "New Food Run!",
        subtitle: `Destination: ${inputs.dest}`,
        details: `Departing in <b>${inputs.time} mins</b>. Lead by ${user?.name}. ${orders.length > 0 ? `Auto-pulled ${orders.length} orders from waitlist.` : ''}`,
        buttonText: "Open App to Join",
        buttonUrl: window.location.href,
        prefix: messagePrefix
      });
    },
    depart: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, status: 'departed' } : r));
      sendToGoogleChat(webhookUrl, {
        title: "Runner is Leaving!",
        subtitle: `En route to ${run.destination}`,
        details: "The runner has departed. Last chance for orders is over.",
        prefix: messagePrefix
      });
      run.orders.forEach(order => triggerPrivateAlert(order.userEmail, 'departed', `Runner leaving for ${run.destination}! Pay now.`));
    },
    arrive: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      sendToGoogleChat(webhookUrl, {
        title: "Food has Arrived!",
        subtitle: `From ${run.destination}`,
        details: `Pickup point: <b>${inputs.loc}</b>.`,
        prefix: messagePrefix
      });
      run.orders.forEach(order => triggerPrivateAlert(order.userEmail, 'arrived', `Your food is waiting at ${inputs.loc}!`));
      setHistory((prev: any) => [{ ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() }, ...prev]);
      setRuns(runs.filter((r: any) => r.id !== runId));
      setModals({ ...modals, arrive: null });
    },
    join: (runId: string) => {
      const order: Order = { 
        id: Math.random().toString(36).substr(2, 9), 
        userName: user?.name || '', 
        userEmail: user?.email || '', 
        itemDescription: inputs.item, 
        floor: inputs.floor, 
        cibusCode: '', 
        timestamp: Date.now() 
      };
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: [...r.orders, order] } : r));
      setModals({ ...modals, join: null });
    },
    waitlist: (e: React.FormEvent) => {
      e.preventDefault();
      const wo: WaitingOrder = {
        id: Math.random().toString(36).substr(2, 9),
        userName: user?.name || '',
        userEmail: user?.email || '',
        destination: inputs.dest,
        itemDescription: inputs.item,
        floor: inputs.floor,
        timestamp: Date.now()
      };
      setWaitingOrders((prev: any) => [...prev, wo]);
      setModals({ ...modals, waitlist: false });
    },
    exportConfig: () => {
      const config = { webhookUrl, messagePrefix, defaultWait, defaultMax };
      navigator.clipboard.writeText(JSON.stringify(config)).then(() => alert("Config copied!"));
    },
    testWebhook: async () => {
      setTestLoading(true);
      const success = await sendToGoogleChat(webhookUrl, {
        title: "Connection Check",
        subtitle: "Webhook Verified",
        details: "If you see this, your Google Chat integration is active.",
        prefix: messagePrefix
      });
      setTestLoading(false);
      alert(success ? "Success!" : "Failed.");
    }
  };

  const isAdmin = user?.isAdmin || isSimulatorAdmin;

  return (
    <div className="h-full flex flex-col bg-slate-50 relative">
      <datalist id="destinations">
        {destinationSuggestions.map(d => <option key={d} value={d} />)}
      </datalist>

      {activeToast && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-[200] animate-in slide-in-from-top-10">
          <div className="bg-slate-900 text-white px-6 py-4 rounded-3xl shadow-2xl flex items-center gap-4 border border-indigo-500/50 min-w-[300px]">
             <div className="w-10 h-10 rounded-2xl bg-indigo-600 flex items-center justify-center text-lg"><i className="fas fa-bell"></i></div>
             <div>
                <p className="text-[10px] font-black uppercase text-indigo-400 tracking-widest">Personal Alert</p>
                <p className="text-[13px] font-bold pr-4">{activeToast.message}</p>
             </div>
             <button onClick={() => setActiveToast(null)} className="ml-auto text-white/30 hover:text-white"><i className="fas fa-times"></i></button>
          </div>
        </div>
      )}

      <header className={`px-6 py-4 flex justify-between items-center border-b ${isAdmin ? 'bg-amber-50 border-amber-100' : 'bg-white border-slate-100'}`}>
        <div className="flex items-center gap-3">
           <div className={`w-9 h-9 rounded-xl flex items-center justify-center text-white text-lg shadow-lg ${isAdmin ? 'bg-amber-500' : 'bg-indigo-600'}`}><i className={`fas ${isAdmin ? 'fa-user-shield' : 'fa-bicycle'}`}></i></div>
           <div>
             <span className="font-black text-sm text-slate-800 tracking-tight">LUNCHRUN</span>
             <span className="text-[8px] font-black text-slate-400 uppercase block">{user?.email}</span>
           </div>
        </div>
        <img src={`https://ui-avatars.com/api/?name=${user?.name}&background=${isAdmin ? 'f59e0b' : '6366f1'}&color=fff`} className="w-9 h-9 rounded-2xl border-2 border-white shadow-sm" alt="u" />
      </header>

      <main className="flex-1 overflow-y-auto p-4 space-y-4">
        {isAdmin && (
          <div className="bg-slate-900 rounded-[2.5rem] p-6 text-white shadow-2xl border-4 border-amber-500/20 relative overflow-hidden">
             <div className="flex justify-between items-center mb-6">
                <div>
                   <h3 className="text-amber-400 text-[10px] font-black uppercase tracking-[0.2em]">Channel Configuration</h3>
                   <p className="text-white/40 text-[9px]">Shared webhook settings.</p>
                </div>
                <div className="flex gap-2">
                   <button onClick={() => actions.exportConfig()} className="bg-white/10 p-2 rounded-xl text-[10px]"><i className="fas fa-share-nodes"></i></button>
                </div>
             </div>
             <div className="space-y-4">
                <div>
                   <label className="text-[9px] font-black uppercase text-white/40 block mb-2 pl-1">Space Webhook</label>
                   <div className="flex gap-2">
                      <input className="flex-1 p-3 bg-white/5 border border-white/10 rounded-2xl font-bold text-xs outline-none focus:ring-2 focus:ring-amber-500" value={webhookUrl} onChange={e => setWebhookUrl(e.target.value)} placeholder="https://chat.googleapis.com/..." />
                      <Button onClick={() => actions.testWebhook()} isLoading={testLoading} className="h-10 px-6 bg-amber-500 text-slate-900 text-[10px] font-black uppercase">Test</Button>
                   </div>
                </div>
             </div>
          </div>
        )}

        <div className="flex justify-between items-center bg-white p-3 rounded-2xl border border-slate-100 shadow-sm">
           <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-2">Active Missions</span>
           <div className="flex gap-2">
              <Button onClick={() => setModals({...modals, waitlist: true})} variant="ghost" className="h-9 px-4 text-[10px] font-black uppercase rounded-xl border border-slate-100">Waitlist</Button>
              <Button onClick={() => setModals({...modals, create: true})} className="h-9 px-4 text-[10px] font-black uppercase rounded-xl bg-indigo-600 shadow-lg">Start Run</Button>
           </div>
        </div>

        <div className="space-y-4 pb-20">
           {runs.length === 0 && (
             <div className="py-20 text-center opacity-20">
                <div className="w-20 h-20 bg-slate-200 rounded-full mx-auto flex items-center justify-center mb-4"><i className="fas fa-shopping-basket text-2xl text-slate-400"></i></div>
                <p className="text-[10px] font-black uppercase tracking-widest">No active runs in your sector</p>
             </div>
           )}

           {runs.map((run: FoodRun) => {
             const isRunner = user?.email === run.runnerEmail;
             const myOrder = run.orders.find(o => o.userEmail === user?.email);
             return (
               <div key={run.id} className={`bg-white rounded-[2.5rem] p-6 shadow-xl border-2 transition-all ${run.status === 'departed' ? 'border-indigo-500 shadow-indigo-100' : 'border-white'}`}>
                  <div className="flex justify-between items-start mb-6">
                     <div className="flex gap-4">
                        <div className="w-14 h-14 rounded-2xl bg-slate-50 flex items-center justify-center text-2xl text-slate-400 shadow-inner">
                           <i className={`fas ${run.status === 'departed' ? 'fa-bolt text-indigo-500' : 'fa-hamburger'}`}></i>
                        </div>
                        <div>
                           <h4 className="text-xl font-black text-slate-800 tracking-tight">{run.destination}</h4>
                           <div className="flex items-center gap-2 mt-1">
                              <span className="text-[10px] font-black bg-slate-100 text-slate-500 px-2 py-0.5 rounded-full">{run.status.toUpperCase()}</span>
                              <span className="text-[10px] font-black text-slate-400 uppercase">{run.runnerName} • {run.minutesUntilDeparture}m wait</span>
                           </div>
                        </div>
                     </div>
                  </div>

                  {run.orders.length > 0 && (
                     <div className="space-y-2 mb-6">
                        {run.orders.map(o => (
                           <div key={o.id} className={`flex justify-between items-center p-3 rounded-2xl text-xs border ${o.userEmail === user?.email ? 'bg-indigo-50 border-indigo-200' : 'bg-slate-50/50 border-slate-100'}`}>
                              <div className="flex items-center gap-3">
                                 <span className="font-bold text-slate-700">{o.userName}</span>
                                 <span className="text-slate-400 truncate max-w-[150px]">"{o.itemDescription}"</span>
                              </div>
                              {o.userEmail === user?.email && run.status === 'departed' && !o.cibusCode && (
                                 <button onClick={() => setModals({...modals, cibus: {runId: run.id, orderId: o.id}})} className="bg-indigo-600 text-white px-3 py-1 rounded-lg text-[10px] font-black uppercase animate-pulse">Pay</button>
                              )}
                              {o.cibusCode && <span className="text-[10px] font-black text-emerald-600 uppercase"><i className="fas fa-check-circle"></i> Paid</span>}
                           </div>
                        ))}
                     </div>
                  )}

                  <div className="flex gap-3">
                     {isRunner ? (
                        run.status === 'active' ? (
                           <Button onClick={() => actions.depart(run.id)} className="flex-1 h-14 bg-indigo-600 text-[11px] font-black uppercase rounded-2xl shadow-lg shadow-indigo-100">Broadcast Departure</Button>
                        ) : (
                           <Button onClick={() => setModals({...modals, arrive: run.id})} className="flex-1 h-14 bg-emerald-600 text-[11px] font-black uppercase rounded-2xl shadow-lg shadow-emerald-100">Signal Arrival</Button>
                        )
                     ) : !myOrder && run.status === 'active' && run.orders.length < run.maxOrders && (
                        <Button onClick={() => setModals({...modals, join: run.id})} className="flex-1 h-14 bg-slate-800 text-[11px] font-black uppercase rounded-2xl">Join Manifest</Button>
                     )}
                     {myOrder && <div className="flex-1 text-center py-4 text-[10px] font-black uppercase text-indigo-400 tracking-widest"><i className="fas fa-check mr-2"></i> You are in this run</div>}
                  </div>
               </div>
             );
           })}
        </div>
      </main>

      {/* MODALS */}
      {modals.create && (
        <Overlay title="Mission Config" onClose={() => setModals({...modals, create: false})}>
           <form onSubmit={actions.createRun} className="space-y-4">
              <input required list="destinations" className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Destination Name" value={inputs.dest} onChange={e => setInputs({...inputs, dest: e.target.value})} />
              <div className="grid grid-cols-2 gap-4">
                 <input required type="number" className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Minutes" value={inputs.time} onChange={e => setInputs({...inputs, time: Number(e.target.value)})} />
                 <input required type="number" className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Capacity" value={inputs.max} onChange={e => setInputs({...inputs, max: Number(e.target.value)})} />
              </div>
              <Button type="submit" className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl">Establish Run</Button>
           </form>
        </Overlay>
      )}

      {modals.join && (
        <Overlay title="Join Manifest" onClose={() => setModals({...modals, join: null})}>
           <form onSubmit={(e) => { e.preventDefault(); actions.join(modals.join); }} className="space-y-4">
              <input required className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="What are you eating?" value={inputs.item} onChange={e => setInputs({...inputs, item: e.target.value})} />
              <input required className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Your Floor" value={inputs.floor} onChange={e => setInputs({...inputs, floor: e.target.value})} />
              <Button type="submit" className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl">Confirm Join</Button>
           </form>
        </Overlay>
      )}

      {modals.arrive && (
        <Overlay title="Drop-off Logic" onClose={() => setModals({...modals, arrive: null})}>
           <form onSubmit={(e) => { e.preventDefault(); actions.arrive(modals.arrive); }} className="space-y-4">
              <input required autoFocus className="w-full p-4 bg-slate-50 rounded-2xl font-bold text-center" placeholder="Where is the food?" value={inputs.loc} onChange={e => setInputs({...inputs, loc: e.target.value})} />
              <Button type="submit" className="w-full h-14 bg-emerald-600 font-black uppercase text-[11px] rounded-2xl">Blast Final Alert</Button>
           </form>
        </Overlay>
      )}

      {modals.waitlist && (
        <Overlay title="Global Waitlist" onClose={() => setModals({...modals, waitlist: false})}>
           <form onSubmit={actions.waitlist} className="space-y-3 mb-6">
              <input required list="destinations" className="w-full p-3 bg-slate-50 rounded-xl font-bold text-xs" placeholder="Place" value={inputs.dest} onChange={e => setInputs({...inputs, dest: e.target.value})} />
              <input required className="w-full p-3 bg-slate-50 rounded-xl font-bold text-xs" placeholder="What you want" value={inputs.item} onChange={e => setInputs({...inputs, item: e.target.value})} />
              <input required className="w-full p-3 bg-slate-50 rounded-xl font-bold text-xs" placeholder="Floor" value={inputs.floor} onChange={e => setInputs({...inputs, floor: e.target.value})} />
              <Button type="submit" className="w-full h-10 bg-slate-800 text-[10px] font-black uppercase rounded-xl">Add to Waitlist</Button>
           </form>
           <div className="space-y-2 max-h-[250px] overflow-y-auto pr-2 border-t pt-4">
              {waitingOrders.length === 0 ? (
                <div className="text-center py-4 opacity-40">
                  <p className="text-[10px] font-black uppercase tracking-widest">Waitlist is empty</p>
                </div>
              ) : (
                waitingOrders.map((wo: any) => (
                  <div key={wo.id} className="p-3 bg-slate-50 rounded-xl border border-slate-100 flex justify-between items-center">
                    <div>
                      <p className="font-bold text-slate-800 text-[10px]">{wo.userName} @ {wo.destination}</p>
                      <p className="text-[10px] text-slate-400 italic">"{wo.itemDescription}"</p>
                    </div>
                    <span className="text-[8px] font-black bg-white px-2 py-0.5 rounded-full border">FL {wo.floor}</span>
                  </div>
                ))
              )}
           </div>
        </Overlay>
      )}

      {modals.cibus && (
        <Overlay title="Payment Code" onClose={() => setModals({...modals, cibus: null})}>
           <div className="space-y-4">
              <input required className="w-full p-4 bg-slate-50 rounded-2xl font-black text-center text-xl tracking-widest border-2 border-indigo-100" placeholder="XXXXXX" value={inputs.cibus} onChange={e => setInputs({...inputs, cibus: e.target.value})} />
              <Button onClick={() => {
                  const { runId, orderId } = modals.cibus;
                  setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: r.orders.map((o: any) => o.id === orderId ? { ...o, cibusCode: inputs.cibus } : o) } : r));
                  setModals({...modals, cibus: null});
                  setInputs({...inputs, cibus: ''});
                }} className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl">Submit Payment</Button>
           </div>
        </Overlay>
      )}
    </div>
  );
};

const Overlay: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
  <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[300] flex items-center justify-center p-6">
    <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-[340px] shadow-2xl animate-in zoom-in-95 duration-300 relative">
      <div className="flex justify-between items-center mb-8">
         <h3 className="text-[11px] font-black uppercase tracking-[0.3em] text-indigo-600">{title}</h3>
         <button onClick={onClose} className="w-9 h-9 rounded-2xl bg-slate-50 text-slate-300 hover:text-slate-600 transition-colors flex items-center justify-center"><i className="fas fa-times"></i></button>
      </div>
      {children}
    </div>
  </div>
);

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { FoodRun, Order, AppEvent, WaitingOrder, UserNotification } from './types';
import { Button } from './components/Button';
import { sendToGoogleChat } from './services/googleChatService';

const ADMIN_EMAIL = 'admin@yourcompany.com'; 
const ALLOWED_DOMAIN = 'yourcompany.com';

/**
 * Normalizes business names for consistent matching.
 * Handles variations like "יום טוב", "יומטוב", "יום-טוב".
 */
const normalizeBusinessName = (name: string): string => {
  return name.trim().toLowerCase()
    .replace(/\s+/g, '')       // Remove spaces
    .replace(/[-_]/g, '')      // Remove dashes/underscores
    .replace(/^ה/g, '');       // Remove common prefix
};

const App: React.FC = () => {
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [notifications, setNotifications] = useState<UserNotification[]>([]);
  const [simulatorMode, setSimulatorMode] = useState(false);
  const [webhookUrl, setWebhookUrl] = useState<string>(localStorage.getItem('lunchrun_webhook') || '');
  const [messagePrefix, setMessagePrefix] = useState<string>(localStorage.getItem('lunchrun_prefix') || '[LunchRun]');
  const [defaultWait, setDefaultWait] = useState<number>(Number(localStorage.getItem('lunchrun_def_wait')) || 20);
  const [defaultMax, setDefaultMax] = useState<number>(Number(localStorage.getItem('lunchrun_def_max')) || 5);
  const [isSimulatorAdmin, setIsSimulatorAdmin] = useState(false);

  // Sync with LocalStorage
  useEffect(() => {
    const saved = {
      history: localStorage.getItem('lunchrun_history'),
      waitlist: localStorage.getItem('lunchrun_waitlist'),
      notifs: localStorage.getItem('lunchrun_notifications'),
      runs: localStorage.getItem('lunchrun_active_runs')
    };
    if (saved.history) setHistory(JSON.parse(saved.history));
    if (saved.waitlist) setWaitingOrders(JSON.parse(saved.waitlist));
    if (saved.notifs) setNotifications(JSON.parse(saved.notifs));
    if (saved.runs) setRuns(JSON.parse(saved.runs));
  }, []);

  useEffect(() => {
    localStorage.setItem('lunchrun_active_runs', JSON.stringify(runs));
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(waitingOrders));
    localStorage.setItem('lunchrun_notifications', JSON.stringify(notifications));
    localStorage.setItem('lunchrun_history', JSON.stringify(history));
    localStorage.setItem('lunchrun_webhook', webhookUrl);
    localStorage.setItem('lunchrun_prefix', messagePrefix);
    localStorage.setItem('lunchrun_def_wait', defaultWait.toString());
    localStorage.setItem('lunchrun_def_max', defaultMax.toString());
  }, [runs, waitingOrders, notifications, history, webhookUrl, messagePrefix, defaultWait, defaultMax]);

  const sharedActions = {
    runs, setRuns,
    history, setHistory,
    waitingOrders, setWaitingOrders,
    notifications, setNotifications,
    webhookUrl, setWebhookUrl,
    messagePrefix, setMessagePrefix,
    defaultWait, setDefaultWait,
    defaultMax, setDefaultMax,
    isSimulatorAdmin
  };

  return (
    <div className={`min-h-screen transition-all duration-500 ${simulatorMode ? 'p-2 bg-slate-200' : 'bg-slate-50'}`}>
      <div className="bg-slate-900 text-white/70 px-6 py-2 flex justify-between items-center text-[10px] font-black uppercase tracking-[0.2em] shadow-xl sticky top-0 z-[100] rounded-b-xl sm:mx-4">
        <div className="flex items-center gap-4">
          <div className={`w-2 h-2 rounded-full animate-pulse ${isSimulatorAdmin ? 'bg-amber-400' : 'bg-indigo-400'}`}></div>
          <span>{isSimulatorAdmin ? 'Admin Terminal' : 'LunchRun Network'}</span>
        </div>
        <div className="flex gap-4">
           {simulatorMode && (
             <button onClick={() => setIsSimulatorAdmin(!isSimulatorAdmin)} className={`px-4 py-1.5 rounded-full border transition-all text-[9px] ${isSimulatorAdmin ? 'bg-amber-500 border-amber-400 text-slate-900' : 'border-slate-700 hover:text-white'}`}>
               {isSimulatorAdmin ? 'ADMIN: ON' : 'ADMIN: OFF'}
             </button>
           )}
           <button onClick={() => setSimulatorMode(!simulatorMode)} className="px-4 py-1.5 rounded-full border border-slate-700 hover:text-white text-[9px] transition-all">
             {simulatorMode ? 'Exit Simulator' : 'Split-Screen QA'}
           </button>
        </div>
      </div>

      {simulatorMode ? (
        <div className="flex flex-col md:flex-row h-[calc(100vh-80px)] gap-4 mt-4 overflow-hidden">
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-indigo-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Persona: Runner</div>
             <AppInstance userOverride={{ name: 'Avi', email: `avi@${ALLOWED_DOMAIN}` }} {...sharedActions} />
          </div>
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-emerald-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Persona: Orderer</div>
             <AppInstance userOverride={{ name: 'Dana', email: `dana@${ALLOWED_DOMAIN}` }} {...sharedActions} />
          </div>
        </div>
      ) : (
        <div className="max-w-4xl mx-auto mt-6">
          <AppInstance {...sharedActions} />
        </div>
      )}
    </div>
  );
};

const AppInstance: React.FC<any> = ({ 
  userOverride, 
  runs, setRuns, 
  history, setHistory, 
  waitingOrders, setWaitingOrders, 
  notifications, setNotifications,
  webhookUrl, setWebhookUrl,
  messagePrefix, setMessagePrefix,
  defaultWait, setDefaultWait,
  defaultMax, setDefaultMax,
  isSimulatorAdmin
}) => {
  const [user, setUser] = useState<{ name: string; email: string; isAdmin?: boolean } | null>(userOverride || null);
  const [activeToast, setActiveToast] = useState<{message: string, type: string} | null>(null);
  const [testLoading, setTestLoading] = useState(false);
  const lastNotifId = useRef<string | null>(null);

  const [modals, setModals] = useState<{ [key: string]: boolean | any }>({
    create: false, waitlist: false, join: null, cibus: null, arrive: null
  });

  const [inputs, setInputs] = useState({ dest: '', time: defaultWait, max: defaultMax, item: '', floor: '', cibus: '', loc: '' });

  // Deep Link Handling: Check for ?action=pay or ?action=join
  useEffect(() => {
    if (!user) return;
    const params = new URLSearchParams(window.location.search);
    const action = params.get('action');
    const runId = params.get('runId');

    if (runId && action === 'pay') {
      const run = runs.find((r: FoodRun) => r.id === runId);
      if (run) {
        const myOrder = run.orders.find((o: Order) => o.userEmail === user.email);
        if (myOrder) {
          setModals(prev => ({ ...prev, cibus: { runId, orderId: myOrder.id } }));
        }
      }
    } else if (runId && action === 'join') {
      setModals(prev => ({ ...prev, join: runId }));
    }

    // Clean URL
    if (action) window.history.replaceState({}, document.title, window.location.pathname);
  }, [user, runs.length]);

  const destinationSuggestions = useMemo(() => {
    const all = [...history, ...runs, ...waitingOrders].map(item => item.destination);
    return Array.from(new Set(all)).sort();
  }, [history, runs, waitingOrders]);

  const triggerPrivateAlert = (targetEmail: string, type: UserNotification['type'], message: string) => {
    const newNotif: UserNotification = {
      id: Math.random().toString(36).substr(2, 9),
      targetEmail, type, message, runId: 'sys', timestamp: Date.now(), read: false
    };
    setNotifications((prev: any) => [newNotif, ...prev]);
  };

  const actions = {
    createRun: (e: React.FormEvent) => {
      e.preventDefault();
      const normDest = normalizeBusinessName(inputs.dest);
      const matches = waitingOrders.filter(wo => normalizeBusinessName(wo.destination) === normDest);
      const ordersToPull = matches.slice(0, inputs.max);

      const orders: Order[] = ordersToPull.map(wo => {
        triggerPrivateAlert(wo.userEmail, 'waitlist_promoted', `Runner picked up your ${wo.destination} request!`);
        return { id: wo.id, userName: wo.userName, userEmail: wo.userEmail, itemDescription: wo.itemDescription, floor: wo.floor, cibusCode: '', timestamp: Date.now() };
      });

      const newRun: FoodRun = {
        id: Math.random().toString(36).substr(2, 9), runnerName: user?.name || '', runnerEmail: user?.email || '',
        destination: inputs.dest, departureTime: Date.now() + inputs.time * 60000, minutesUntilDeparture: inputs.time,
        maxOrders: inputs.max, status: 'active', orders
      };

      setWaitingOrders((prev: any) => prev.filter((wo: any) => !ordersToPull.some(o => o.id === wo.id)));
      setRuns((prev: any) => [newRun, ...prev]);
      setModals({ ...modals, create: false });

      const baseUrl = window.location.href.split('?')[0];
      sendToGoogleChat(webhookUrl, {
        title: "New Run Established!",
        subtitle: inputs.dest,
        details: `Departing in <b>${inputs.time} mins</b>. Lead: ${user?.name}.`,
        buttonText: "Join the Run",
        buttonUrl: `${baseUrl}?action=join&runId=${newRun.id}`,
        prefix: messagePrefix
      });
    },
    depart: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, status: 'departed' } : r));

      const baseUrl = window.location.href.split('?')[0];
      sendToGoogleChat(webhookUrl, {
        title: "Runner En Route!",
        subtitle: run.destination,
        details: "Please provide your payment codes now to avoid delays.",
        buttonText: "Enter Cibus Code",
        buttonUrl: `${baseUrl}?action=pay&runId=${runId}`,
        prefix: messagePrefix
      });
      run.orders.forEach(order => triggerPrivateAlert(order.userEmail, 'departed', `Runner leaving! Enter your code for ${run.destination}.`));
    },
    arrive: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      sendToGoogleChat(webhookUrl, {
        title: "Mission Accomplished!",
        subtitle: `Food at: ${inputs.loc}`,
        details: `Delicious stuff from ${run.destination} is waiting for you.`,
        prefix: messagePrefix
      });
      run.orders.forEach(order => triggerPrivateAlert(order.userEmail, 'arrived', `Food is here! Location: ${inputs.loc}`));
      setHistory((prev: any) => [{ ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() }, ...prev]);
      setRuns(runs.filter((r: any) => r.id !== runId));
      setModals({ ...modals, arrive: null });
    },
    join: (runId: string) => {
      const order: Order = { id: Math.random().toString(36).substr(2, 9), userName: user?.name || '', userEmail: user?.email || '', itemDescription: inputs.item, floor: inputs.floor, cibusCode: '', timestamp: Date.now() };
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: [...r.orders, order] } : r));
      setModals({ ...modals, join: null });
    }
  };

  const isAdmin = user?.isAdmin || isSimulatorAdmin;

  if (!user) {
    return (
      <div className="h-full flex flex-col items-center justify-center p-8 bg-white">
        <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-3xl mb-6 animate-bounce shadow-xl"><i className="fas fa-bicycle"></i></div>
        <h1 className="text-2xl font-black text-slate-800 tracking-tighter">LunchRun Access</h1>
        <form onSubmit={(e) => { e.preventDefault(); setUser({ name: 'User', email: `user@${ALLOWED_DOMAIN}` }); }} className="mt-8 w-full max-w-xs space-y-3">
           <input required type="email" placeholder="Work Email" className="w-full p-4 bg-slate-50 border-0 rounded-2xl font-bold text-sm" />
           <Button type="submit" className="w-full h-14 bg-indigo-600 text-[11px] font-black uppercase rounded-2xl">Enter Fleet</Button>
           <button type="button" onClick={() => setUser({name: 'Admin', email: 'admin@system.local', isAdmin: true})} className="w-full py-2 text-[9px] font-black text-slate-400 uppercase tracking-widest">Admin Override</button>
        </form>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col bg-slate-50 relative overflow-hidden">
      <datalist id="dest-options">
        {destinationSuggestions.map(d => <option key={d} value={d} />)}
      </datalist>

      <header className={`px-6 py-4 flex justify-between items-center border-b transition-colors ${isAdmin ? 'bg-amber-50 border-amber-100' : 'bg-white border-slate-100'}`}>
        <div className="flex items-center gap-3">
           <div className={`w-9 h-9 rounded-xl flex items-center justify-center text-white text-lg shadow-lg ${isAdmin ? 'bg-amber-500' : 'bg-indigo-600'}`}><i className={`fas ${isAdmin ? 'fa-user-shield' : 'fa-hamburger'}`}></i></div>
           <div>
             <span className="font-black text-sm text-slate-800 tracking-tight">LUNCHRUN</span>
             <span className="text-[8px] font-black text-slate-400 uppercase block tracking-widest">{user.email}</span>
           </div>
        </div>
        <img src={`https://ui-avatars.com/api/?name=${user.name}&background=${isAdmin ? 'f59e0b' : '6366f1'}&color=fff`} className="w-9 h-9 rounded-2xl border-2 border-white shadow-sm" alt="u" />
      </header>

      <main className="flex-1 overflow-y-auto p-4 space-y-4">
        {isAdmin && (
          <div className="bg-slate-900 rounded-[2.5rem] p-6 text-white shadow-2xl border-4 border-amber-500/20">
             <div className="flex justify-between items-center mb-4">
                <h3 className="text-amber-400 text-[10px] font-black uppercase tracking-widest">Global Fleet Link</h3>
                <button onClick={() => { localStorage.clear(); window.location.reload(); }} className="text-[9px] font-black text-red-400 uppercase">Clear All</button>
             </div>
             <div className="space-y-4">
                <div className="flex gap-2">
                   <input className="flex-1 p-3 bg-white/5 border border-white/10 rounded-2xl font-bold text-xs outline-none" value={webhookUrl} onChange={e => setWebhookUrl(e.target.value)} placeholder="Google Chat Webhook URL" />
                   <Button onClick={async () => { setTestLoading(true); const ok = await sendToGoogleChat(webhookUrl, { title: "Test", subtitle: "Live", details: "Integration works!", prefix: messagePrefix }); setTestLoading(false); alert(ok ? "OK" : "Err"); }} isLoading={testLoading} className="h-10 px-4 bg-amber-500 text-slate-900 text-[10px] uppercase font-black">Test</Button>
                </div>
                <div className="p-3 bg-indigo-500/10 rounded-2xl border border-indigo-500/20">
                   <p className="text-[9px] font-black text-indigo-300 uppercase flex items-center gap-2"><i className="fas fa-link"></i> Deep Response Logic</p>
                   <p className="text-[10px] text-white/50 mt-1">Webhook notifications now include "Direct Action" buttons that trigger modals inside the app.</p>
                </div>
             </div>
          </div>
        )}

        <div className="flex justify-between items-center bg-white p-3 rounded-2xl border border-slate-100 shadow-sm">
           <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-2">Sector Manifest</span>
           <div className="flex gap-2">
              <Button onClick={() => setModals({...modals, waitlist: true})} variant="ghost" className="h-9 px-4 text-[10px] font-black uppercase rounded-xl border border-slate-100">Waitlist</Button>
              <Button onClick={() => setModals({...modals, create: true})} className="h-9 px-4 text-[10px] font-black uppercase rounded-xl bg-indigo-600 shadow-lg shadow-indigo-200">Start Run</Button>
           </div>
        </div>

        <div className="space-y-4 pb-20">
           {runs.length === 0 && (
             <div className="py-20 text-center opacity-10">
                <i className="fas fa-truck-loading text-4xl mb-4"></i>
                <p className="text-[10px] font-black uppercase tracking-[0.3em]">Quiet on the food front</p>
             </div>
           )}

           {runs.map((run: FoodRun) => {
             const isRunner = user.email === run.runnerEmail;
             const myOrder = run.orders.find(o => o.userEmail === user.email);
             return (
               <div key={run.id} className={`bg-white rounded-[2.5rem] p-6 shadow-xl border-2 transition-all ${run.status === 'departed' ? 'border-indigo-500 shadow-indigo-100' : 'border-white'}`}>
                  <div className="flex justify-between items-start mb-6">
                     <div className="flex gap-4">
                        <div className="w-14 h-14 rounded-2xl bg-slate-50 flex items-center justify-center text-2xl text-slate-300 shadow-inner">
                           <i className={`fas ${run.status === 'departed' ? 'fa-motorcycle text-indigo-500' : 'fa-pizza-slice'}`}></i>
                        </div>
                        <div>
                           <h4 className="text-xl font-black text-slate-800 tracking-tight">{run.destination}</h4>
                           <div className="flex items-center gap-2 mt-1">
                              <span className={`text-[9px] font-black px-2 py-0.5 rounded-full ${run.status === 'departed' ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-100 text-slate-400'}`}>{run.status.toUpperCase()}</span>
                              <span className="text-[10px] font-bold text-slate-400">{run.runnerName} • {run.minutesUntilDeparture}m left</span>
                           </div>
                        </div>
                     </div>
                  </div>

                  {run.orders.length > 0 && (
                     <div className="space-y-2 mb-6">
                        {run.orders.map(o => (
                           <div key={o.id} className={`flex justify-between items-center p-3 rounded-2xl text-xs border ${o.userEmail === user.email ? 'bg-indigo-50 border-indigo-200' : 'bg-slate-50 border-slate-100'}`}>
                              <div className="flex items-center gap-3">
                                 <span className="font-bold text-slate-700">{o.userName}</span>
                                 <span className="text-slate-400 italic">"{o.itemDescription}"</span>
                              </div>
                              {o.userEmail === user.email && run.status === 'departed' && !o.cibusCode && (
                                 <button onClick={() => setModals({...modals, cibus: {runId: run.id, orderId: o.id}})} className="bg-indigo-600 text-white px-3 py-1 rounded-lg text-[9px] font-black uppercase shadow-lg shadow-indigo-200">Send Code</button>
                              )}
                              {o.cibusCode && <span className="text-[9px] font-black text-emerald-600 uppercase"><i className="fas fa-check-circle"></i> Paid</span>}
                           </div>
                        ))}
                     </div>
                  )}

                  <div className="flex gap-3">
                     {isRunner ? (
                        run.status === 'active' ? (
                           <Button onClick={() => actions.depart(run.id)} className="flex-1 h-14 bg-indigo-600 text-[11px] font-black uppercase rounded-2xl shadow-xl shadow-indigo-100">Broadcast Departure</Button>
                        ) : (
                           <Button onClick={() => setModals({...modals, arrive: run.id})} className="flex-1 h-14 bg-emerald-600 text-[11px] font-black uppercase rounded-2xl shadow-xl shadow-emerald-100">Broadcast Arrival</Button>
                        )
                     ) : !myOrder && run.status === 'active' && run.orders.length < run.maxOrders && (
                        <Button onClick={() => setModals({...modals, join: run.id})} className="flex-1 h-14 bg-slate-800 text-[11px] font-black uppercase rounded-2xl">Join Run</Button>
                     )}
                     {myOrder && <div className="flex-1 text-center py-4 text-[10px] font-black uppercase text-indigo-400 tracking-widest"><i className="fas fa-check-circle mr-2"></i> In Manifest</div>}
                  </div>
               </div>
             );
           })}
        </div>
      </main>

      {/* OVERLAYS */}
      {modals.create && (
        <Overlay title="Mission Genesis" onClose={() => setModals({...modals, create: false})}>
           <form onSubmit={actions.createRun} className="space-y-4">
              <input required list="dest-options" className="w-full p-4 bg-slate-50 rounded-2xl font-bold border-2 border-transparent focus:border-indigo-500 outline-none" placeholder="Destination Name" value={inputs.dest} onChange={e => setInputs({...inputs, dest: e.target.value})} />
              <div className="grid grid-cols-2 gap-4">
                 <input required type="number" className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Wait (m)" value={inputs.time} onChange={e => setInputs({...inputs, time: Number(e.target.value)})} />
                 <input required type="number" className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Max Spots" value={inputs.max} onChange={e => setInputs({...inputs, max: Number(e.target.value)})} />
              </div>
              <Button type="submit" className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl">Establish Run</Button>
           </form>
        </Overlay>
      )}

      {modals.join && (
        <Overlay title="Manifest Addition" onClose={() => setModals({...modals, join: null})}>
           <form onSubmit={(e) => { e.preventDefault(); actions.join(modals.join); }} className="space-y-4">
              <input required className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="What are you craving?" value={inputs.item} onChange={e => setInputs({...inputs, item: e.target.value})} />
              <input required className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Office Floor" value={inputs.floor} onChange={e => setInputs({...inputs, floor: e.target.value})} />
              <Button type="submit" className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl">Confirm Join</Button>
           </form>
        </Overlay>
      )}

      {modals.arrive && (
        <Overlay title="Drop-off Signal" onClose={() => setModals({...modals, arrive: null})}>
           <form onSubmit={(e) => { e.preventDefault(); actions.arrive(modals.arrive); }} className="space-y-4">
              <input required autoFocus className="w-full p-4 bg-slate-50 rounded-2xl font-bold text-center text-lg" placeholder="Exact Location (e.g Kitchen 4)" value={inputs.loc} onChange={e => setInputs({...inputs, loc: e.target.value})} />
              <Button type="submit" className="w-full h-14 bg-emerald-600 font-black uppercase text-[11px] rounded-2xl">Send Final Alert</Button>
           </form>
        </Overlay>
      )}

      {modals.waitlist && (
        <Overlay title="Global Crave List" onClose={() => setModals({...modals, waitlist: false})}>
           <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2">
              {waitingOrders.length === 0 ? (
                <div className="text-center py-10 opacity-30 text-[10px] font-black uppercase">Waitlist Empty</div>
              ) : (
                waitingOrders.map((wo: any) => (
                  <div key={wo.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex justify-between items-center">
                    <div>
                      <p className="font-black text-slate-800 text-xs">{wo.destination}</p>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">{wo.userName} • {wo.itemDescription}</p>
                    </div>
                    <span className="text-[9px] font-black bg-white px-2 py-0.5 rounded-full border shadow-sm">FL {wo.floor}</span>
                  </div>
                ))
              )}
           </div>
        </Overlay>
      )}

      {modals.cibus && (
        <Overlay title="Payment Transmission" onClose={() => setModals({...modals, cibus: null})}>
           <div className="space-y-4">
              <input required autoFocus className="w-full p-6 bg-slate-50 rounded-[2rem] font-black text-center text-3xl tracking-[0.2em] border-4 border-indigo-100 outline-none" placeholder="000000" maxLength={6} value={inputs.cibus} onChange={e => setInputs({...inputs, cibus: e.target.value})} />
              <Button onClick={() => {
                  const { runId, orderId } = modals.cibus;
                  setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: r.orders.map((o: any) => o.id === orderId ? { ...o, cibusCode: inputs.cibus } : o) } : r));
                  setModals({...modals, cibus: null});
                  setInputs({...inputs, cibus: ''});
                }} className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl">Submit to Runner</Button>
           </div>
        </Overlay>
      )}
    </div>
  );
};

const Overlay: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
  <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[300] flex items-center justify-center p-6">
    <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-[340px] shadow-2xl animate-in zoom-in-95 duration-300 relative border border-slate-100">
      <div className="flex justify-between items-center mb-8">
         <h3 className="text-[11px] font-black uppercase tracking-[0.3em] text-indigo-600">{title}</h3>
         <button onClick={onClose} className="w-9 h-9 rounded-2xl bg-slate-50 text-slate-300 hover:text-slate-600 transition-colors flex items-center justify-center"><i className="fas fa-times"></i></button>
      </div>
      {children}
    </div>
  </div>
);

