export interface GoogleChatCardParams {
  title: string;
  subtitle: string;
  details: string;
  buttons?: { text: string; url: string }[];
  prefix?: string;
}

/**
 * Sends a notification to Google Chat.
 * Uses both 'text' (for notifications/mobile) and 'cardsV2' (for rich UI with buttons).
 */
export const sendToGoogleChat = async (webhookUrl: string, params: GoogleChatCardParams) => {
  if (!webhookUrl || !webhookUrl.startsWith('http')) return false;

  const summary = `${params.prefix || '[LunchRun]'} ${params.title}: ${params.subtitle}\n${params.details}`;

  // Construct a robust payload
  const payload: any = {
    text: summary, // Fallback text so it's never empty
    cardsV2: [
      {
        cardId: "lunchrun_" + Date.now(),
        card: {
          header: {
            title: params.prefix || "LunchRun",
            subtitle: params.title,
            imageUrl: "https://fonts.gstatic.com/s/i/short-term/release/googlesymbols/directions_run/default/48px.svg",
          },
          sections: [
            {
              widgets: [
                {
                  decoratedText: {
                    topLabel: params.subtitle,
                    text: params.details,
                    wrapText: true
                  }
                }
              ]
            }
          ]
        }
      }
    ]
  };

  // Add buttons if provided
  if (params.buttons && params.buttons.length > 0) {
    payload.cardsV2[0].card.sections[0].widgets.push({
      buttonList: {
        buttons: params.buttons.map(btn => ({
          text: btn.text,
          onClick: {
            openLink: { url: btn.url }
          }
        }))
      }
    });

    // Add URLs to text fallback as well for compatibility
    payload.text += "\n\n" + params.buttons.map(b => `${b.text}: ${b.url}`).join("\n");
  }

  try {
    const response = await fetch(webhookUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json; charset=UTF-8' },
      body: JSON.stringify(payload),
    });
    return response.ok;
  } catch (error) {
    console.error("Google Chat Webhook Error:", error);
    return false;
  }
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { FoodRun, Order, WaitingOrder, UserNotification } from './types';
import { Button } from './components/Button';
import { sendToGoogleChat } from './services/googleChatService';

const ALLOWED_DOMAIN = 'yourcompany.com';

const normalizeBusinessName = (name: string): string => {
  return name.trim().toLowerCase()
    .replace(/\s+/g, '')
    .replace(/[-_]/g, '')
    .replace(/^ה/g, '');
};

const App: React.FC = () => {
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [notifications, setNotifications] = useState<UserNotification[]>([]);
  const [simulatorMode, setSimulatorMode] = useState(false);
  const [webhookUrl, setWebhookUrl] = useState<string>(localStorage.getItem('lunchrun_webhook') || '');
  const [messagePrefix, setMessagePrefix] = useState<string>(localStorage.getItem('lunchrun_prefix') || '[LunchRun]');
  const [defaultWait, setDefaultWait] = useState<number>(Number(localStorage.getItem('lunchrun_def_wait')) || 20);
  const [defaultMax, setDefaultMax] = useState<number>(Number(localStorage.getItem('lunchrun_def_max')) || 5);
  const [isSimulatorAdmin, setIsSimulatorAdmin] = useState(false);

  useEffect(() => {
    const saved = {
      history: localStorage.getItem('lunchrun_history'),
      waitlist: localStorage.getItem('lunchrun_waitlist'),
      notifs: localStorage.getItem('lunchrun_notifications'),
      runs: localStorage.getItem('lunchrun_active_runs')
    };
    if (saved.history) setHistory(JSON.parse(saved.history));
    if (saved.waitlist) setWaitingOrders(JSON.parse(saved.waitlist));
    if (saved.notifs) setNotifications(JSON.parse(saved.notifs));
    if (saved.runs) setRuns(JSON.parse(saved.runs));
  }, []);

  useEffect(() => {
    localStorage.setItem('lunchrun_active_runs', JSON.stringify(runs));
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(waitingOrders));
    localStorage.setItem('lunchrun_notifications', JSON.stringify(notifications));
    localStorage.setItem('lunchrun_history', JSON.stringify(history));
    localStorage.setItem('lunchrun_webhook', webhookUrl);
    localStorage.setItem('lunchrun_prefix', messagePrefix);
    localStorage.setItem('lunchrun_def_wait', defaultWait.toString());
    localStorage.setItem('lunchrun_def_max', defaultMax.toString());
  }, [runs, waitingOrders, notifications, history, webhookUrl, messagePrefix, defaultWait, defaultMax]);

  const sharedActions = {
    runs, setRuns,
    history, setHistory,
    waitingOrders, setWaitingOrders,
    notifications, setNotifications,
    webhookUrl, setWebhookUrl,
    messagePrefix, setMessagePrefix,
    defaultWait, setDefaultWait,
    defaultMax, setDefaultMax,
    isSimulatorAdmin
  };

  return (
    <div className={`min-h-screen transition-all duration-500 ${simulatorMode ? 'p-2 bg-slate-200' : 'bg-slate-50'}`}>
      <div className="bg-slate-900 text-white/70 px-6 py-2 flex justify-between items-center text-[10px] font-black uppercase tracking-[0.2em] shadow-xl sticky top-0 z-[100] rounded-b-xl sm:mx-4">
        <div className="flex items-center gap-4">
          <div className={`w-2 h-2 rounded-full animate-pulse ${isSimulatorAdmin ? 'bg-amber-400' : 'bg-indigo-400'}`}></div>
          <span>LunchRun Network</span>
        </div>
        <div className="flex gap-4">
           {simulatorMode && (
             <button onClick={() => setIsSimulatorAdmin(!isSimulatorAdmin)} className={`px-4 py-1.5 rounded-full border transition-all text-[9px] ${isSimulatorAdmin ? 'bg-amber-500 border-amber-400 text-slate-900' : 'border-slate-700 hover:text-white'}`}>
               {isSimulatorAdmin ? 'ADMIN: ON' : 'ADMIN: OFF'}
             </button>
           )}
           <button onClick={() => setSimulatorMode(!simulatorMode)} className="px-4 py-1.5 rounded-full border border-slate-700 hover:text-white text-[9px] transition-all">
             {simulatorMode ? 'Exit Simulator' : 'Test Environment'}
           </button>
        </div>
      </div>

      {simulatorMode ? (
        <div className="flex flex-col md:flex-row h-[calc(100vh-80px)] gap-4 mt-4 overflow-hidden">
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-indigo-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Persona: Runner</div>
             <AppInstance userOverride={{ name: 'Avi', email: `avi@${ALLOWED_DOMAIN}` }} {...sharedActions} />
          </div>
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-emerald-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Persona: Orderer</div>
             <AppInstance userOverride={{ name: 'Dana', email: `dana@${ALLOWED_DOMAIN}` }} {...sharedActions} />
          </div>
        </div>
      ) : (
        <div className="max-w-4xl mx-auto mt-6 px-4">
          <AppInstance {...sharedActions} />
        </div>
      )}
    </div>
  );
};

const AppInstance: React.FC<any> = ({ 
  userOverride, 
  runs, setRuns, 
  history, setHistory, 
  waitingOrders, setWaitingOrders, 
  notifications, setNotifications,
  webhookUrl, setWebhookUrl,
  messagePrefix, setMessagePrefix,
  defaultWait, setDefaultWait,
  defaultMax, setDefaultMax,
  isSimulatorAdmin
}) => {
  const [user, setUser] = useState<{ name: string; email: string; isAdmin?: boolean } | null>(userOverride || null);
  const [testLoading, setTestLoading] = useState(false);

  const [modals, setModals] = useState<{ [key: string]: boolean | any }>({
    create: false, waitlist: false, join: null, cibus: null, arrive: null
  });

  const [inputs, setInputs] = useState({ dest: '', time: defaultWait, max: defaultMax, item: '', floor: '', cibus: '', loc: '' });

  useEffect(() => {
    if (!user) return;
    const params = new URLSearchParams(window.location.search);
    const action = params.get('action');
    const runId = params.get('runId');

    if (runId && action === 'pay') {
      const run = runs.find((r: FoodRun) => r.id === runId);
      if (run) {
        const myOrder = run.orders.find((o: Order) => o.userEmail === user.email);
        if (myOrder) setModals(prev => ({ ...prev, cibus: { runId, orderId: myOrder.id } }));
      }
    } else if (runId && action === 'join') {
      setModals(prev => ({ ...prev, join: runId }));
    }
    if (action) window.history.replaceState({}, document.title, window.location.pathname);
  }, [user, runs.length]);

  const destinationSuggestions = useMemo(() => {
    const all = [...history, ...runs, ...waitingOrders].map(item => item.destination);
    return Array.from(new Set(all)).sort();
  }, [history, runs, waitingOrders]);

  const actions = {
    createRun: (e: React.FormEvent) => {
      e.preventDefault();
      const normDest = normalizeBusinessName(inputs.dest);
      const matches = waitingOrders.filter(wo => normalizeBusinessName(wo.destination) === normDest);
      const ordersToPull = matches.slice(0, inputs.max);

      const orders: Order[] = ordersToPull.map(wo => ({ id: wo.id, userName: wo.userName, userEmail: wo.userEmail, itemDescription: wo.itemDescription, floor: wo.floor, cibusCode: '', timestamp: Date.now() }));

      const newRun: FoodRun = {
        id: Math.random().toString(36).substr(2, 9), runnerName: user?.name || '', runnerEmail: user?.email || '',
        destination: inputs.dest, departureTime: Date.now() + inputs.time * 60000, minutesUntilDeparture: inputs.time,
        maxOrders: inputs.max, status: 'active', orders
      };

      setWaitingOrders((prev: any) => prev.filter((wo: any) => !ordersToPull.some(o => o.id === wo.id)));
      setRuns((prev: any) => [newRun, ...prev]);
      setModals({ ...modals, create: false });

      const baseUrl = window.location.href.split('?')[0];
      sendToGoogleChat(webhookUrl, {
        title: "New Run Established!",
        subtitle: inputs.dest,
        details: `Departing in ${inputs.time} mins. Started by ${user?.name}.`,
        buttons: [
          { text: "Join Run", url: `${baseUrl}?action=join&runId=${newRun.id}` },
          { text: "DM Runner", url: `https://mail.google.com/chat/u/0/#chat/dm/${user?.email}` }
        ],
        prefix: messagePrefix
      });
    },
    depart: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, status: 'departed' } : r));

      const baseUrl = window.location.href.split('?')[0];
      sendToGoogleChat(webhookUrl, {
        title: "Runner is En Route!",
        subtitle: run.destination,
        details: "The runner is leaving. Please provide your Cibus code now.",
        buttons: [
          { text: "Enter Code", url: `${baseUrl}?action=pay&runId=${runId}` },
          { text: "Send Code via DM", url: `https://mail.google.com/chat/u/0/#chat/dm/${run.runnerEmail}` }
        ],
        prefix: messagePrefix
      });
    },
    arrive: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      sendToGoogleChat(webhookUrl, {
        title: "Food is Here!",
        subtitle: `Pickup: ${inputs.loc}`,
        details: `Delicious stuff from ${run.destination} is ready for you.`,
        prefix: messagePrefix
      });
      setHistory((prev: any) => [{ ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() }, ...prev]);
      setRuns(runs.filter((r: any) => r.id !== runId));
      setModals({ ...modals, arrive: null });
    },
    join: (runId: string) => {
      const order: Order = { id: Math.random().toString(36).substr(2, 9), userName: user?.name || '', userEmail: user?.email || '', itemDescription: inputs.item, floor: inputs.floor, cibusCode: '', timestamp: Date.now() };
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: [...r.orders, order] } : r));
      setModals({ ...modals, join: null });
    }
  };

  const isAdmin = user?.isAdmin || isSimulatorAdmin;

  if (!user) {
    return (
      <div className="h-full flex flex-col items-center justify-center p-8 bg-white">
        <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-3xl mb-6 shadow-xl"><i className="fas fa-motorcycle"></i></div>
        <h1 className="text-2xl font-black text-slate-800 tracking-tighter">LunchRun Access</h1>
        <form onSubmit={(e) => { e.preventDefault(); setUser({ name: 'User', email: `user@${ALLOWED_DOMAIN}` }); }} className="mt-8 w-full max-w-xs space-y-3">
           <input required type="email" placeholder="Corporate Email" className="w-full p-4 bg-slate-50 border-0 rounded-2xl font-bold" />
           <Button type="submit" className="w-full h-14 bg-indigo-600 font-black uppercase rounded-2xl">Sign In</Button>
           <button type="button" onClick={() => setUser({name: 'Admin', email: 'admin@system.local', isAdmin: true})} className="w-full py-2 text-[9px] font-black text-slate-400 uppercase tracking-widest">Admin Override</button>
        </form>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col bg-slate-50 relative">
      <datalist id="dest-options">
        {destinationSuggestions.map(d => <option key={d} value={d} />)}
      </datalist>

      <header className={`px-6 py-4 flex justify-between items-center border-b ${isAdmin ? 'bg-amber-50 border-amber-100' : 'bg-white border-slate-100'}`}>
        <div className="flex items-center gap-3">
           <div className={`w-9 h-9 rounded-xl flex items-center justify-center text-white text-lg shadow-lg ${isAdmin ? 'bg-amber-500' : 'bg-indigo-600'}`}><i className={`fas ${isAdmin ? 'fa-user-shield' : 'fa-hamburger'}`}></i></div>
           <div>
             <span className="font-black text-sm text-slate-800 tracking-tight">LUNCHRUN</span>
             <span className="text-[8px] font-black text-slate-400 uppercase block tracking-widest">{user.email}</span>
           </div>
        </div>
        <img src={`https://ui-avatars.com/api/?name=${user.name}&background=${isAdmin ? 'f59e0b' : '6366f1'}&color=fff`} className="w-9 h-9 rounded-2xl border-2 border-white shadow-sm" alt="u" />
      </header>

      <main className="flex-1 overflow-y-auto p-4 space-y-4 pb-24">
        {isAdmin && (
          <div className="bg-slate-900 rounded-[2rem] p-6 text-white shadow-2xl border-4 border-amber-500/20">
             <h3 className="text-amber-400 text-[10px] font-black uppercase tracking-widest mb-4">Webhook Terminal</h3>
             <div className="flex gap-2">
                <input className="flex-1 p-3 bg-white/5 border border-white/10 rounded-2xl font-bold text-xs outline-none" value={webhookUrl} onChange={e => setWebhookUrl(e.target.value)} placeholder="Webhook URL" />
                <Button onClick={async () => { setTestLoading(true); const ok = await sendToGoogleChat(webhookUrl, { title: "Test", subtitle: "Live", details: "Integration works!", prefix: messagePrefix }); setTestLoading(false); alert(ok ? "Sent" : "Error"); }} isLoading={testLoading} className="h-10 px-4 bg-amber-500 text-slate-900 text-[10px] uppercase font-black">Test</Button>
             </div>
          </div>
        )}

        <div className="flex justify-between items-center bg-white p-3 rounded-2xl border border-slate-100 shadow-sm">
           <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-2">Active Fleet</span>
           <div className="flex gap-2">
              <Button onClick={() => setModals({...modals, waitlist: true})} variant="ghost" className="h-9 px-4 text-[10px] font-black uppercase rounded-xl border border-slate-100">Waitlist</Button>
              <Button onClick={() => setModals({...modals, create: true})} className="h-9 px-4 text-[10px] font-black uppercase rounded-xl bg-indigo-600 shadow-lg">Start Run</Button>
           </div>
        </div>

        <div className="space-y-4">
           {runs.map((run: FoodRun) => {
             const isRunner = user.email === run.runnerEmail;
             const myOrder = run.orders.find(o => o.userEmail === user.email);
             return (
               <div key={run.id} className={`bg-white rounded-[2rem] p-6 shadow-xl border-2 transition-all ${run.status === 'departed' ? 'border-indigo-500 shadow-indigo-50' : 'border-white'}`}>
                  <div className="flex justify-between items-start mb-6">
                     <div className="flex gap-4">
                        <div className="w-14 h-14 rounded-2xl bg-slate-50 flex items-center justify-center text-2xl text-slate-300">
                           <i className={`fas ${run.status === 'departed' ? 'fa-motorcycle text-indigo-500' : 'fa-pizza-slice'}`}></i>
                        </div>
                        <div>
                           <h4 className="text-xl font-black text-slate-800 tracking-tight">{run.destination}</h4>
                           <div className="flex items-center gap-2 mt-1">
                              <span className={`text-[9px] font-black px-2 py-0.5 rounded-full ${run.status === 'departed' ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-100 text-slate-400'}`}>{run.status.toUpperCase()}</span>
                              <span className="text-[10px] font-bold text-slate-400">Led by {run.runnerName}</span>
                           </div>
                        </div>
                     </div>
                  </div>

                  {run.orders.length > 0 && (
                     <div className="space-y-2 mb-6">
                        {run.orders.map(o => (
                           <div key={o.id} className={`flex justify-between items-center p-3 rounded-2xl text-xs border ${o.userEmail === user.email ? 'bg-indigo-50 border-indigo-200' : 'bg-slate-50 border-slate-100'}`}>
                              <span className="font-bold text-slate-700">{o.userName}: <span className="font-normal text-slate-500 italic">"{o.itemDescription}"</span></span>
                              {o.userEmail === user.email && run.status === 'departed' && !o.cibusCode && (
                                 <button onClick={() => setModals({...modals, cibus: {runId: run.id, orderId: o.id}})} className="bg-indigo-600 text-white px-3 py-1 rounded-lg text-[9px] font-black uppercase">Send Code</button>
                              )}
                              {o.cibusCode && <span className="text-[9px] font-black text-emerald-600"><i className="fas fa-check-circle"></i> {o.cibusCode}</span>}
                           </div>
                        ))}
                     </div>
                  )}

                  <div className="flex gap-3">
                     {isRunner ? (
                        run.status === 'active' ? (
                           <Button onClick={() => actions.depart(run.id)} className="flex-1 h-12 bg-indigo-600 text-[10px] font-black uppercase rounded-xl">Signal Departure</Button>
                        ) : (
                           <Button onClick={() => setModals({...modals, arrive: run.id})} className="flex-1 h-12 bg-emerald-600 text-[10px] font-black uppercase rounded-xl">Signal Arrival</Button>
                        )
                     ) : !myOrder && run.status === 'active' && (
                        <Button onClick={() => setModals({...modals, join: run.id})} className="flex-1 h-12 bg-slate-800 text-[10px] font-black uppercase rounded-xl">Join Manifest</Button>
                     )}
                     {myOrder && <div className="flex-1 text-center py-4 text-[10px] font-black uppercase text-indigo-400 tracking-widest"><i className="fas fa-check-circle mr-2"></i> Manifested</div>}
                  </div>
               </div>
             );
           })}
        </div>
      </main>

      {/* OVERLAYS */}
      {modals.create && (
        <Overlay title="Establish Run" onClose={() => setModals({...modals, create: false})}>
           <form onSubmit={actions.createRun} className="space-y-4">
              <input required list="dest-options" className="w-full p-4 bg-slate-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-indigo-500" placeholder="Place" value={inputs.dest} onChange={e => setInputs({...inputs, dest: e.target.value})} />
              <div className="grid grid-cols-2 gap-4">
                 <input required type="number" className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Wait (m)" value={inputs.time} onChange={e => setInputs({...inputs, time: Number(e.target.value)})} />
                 <input required type="number" className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Max" value={inputs.max} onChange={e => setInputs({...inputs, max: Number(e.target.value)})} />
              </div>
              <Button type="submit" className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl">Start Session</Button>
           </form>
        </Overlay>
      )}

      {modals.join && (
        <Overlay title="Order Manifest" onClose={() => setModals({...modals, join: null})}>
           <form onSubmit={(e) => { e.preventDefault(); actions.join(modals.join); }} className="space-y-4">
              <input required className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="What food?" value={inputs.item} onChange={e => setInputs({...inputs, item: e.target.value})} />
              <input required className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Floor" value={inputs.floor} onChange={e => setInputs({...inputs, floor: e.target.value})} />
              <Button type="submit" className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl">Confirm Join</Button>
           </form>
        </Overlay>
      )}

      {modals.cibus && (
        <Overlay title="Enter Cibus Code" onClose={() => setModals({...modals, cibus: null})}>
           <div className="space-y-4">
              <input required autoFocus className="w-full p-6 bg-slate-50 rounded-[2rem] font-black text-center text-3xl tracking-[0.2em] border-4 border-indigo-100 outline-none" placeholder="000000" maxLength={6} value={inputs.cibus} onChange={e => setInputs({...inputs, cibus: e.target.value})} />
              <Button onClick={() => {
                  const { runId, orderId } = modals.cibus;
                  setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: r.orders.map((o: any) => o.id === orderId ? { ...o, cibusCode: inputs.cibus } : o) } : r));
                  setModals({...modals, cibus: null});
                  setInputs({...inputs, cibus: ''});
                }} className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl">Confirm Payment</Button>
           </div>
        </Overlay>
      )}

      {modals.arrive && (
        <Overlay title="Drop-off Signal" onClose={() => setModals({...modals, arrive: null})}>
           <form onSubmit={(e) => { e.preventDefault(); actions.arrive(modals.arrive); }} className="space-y-4">
              <input required autoFocus className="w-full p-4 bg-slate-50 rounded-2xl font-bold text-center" placeholder="Where is it?" value={inputs.loc} onChange={e => setInputs({...inputs, loc: e.target.value})} />
              <Button type="submit" className="w-full h-14 bg-emerald-600 font-black uppercase text-[11px] rounded-2xl">Send Arrival Alert</Button>
           </form>
        </Overlay>
      )}

      {modals.waitlist && (
        <Overlay title="Sector Waitlist" onClose={() => setModals({...modals, waitlist: false})}>
           <div className="space-y-2 max-h-[300px] overflow-y-auto pr-2">
              {waitingOrders.length === 0 ? (
                <div className="text-center py-6 opacity-30 text-[10px] font-black uppercase">Waitlist Empty</div>
              ) : (
                waitingOrders.map((wo: any) => (
                  <div key={wo.id} className="p-3 bg-slate-50 rounded-xl flex justify-between items-center text-[10px]">
                    <span className="font-bold">{wo.userName} @ {wo.destination}</span>
                    <span className="bg-white px-2 py-0.5 rounded border">FL {wo.floor}</span>
                  </div>
                ))
              )}
           </div>
        </Overlay>
      )}
    </div>
  );
};

const Overlay: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
  <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[300] flex items-center justify-center p-6">
    <div className="bg-white rounded-[2rem] p-8 w-full max-w-[340px] shadow-2xl relative border border-slate-100">
      <div className="flex justify-between items-center mb-8">
         <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-indigo-600">{title}</h3>
         <button onClick={onClose} className="w-8 h-8 rounded-full bg-slate-50 text-slate-300 hover:text-slate-600 transition-colors flex items-center justify-center"><i className="fas fa-times"></i></button>
      </div>
      {children}
    </div>
  </div>
);

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { FoodRun, Order, WaitingOrder, UserNotification } from './types';
import { Button } from './components/Button';
import { sendToGoogleChat } from './services/googleChatService';

const ALLOWED_DOMAIN = 'yourcompany.com';

const normalizeBusinessName = (name: string): string => {
  return name.trim().toLowerCase()
    .replace(/\s+/g, '')
    .replace(/[-_]/g, '')
    .replace(/^ה/g, '');
};

const App: React.FC = () => {
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [notifications, setNotifications] = useState<UserNotification[]>([]);
  const [simulatorMode, setSimulatorMode] = useState(false);
  const [webhookUrl, setWebhookUrl] = useState<string>(localStorage.getItem('lunchrun_webhook') || '');
  const [messagePrefix, setMessagePrefix] = useState<string>(localStorage.getItem('lunchrun_prefix') || '[LunchRun]');
  const [defaultWait, setDefaultWait] = useState<number>(Number(localStorage.getItem('lunchrun_def_wait')) || 20);
  const [defaultMax, setDefaultMax] = useState<number>(Number(localStorage.getItem('lunchrun_def_max')) || 5);
  const [isSimulatorAdmin, setIsSimulatorAdmin] = useState(false);

  useEffect(() => {
    const saved = {
      history: localStorage.getItem('lunchrun_history'),
      waitlist: localStorage.getItem('lunchrun_waitlist'),
      notifs: localStorage.getItem('lunchrun_notifications'),
      runs: localStorage.getItem('lunchrun_active_runs')
    };
    if (saved.history) setHistory(JSON.parse(saved.history));
    if (saved.waitlist) setWaitingOrders(JSON.parse(saved.waitlist));
    if (saved.notifs) setNotifications(JSON.parse(saved.notifs));
    if (saved.runs) setRuns(JSON.parse(saved.runs));
  }, []);

  useEffect(() => {
    localStorage.setItem('lunchrun_active_runs', JSON.stringify(runs));
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(waitingOrders));
    localStorage.setItem('lunchrun_notifications', JSON.stringify(notifications));
    localStorage.setItem('lunchrun_history', JSON.stringify(history));
    localStorage.setItem('lunchrun_webhook', webhookUrl);
    localStorage.setItem('lunchrun_prefix', messagePrefix);
    localStorage.setItem('lunchrun_def_wait', defaultWait.toString());
    localStorage.setItem('lunchrun_def_max', defaultMax.toString());
  }, [runs, waitingOrders, notifications, history, webhookUrl, messagePrefix, defaultWait, defaultMax]);

  const sharedActions = {
    runs, setRuns,
    history, setHistory,
    waitingOrders, setWaitingOrders,
    notifications, setNotifications,
    webhookUrl, setWebhookUrl,
    messagePrefix, setMessagePrefix,
    defaultWait, setDefaultWait,
    defaultMax, setDefaultMax,
    isSimulatorAdmin
  };

  return (
    <div className={`min-h-screen transition-all duration-500 ${simulatorMode ? 'p-2 bg-slate-200' : 'bg-[#fcfdfe]'}`}>
      <div className="bg-slate-900 text-white/70 px-6 py-2 flex justify-between items-center text-[10px] font-black uppercase tracking-[0.2em] shadow-xl sticky top-0 z-[100] rounded-b-xl sm:mx-4">
        <div className="flex items-center gap-4">
          <div className={`w-2 h-2 rounded-full animate-pulse ${isSimulatorAdmin ? 'bg-amber-400' : 'bg-indigo-400'}`}></div>
          <span>LunchRun Fleet Control</span>
        </div>
        <div className="flex gap-4">
           {simulatorMode && (
             <button onClick={() => setIsSimulatorAdmin(!isSimulatorAdmin)} className={`px-4 py-1.5 rounded-full border transition-all text-[9px] ${isSimulatorAdmin ? 'bg-amber-500 border-amber-400 text-slate-900' : 'border-slate-700 hover:text-white'}`}>
               {isSimulatorAdmin ? 'ADMIN: ON' : 'ADMIN: OFF'}
             </button>
           )}
           <button onClick={() => setSimulatorMode(!simulatorMode)} className="px-4 py-1.5 rounded-full border border-slate-700 hover:text-white text-[9px] transition-all">
             {simulatorMode ? 'Exit Simulator' : 'Simulation Mode'}
           </button>
        </div>
      </div>

      {simulatorMode ? (
        <div className="flex flex-col md:flex-row h-[calc(100vh-80px)] gap-4 mt-4 overflow-hidden">
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-indigo-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Persona: Runner</div>
             <AppInstance userOverride={{ name: 'Avi', email: `avi@${ALLOWED_DOMAIN}` }} {...sharedActions} />
          </div>
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-emerald-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Persona: Orderer</div>
             <AppInstance userOverride={{ name: 'Dana', email: `dana@${ALLOWED_DOMAIN}` }} {...sharedActions} />
          </div>
        </div>
      ) : (
        <div className="max-w-4xl mx-auto mt-6 px-4">
          <AppInstance {...sharedActions} />
        </div>
      )}
    </div>
  );
};

const AppInstance: React.FC<any> = ({ 
  userOverride, 
  runs, setRuns, 
  history, setHistory, 
  waitingOrders, setWaitingOrders, 
  notifications, setNotifications,
  webhookUrl, setWebhookUrl,
  messagePrefix, setMessagePrefix,
  defaultWait, setDefaultWait,
  defaultMax, setDefaultMax,
  isSimulatorAdmin
}) => {
  const [user, setUser] = useState<{ name: string; email: string; isAdmin?: boolean } | null>(userOverride || null);
  const [testLoading, setTestLoading] = useState(false);
  const [modals, setModals] = useState<{ [key: string]: boolean | any }>({
    create: false, waitlist: false, join: null, cibus: null, arrive: null
  });
  const [inputs, setInputs] = useState({ dest: '', time: defaultWait, max: defaultMax, item: '', floor: '', cibus: '', loc: '' });

  useEffect(() => {
    if (!user) return;
    const params = new URLSearchParams(window.location.search);
    const action = params.get('action');
    const runId = params.get('runId');

    if (runId && action === 'pay') {
      const run = runs.find((r: FoodRun) => r.id === runId);
      if (run) {
        const myOrder = run.orders.find((o: Order) => o.userEmail === user.email);
        if (myOrder) setModals(prev => ({ ...prev, cibus: { runId, orderId: myOrder.id } }));
      }
    } else if (runId && action === 'join') {
      setModals(prev => ({ ...prev, join: runId }));
    }
    if (action) window.history.replaceState({}, document.title, window.location.pathname);
  }, [user, runs.length]);

  const destinationSuggestions = useMemo(() => {
    const all = [...history, ...runs, ...waitingOrders].map(item => item.destination);
    return Array.from(new Set(all)).sort();
  }, [history, runs, waitingOrders]);

  const actions = {
    createRun: (e: React.FormEvent) => {
      e.preventDefault();
      const normDest = normalizeBusinessName(inputs.dest);
      const matches = waitingOrders.filter(wo => normalizeBusinessName(wo.destination) === normDest);
      const ordersToPull = matches.slice(0, inputs.max);

      const orders: Order[] = ordersToPull.map(wo => ({ id: wo.id, userName: wo.userName, userEmail: wo.userEmail, itemDescription: wo.itemDescription, floor: wo.floor, cibusCode: '', timestamp: Date.now() }));

      const newRun: FoodRun = {
        id: Math.random().toString(36).substr(2, 9), runnerName: user?.name || '', runnerEmail: user?.email || '',
        destination: inputs.dest, departureTime: Date.now() + inputs.time * 60000, minutesUntilDeparture: inputs.time,
        maxOrders: inputs.max, status: 'active', orders
      };

      setWaitingOrders((prev: any) => prev.filter((wo: any) => !ordersToPull.some(o => o.id === wo.id)));
      setRuns((prev: any) => [newRun, ...prev]);
      setModals({ ...modals, create: false });

      const baseUrl = window.location.href.split('?')[0];
      sendToGoogleChat(webhookUrl, {
        title: "New Fleet Launched",
        subtitle: inputs.dest,
        details: `Departing in ${inputs.time} minutes. Coordinator: ${user?.name}.`,
        buttons: [
          { text: "Join via App", url: `${baseUrl}?action=join&runId=${newRun.id}` },
          { text: "Direct Message", url: `https://mail.google.com/chat/u/0/#chat/dm/${user?.email}` }
        ],
        prefix: messagePrefix
      });
    },
    depart: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, status: 'departed' } : r));

      const baseUrl = window.location.href.split('?')[0];
      sendToGoogleChat(webhookUrl, {
        title: "Fleet Departure Alert",
        subtitle: run.destination,
        details: "The runner has departed. Please submit your payment code.",
        buttons: [
          { text: "Submit Payment", url: `${baseUrl}?action=pay&runId=${runId}` },
          { text: "DM Runner", url: `https://mail.google.com/chat/u/0/#chat/dm/${run.runnerEmail}` }
        ],
        prefix: messagePrefix
      });
    },
    arrive: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      sendToGoogleChat(webhookUrl, {
        title: "Delivery Arrived",
        subtitle: `Location: ${inputs.loc}`,
        details: `Your order from ${run.destination} is ready for pickup.`,
        prefix: messagePrefix
      });
      setHistory((prev: any) => [{ ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() }, ...prev]);
      setRuns(runs.filter((r: any) => r.id !== runId));
      setModals({ ...modals, arrive: null });
    },
    join: (runId: string) => {
      const order: Order = { id: Math.random().toString(36).substr(2, 9), userName: user?.name || '', userEmail: user?.email || '', itemDescription: inputs.item, floor: inputs.floor, cibusCode: '', timestamp: Date.now() };
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: [...r.orders, order] } : r));
      setModals({ ...modals, join: null });
    }
  };

  const isAdmin = user?.isAdmin || isSimulatorAdmin;

  if (!user) {
    return (
      <div className="fixed inset-0 flex flex-col items-center justify-center p-6 bg-[#f8fafc]">
        {/* Subtle background decoration */}
        <div className="absolute top-0 left-0 w-full h-1/2 bg-gradient-to-b from-indigo-50/50 to-transparent pointer-events-none"></div>

        <div className="w-full max-w-md bg-white rounded-[3rem] shadow-[0_32px_64px_-16px_rgba(0,0,0,0.12)] p-12 relative z-10 border border-slate-100 flex flex-col items-center">
          <div className="w-20 h-20 bg-indigo-600 rounded-[2rem] flex items-center justify-center text-white text-3xl mb-10 shadow-2xl shadow-indigo-200 animate-in zoom-in-50 duration-500">
            <i className="fas fa-bicycle"></i>
          </div>

          <div className="text-center mb-10">
            <h1 className="text-3xl font-black text-slate-900 tracking-tighter mb-2">LunchRun</h1>
            <p className="text-slate-400 font-bold uppercase text-[10px] tracking-[0.3em]">Fleet Management Network</p>
          </div>

          <form onSubmit={(e) => { e.preventDefault(); setUser({ name: 'Member', email: `user@${ALLOWED_DOMAIN}` }); }} className="w-full space-y-4">
             <div className="relative">
                <i className="fas fa-at absolute left-5 top-1/2 -translate-y-1/2 text-slate-300"></i>
                <input 
                  required 
                  type="email" 
                  placeholder="name@company.com" 
                  className="w-full pl-12 pr-6 py-5 bg-slate-50 border-2 border-slate-50 rounded-2xl font-bold text-slate-800 placeholder:text-slate-300 focus:bg-white focus:border-indigo-600 outline-none transition-all" 
                />
             </div>

             <button 
               type="submit" 
               className="w-full h-16 bg-indigo-600 hover:bg-indigo-700 active:scale-[0.98] text-white font-black uppercase text-xs tracking-widest rounded-2xl shadow-xl shadow-indigo-100 transition-all flex items-center justify-center gap-3"
             >
               Enter Fleet <i className="fas fa-arrow-right text-[10px]"></i>
             </button>

             <button 
               type="button" 
               onClick={() => setUser({name: 'Admin', email: 'admin@system.local', isAdmin: true})} 
               className="w-full pt-4 text-[9px] font-black text-slate-300 hover:text-indigo-400 uppercase tracking-widest transition-colors"
             >
               Admin Override
             </button>
          </form>
        </div>
        <p className="mt-8 text-slate-300 font-bold text-[10px] uppercase tracking-widest">© 2025 Fleet Logistics Protocol</p>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col bg-[#fcfdfe] relative">
      <datalist id="dest-options">
        {destinationSuggestions.map(d => <option key={d} value={d} />)}
      </datalist>

      <header className={`px-6 py-4 flex justify-between items-center border-b ${isAdmin ? 'bg-amber-50 border-amber-100' : 'bg-white border-slate-100'}`}>
        <div className="flex items-center gap-3">
           <div className={`w-10 h-10 rounded-2xl flex items-center justify-center text-white text-lg shadow-lg ${isAdmin ? 'bg-amber-500' : 'bg-indigo-600'}`}>
             <i className={`fas ${isAdmin ? 'fa-user-shield' : 'fa-hamburger'}`}></i>
           </div>
           <div>
             <span className="font-black text-base text-slate-800 tracking-tight">LUNCHRUN</span>
             <span className="text-[8px] font-black text-slate-400 uppercase block tracking-[0.2em]">{user.email}</span>
           </div>
        </div>
        <img src={`https://ui-avatars.com/api/?name=${user.name}&background=${isAdmin ? 'f59e0b' : '6366f1'}&color=fff`} className="w-10 h-10 rounded-2xl border-2 border-white shadow-xl" alt="u" />
      </header>

      <main className="flex-1 overflow-y-auto p-4 space-y-4 pb-24">
        {isAdmin && (
          <div className="bg-slate-900 rounded-[2.5rem] p-6 text-white shadow-2xl border-4 border-amber-500/20">
             <h3 className="text-amber-400 text-[10px] font-black uppercase tracking-widest mb-4">Webhook Terminal</h3>
             <div className="flex gap-2">
                <input className="flex-1 p-4 bg-white/5 border border-white/10 rounded-2xl font-bold text-xs outline-none" value={webhookUrl} onChange={e => setWebhookUrl(e.target.value)} placeholder="Webhook URL" />
                <Button onClick={async () => { setTestLoading(true); const ok = await sendToGoogleChat(webhookUrl, { title: "Test", subtitle: "Live", details: "Communication link active.", prefix: messagePrefix }); setTestLoading(false); alert(ok ? "Success" : "Error"); }} isLoading={testLoading} className="h-12 px-6 bg-amber-500 text-slate-900 text-[10px] uppercase font-black">Test Connection</Button>
             </div>
          </div>
        )}

        <div className="flex justify-between items-center bg-white p-3 rounded-2xl border border-slate-100 shadow-sm">
           <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-2">Active Operations</span>
           <div className="flex gap-2">
              <Button onClick={() => setModals({...modals, waitlist: true})} variant="ghost" className="h-10 px-5 text-[10px] font-black uppercase rounded-xl border border-slate-100">Waitlist</Button>
              <Button onClick={() => setModals({...modals, create: true})} className="h-10 px-5 text-[10px] font-black uppercase rounded-xl bg-indigo-600 shadow-xl shadow-indigo-100">Establish Run</Button>
           </div>
        </div>

        <div className="space-y-4">
           {runs.map((run: FoodRun) => {
             const isRunner = user.email === run.runnerEmail;
             const myOrder = run.orders.find(o => o.userEmail === user.email);
             return (
               <div key={run.id} className={`bg-white rounded-[2.5rem] p-7 shadow-xl border-2 transition-all ${run.status === 'departed' ? 'border-indigo-500' : 'border-white'}`}>
                  <div className="flex justify-between items-start mb-6">
                     <div className="flex gap-4">
                        <div className="w-16 h-16 rounded-[1.5rem] bg-slate-50 flex items-center justify-center text-2xl text-slate-300">
                           <i className={`fas ${run.status === 'departed' ? 'fa-motorcycle text-indigo-500' : 'fa-pizza-slice'}`}></i>
                        </div>
                        <div>
                           <h4 className="text-2xl font-black text-slate-800 tracking-tight">{run.destination}</h4>
                           <div className="flex items-center gap-2 mt-1">
                              <span className={`text-[9px] font-black px-2 py-0.5 rounded-full ${run.status === 'departed' ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-100 text-slate-400'}`}>{run.status.toUpperCase()}</span>
                              <span className="text-[11px] font-bold text-slate-400">{run.runnerName}</span>
                           </div>
                        </div>
                     </div>
                  </div>

                  {run.orders.length > 0 && (
                     <div className="space-y-2 mb-6">
                        {run.orders.map(o => (
                           <div key={o.id} className={`flex justify-between items-center p-4 rounded-2xl text-xs border ${o.userEmail === user.email ? 'bg-indigo-50 border-indigo-200' : 'bg-slate-50 border-slate-100'}`}>
                              <span className="font-bold text-slate-700">{o.userName}: <span className="font-normal text-slate-500 italic">"{o.itemDescription}"</span></span>
                              {o.userEmail === user.email && run.status === 'departed' && !o.cibusCode && (
                                 <button onClick={() => setModals({...modals, cibus: {runId: run.id, orderId: o.id}})} className="bg-indigo-600 text-white px-4 py-1.5 rounded-xl text-[10px] font-black uppercase">Submit Code</button>
                              )}
                              {o.cibusCode && <span className="text-[10px] font-black text-emerald-600"><i className="fas fa-check-circle mr-1"></i> {o.cibusCode}</span>}
                           </div>
                        ))}
                     </div>
                  )}

                  <div className="flex gap-3">
                     {isRunner ? (
                        run.status === 'active' ? (
                           <Button onClick={() => actions.depart(run.id)} className="flex-1 h-14 bg-indigo-600 text-[11px] font-black uppercase rounded-2xl shadow-lg">Broadcast Departure</Button>
                        ) : (
                           <Button onClick={() => setModals({...modals, arrive: run.id})} className="flex-1 h-14 bg-emerald-600 text-[11px] font-black uppercase rounded-2xl shadow-lg">Signal Arrival</Button>
                        )
                     ) : !myOrder && run.status === 'active' && (
                        <Button onClick={() => setModals({...modals, join: run.id})} className="flex-1 h-14 bg-slate-800 text-[11px] font-black uppercase rounded-2xl">Join Mission</Button>
                     )}
                     {myOrder && <div className="flex-1 text-center py-4 text-[11px] font-black uppercase text-indigo-400 tracking-widest"><i className="fas fa-check-circle mr-2"></i> In Fleet</div>}
                  </div>
               </div>
             );
           })}
        </div>
      </main>

      {/* OVERLAYS */}
      {modals.create && (
        <Overlay title="Initiate Run" onClose={() => setModals({...modals, create: false})}>
           <form onSubmit={actions.createRun} className="space-y-4">
              <input required list="dest-options" className="w-full p-5 bg-slate-50 rounded-2xl font-bold border-2 border-transparent focus:border-indigo-600 outline-none transition-all" placeholder="Destination Name" value={inputs.dest} onChange={e => setInputs({...inputs, dest: e.target.value})} />
              <div className="grid grid-cols-2 gap-4">
                 <input required type="number" className="w-full p-5 bg-slate-50 rounded-2xl font-bold" placeholder="Wait (m)" value={inputs.time} onChange={e => setInputs({...inputs, time: Number(e.target.value)})} />
                 <input required type="number" className="w-full p-5 bg-slate-50 rounded-2xl font-bold" placeholder="Capacity" value={inputs.max} onChange={e => setInputs({...inputs, max: Number(e.target.value)})} />
              </div>
              <Button type="submit" className="w-full h-16 bg-indigo-600 font-black uppercase text-[12px] tracking-widest rounded-2xl shadow-2xl shadow-indigo-100">Launch Session</Button>
           </form>
        </Overlay>
      )}

      {modals.join && (
        <Overlay title="Manifest Entry" onClose={() => setModals({...modals, join: null})}>
           <form onSubmit={(e) => { e.preventDefault(); actions.join(modals.join); }} className="space-y-4">
              <input required className="w-full p-5 bg-slate-50 rounded-2xl font-bold" placeholder="Item Details" value={inputs.item} onChange={e => setInputs({...inputs, item: e.target.value})} />
              <input required className="w-full p-5 bg-slate-50 rounded-2xl font-bold" placeholder="Floor Number" value={inputs.floor} onChange={e => setInputs({...inputs, floor: e.target.value})} />
              <Button type="submit" className="w-full h-16 bg-indigo-600 font-black uppercase text-[12px] rounded-2xl shadow-xl">Join Fleet</Button>
           </form>
        </Overlay>
      )}

      {modals.cibus && (
        <Overlay title="Payment Gateway" onClose={() => setModals({...modals, cibus: null})}>
           <div className="space-y-4">
              <input required autoFocus className="w-full p-8 bg-slate-50 rounded-[2.5rem] font-black text-center text-4xl tracking-[0.3em] border-4 border-indigo-100 outline-none focus:border-indigo-600 transition-all" placeholder="000000" maxLength={6} value={inputs.cibus} onChange={e => setInputs({...inputs, cibus: e.target.value})} />
              <Button onClick={() => {
                  const { runId, orderId } = modals.cibus;
                  setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: r.orders.map((o: any) => o.id === orderId ? { ...o, cibusCode: inputs.cibus } : o) } : r));
                  setModals({...modals, cibus: null});
                  setInputs({...inputs, cibus: ''});
                }} className="w-full h-16 bg-indigo-600 font-black uppercase text-[12px] rounded-2xl shadow-xl">Confirm Code</Button>
           </div>
        </Overlay>
      )}

      {modals.arrive && (
        <Overlay title="Drop-off Target" onClose={() => setModals({...modals, arrive: null})}>
           <form onSubmit={(e) => { e.preventDefault(); actions.arrive(modals.arrive); }} className="space-y-4">
              <input required autoFocus className="w-full p-5 bg-slate-50 rounded-2xl font-bold text-center text-lg" placeholder="Pickup Location (e.g. Lobby)" value={inputs.loc} onChange={e => setInputs({...inputs, loc: e.target.value})} />
              <Button type="submit" className="w-full h-16 bg-emerald-600 font-black uppercase text-[12px] rounded-2xl">Broadcast Arrival</Button>
           </form>
        </Overlay>
      )}

      {modals.waitlist && (
        <Overlay title="Sector Waitlist" onClose={() => setModals({...modals, waitlist: false})}>
           <div className="space-y-3 max-h-[350px] overflow-y-auto pr-2">
              {waitingOrders.length === 0 ? (
                <div className="text-center py-10 opacity-30 text-[11px] font-black uppercase tracking-widest">Waitlist Clear</div>
              ) : (
                waitingOrders.map((wo: any) => (
                  <div key={wo.id} className="p-5 bg-slate-50 rounded-[1.5rem] border border-slate-100 flex justify-between items-center">
                    <div>
                      <p className="font-black text-slate-800 text-sm">{wo.destination}</p>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">{wo.userName} • FL {wo.floor}</p>
                    </div>
                    <span className="w-8 h-8 flex items-center justify-center bg-white rounded-full border shadow-sm text-indigo-400"><i className="fas fa-clock text-[10px]"></i></span>
                  </div>
                ))
              )}
           </div>
        </Overlay>
      )}
    </div>
  );
};

const Overlay: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
  <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-xl z-[300] flex items-center justify-center p-6">
    <div className="bg-white rounded-[3rem] p-10 w-full max-w-[380px] shadow-[0_32px_64px_-16px_rgba(0,0,0,0.2)] animate-in zoom-in-95 fade-in duration-300 relative border border-white/20">
      <div className="flex justify-between items-center mb-10">
         <h3 className="text-[11px] font-black uppercase tracking-[0.4em] text-indigo-600">{title}</h3>
         <button onClick={onClose} className="w-10 h-10 rounded-2xl bg-slate-50 text-slate-300 hover:text-slate-600 transition-all flex items-center justify-center"><i className="fas fa-times"></i></button>
      </div>
      {children}
    </div>
  </div>
);

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { FoodRun, Order, WaitingOrder, UserNotification } from './types';
import { Button } from './components/Button';
import { sendToGoogleChat } from './services/googleChatService';

const ALLOWED_DOMAIN = 'yourcompany.com';

const normalizeBusinessName = (name: string): string => {
  return name.trim().toLowerCase()
    .replace(/\s+/g, '')
    .replace(/[-_]/g, '')
    .replace(/^ה/g, '');
};

const App: React.FC = () => {
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [notifications, setNotifications] = useState<UserNotification[]>([]);
  const [simulatorMode, setSimulatorMode] = useState(false);
  const [webhookUrl, setWebhookUrl] = useState<string>(localStorage.getItem('lunchrun_webhook') || '');
  const [messagePrefix, setMessagePrefix] = useState<string>(localStorage.getItem('lunchrun_prefix') || '[LunchRun]');
  const [defaultWait, setDefaultWait] = useState<number>(Number(localStorage.getItem('lunchrun_def_wait')) || 20);
  const [defaultMax, setDefaultMax] = useState<number>(Number(localStorage.getItem('lunchrun_def_max')) || 5);
  const [isSimulatorAdmin, setIsSimulatorAdmin] = useState(false);

  useEffect(() => {
    const saved = {
      history: localStorage.getItem('lunchrun_history'),
      waitlist: localStorage.getItem('lunchrun_waitlist'),
      notifs: localStorage.getItem('lunchrun_notifications'),
      runs: localStorage.getItem('lunchrun_active_runs')
    };
    if (saved.history) setHistory(JSON.parse(saved.history));
    if (saved.waitlist) setWaitingOrders(JSON.parse(saved.waitlist));
    if (saved.notifs) setNotifications(JSON.parse(saved.notifs));
    if (saved.runs) setRuns(JSON.parse(saved.runs));
  }, []);

  useEffect(() => {
    localStorage.setItem('lunchrun_active_runs', JSON.stringify(runs));
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(waitingOrders));
    localStorage.setItem('lunchrun_notifications', JSON.stringify(notifications));
    localStorage.setItem('lunchrun_history', JSON.stringify(history));
    localStorage.setItem('lunchrun_webhook', webhookUrl);
    localStorage.setItem('lunchrun_prefix', messagePrefix);
    localStorage.setItem('lunchrun_def_wait', defaultWait.toString());
    localStorage.setItem('lunchrun_def_max', defaultMax.toString());
  }, [runs, waitingOrders, notifications, history, webhookUrl, messagePrefix, defaultWait, defaultMax]);

  const sharedActions = {
    runs, setRuns,
    history, setHistory,
    waitingOrders, setWaitingOrders,
    notifications, setNotifications,
    webhookUrl, setWebhookUrl,
    messagePrefix, setMessagePrefix,
    defaultWait, setDefaultWait,
    defaultMax, setDefaultMax,
    isSimulatorAdmin
  };

  return (
    <div className={`min-h-screen transition-all duration-500 ${simulatorMode ? 'p-2 bg-slate-200' : 'bg-white'}`}>
      <div className="bg-slate-900 text-white/70 px-6 py-2 flex justify-between items-center text-[10px] font-black uppercase tracking-[0.2em] shadow-xl sticky top-0 z-[100] rounded-b-xl sm:mx-4">
        <div className="flex items-center gap-4">
          <div className={`w-2 h-2 rounded-full animate-pulse ${isSimulatorAdmin ? 'bg-amber-400' : 'bg-indigo-400'}`}></div>
          <span>LunchRun</span>
        </div>
        <div className="flex gap-4">
           {simulatorMode && (
             <button onClick={() => setIsSimulatorAdmin(!isSimulatorAdmin)} className={`px-4 py-1.5 rounded-full border transition-all text-[9px] ${isSimulatorAdmin ? 'bg-amber-500 border-amber-400 text-slate-900' : 'border-slate-700 hover:text-white'}`}>
               {isSimulatorAdmin ? 'ADMIN: ON' : 'ADMIN: OFF'}
             </button>
           )}
           <button onClick={() => setSimulatorMode(!simulatorMode)} className="px-4 py-1.5 rounded-full border border-slate-700 hover:text-white text-[9px] transition-all">
             {simulatorMode ? 'Exit Simulator' : 'Split-Screen QA'}
           </button>
        </div>
      </div>

      {simulatorMode ? (
        <div className="flex flex-col md:flex-row h-[calc(100vh-80px)] gap-4 mt-4 overflow-hidden">
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-indigo-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Persona: Runner</div>
             <AppInstance userOverride={{ name: 'Avi', email: `avi@${ALLOWED_DOMAIN}` }} {...sharedActions} />
          </div>
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-emerald-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Persona: Orderer</div>
             <AppInstance userOverride={{ name: 'Dana', email: `dana@${ALLOWED_DOMAIN}` }} {...sharedActions} />
          </div>
        </div>
      ) : (
        <div className="max-w-4xl mx-auto mt-6 px-4">
          <AppInstance {...sharedActions} />
        </div>
      )}
    </div>
  );
};

const AppInstance: React.FC<any> = ({ 
  userOverride, 
  runs, setRuns, 
  history, setHistory, 
  waitingOrders, setWaitingOrders, 
  notifications, setNotifications,
  webhookUrl, setWebhookUrl,
  messagePrefix, setMessagePrefix,
  defaultWait, setDefaultWait,
  defaultMax, setDefaultMax,
  isSimulatorAdmin
}) => {
  const [user, setUser] = useState<{ name: string; email: string; isAdmin?: boolean } | null>(userOverride || null);
  const [testLoading, setTestLoading] = useState(false);
  const [modals, setModals] = useState<{ [key: string]: boolean | any }>({
    create: false, waitlist: false, join: null, cibus: null, arrive: null
  });
  const [inputs, setInputs] = useState({ dest: '', time: defaultWait, max: defaultMax, item: '', floor: '', cibus: '', loc: '' });

  useEffect(() => {
    if (!user) return;
    const params = new URLSearchParams(window.location.search);
    const action = params.get('action');
    const runId = params.get('runId');

    if (runId && action === 'pay') {
      const run = runs.find((r: FoodRun) => r.id === runId);
      if (run) {
        const myOrder = run.orders.find((o: Order) => o.userEmail === user.email);
        if (myOrder) setModals(prev => ({ ...prev, cibus: { runId, orderId: myOrder.id } }));
      }
    } else if (runId && action === 'join') {
      setModals(prev => ({ ...prev, join: runId }));
    }
    if (action) window.history.replaceState({}, document.title, window.location.pathname);
  }, [user, runs.length]);

  const destinationSuggestions = useMemo(() => {
    const all = [...history, ...runs, ...waitingOrders].map(item => item.destination);
    return Array.from(new Set(all)).sort();
  }, [history, runs, waitingOrders]);

  const actions = {
    createRun: (e: React.FormEvent) => {
      e.preventDefault();
      const normDest = normalizeBusinessName(inputs.dest);
      const matches = waitingOrders.filter(wo => normalizeBusinessName(wo.destination) === normDest);
      const ordersToPull = matches.slice(0, inputs.max);

      const orders: Order[] = ordersToPull.map(wo => ({ id: wo.id, userName: wo.userName, userEmail: wo.userEmail, itemDescription: wo.itemDescription, floor: wo.floor, cibusCode: '', timestamp: Date.now() }));

      const newRun: FoodRun = {
        id: Math.random().toString(36).substr(2, 9), runnerName: user?.name || '', runnerEmail: user?.email || '',
        destination: inputs.dest, departureTime: Date.now() + inputs.time * 60000, minutesUntilDeparture: inputs.time,
        maxOrders: inputs.max, status: 'active', orders
      };

      setWaitingOrders((prev: any) => prev.filter((wo: any) => !ordersToPull.some(o => o.id === wo.id)));
      setRuns((prev: any) => [newRun, ...prev]);
      setModals({ ...modals, create: false });

      const baseUrl = window.location.href.split('?')[0];
      sendToGoogleChat(webhookUrl, {
        title: "New Run Started",
        subtitle: inputs.dest,
        details: `Departing in ${inputs.time} mins. Runner: ${user?.name}.`,
        buttons: [
          { text: "Join via App", url: `${baseUrl}?action=join&runId=${newRun.id}` },
          { text: "Send DM to Runner", url: `https://mail.google.com/chat/u/0/#chat/dm/${user?.email}` }
        ],
        prefix: messagePrefix
      });
    },
    depart: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, status: 'departed' } : r));

      const baseUrl = window.location.href.split('?')[0];
      sendToGoogleChat(webhookUrl, {
        title: "Departure Alert",
        subtitle: run.destination,
        details: "The runner is leaving. Please enter your Cibus payment code.",
        buttons: [
          { text: "Enter Code", url: `${baseUrl}?action=pay&runId=${runId}` },
          { text: "Message Runner", url: `https://mail.google.com/chat/u/0/#chat/dm/${run.runnerEmail}` }
        ],
        prefix: messagePrefix
      });
    },
    arrive: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      sendToGoogleChat(webhookUrl, {
        title: "Food is Here!",
        subtitle: `Pickup: ${inputs.loc}`,
        details: `Order from ${run.destination} has arrived. Enjoy!`,
        prefix: messagePrefix
      });
      setHistory((prev: any) => [{ ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() }, ...prev]);
      setRuns(runs.filter((r: any) => r.id !== runId));
      setModals({ ...modals, arrive: null });
    },
    join: (runId: string) => {
      const order: Order = { id: Math.random().toString(36).substr(2, 9), userName: user?.name || '', userEmail: user?.email || '', itemDescription: inputs.item, floor: inputs.floor, cibusCode: '', timestamp: Date.now() };
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: [...r.orders, order] } : r));
      setModals({ ...modals, join: null });
    }
  };

  const isAdmin = user?.isAdmin || isSimulatorAdmin;

  if (!user) {
    return (
      <div className="h-[100vh] flex flex-col items-center justify-center p-8 bg-white">
        <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-3xl mb-6 shadow-xl">
          <i className="fas fa-motorcycle"></i>
        </div>
        <h1 className="text-2xl font-black text-slate-800 tracking-tighter">LunchRun Access</h1>
        <form onSubmit={(e) => { e.preventDefault(); setUser({ name: 'User', email: `user@${ALLOWED_DOMAIN}` }); }} className="mt-8 w-full max-w-xs space-y-3">
           <input 
             required 
             type="email" 
             placeholder="Corporate Email" 
             className="w-full p-4 bg-slate-50 border-0 rounded-2xl font-bold placeholder:text-slate-400 focus:bg-slate-100 outline-none" 
           />
           <Button type="submit" className="w-full h-14 bg-orange-600 text-white font-black uppercase rounded-2xl">SIGN IN</Button>
           <button 
             type="button" 
             onClick={() => setUser({name: 'Admin', email: 'admin@system.local', isAdmin: true})} 
             className="w-full py-2 text-[9px] font-black text-slate-400 uppercase tracking-widest hover:text-orange-600 transition-colors"
           >
             ADMIN OVERRIDE
           </button>
        </form>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col bg-slate-50 relative">
      <datalist id="dest-options">
        {destinationSuggestions.map(d => <option key={d} value={d} />)}
      </datalist>

      <header className={`px-6 py-4 flex justify-between items-center border-b ${isAdmin ? 'bg-amber-50 border-amber-100' : 'bg-white border-slate-100'}`}>
        <div className="flex items-center gap-3">
           <div className={`w-9 h-9 rounded-xl flex items-center justify-center text-white text-lg shadow-lg ${isAdmin ? 'bg-amber-500' : 'bg-indigo-600'}`}>
             <i className={`fas ${isAdmin ? 'fa-user-shield' : 'fa-hamburger'}`}></i>
           </div>
           <div>
             <span className="font-black text-sm text-slate-800 tracking-tight">LUNCHRUN</span>
             <span className="text-[8px] font-black text-slate-400 uppercase block tracking-widest">{user.email}</span>
           </div>
        </div>
        <img src={`https://ui-avatars.com/api/?name=${user.name}&background=${isAdmin ? 'f59e0b' : '6366f1'}&color=fff`} className="w-9 h-9 rounded-2xl border-2 border-white shadow-sm" alt="u" />
      </header>

      <main className="flex-1 overflow-y-auto p-4 space-y-4 pb-24">
        {isAdmin && (
          <div className="bg-slate-900 rounded-[2rem] p-6 text-white shadow-2xl border-4 border-amber-500/20">
             <h3 className="text-amber-400 text-[10px] font-black uppercase tracking-widest mb-4">Admin Webhook Config</h3>
             <div className="flex gap-2">
                <input className="flex-1 p-3 bg-white/5 border border-white/10 rounded-2xl font-bold text-xs outline-none" value={webhookUrl} onChange={e => setWebhookUrl(e.target.value)} placeholder="Google Chat Webhook URL" />
                <Button onClick={async () => { setTestLoading(true); const ok = await sendToGoogleChat(webhookUrl, { title: "Test", subtitle: "Live", details: "Communication test successful.", prefix: messagePrefix }); setTestLoading(false); alert(ok ? "Sent" : "Failed"); }} isLoading={testLoading} className="h-10 px-4 bg-amber-500 text-slate-900 text-[10px] uppercase font-black">Test</Button>
             </div>
          </div>
        )}

        <div className="flex justify-between items-center bg-white p-3 rounded-2xl border border-slate-100 shadow-sm">
           <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-2">Active Runs</span>
           <div className="flex gap-2">
              <Button onClick={() => setModals({...modals, waitlist: true})} variant="ghost" className="h-9 px-4 text-[10px] font-black uppercase rounded-xl border border-slate-100">Waitlist</Button>
              <Button onClick={() => setModals({...modals, create: true})} className="h-9 px-4 text-[10px] font-black uppercase rounded-xl bg-indigo-600 shadow-lg">Start Run</Button>
           </div>
        </div>

        <div className="space-y-4">
           {runs.map((run: FoodRun) => {
             const isRunner = user.email === run.runnerEmail;
             const myOrder = run.orders.find(o => o.userEmail === user.email);
             return (
               <div key={run.id} className={`bg-white rounded-[2rem] p-6 shadow-xl border-2 transition-all ${run.status === 'departed' ? 'border-indigo-500' : 'border-white'}`}>
                  <div className="flex justify-between items-start mb-6">
                     <div className="flex gap-4">
                        <div className="w-14 h-14 rounded-2xl bg-slate-50 flex items-center justify-center text-2xl text-slate-300 shadow-inner">
                           <i className={`fas ${run.status === 'departed' ? 'fa-motorcycle text-indigo-500' : 'fa-pizza-slice'}`}></i>
                        </div>
                        <div>
                           <h4 className="text-xl font-black text-slate-800 tracking-tight">{run.destination}</h4>
                           <div className="flex items-center gap-2 mt-1">
                              <span className={`text-[9px] font-black px-2 py-0.5 rounded-full ${run.status === 'departed' ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-100 text-slate-400'}`}>{run.status.toUpperCase()}</span>
                              <span className="text-[10px] font-bold text-slate-400">Runner: {run.runnerName}</span>
                           </div>
                        </div>
                     </div>
                  </div>

                  {run.orders.length > 0 && (
                     <div className="space-y-2 mb-6">
                        {run.orders.map(o => (
                           <div key={o.id} className={`flex justify-between items-center p-3 rounded-2xl text-xs border ${o.userEmail === user.email ? 'bg-indigo-50 border-indigo-200 shadow-sm' : 'bg-slate-50 border-slate-100'}`}>
                              <span className="font-bold text-slate-700">{o.userName}: <span className="font-normal text-slate-500 italic">"{o.itemDescription}"</span></span>
                              {o.userEmail === user.email && run.status === 'departed' && !o.cibusCode && (
                                 <button onClick={() => setModals({...modals, cibus: {runId: run.id, orderId: o.id}})} className="bg-indigo-600 text-white px-3 py-1 rounded-lg text-[9px] font-black uppercase shadow-lg shadow-indigo-100">Send Code</button>
                              )}
                              {o.cibusCode && <span className="text-[9px] font-black text-emerald-600"><i className="fas fa-check-circle"></i> {o.cibusCode}</span>}
                           </div>
                        ))}
                     </div>
                  )}

                  <div className="flex gap-3">
                     {isRunner ? (
                        run.status === 'active' ? (
                           <Button onClick={() => actions.depart(run.id)} className="flex-1 h-12 bg-indigo-600 text-[10px] font-black uppercase rounded-xl">Broadcast Departure</Button>
                        ) : (
                           <Button onClick={() => setModals({...modals, arrive: run.id})} className="flex-1 h-12 bg-emerald-600 text-[10px] font-black uppercase rounded-xl">Broadcast Arrival</Button>
                        )
                     ) : !myOrder && run.status === 'active' && (
                        <Button onClick={() => setModals({...modals, join: run.id})} className="flex-1 h-12 bg-slate-800 text-[10px] font-black uppercase rounded-xl">Join Run</Button>
                     )}
                     {myOrder && <div className="flex-1 text-center py-4 text-[10px] font-black uppercase text-indigo-400 tracking-widest"><i className="fas fa-check-circle mr-2"></i> Manifested</div>}
                  </div>
               </div>
             );
           })}
        </div>
      </main>

      {/* OVERLAYS */}
      {modals.create && (
        <Overlay title="New Food Run" onClose={() => setModals({...modals, create: false})}>
           <form onSubmit={actions.createRun} className="space-y-4">
              <input required list="dest-options" className="w-full p-4 bg-slate-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-indigo-500" placeholder="Destination (e.g. Hummus)" value={inputs.dest} onChange={e => setInputs({...inputs, dest: e.target.value})} />
              <div className="grid grid-cols-2 gap-4">
                 <input required type="number" className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Wait (m)" value={inputs.time} onChange={e => setInputs({...inputs, time: Number(e.target.value)})} />
                 <input required type="number" className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Max Spots" value={inputs.max} onChange={e => setInputs({...inputs, max: Number(e.target.value)})} />
              </div>
              <Button type="submit" className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl shadow-xl">Launch Run</Button>
           </form>
        </Overlay>
      )}

      {modals.join && (
        <Overlay title="Join the Run" onClose={() => setModals({...modals, join: null})}>
           <form onSubmit={(e) => { e.preventDefault(); actions.join(modals.join); }} className="space-y-4">
              <input required className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Item (e.g. Salad)" value={inputs.item} onChange={e => setInputs({...inputs, item: e.target.value})} />
              <input required className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Floor #" value={inputs.floor} onChange={e => setInputs({...inputs, floor: e.target.value})} />
              <Button type="submit" className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl shadow-xl">Confirm Join</Button>
           </form>
        </Overlay>
      )}

      {modals.cibus && (
        <Overlay title="Cibus Payment" onClose={() => setModals({...modals, cibus: null})}>
           <div className="space-y-4">
              <p className="text-[10px] text-center text-slate-400 font-bold uppercase mb-2 tracking-widest">Enter 6-digit code for the runner</p>
              <input required autoFocus className="w-full p-6 bg-slate-50 rounded-[2rem] font-black text-center text-3xl tracking-[0.2em] border-4 border-indigo-100 outline-none focus:border-indigo-600" placeholder="000000" maxLength={6} value={inputs.cibus} onChange={e => setInputs({...inputs, cibus: e.target.value})} />
              <Button onClick={() => {
                  const { runId, orderId } = modals.cibus;
                  setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: r.orders.map((o: any) => o.id === orderId ? { ...o, cibusCode: inputs.cibus } : o) } : r));
                  setModals({...modals, cibus: null});
                  setInputs({...inputs, cibus: ''});
                }} className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl shadow-xl">Confirm Code</Button>
           </div>
        </Overlay>
      )}

      {modals.arrive && (
        <Overlay title="Food Arrival" onClose={() => setModals({...modals, arrive: null})}>
           <form onSubmit={(e) => { e.preventDefault(); actions.arrive(modals.arrive); }} className="space-y-4">
              <input required autoFocus className="w-full p-4 bg-slate-50 rounded-2xl font-bold text-center" placeholder="Where to pick up?" value={inputs.loc} onChange={e => setInputs({...inputs, loc: e.target.value})} />
              <Button type="submit" className="w-full h-14 bg-emerald-600 font-black uppercase text-[11px] rounded-2xl shadow-xl">Broadcast Arrival</Button>
           </form>
        </Overlay>
      )}

      {modals.waitlist && (
        <Overlay title="Global Waitlist" onClose={() => setModals({...modals, waitlist: false})}>
           <div className="space-y-3 max-h-[350px] overflow-y-auto pr-2">
              {waitingOrders.length === 0 ? (
                <div className="text-center py-10 opacity-30 text-[10px] font-black uppercase tracking-widest">Waitlist Empty</div>
              ) : (
                waitingOrders.map((wo: any) => (
                  <div key={wo.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex justify-between items-center">
                    <div>
                      <p className="font-black text-slate-800 text-xs">{wo.destination}</p>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">{wo.userName} • {wo.itemDescription}</p>
                    </div>
                    <span className="text-[9px] font-black bg-white px-2 py-0.5 rounded-full border shadow-sm">FL {wo.floor}</span>
                  </div>
                ))
              )}
           </div>
        </Overlay>
      )}
    </div>
  );
};

const Overlay: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
  <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[300] flex items-center justify-center p-6">
    <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-[340px] shadow-[0_20px_50px_rgba(0,0,0,0.3)] animate-in zoom-in-95 duration-300 relative border border-slate-100">
      <div className="flex justify-between items-center mb-8">
         <h3 className="text-[11px] font-black uppercase tracking-[0.2em] text-indigo-600">{title}</h3>
         <button onClick={onClose} className="w-9 h-9 rounded-full bg-slate-50 text-slate-300 hover:text-slate-600 transition-colors flex items-center justify-center"><i className="fas fa-times"></i></button>
      </div>
      {children}
    </div>
  </div>
);

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { FoodRun, Order, WaitingOrder, UserNotification } from './types';
import { Button } from './components/Button';
import { sendToGoogleChat } from './services/googleChatService';

const ALLOWED_DOMAIN = 'yourcompany.com';

const normalizeBusinessName = (name: string): string => {
  return name.trim().toLowerCase()
    .replace(/\s+/g, '')
    .replace(/[-_]/g, '')
    .replace(/^ה/g, '');
};

const App: React.FC = () => {
  const [user, setUser] = useState<{ name: string; email: string; isAdmin?: boolean } | null>(null);
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [notifications, setNotifications] = useState<UserNotification[]>([]);
  const [simulatorMode, setSimulatorMode] = useState(false);
  const [webhookUrl, setWebhookUrl] = useState<string>(localStorage.getItem('lunchrun_webhook') || '');
  const [messagePrefix, setMessagePrefix] = useState<string>(localStorage.getItem('lunchrun_prefix') || '[LunchRun]');
  const [defaultWait, setDefaultWait] = useState<number>(Number(localStorage.getItem('lunchrun_def_wait')) || 20);
  const [defaultMax, setDefaultMax] = useState<number>(Number(localStorage.getItem('lunchrun_def_max')) || 5);
  const [isSimulatorAdmin, setIsSimulatorAdmin] = useState(false);

  useEffect(() => {
    const saved = {
      history: localStorage.getItem('lunchrun_history'),
      waitlist: localStorage.getItem('lunchrun_waitlist'),
      notifs: localStorage.getItem('lunchrun_notifications'),
      runs: localStorage.getItem('lunchrun_active_runs')
    };
    if (saved.history) setHistory(JSON.parse(saved.history));
    if (saved.waitlist) setWaitingOrders(JSON.parse(saved.waitlist));
    if (saved.notifs) setNotifications(JSON.parse(saved.notifs));
    if (saved.runs) setRuns(JSON.parse(saved.runs));
  }, []);

  useEffect(() => {
    localStorage.setItem('lunchrun_active_runs', JSON.stringify(runs));
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(waitingOrders));
    localStorage.setItem('lunchrun_notifications', JSON.stringify(notifications));
    localStorage.setItem('lunchrun_history', JSON.stringify(history));
    localStorage.setItem('lunchrun_webhook', webhookUrl);
    localStorage.setItem('lunchrun_prefix', messagePrefix);
    localStorage.setItem('lunchrun_def_wait', defaultWait.toString());
    localStorage.setItem('lunchrun_def_max', defaultMax.toString());
  }, [runs, waitingOrders, notifications, history, webhookUrl, messagePrefix, defaultWait, defaultMax]);

  const sharedActions = {
    runs, setRuns,
    history, setHistory,
    waitingOrders, setWaitingOrders,
    notifications, setNotifications,
    webhookUrl, setWebhookUrl,
    messagePrefix, setMessagePrefix,
    defaultWait, setDefaultWait,
    defaultMax, setDefaultMax,
    isSimulatorAdmin
  };

  // Login Screen
  if (!user) {
    return (
      <div className="h-screen flex flex-col items-center justify-center p-8 bg-white">
        <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-3xl mb-6 shadow-xl shadow-indigo-100">
          <i className="fas fa-motorcycle"></i>
        </div>
        <h1 className="text-2xl font-black text-slate-800 tracking-tighter mb-8">LunchRun Access</h1>
        <form 
          onSubmit={(e) => { 
            e.preventDefault(); 
            setUser({ name: 'Member', email: `user@${ALLOWED_DOMAIN}`, isAdmin: false }); 
          }} 
          className="w-full max-w-xs space-y-4"
        >
          <input 
            required 
            type="email" 
            placeholder="Corporate Email" 
            className="w-full p-4 bg-slate-50 border-0 rounded-2xl font-bold placeholder:text-slate-400 focus:bg-slate-100 outline-none transition-all" 
          />
          <button 
            type="submit" 
            className="w-full h-14 bg-orange-600 hover:bg-orange-700 text-white font-black uppercase rounded-2xl shadow-xl shadow-orange-100 transition-all active:scale-95"
          >
            SIGN IN
          </button>
          <button 
            type="button" 
            onClick={() => setUser({ name: 'Admin', email: 'admin@system.local', isAdmin: true })} 
            className="w-full py-2 text-[9px] font-black text-slate-300 uppercase tracking-widest hover:text-slate-500 transition-colors"
          >
            ADMIN OVERRIDE
          </button>
        </form>
      </div>
    );
  }

  // Main App
  return (
    <div className={`min-h-screen transition-all duration-500 ${simulatorMode ? 'p-2 bg-slate-200' : 'bg-white'}`}>
      {/* Simulation Bar - ONLY FOR ADMINS */}
      {user.isAdmin && (
        <div className="bg-slate-900 text-white/70 px-6 py-2 flex justify-between items-center text-[10px] font-black uppercase tracking-[0.2em] shadow-xl sticky top-0 z-[100] rounded-b-xl sm:mx-4">
          <div className="flex items-center gap-4">
            <div className={`w-2 h-2 rounded-full animate-pulse ${isSimulatorAdmin ? 'bg-amber-400' : 'bg-indigo-400'}`}></div>
            <span>Admin Control Panel</span>
          </div>
          <div className="flex gap-4">
            <button 
              onClick={() => setIsSimulatorAdmin(!isSimulatorAdmin)} 
              className={`px-4 py-1.5 rounded-full border transition-all text-[9px] ${isSimulatorAdmin ? 'bg-amber-500 border-amber-400 text-slate-900' : 'border-slate-700 hover:text-white'}`}
            >
              {isSimulatorAdmin ? 'ADMIN OVERRIDE: ON' : 'ADMIN OVERRIDE: OFF'}
            </button>
            <button 
              onClick={() => setSimulatorMode(!simulatorMode)} 
              className="px-4 py-1.5 rounded-full border border-slate-700 hover:text-white text-[9px] transition-all"
            >
              {simulatorMode ? 'Exit Simulator' : 'Split-Screen Simulation'}
            </button>
          </div>
        </div>
      )}

      {simulatorMode && user.isAdmin ? (
        <div className="flex flex-col md:flex-row h-[calc(100vh-80px)] gap-4 mt-4 overflow-hidden">
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-indigo-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Persona: Runner</div>
             <AppInstance user={user} {...sharedActions} />
          </div>
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-emerald-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Persona: Orderer</div>
             <AppInstance user={{ name: 'Dana', email: `dana@${ALLOWED_DOMAIN}`, isAdmin: false }} {...sharedActions} />
          </div>
        </div>
      ) : (
        <div className="max-w-4xl mx-auto mt-6 px-4">
          <AppInstance user={user} {...sharedActions} />
        </div>
      )}
    </div>
  );
};

const AppInstance: React.FC<any> = ({ 
  user, 
  runs, setRuns, 
  history, setHistory, 
  waitingOrders, setWaitingOrders, 
  notifications, setNotifications,
  webhookUrl, setWebhookUrl,
  messagePrefix, setMessagePrefix,
  defaultWait, setDefaultWait,
  defaultMax, setDefaultMax,
  isSimulatorAdmin
}) => {
  const [testLoading, setTestLoading] = useState(false);
  const [modals, setModals] = useState<{ [key: string]: boolean | any }>({
    create: false, waitlist: false, join: null, cibus: null, arrive: null
  });
  const [inputs, setInputs] = useState({ dest: '', time: defaultWait, max: defaultMax, item: '', floor: '', cibus: '', loc: '' });

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const action = params.get('action');
    const runId = params.get('runId');

    if (runId && action === 'pay') {
      const run = runs.find((r: FoodRun) => r.id === runId);
      if (run) {
        const myOrder = run.orders.find((o: Order) => o.userEmail === user.email);
        if (myOrder) setModals(prev => ({ ...prev, cibus: { runId, orderId: myOrder.id } }));
      }
    } else if (runId && action === 'join') {
      setModals(prev => ({ ...prev, join: runId }));
    }
    if (action) window.history.replaceState({}, document.title, window.location.pathname);
  }, [user.email, runs.length]);

  const destinationSuggestions = useMemo(() => {
    const all = [...history, ...runs, ...waitingOrders].map(item => item.destination);
    return Array.from(new Set(all)).sort();
  }, [history, runs, waitingOrders]);

  const actions = {
    createRun: (e: React.FormEvent) => {
      e.preventDefault();
      const normDest = normalizeBusinessName(inputs.dest);
      const matches = waitingOrders.filter(wo => normalizeBusinessName(wo.destination) === normDest);
      const ordersToPull = matches.slice(0, inputs.max);

      const orders: Order[] = ordersToPull.map(wo => ({ id: wo.id, userName: wo.userName, userEmail: wo.userEmail, itemDescription: wo.itemDescription, floor: wo.floor, cibusCode: '', timestamp: Date.now() }));

      const newRun: FoodRun = {
        id: Math.random().toString(36).substr(2, 9), runnerName: user.name, runnerEmail: user.email,
        destination: inputs.dest, departureTime: Date.now() + inputs.time * 60000, minutesUntilDeparture: inputs.time,
        maxOrders: inputs.max, status: 'active', orders
      };

      setWaitingOrders((prev: any) => prev.filter((wo: any) => !ordersToPull.some(o => o.id === wo.id)));
      setRuns((prev: any) => [newRun, ...prev]);
      setModals({ ...modals, create: false });

      const baseUrl = window.location.href.split('?')[0];
      sendToGoogleChat(webhookUrl, {
        title: "New Run Started",
        subtitle: inputs.dest,
        details: `Departing in ${inputs.time} mins. Runner: ${user.name}.`,
        buttons: [
          { text: "Join via App", url: `${baseUrl}?action=join&runId=${newRun.id}` },
          { text: "Send DM to Runner", url: `https://mail.google.com/chat/u/0/#chat/dm/${user.email}` }
        ],
        prefix: messagePrefix
      });
    },
    depart: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, status: 'departed' } : r));

      const baseUrl = window.location.href.split('?')[0];
      sendToGoogleChat(webhookUrl, {
        title: "Departure Alert",
        subtitle: run.destination,
        details: "The runner is leaving. Please enter your Cibus payment code.",
        buttons: [
          { text: "Enter Code", url: `${baseUrl}?action=pay&runId=${runId}` },
          { text: "Message Runner", url: `https://mail.google.com/chat/u/0/#chat/dm/${run.runnerEmail}` }
        ],
        prefix: messagePrefix
      });
    },
    arrive: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      sendToGoogleChat(webhookUrl, {
        title: "Food is Here!",
        subtitle: `Pickup: ${inputs.loc}`,
        details: `Order from ${run.destination} has arrived. Enjoy!`,
        prefix: messagePrefix
      });
      setHistory((prev: any) => [{ ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() }, ...prev]);
      setRuns(runs.filter((r: any) => r.id !== runId));
      setModals({ ...modals, arrive: null });
    },
    join: (runId: string) => {
      const order: Order = { id: Math.random().toString(36).substr(2, 9), userName: user.name, userEmail: user.email, itemDescription: inputs.item, floor: inputs.floor, cibusCode: '', timestamp: Date.now() };
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: [...r.orders, order] } : r));
      setModals({ ...modals, join: null });
    }
  };

  const isAdmin = user.isAdmin || isSimulatorAdmin;

  return (
    <div className="h-full flex flex-col bg-slate-50 relative">
      <datalist id="dest-options">
        {destinationSuggestions.map(d => <option key={d} value={d} />)}
      </datalist>

      <header className={`px-6 py-4 flex justify-between items-center border-b ${isAdmin ? 'bg-amber-50 border-amber-100' : 'bg-white border-slate-100'}`}>
        <div className="flex items-center gap-3">
           <div className={`w-9 h-9 rounded-xl flex items-center justify-center text-white text-lg shadow-lg ${isAdmin ? 'bg-amber-500' : 'bg-indigo-600'}`}>
             <i className={`fas ${isAdmin ? 'fa-user-shield' : 'fa-hamburger'}`}></i>
           </div>
           <div>
             <span className="font-black text-sm text-slate-800 tracking-tight">LUNCHRUN</span>
             <span className="text-[8px] font-black text-slate-400 uppercase block tracking-widest">{user.email}</span>
           </div>
        </div>
        <img src={`https://ui-avatars.com/api/?name=${user.name}&background=${isAdmin ? 'f59e0b' : '6366f1'}&color=fff`} className="w-9 h-9 rounded-2xl border-2 border-white shadow-sm" alt="u" />
      </header>

      <main className="flex-1 overflow-y-auto p-4 space-y-4 pb-24">
        {isAdmin && (
          <div className="bg-slate-900 rounded-[2rem] p-6 text-white shadow-2xl border-4 border-amber-500/20">
             <h3 className="text-amber-400 text-[10px] font-black uppercase tracking-widest mb-4">Admin Webhook Config</h3>
             <div className="flex gap-2">
                <input className="flex-1 p-3 bg-white/5 border border-white/10 rounded-2xl font-bold text-xs outline-none" value={webhookUrl} onChange={e => setWebhookUrl(e.target.value)} placeholder="Google Chat Webhook URL" />
                <Button onClick={async () => { setTestLoading(true); const ok = await sendToGoogleChat(webhookUrl, { title: "Test", subtitle: "Live", details: "Communication test successful.", prefix: messagePrefix }); setTestLoading(false); alert(ok ? "Sent" : "Failed"); }} isLoading={testLoading} className="h-10 px-4 bg-amber-500 text-slate-900 text-[10px] uppercase font-black">Test</Button>
             </div>
          </div>
        )}

        <div className="flex justify-between items-center bg-white p-3 rounded-2xl border border-slate-100 shadow-sm">
           <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-2">Active Runs</span>
           <div className="flex gap-2">
              <Button onClick={() => setModals({...modals, waitlist: true})} variant="ghost" className="h-9 px-4 text-[10px] font-black uppercase rounded-xl border border-slate-100">Waitlist</Button>
              <Button onClick={() => setModals({...modals, create: true})} className="h-9 px-4 text-[10px] font-black uppercase rounded-xl bg-indigo-600 shadow-lg">Start Run</Button>
           </div>
        </div>

        <div className="space-y-4">
           {runs.length === 0 ? (
             <div className="py-20 text-center opacity-20">
               <i className="fas fa-ghost text-4xl mb-4"></i>
               <p className="text-xs font-black uppercase tracking-widest">No active runs nearby</p>
             </div>
           ) : runs.map((run: FoodRun) => {
             const isRunner = user.email === run.runnerEmail;
             const myOrder = run.orders.find(o => o.userEmail === user.email);
             return (
               <div key={run.id} className={`bg-white rounded-[2rem] p-6 shadow-xl border-2 transition-all ${run.status === 'departed' ? 'border-indigo-500' : 'border-white'}`}>
                  <div className="flex justify-between items-start mb-6">
                     <div className="flex gap-4">
                        <div className="w-14 h-14 rounded-2xl bg-slate-50 flex items-center justify-center text-2xl text-slate-300 shadow-inner">
                           <i className={`fas ${run.status === 'departed' ? 'fa-motorcycle text-indigo-500' : 'fa-pizza-slice'}`}></i>
                        </div>
                        <div>
                           <h4 className="text-xl font-black text-slate-800 tracking-tight">{run.destination}</h4>
                           <div className="flex items-center gap-2 mt-1">
                              <span className={`text-[9px] font-black px-2 py-0.5 rounded-full ${run.status === 'departed' ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-100 text-slate-400'}`}>{run.status.toUpperCase()}</span>
                              <span className="text-[10px] font-bold text-slate-400">Runner: {run.runnerName}</span>
                           </div>
                        </div>
                     </div>
                  </div>

                  {run.orders.length > 0 && (
                     <div className="space-y-2 mb-6">
                        {run.orders.map(o => (
                           <div key={o.id} className={`flex justify-between items-center p-3 rounded-2xl text-xs border ${o.userEmail === user.email ? 'bg-indigo-50 border-indigo-200 shadow-sm' : 'bg-slate-50 border-slate-100'}`}>
                              <span className="font-bold text-slate-700">{o.userName}: <span className="font-normal text-slate-500 italic">"{o.itemDescription}"</span></span>
                              {o.userEmail === user.email && run.status === 'departed' && !o.cibusCode && (
                                 <button onClick={() => setModals({...modals, cibus: {runId: run.id, orderId: o.id}})} className="bg-indigo-600 text-white px-3 py-1 rounded-lg text-[9px] font-black uppercase shadow-lg shadow-indigo-100">Send Code</button>
                              )}
                              {o.cibusCode && <span className="text-[9px] font-black text-emerald-600"><i className="fas fa-check-circle"></i> {o.cibusCode}</span>}
                           </div>
                        ))}
                     </div>
                  )}

                  <div className="flex gap-3">
                     {isRunner ? (
                        run.status === 'active' ? (
                           <Button onClick={() => actions.depart(run.id)} className="flex-1 h-12 bg-indigo-600 text-[10px] font-black uppercase rounded-xl">Broadcast Departure</Button>
                        ) : (
                           <Button onClick={() => setModals({...modals, arrive: run.id})} className="flex-1 h-12 bg-emerald-600 text-[10px] font-black uppercase rounded-xl">Broadcast Arrival</Button>
                        )
                     ) : !myOrder && run.status === 'active' && (
                        <Button onClick={() => setModals({...modals, join: run.id})} className="flex-1 h-12 bg-slate-800 text-[10px] font-black uppercase rounded-xl">Join Run</Button>
                     )}
                     {myOrder && <div className="flex-1 text-center py-4 text-[10px] font-black uppercase text-indigo-400 tracking-widest"><i className="fas fa-check-circle mr-2"></i> Manifested</div>}
                  </div>
               </div>
             );
           })}
        </div>
      </main>

      {/* OVERLAYS */}
      {modals.create && (
        <Overlay title="New Food Run" onClose={() => setModals({...modals, create: false})}>
           <form onSubmit={actions.createRun} className="space-y-4">
              <input required list="dest-options" className="w-full p-4 bg-slate-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-indigo-500" placeholder="Destination (e.g. Hummus)" value={inputs.dest} onChange={e => setInputs({...inputs, dest: e.target.value})} />
              <div className="grid grid-cols-2 gap-4">
                 <input required type="number" className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Wait (m)" value={inputs.time} onChange={e => setInputs({...inputs, time: Number(e.target.value)})} />
                 <input required type="number" className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Max Spots" value={inputs.max} onChange={e => setInputs({...inputs, max: Number(e.target.value)})} />
              </div>
              <Button type="submit" className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl shadow-xl">Launch Run</Button>
           </form>
        </Overlay>
      )}

      {modals.join && (
        <Overlay title="Join the Run" onClose={() => setModals({...modals, join: null})}>
           <form onSubmit={(e) => { e.preventDefault(); actions.join(modals.join); }} className="space-y-4">
              <input required className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Item (e.g. Salad)" value={inputs.item} onChange={e => setInputs({...inputs, item: e.target.value})} />
              <input required className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Floor #" value={inputs.floor} onChange={e => setInputs({...inputs, floor: e.target.value})} />
              <Button type="submit" className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl shadow-xl">Confirm Join</Button>
           </form>
        </Overlay>
      )}

      {modals.cibus && (
        <Overlay title="Cibus Payment" onClose={() => setModals({...modals, cibus: null})}>
           <div className="space-y-4">
              <p className="text-[10px] text-center text-slate-400 font-bold uppercase mb-2 tracking-widest">Enter 6-digit code for the runner</p>
              <input required autoFocus className="w-full p-6 bg-slate-50 rounded-[2rem] font-black text-center text-3xl tracking-[0.2em] border-4 border-indigo-100 outline-none focus:border-indigo-600" placeholder="000000" maxLength={6} value={inputs.cibus} onChange={e => setInputs({...inputs, cibus: e.target.value})} />
              <Button onClick={() => {
                  const { runId, orderId } = modals.cibus;
                  setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: r.orders.map((o: any) => o.id === orderId ? { ...o, cibusCode: inputs.cibus } : o) } : r));
                  setModals({...modals, cibus: null});
                  setInputs({...inputs, cibus: ''});
                }} className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl shadow-xl">Confirm Code</Button>
           </div>
        </Overlay>
      )}

      {modals.arrive && (
        <Overlay title="Food Arrival" onClose={() => setModals({...modals, arrive: null})}>
           <form onSubmit={(e) => { e.preventDefault(); actions.arrive(modals.arrive); }} className="space-y-4">
              <input required autoFocus className="w-full p-4 bg-slate-50 rounded-2xl font-bold text-center" placeholder="Where to pick up?" value={inputs.loc} onChange={e => setInputs({...inputs, loc: e.target.value})} />
              <Button type="submit" className="w-full h-14 bg-emerald-600 font-black uppercase text-[11px] rounded-2xl shadow-xl">Broadcast Arrival</Button>
           </form>
        </Overlay>
      )}

      {modals.waitlist && (
        <Overlay title="Global Waitlist" onClose={() => setModals({...modals, waitlist: false})}>
           <div className="space-y-3 max-h-[350px] overflow-y-auto pr-2">
              {waitingOrders.length === 0 ? (
                <div className="text-center py-10 opacity-30 text-[10px] font-black uppercase tracking-widest">Waitlist Empty</div>
              ) : (
                waitingOrders.map((wo: any) => (
                  <div key={wo.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex justify-between items-center">
                    <div>
                      <p className="font-black text-slate-800 text-xs">{wo.destination}</p>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">{wo.userName} • {wo.itemDescription}</p>
                    </div>
                    <span className="text-[9px] font-black bg-white px-2 py-0.5 rounded-full border shadow-sm">FL {wo.floor}</span>
                  </div>
                ))
              )}
           </div>
        </Overlay>
      )}
    </div>
  );
};

const Overlay: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
  <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[300] flex items-center justify-center p-6">
    <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-[340px] shadow-[0_20px_50px_rgba(0,0,0,0.3)] animate-in zoom-in-95 duration-300 relative border border-slate-100">
      <div className="flex justify-between items-center mb-8">
         <h3 className="text-[11px] font-black uppercase tracking-[0.2em] text-indigo-600">{title}</h3>
         <button onClick={onClose} className="w-9 h-9 rounded-full bg-slate-50 text-slate-300 hover:text-slate-600 transition-colors flex items-center justify-center"><i className="fas fa-times"></i></button>
      </div>
      {children}
    </div>
  </div>
);

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { FoodRun, Order, WaitingOrder, UserNotification } from './types';
import { Button } from './components/Button';
import { sendToGoogleChat } from './services/googleChatService';

/**
 * Extracts a clean name from an email address.
 * Example: avi.cohen@naturalint.com -> Avi Cohen
 */
const extractNameFromEmail = (email: string): string => {
  if (!email) return 'User';
  const namePart = email.split('@')[0];
  return namePart
    .split(/[._-]/)
    .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(' ');
};

const normalizeBusinessName = (name: string): string => {
  return name.trim().toLowerCase()
    .replace(/\s+/g, '')
    .replace(/[-_]/g, '')
    .replace(/^ה/g, '');
};

const App: React.FC = () => {
  const [user, setUser] = useState<{ name: string; email: string; isAdmin?: boolean } | null>(null);
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [notifications, setNotifications] = useState<UserNotification[]>([]);
  const [simulatorMode, setSimulatorMode] = useState(false);
  const [webhookUrl, setWebhookUrl] = useState<string>(localStorage.getItem('lunchrun_webhook') || '');
  const [messagePrefix, setMessagePrefix] = useState<string>(localStorage.getItem('lunchrun_prefix') || '[LunchRun]');
  const [defaultWait, setDefaultWait] = useState<number>(Number(localStorage.getItem('lunchrun_def_wait')) || 20);
  const [defaultMax, setDefaultMax] = useState<number>(Number(localStorage.getItem('lunchrun_def_max')) || 5);
  const [isSimulatorAdmin, setIsSimulatorAdmin] = useState(false);

  useEffect(() => {
    const saved = {
      history: localStorage.getItem('lunchrun_history'),
      waitlist: localStorage.getItem('lunchrun_waitlist'),
      notifs: localStorage.getItem('lunchrun_notifications'),
      runs: localStorage.getItem('lunchrun_active_runs')
    };
    if (saved.history) setHistory(JSON.parse(saved.history));
    if (saved.waitlist) setWaitingOrders(JSON.parse(saved.waitlist));
    if (saved.notifs) setNotifications(JSON.parse(saved.notifs));
    if (saved.runs) setRuns(JSON.parse(saved.runs));
  }, []);

  useEffect(() => {
    localStorage.setItem('lunchrun_active_runs', JSON.stringify(runs));
    localStorage.setItem('lunchrun_waitlist', JSON.stringify(waitingOrders));
    localStorage.setItem('lunchrun_notifications', JSON.stringify(notifications));
    localStorage.setItem('lunchrun_history', JSON.stringify(history));
    localStorage.setItem('lunchrun_webhook', webhookUrl);
    localStorage.setItem('lunchrun_prefix', messagePrefix);
    localStorage.setItem('lunchrun_def_wait', defaultWait.toString());
    localStorage.setItem('lunchrun_def_max', defaultMax.toString());
  }, [runs, waitingOrders, notifications, history, webhookUrl, messagePrefix, defaultWait, defaultMax]);

  const sharedActions = {
    runs, setRuns,
    history, setHistory,
    waitingOrders, setWaitingOrders,
    notifications, setNotifications,
    webhookUrl, setWebhookUrl,
    messagePrefix, setMessagePrefix,
    defaultWait, setDefaultWait,
    defaultMax, setDefaultMax,
    isSimulatorAdmin
  };

  const handleLogin = (email: string) => {
    const name = extractNameFromEmail(email);
    setUser({ name, email, isAdmin: false });
  };

  // Login Screen
  if (!user) {
    return (
      <div className="h-screen flex flex-col items-center justify-center p-8 bg-white">
        <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-3xl mb-6 shadow-xl shadow-indigo-100">
          <i className="fas fa-motorcycle"></i>
        </div>
        <h1 className="text-2xl font-black text-slate-800 tracking-tighter mb-8">LunchRun Access</h1>
        <form 
          onSubmit={(e) => { 
            e.preventDefault(); 
            const email = (e.currentTarget.elements[0] as HTMLInputElement).value;
            handleLogin(email);
          }} 
          className="w-full max-w-xs space-y-4"
        >
          <input 
            required 
            type="email" 
            placeholder="Corporate Email" 
            className="w-full p-4 bg-slate-50 border-0 rounded-2xl font-bold placeholder:text-slate-400 focus:bg-slate-100 outline-none transition-all" 
          />
          <button 
            type="submit" 
            className="w-full h-14 bg-orange-600 hover:bg-orange-700 text-white font-black uppercase rounded-2xl shadow-xl shadow-orange-100 transition-all active:scale-95"
          >
            SIGN IN
          </button>
          <button 
            type="button" 
            onClick={() => setUser({ name: 'System Admin', email: 'admin@system.local', isAdmin: true })} 
            className="w-full py-2 text-[9px] font-black text-slate-300 uppercase tracking-widest hover:text-slate-500 transition-colors"
          >
            ADMIN OVERRIDE
          </button>
        </form>
      </div>
    );
  }

  // Main App
  return (
    <div className={`min-h-screen transition-all duration-500 ${simulatorMode ? 'p-2 bg-slate-200' : 'bg-white'}`}>
      {/* Simulation Bar - ONLY FOR ADMINS */}
      {user.isAdmin && (
        <div className="bg-slate-900 text-white/70 px-6 py-2 flex justify-between items-center text-[10px] font-black uppercase tracking-[0.2em] shadow-xl sticky top-0 z-[100] rounded-b-xl sm:mx-4">
          <div className="flex items-center gap-4">
            <div className={`w-2 h-2 rounded-full animate-pulse ${isSimulatorAdmin ? 'bg-amber-400' : 'bg-indigo-400'}`}></div>
            <span>Admin Control Panel</span>
          </div>
          <div className="flex gap-4">
            <button 
              onClick={() => setIsSimulatorAdmin(!isSimulatorAdmin)} 
              className={`px-4 py-1.5 rounded-full border transition-all text-[9px] ${isSimulatorAdmin ? 'bg-amber-500 border-amber-400 text-slate-900' : 'border-slate-700 hover:text-white'}`}
            >
              {isSimulatorAdmin ? 'ADMIN OVERRIDE: ON' : 'ADMIN OVERRIDE: OFF'}
            </button>
            <button 
              onClick={() => setSimulatorMode(!simulatorMode)} 
              className="px-4 py-1.5 rounded-full border border-slate-700 hover:text-white text-[9px] transition-all"
            >
              {simulatorMode ? 'Exit Simulator' : 'Split-Screen Simulation'}
            </button>
          </div>
        </div>
      )}

      {simulatorMode && user.isAdmin ? (
        <div className="flex flex-col md:flex-row h-[calc(100vh-80px)] gap-4 mt-4 overflow-hidden">
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-indigo-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Persona: Runner</div>
             <AppInstance user={user} {...sharedActions} />
          </div>
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-emerald-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Persona: Orderer</div>
             <AppInstance user={{ name: 'Dana Kaplan', email: `dana@naturalint.com`, isAdmin: false }} {...sharedActions} />
          </div>
        </div>
      ) : (
        <div className="max-w-4xl mx-auto px-4 py-6">
          <AppInstance user={user} {...sharedActions} />
        </div>
      )}
    </div>
  );
};

const AppInstance: React.FC<any> = ({ 
  user, 
  runs, setRuns, 
  history, setHistory, 
  waitingOrders, setWaitingOrders, 
  notifications, setNotifications,
  webhookUrl, setWebhookUrl,
  messagePrefix, setMessagePrefix,
  defaultWait, setDefaultWait,
  defaultMax, setDefaultMax,
  isSimulatorAdmin
}) => {
  const [testLoading, setTestLoading] = useState(false);
  const [modals, setModals] = useState<{ [key: string]: boolean | any }>({
    create: false, waitlist: false, join: null, cibus: null, arrive: null
  });
  const [inputs, setInputs] = useState({ dest: '', time: defaultWait, max: defaultMax, item: '', floor: '', cibus: '', loc: '' });

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const action = params.get('action');
    const runId = params.get('runId');

    if (runId && action === 'pay') {
      const run = runs.find((r: FoodRun) => r.id === runId);
      if (run) {
        const myOrder = run.orders.find((o: Order) => o.userEmail === user.email);
        if (myOrder) setModals(prev => ({ ...prev, cibus: { runId, orderId: myOrder.id } }));
      }
    } else if (runId && action === 'join') {
      setModals(prev => ({ ...prev, join: runId }));
    }
    if (action) window.history.replaceState({}, document.title, window.location.pathname);
  }, [user.email, runs.length]);

  const destinationSuggestions = useMemo(() => {
    const all = [...history, ...runs, ...waitingOrders].map(item => item.destination);
    return Array.from(new Set(all)).sort();
  }, [history, runs, waitingOrders]);

  const actions = {
    createRun: (e: React.FormEvent) => {
      e.preventDefault();
      const normDest = normalizeBusinessName(inputs.dest);
      const matches = waitingOrders.filter(wo => normalizeBusinessName(wo.destination) === normDest);
      const ordersToPull = matches.slice(0, inputs.max);

      const orders: Order[] = ordersToPull.map(wo => ({ id: wo.id, userName: wo.userName, userEmail: wo.userEmail, itemDescription: wo.itemDescription, floor: wo.floor, cibusCode: '', timestamp: Date.now() }));

      const newRun: FoodRun = {
        id: Math.random().toString(36).substr(2, 9), runnerName: user.name, runnerEmail: user.email,
        destination: inputs.dest, departureTime: Date.now() + inputs.time * 60000, minutesUntilDeparture: inputs.time,
        maxOrders: inputs.max, status: 'active', orders
      };

      setWaitingOrders((prev: any) => prev.filter((wo: any) => !ordersToPull.some(o => o.id === wo.id)));
      setRuns((prev: any) => [newRun, ...prev]);
      setModals({ ...modals, create: false });

      const baseUrl = window.location.href.split('?')[0];
      sendToGoogleChat(webhookUrl, {
        title: "New Run Started",
        subtitle: inputs.dest,
        details: `Departing in ${inputs.time} mins. Runner: ${user.name}.`,
        buttons: [
          { text: "Join via App", url: `${baseUrl}?action=join&runId=${newRun.id}` },
          { text: "Send DM to Runner", url: `https://mail.google.com/chat/u/0/#chat/dm/${user.email}` }
        ],
        prefix: messagePrefix
      });
    },
    depart: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, status: 'departed' } : r));

      const baseUrl = window.location.href.split('?')[0];
      sendToGoogleChat(webhookUrl, {
        title: "Departure Alert",
        subtitle: run.destination,
        details: "The runner is leaving. Please enter your Cibus payment code.",
        buttons: [
          { text: "Enter Code", url: `${baseUrl}?action=pay&runId=${runId}` },
          { text: "Message Runner", url: `https://mail.google.com/chat/u/0/#chat/dm/${run.runnerEmail}` }
        ],
        prefix: messagePrefix
      });
    },
    arrive: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      sendToGoogleChat(webhookUrl, {
        title: "Food is Here!",
        subtitle: `Pickup: ${inputs.loc}`,
        details: `Order from ${run.destination} has arrived. Enjoy!`,
        prefix: messagePrefix
      });
      setHistory((prev: any) => [{ ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() }, ...prev]);
      setRuns(runs.filter((r: any) => r.id !== runId));
      setModals({ ...modals, arrive: null });
    },
    join: (runId: string) => {
      const order: Order = { id: Math.random().toString(36).substr(2, 9), userName: user.name, userEmail: user.email, itemDescription: inputs.item, floor: inputs.floor, cibusCode: '', timestamp: Date.now() };
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: [...r.orders, order] } : r));
      setModals({ ...modals, join: null });
    }
  };

  const isAdmin = user.isAdmin || isSimulatorAdmin;

  return (
    <div className="h-full flex flex-col bg-white relative">
      <datalist id="dest-options">
        {destinationSuggestions.map(d => <option key={d} value={d} />)}
      </datalist>

      {/* HEADER - Updated to show Name and Email as requested */}
      <header className="flex justify-between items-center mb-10">
        <div className="flex items-center gap-4">
           <div className={`w-11 h-11 rounded-2xl flex items-center justify-center text-white text-xl shadow-lg ${isAdmin ? 'bg-amber-500' : 'bg-indigo-600'}`}>
             <i className={`fas ${isAdmin ? 'fa-user-shield' : 'fa-hamburger'}`}></i>
           </div>
           <div className="flex flex-col">
             <span className="font-black text-lg text-slate-900 leading-none tracking-tighter uppercase">{user.name}</span>
             <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">{user.email}</span>
           </div>
        </div>
        <div className="w-10 h-10 rounded-full bg-slate-50 border border-slate-100 flex items-center justify-center text-slate-200">
          <i className="fas fa-user"></i>
        </div>
      </header>

      <main className="space-y-6 pb-24">
        {isAdmin && (
          <div className="bg-slate-900 rounded-[2rem] p-6 text-white shadow-2xl border-4 border-amber-500/20">
             <h3 className="text-amber-400 text-[10px] font-black uppercase tracking-widest mb-4">Admin Hub</h3>
             <div className="flex gap-2">
                <input className="flex-1 p-3 bg-white/5 border border-white/10 rounded-2xl font-bold text-xs outline-none" value={webhookUrl} onChange={e => setWebhookUrl(e.target.value)} placeholder="Webhook URL" />
                <Button onClick={async () => { setTestLoading(true); const ok = await sendToGoogleChat(webhookUrl, { title: "Test", subtitle: "Live", details: "Communication test successful.", prefix: messagePrefix }); setTestLoading(false); alert(ok ? "Sent" : "Failed"); }} isLoading={testLoading} className="h-10 px-4 bg-amber-500 text-slate-900 text-[10px] uppercase font-black">Test</Button>
             </div>
          </div>
        )}

        <div className="bg-slate-50 p-2 rounded-2xl flex justify-between items-center border border-slate-100 shadow-sm">
           <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-4">Active Operations</span>
           <div className="flex gap-2">
              <Button onClick={() => setModals({...modals, waitlist: true})} variant="ghost" className="h-10 px-4 text-[10px] font-black uppercase rounded-xl border-slate-200 bg-white">Waitlist</Button>
              <Button onClick={() => setModals({...modals, create: true})} className="h-10 px-6 text-[10px] font-black uppercase rounded-xl bg-orange-600 shadow-lg shadow-orange-100">Start Run</Button>
           </div>
        </div>

        <div className="space-y-4">
           {runs.length === 0 ? (
             <div className="py-24 text-center">
               <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-6 text-slate-200">
                 <i className="fas fa-ghost text-3xl"></i>
               </div>
               <p className="text-[10px] font-black text-slate-300 uppercase tracking-[0.2em]">No active runs nearby</p>
             </div>
           ) : runs.map((run: FoodRun) => {
             const isRunner = user.email === run.runnerEmail;
             const myOrder = run.orders.find(o => o.userEmail === user.email);
             return (
               <div key={run.id} className={`bg-white rounded-[2.5rem] p-7 shadow-xl border-2 transition-all ${run.status === 'departed' ? 'border-indigo-500' : 'border-slate-100'}`}>
                  <div className="flex justify-between items-start mb-6">
                     <div className="flex gap-4">
                        <div className="w-14 h-14 rounded-2xl bg-slate-50 flex items-center justify-center text-2xl text-slate-300">
                           <i className={`fas ${run.status === 'departed' ? 'fa-motorcycle text-indigo-500' : 'fa-pizza-slice'}`}></i>
                        </div>
                        <div>
                           <h4 className="text-xl font-black text-slate-800 tracking-tight">{run.destination}</h4>
                           <div className="flex items-center gap-2 mt-1">
                              <span className={`text-[9px] font-black px-2 py-0.5 rounded-full ${run.status === 'departed' ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-100 text-slate-400'}`}>{run.status.toUpperCase()}</span>
                              <span className="text-[10px] font-bold text-slate-400">{run.runnerName}</span>
                           </div>
                        </div>
                     </div>
                  </div>

                  {run.orders.length > 0 && (
                     <div className="space-y-2 mb-6">
                        {run.orders.map(o => (
                           <div key={o.id} className={`flex justify-between items-center p-3 rounded-2xl text-xs border ${o.userEmail === user.email ? 'bg-indigo-50 border-indigo-200' : 'bg-slate-50 border-slate-100'}`}>
                              <span className="font-bold text-slate-700">{o.userName}: <span className="font-normal text-slate-500 italic">"{o.itemDescription}"</span></span>
                              {o.userEmail === user.email && run.status === 'departed' && !o.cibusCode && (
                                 <button onClick={() => setModals({...modals, cibus: {runId: run.id, orderId: o.id}})} className="bg-indigo-600 text-white px-3 py-1 rounded-lg text-[9px] font-black uppercase shadow-lg">Submit Code</button>
                              )}
                              {o.cibusCode && <span className="text-[9px] font-black text-emerald-600"><i className="fas fa-check-circle mr-1"></i> {o.cibusCode}</span>}
                           </div>
                        ))}
                     </div>
                  )}

                  <div className="flex gap-3">
                     {isRunner ? (
                        run.status === 'active' ? (
                           <Button onClick={() => actions.depart(run.id)} className="flex-1 h-12 bg-indigo-600 text-[10px] font-black uppercase rounded-xl">Broadcast Departure</Button>
                        ) : (
                           <Button onClick={() => setModals({...modals, arrive: run.id})} className="flex-1 h-12 bg-emerald-600 text-[10px] font-black uppercase rounded-xl">Signal Arrival</Button>
                        )
                     ) : !myOrder && run.status === 'active' && (
                        <Button onClick={() => setModals({...modals, join: run.id})} className="flex-1 h-12 bg-slate-800 text-[10px] font-black uppercase rounded-xl">Join Run</Button>
                     )}
                     {myOrder && <div className="flex-1 text-center py-4 text-[10px] font-black uppercase text-indigo-400 tracking-widest"><i className="fas fa-check-circle mr-2"></i> Manifested</div>}
                  </div>
               </div>
             );
           })}
        </div>
      </main>

      {/* OVERLAYS */}
      {modals.create && (
        <Overlay title="New Mission" onClose={() => setModals({...modals, create: false})}>
           <form onSubmit={actions.createRun} className="space-y-4">
              <input required list="dest-options" className="w-full p-4 bg-slate-50 rounded-2xl font-bold border-2 border-transparent focus:border-indigo-600 outline-none transition-all" placeholder="Destination" value={inputs.dest} onChange={e => setInputs({...inputs, dest: e.target.value})} />
              <div className="grid grid-cols-2 gap-4">
                 <input required type="number" className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Wait (m)" value={inputs.time} onChange={e => setInputs({...inputs, time: Number(e.target.value)})} />
                 <input required type="number" className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Max" value={inputs.max} onChange={e => setInputs({...inputs, max: Number(e.target.value)})} />
              </div>
              <Button type="submit" className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl">Launch Run</Button>
           </form>
        </Overlay>
      )}

      {modals.join && (
        <Overlay title="Manifest Entry" onClose={() => setModals({...modals, join: null})}>
           <form onSubmit={(e) => { e.preventDefault(); actions.join(modals.join); }} className="space-y-4">
              <input required className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Item Details" value={inputs.item} onChange={e => setInputs({...inputs, item: e.target.value})} />
              <input required className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="Floor" value={inputs.floor} onChange={e => setInputs({...inputs, floor: e.target.value})} />
              <Button type="submit" className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl">Confirm Join</Button>
           </form>
        </Overlay>
      )}

      {modals.cibus && (
        <Overlay title="Payment Code" onClose={() => setModals({...modals, cibus: null})}>
           <div className="space-y-4">
              <input required autoFocus className="w-full p-6 bg-slate-50 rounded-[2rem] font-black text-center text-3xl tracking-[0.2em] border-4 border-indigo-100 outline-none focus:border-indigo-600 transition-all" placeholder="000000" maxLength={6} value={inputs.cibus} onChange={e => setInputs({...inputs, cibus: e.target.value})} />
              <Button onClick={() => {
                  const { runId, orderId } = modals.cibus;
                  setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: r.orders.map((o: any) => o.id === orderId ? { ...o, cibusCode: inputs.cibus } : o) } : r));
                  setModals({...modals, cibus: null});
                  setInputs({...inputs, cibus: ''});
                }} className="w-full h-14 bg-indigo-600 font-black uppercase text-[11px] rounded-2xl">Confirm Code</Button>
           </div>
        </Overlay>
      )}

      {modals.arrive && (
        <Overlay title="Arrival Point" onClose={() => setModals({...modals, arrive: null})}>
           <form onSubmit={(e) => { e.preventDefault(); actions.arrive(modals.arrive); }} className="space-y-4">
              <input required autoFocus className="w-full p-4 bg-slate-50 rounded-2xl font-bold text-center" placeholder="Drop-off Location" value={inputs.loc} onChange={e => setInputs({...inputs, loc: e.target.value})} />
              <Button type="submit" className="w-full h-14 bg-emerald-600 font-black uppercase text-[11px] rounded-2xl">Signal Arrival</Button>
           </form>
        </Overlay>
      )}

      {modals.waitlist && (
        <Overlay title="Sector Waitlist" onClose={() => setModals({...modals, waitlist: false})}>
           <div className="space-y-3 max-h-[350px] overflow-y-auto pr-2">
              {waitingOrders.length === 0 ? (
                <div className="text-center py-10 opacity-30 text-[10px] font-black uppercase tracking-widest">Waitlist Empty</div>
              ) : (
                waitingOrders.map((wo: any) => (
                  <div key={wo.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex justify-between items-center">
                    <div>
                      <p className="font-black text-slate-800 text-xs">{wo.destination}</p>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">{wo.userName} • {wo.itemDescription}</p>
                    </div>
                    <span className="text-[9px] font-black bg-white px-2 py-0.5 rounded-full border shadow-sm">FL {wo.floor}</span>
                  </div>
                ))
              )}
           </div>
        </Overlay>
      )}
    </div>
  );
};

const Overlay: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
  <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-[300] flex items-center justify-center p-6">
    <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-[340px] shadow-[0_20px_50px_rgba(0,0,0,0.3)] animate-in zoom-in-95 duration-300 relative border border-slate-100">
      <div className="flex justify-between items-center mb-8">
         <h3 className="text-[11px] font-black uppercase tracking-[0.2em] text-indigo-600">{title}</h3>
         <button onClick={onClose} className="w-9 h-9 rounded-full bg-slate-50 text-slate-300 hover:text-slate-600 transition-colors flex items-center justify-center"><i className="fas fa-times"></i></button>
      </div>
      {children}
    </div>
  </div>
);

export default App;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { FoodRun, Order, WaitingOrder, UserNotification } from './types';
import { Button } from './components/Button';
import { sendToGoogleChat } from './services/googleChatService';

// Initialize a broadcast channel for "Live" feel between tabs on the same machine
const syncChannel = new BroadcastChannel('lunchrun_sync');

const CORPORATE_DOMAINS = ['naturalint.com', 'cappsool.com', 'bimprssion.com'];

/**
 * Extracts a clean name from an email address.
 * Example: avi.cohen@naturalint.com -> Avi Cohen
 */
const extractNameFromEmail = (email: string): string => {
  if (!email) return 'User';
  const namePart = email.split('@')[0];
  return namePart
    .split(/[._-]/)
    .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(' ');
};

const normalizeBusinessName = (name: string): string => {
  return name.trim().toLowerCase()
    .replace(/\s+/g, '')
    .replace(/[-_]/g, '')
    .replace(/^ה/g, '');
};

const App: React.FC = () => {
  const [user, setUser] = useState<{ name: string; email: string; isAdmin?: boolean } | null>(null);
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [simulatorMode, setSimulatorMode] = useState(false);
  const [isSimulatorAdmin, setIsSimulatorAdmin] = useState(false);
  const [webhookUrl, setWebhookUrl] = useState<string>(localStorage.getItem('lunchrun_webhook') || '');
  const [messagePrefix, setMessagePrefix] = useState<string>(localStorage.getItem('lunchrun_prefix') || '[LunchRun]');
  const [defaultWait, setDefaultWait] = useState<number>(Number(localStorage.getItem('lunchrun_def_wait')) || 20);
  const [defaultMax, setDefaultMax] = useState<number>(Number(localStorage.getItem('lunchrun_def_max')) || 5);

  // Load initial state
  useEffect(() => {
    const saved = {
      history: localStorage.getItem('lunchrun_history'),
      waitlist: localStorage.getItem('lunchrun_waitlist'),
      runs: localStorage.getItem('lunchrun_active_runs')
    };
    if (saved.history) setHistory(JSON.parse(saved.history));
    if (saved.waitlist) setWaitingOrders(JSON.parse(saved.waitlist));
    if (saved.runs) setRuns(JSON.parse(saved.runs));
  }, []);

  // Sync state to localStorage and broadcast to other tabs
  const broadcastAndSave = (type: string, data: any) => {
    localStorage.setItem(`lunchrun_${type}`, JSON.stringify(data));
    syncChannel.postMessage({ type, data });
  };

  // Listen for sync messages from other tabs
  useEffect(() => {
    const handleSync = (event: MessageEvent) => {
      const { type, data } = event.data;
      if (type === 'active_runs') setRuns(data);
      if (type === 'waitlist') setWaitingOrders(data);
      if (type === 'history') setHistory(data);
    };
    syncChannel.addEventListener('message', handleSync);
    return () => syncChannel.removeEventListener('message', handleSync);
  }, []);

  // Wrappers for state updates that need broadcasting
  const updateRuns = (newRuns: FoodRun[]) => {
    setRuns(newRuns);
    broadcastAndSave('active_runs', newRuns);
  };

  const updateWaitingOrders = (newOrders: WaitingOrder[]) => {
    setWaitingOrders(newOrders);
    broadcastAndSave('waitlist', newOrders);
  };

  const updateHistory = (newHistory: FoodRun[]) => {
    setHistory(newHistory);
    broadcastAndSave('history', newHistory);
  };

  const sharedActions = {
    runs, setRuns: updateRuns,
    history, setHistory: updateHistory,
    waitingOrders, setWaitingOrders: updateWaitingOrders,
    webhookUrl, setWebhookUrl,
    messagePrefix, setMessagePrefix,
    defaultWait, setDefaultWait,
    defaultMax, setDefaultMax,
    isSimulatorAdmin
  };

  const handleLogin = (email: string) => {
    const name = extractNameFromEmail(email);
    setUser({ name, email, isAdmin: false });
  };

  // Login Screen
  if (!user) {
    return (
      <div className="h-screen flex flex-col items-center justify-center p-8 bg-white">
        <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-3xl mb-6 shadow-xl shadow-indigo-100">
          <i className="fas fa-motorcycle"></i>
        </div>
        <h1 className="text-2xl font-black text-slate-800 tracking-tighter mb-8">LunchRun Access</h1>
        <form 
          onSubmit={(e) => { 
            e.preventDefault(); 
            const email = (e.currentTarget.elements[0] as HTMLInputElement).value;
            handleLogin(email);
          }} 
          className="w-full max-w-xs space-y-4"
        >
          <input 
            required 
            type="email" 
            placeholder="Corporate Email" 
            className="w-full p-4 bg-slate-50 border-0 rounded-2xl font-bold placeholder:text-slate-400 focus:bg-slate-100 outline-none transition-all" 
          />
          <button 
            type="submit" 
            className="w-full h-14 bg-orange-600 hover:bg-orange-700 text-white font-black uppercase rounded-2xl shadow-xl shadow-orange-100 transition-all active:scale-95"
          >
            SIGN IN
          </button>
          <button 
            type="button" 
            onClick={() => setUser({ name: 'System Admin', email: 'admin@system.local', isAdmin: true })} 
            className="w-full py-2 text-[9px] font-black text-slate-200 uppercase tracking-widest hover:text-slate-400 transition-colors"
          >
            ADMIN OVERRIDE
          </button>
        </form>
      </div>
    );
  }

  // Main Container
  return (
    <div className={`min-h-screen transition-all duration-500 bg-white`}>
      {/* Simulation Bar - STRICTLY HIDDEN FOR NON-ADMINS */}
      {user.isAdmin && (
        <div className="bg-[#0f172a] text-white/70 px-6 py-2 flex justify-between items-center text-[10px] font-black uppercase tracking-[0.2em] shadow-xl sticky top-0 z-[100] border-b border-white/5">
          <div className="flex items-center gap-4">
            <div className="w-1.5 h-1.5 rounded-full bg-indigo-400 animate-pulse"></div>
            <span>LUNCHRUN FLEET CONTROL</span>
          </div>
          <div className="flex gap-4">
            <button 
              onClick={() => setSimulatorMode(!simulatorMode)} 
              className="px-4 py-1.5 rounded-full border border-slate-700 hover:text-white text-[9px] transition-all bg-slate-800/50"
            >
              {simulatorMode ? 'Close Simulator' : 'Simulation Mode'}
            </button>
          </div>
        </div>
      )}

      {simulatorMode && user.isAdmin ? (
        <div className="flex flex-col md:flex-row h-[calc(100vh-40px)] gap-4 p-4 bg-slate-100 overflow-hidden">
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-indigo-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Persona: Runner</div>
             <AppInstance user={user} {...sharedActions} />
          </div>
          <div className="flex-1 bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-300 relative">
             <div className="absolute top-0 inset-x-0 bg-emerald-600 text-white px-4 py-1 text-[9px] font-black z-50 text-center uppercase tracking-widest">Persona: Orderer</div>
             <AppInstance user={{ name: 'Dana Kaplan', email: `dana@naturalint.com`, isAdmin: false }} {...sharedActions} />
          </div>
        </div>
      ) : (
        <div className="max-w-4xl mx-auto px-4 py-8">
          <AppInstance user={user} {...sharedActions} />
        </div>
      )}
    </div>
  );
};

const AppInstance: React.FC<any> = ({ 
  user, 
  runs, setRuns, 
  history, setHistory, 
  waitingOrders, setWaitingOrders, 
  webhookUrl, setWebhookUrl,
  messagePrefix, setMessagePrefix,
  defaultWait, setDefaultWait,
  defaultMax, setDefaultMax,
  isSimulatorAdmin
}) => {
  const [testLoading, setTestLoading] = useState(false);
  const [modals, setModals] = useState<{ [key: string]: boolean | any }>({
    create: false, waitlist: false, join: null, cibus: null, arrive: null
  });
  const [inputs, setInputs] = useState({ dest: '', time: defaultWait, max: defaultMax, item: '', floor: '', cibus: '', loc: '' });

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const action = params.get('action');
    const runId = params.get('runId');

    if (runId && action === 'pay') {
      const run = runs.find((r: FoodRun) => r.id === runId);
      if (run) {
        const myOrder = run.orders.find((o: Order) => o.userEmail === user.email);
        if (myOrder) setModals(prev => ({ ...prev, cibus: { runId, orderId: myOrder.id } }));
      }
    } else if (runId && action === 'join') {
      setModals(prev => ({ ...prev, join: runId }));
    }
    if (action) window.history.replaceState({}, document.title, window.location.pathname);
  }, [user.email, runs.length]);

  const actions = {
    createRun: (e: React.FormEvent) => {
      e.preventDefault();
      const normDest = normalizeBusinessName(inputs.dest);
      const matches = waitingOrders.filter(wo => normalizeBusinessName(wo.destination) === normDest);
      const ordersToPull = matches.slice(0, inputs.max);

      const orders: Order[] = ordersToPull.map(wo => ({ id: wo.id, userName: wo.userName, userEmail: wo.userEmail, itemDescription: wo.itemDescription, floor: wo.floor, cibusCode: '', timestamp: Date.now() }));

      const newRun: FoodRun = {
        id: Math.random().toString(36).substr(2, 9), runnerName: user.name, runnerEmail: user.email,
        destination: inputs.dest, departureTime: Date.now() + inputs.time * 60000, minutesUntilDeparture: inputs.time,
        maxOrders: inputs.max, status: 'active', orders
      };

      setWaitingOrders(waitingOrders.filter((wo: any) => !ordersToPull.some(o => o.id === wo.id)));
      setRuns([newRun, ...runs]);
      setModals({ ...modals, create: false });

      const baseUrl = window.location.href.split('?')[0];
      sendToGoogleChat(webhookUrl, {
        title: "New Run Started",
        subtitle: inputs.dest,
        details: `Departing in ${inputs.time} mins. Runner: ${user.name}.`,
        buttons: [
          { text: "Join via App", url: `${baseUrl}?action=join&runId=${newRun.id}` },
          { text: "Send DM to Runner", url: `https://mail.google.com/chat/u/0/#chat/dm/${user.email}` }
        ],
        prefix: messagePrefix
      });
    },
    depart: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, status: 'departed' } : r));

      const baseUrl = window.location.href.split('?')[0];
      sendToGoogleChat(webhookUrl, {
        title: "Departure Alert",
        subtitle: run.destination,
        details: "The runner is leaving. Please enter your Cibus payment code.",
        buttons: [
          { text: "Enter Code", url: `${baseUrl}?action=pay&runId=${runId}` },
          { text: "Message Runner", url: `https://mail.google.com/chat/u/0/#chat/dm/${run.runnerEmail}` }
        ],
        prefix: messagePrefix
      });
    },
    arrive: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      if (!run) return;
      sendToGoogleChat(webhookUrl, {
        title: "Food is Here!",
        subtitle: `Pickup: ${inputs.loc}`,
        details: `Order from ${run.destination} has arrived. Enjoy!`,
        prefix: messagePrefix
      });
      setHistory([{ ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() }, ...history]);
      setRuns(runs.filter((r: any) => r.id !== runId));
      setModals({ ...modals, arrive: null });
    },
    join: (runId: string) => {
      const order: Order = { id: Math.random().toString(36).substr(2, 9), userName: user.name, userEmail: user.email, itemDescription: inputs.item, floor: inputs.floor, cibusCode: '', timestamp: Date.now() };
      setRuns(runs.map((r: any) => r.id === runId ? { ...r, orders: [...r.orders, order] } : r));
      setModals({ ...modals, join: null });
    }
  };

  const isAdmin = user.isAdmin || isSimulatorAdmin;

  return (
    <div className="h-full flex flex-col bg-white relative">
      {/* HEADER - MATCHING SCREENSHOT EXACTLY */}
      <header className="flex justify-between items-center mb-10 px-2">
        <div className="flex items-center gap-4">
           <div className={`w-11 h-11 rounded-2xl flex items-center justify-center text-white text-xl shadow-lg transition-colors ${isAdmin ? 'bg-amber-500' : 'bg-[#6366f1]'}`}>
             <i className="fas fa-hamburger"></i>
           </div>
           <div className="flex flex-col">
             <span className="font-black text-lg text-slate-900 leading-none tracking-tight uppercase">{user.name}</span>
             <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1.5">{user.email}</span>
           </div>
        </div>
        <div className="w-10 h-10 rounded-full bg-slate-50 border border-slate-100 flex items-center justify-center text-slate-200">
          <i className="fas fa-user text-sm"></i>
        </div>
      </header>

      <main className="space-y-6 pb-24">
        {isAdmin && (
          <div className="bg-[#0f172a] rounded-[2rem] p-6 text-white shadow-2xl border-4 border-amber-500/20 mb-8">
             <h3 className="text-amber-400 text-[10px] font-black uppercase tracking-widest mb-4">Configuration</h3>
             <div className="flex gap-2">
                <input className="flex-1 p-3 bg-white/5 border border-white/10 rounded-2xl font-bold text-xs outline-none" value={webhookUrl} onChange={e => setWebhookUrl(e.target.value)} placeholder="Webhook URL" />
                <Button onClick={async () => { setTestLoading(true); const ok = await sendToGoogleChat(webhookUrl, { title: "Test", subtitle: "Live", details: "Communication test successful.", prefix: messagePrefix }); setTestLoading(false); alert(ok ? "Sent" : "Failed"); }} isLoading={testLoading} className="h-10 px-4 bg-amber-500 text-slate-900 text-[10px] uppercase font-black">Test</Button>
             </div>
          </div>
        )}

        {/* SUB-HEADER CONTROL BAR */}
        <div className="bg-slate-50/50 p-1.5 rounded-2xl flex justify-between items-center border border-slate-100 shadow-sm">
           <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-4">Active Runs</span>
           <div className="flex gap-2">
              <Button onClick={() => setModals({...modals, waitlist: true})} variant="ghost" className="h-10 px-4 text-[10px] font-black uppercase rounded-xl border-slate-200 bg-white">Waitlist</Button>
              <Button onClick={() => setModals({...modals, create: true})} className="h-10 px-6 text-[10px] font-black uppercase rounded-xl bg-[#e65100] hover:bg-[#bf360c] text-white shadow-lg shadow-orange-100 transition-all">Start Run</Button>
           </div>
        </div>

        {/* RUNS LIST */}
        <div className="space-y-4">
           {runs.length === 0 ? (
             <div className="py-24 text-center">
               <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-6 text-slate-200">
                 <i className="fas fa-ghost text-3xl"></i>
               </div>
               <p className="text-[10px] font-black text-slate-300 uppercase tracking-[0.2em]">No active runs nearby</p>
             </div>
           ) : runs.map((run: FoodRun) => {
             const isRunner = user.email === run.runnerEmail;
             const myOrder = run.orders.find(o => o.userEmail === user.email);
             return (
               <div key={run.id} className={`bg-white rounded-[2.5rem] p-7 shadow-xl border-2 transition-all ${run.status === 'departed' ? 'border-[#6366f1]' : 'border-slate-50'}`}>
                  <div className="flex justify-between items-start mb-6">
                     <div className="flex gap-4">
                        <div className="w-14 h-14 rounded-2xl bg-slate-50 flex items-center justify-center text-2xl text-slate-300">
                           <i className={`fas ${run.status === 'departed' ? 'fa-motorcycle text-[#6366f1]' : 'fa-pizza-slice'}`}></i>
                        </div>
                        <div>
                           <h4 className="text-xl font-black text-slate-800 tracking-tight">{run.destination}</h4>
                           <div className="flex items-center gap-2 mt-1">
                              <span className={`text-[9px] font-black px-2 py-0.5 rounded-full ${run.status === 'departed' ? 'bg-indigo-50 text-indigo-600' : 'bg-slate-100 text-slate-400'}`}>{run.status.toUpperCase()}</span>
                              <span className="text-[10px] font-bold text-slate-400">{run.runnerName}</span>
