import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { FoodRun, Order, WaitingOrder, UserNotification } from './types';
import { Button } from './components/Button';
import { sendToGoogleChat } from './services/googleChatService';

/**
 * CLOUD SYNC CONFIGURATION
 * In a real production environment, this would be a proper backend/Firebase.
 * For this workplace tool, we use a deterministic cloud bin based on the company domain.
 */
const CLOUD_API_BASE = 'https://api.npoint.io';

const extractDomain = (email: string) => email.split('@')[1]?.toLowerCase() || 'public';

const extractNameFromEmail = (email: string): string => {
  if (!email) return 'User';
  const namePart = email.split('@')[0];
  return namePart
    .split(/[._-]/)
    .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(' ');
};

const normalizeBusinessName = (name: string): string => {
  return name.trim().toLowerCase()
    .replace(/\s+/g, '')
    .replace(/[-_]/g, '')
    .replace(/^ה/g, '');
};

const App: React.FC = () => {
  const [user, setUser] = useState<{ name: string; email: string; isAdmin?: boolean } | null>(null);
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSync, setLastSync] = useState<number>(Date.now());
  const [view, setView] = useState<'app' | 'admin'>('app');
  const [simulatorMode, setSimulatorMode] = useState(false);
  const [webhookUrl, setWebhookUrl] = useState<string>(localStorage.getItem('lunchrun_webhook') || '');

  // Persistent Settings
  const [messagePrefix] = useState<string>(localStorage.getItem('lunchrun_prefix') || '[LunchRun]');
  const [defaultWait] = useState<number>(Number(localStorage.getItem('lunchrun_def_wait')) || 20);
  const [defaultMax] = useState<number>(Number(localStorage.getItem('lunchrun_def_max')) || 5);

  // Cloud Persistence Logic
  const getBinId = () => {
    if (!user) return null;
    const domain = extractDomain(user.email);
    // Simple deterministic ID for demo purposes. 
    // In production, you'd store this ID in a registry or use a real DB.
    return `lunchrun_v1_${domain.replace(/[^a-zA-Z0-9]/g, '')}`;
  };

  const syncToCloud = async (currentRuns: FoodRun[], currentWait: WaitingOrder[], currentHistory: FoodRun[]) => {
    const binId = getBinId();
    if (!binId) return;
    setIsSyncing(true);
    try {
      // We store the ID in localStorage to keep track of the specific company bin
      let realBinId = localStorage.getItem(`bin_${binId}`);

      const payload = { runs: currentRuns, waitlist: currentWait, history: currentHistory, lastUpdate: Date.now() };

      if (!realBinId) {
        // Create new bin
        const res = await fetch(`${CLOUD_API_BASE}`, {
          method: 'POST',
          body: JSON.stringify(payload)
        });
        const data = await res.json();
        localStorage.setItem(`bin_${binId}`, data.binId);
      } else {
        // Update existing bin
        await fetch(`${CLOUD_API_BASE}/${realBinId}`, {
          method: 'PUT',
          body: JSON.stringify(payload)
        });
      }
      setLastSync(Date.now());
    } catch (e) {
      console.error("Sync Error", e);
    } finally {
      setIsSyncing(false);
    }
  };

  const fetchFromCloud = async () => {
    const binId = getBinId();
    if (!binId) return;
    const realBinId = localStorage.getItem(`bin_${binId}`);
    if (!realBinId) return;

    try {
      const res = await fetch(`${CLOUD_API_BASE}/${realBinId}`);
      if (res.ok) {
        const data = await res.json();
        // Simple merge/override for demo
        if (data.lastUpdate > lastSync) {
          setRuns(data.runs || []);
          setWaitingOrders(data.waitlist || []);
          setHistory(data.history || []);
          setLastSync(data.lastUpdate);
        }
      }
    } catch (e) {
      console.error("Fetch Error", e);
    }
  };

  // Polling Effect
  useEffect(() => {
    if (!user) return;
    const interval = setInterval(fetchFromCloud, 8000);
    fetchFromCloud(); // Initial fetch
    return () => clearInterval(interval);
  }, [user?.email]);

  const updateAndSync = (newRuns: FoodRun[], newWait: WaitingOrder[], newHistory: FoodRun[]) => {
    setRuns(newRuns);
    setWaitingOrders(newWait);
    setHistory(newHistory);
    syncToCloud(newRuns, newWait, newHistory);
  };

  if (!user) {
    return (
      <div className="h-screen flex flex-col items-center justify-center p-8 bg-white">
        <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-3xl mb-6 shadow-xl shadow-indigo-100">
          <i className="fas fa-motorcycle"></i>
        </div>
        <h1 className="text-2xl font-black text-slate-800 tracking-tighter mb-8">LunchRun Access</h1>
        <form 
          onSubmit={(e) => { 
            e.preventDefault(); 
            const emailInput = (e.currentTarget.elements[0] as HTMLInputElement).value;
            setUser({ name: extractNameFromEmail(emailInput), email: emailInput, isAdmin: false });
          }} 
          className="w-full max-w-xs space-y-4"
        >
          <input required type="email" placeholder="Corporate Email" className="w-full p-4 bg-slate-50 border-0 rounded-2xl font-bold placeholder:text-slate-400 focus:bg-slate-100 outline-none transition-all" />
          <button type="submit" className="w-full h-14 bg-orange-600 hover:bg-orange-700 text-white font-black uppercase rounded-2xl shadow-xl transition-all active:scale-95">SIGN IN</button>
          <button type="button" onClick={() => setUser({ name: 'System Admin', email: 'admin@system.local', isAdmin: true })} className="w-full py-2 text-[9px] font-black text-slate-200 uppercase tracking-widest hover:text-slate-400 transition-colors">ADMIN OVERRIDE</button>
        </form>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white">
      {/* SYSTEM TOOLBAR - ADMIN ONLY */}
      {user.isAdmin && (
        <div className="bg-[#0f172a] text-white/70 px-6 py-2 flex justify-between items-center text-[10px] font-black uppercase tracking-[0.2em] sticky top-0 z-[100]">
          <div className="flex items-center gap-4">
            <div className={`w-2 h-2 rounded-full ${isSyncing ? 'bg-amber-400 animate-pulse' : 'bg-emerald-400'}`}></div>
            <span>LUNCHRUN FLEET COMMAND</span>
          </div>
          <div className="flex gap-4">
            <button onClick={() => setView(view === 'admin' ? 'app' : 'admin')} className={`px-4 py-1.5 rounded-full border transition-all ${view === 'admin' ? 'bg-indigo-600 text-white border-indigo-500' : 'border-slate-700'}`}>
              {view === 'admin' ? 'BACK TO APP' : 'DASHBOARD'}
            </button>
            <button onClick={() => setSimulatorMode(!simulatorMode)} className="px-4 py-1.5 rounded-full border border-slate-700 hover:text-white">SIMULATE</button>
          </div>
        </div>
      )}

      {view === 'admin' ? (
        <AdminDashboard user={user} runs={runs} waitingOrders={waitingOrders} history={history} onReset={() => updateAndSync([], [], [])} />
      ) : (
        <div className="max-w-4xl mx-auto px-4 py-8">
           <header className="flex justify-between items-center mb-10 px-2">
            <div className="flex items-center gap-4">
              <div className="w-11 h-11 rounded-2xl bg-[#6366f1] flex items-center justify-center text-white text-xl shadow-lg">
                <i className="fas fa-hamburger"></i>
              </div>
              <div className="flex flex-col">
                <span className="font-black text-lg text-slate-900 leading-none tracking-tight uppercase">{user.name}</span>
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1.5 flex items-center gap-2">
                  {user.email}
                  <div className={`w-1.5 h-1.5 rounded-full ${isSyncing ? 'bg-amber-400' : 'bg-emerald-400'}`}></div>
                </span>
              </div>
            </div>
          </header>

          <AppInstance 
            user={user} 
            runs={runs} 
            history={history}
            waitingOrders={waitingOrders}
            updateAll={(r: any, w: any, h: any) => updateAndSync(r, w, h)}
            webhookUrl={webhookUrl}
            setWebhookUrl={(url: string) => { setWebhookUrl(url); localStorage.setItem('lunchrun_webhook', url); }}
          />
        </div>
      )}
    </div>
  );
};

