const AppInstance: React.FC<any> = ({ user, runs, history, waitingOrders, updateAll, webhookUrl, setWebhookUrl }) => {
  const [modals, setModals] = useState<{ [key: string]: any }>({ create: false, waitlist: false });
  const [inputs, setInputs] = useState({ dest: '', time: 20, max: 5, item: '', floor: '', cibus: '', loc: '' });

  const actions = {
    createRun: (e: React.FormEvent) => {
      e.preventDefault();
      const newRun: FoodRun = {
        id: Math.random().toString(36).substr(2, 9), runnerName: user.name, runnerEmail: user.email,
        destination: inputs.dest, departureTime: Date.now() + inputs.time * 60000, minutesUntilDeparture: inputs.time,
        maxOrders: inputs.max, status: 'active', orders: []
      };
      updateAll([newRun, ...runs], waitingOrders, history);
      setModals({ ...modals, create: false });
      sendToGoogleChat(webhookUrl, { title: "New Mission", subtitle: inputs.dest, details: `Departing in ${inputs.time}m by ${user.name}`, prefix: "[LunchRun]" });
    },
    join: (runId: string) => {
      const order: Order = { id: Math.random().toString(36).substr(2, 9), userName: user.name, userEmail: user.email, itemDescription: inputs.item, floor: inputs.floor, cibusCode: '', timestamp: Date.now() };
      const newRuns = runs.map((r: any) => r.id === runId ? { ...r, orders: [...r.orders, order] } : r);
      updateAll(newRuns, waitingOrders, history);
      setModals({ ...modals, join: null });
    },
    depart: (runId: string) => {
      const newRuns = runs.map((r: any) => r.id === runId ? { ...r, status: 'departed' } : r);
      updateAll(newRuns, waitingOrders, history);
      sendToGoogleChat(webhookUrl, { title: "Departure", subtitle: "Food is en route!", details: "Runner has left the building.", prefix: "[LunchRun]" });
    },
    arrive: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      const finishedRun = { ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() };
      updateAll(runs.filter((r: any) => r.id !== runId), waitingOrders, [finishedRun, ...history]);
      setModals({ ...modals, arrive: null });
      sendToGoogleChat(webhookUrl, { title: "Delivery Complete", subtitle: inputs.loc, details: `Pick up your ${run.destination} orders!`, prefix: "[LunchRun]" });
    }
  };

  return (
    <main className="space-y-6">
      {user.isAdmin && (
        <div className="bg-[#0f172a] rounded-[2rem] p-6 text-white mb-8 border-4 border-amber-500/20 shadow-2xl">
          <h3 className="text-amber-400 text-[10px] font-black uppercase tracking-widest mb-4">Webhook Settings</h3>
          <div className="flex gap-2">
            <input className="flex-1 p-3 bg-white/5 border border-white/10 rounded-2xl font-bold text-xs" value={webhookUrl} onChange={e => setWebhookUrl(e.target.value)} placeholder="Google Chat Webhook" />
          </div>
        </div>
      )}

      <div className="bg-slate-50 p-2 rounded-2xl flex justify-between items-center border border-slate-100 shadow-sm">
        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-4">Network Status: Online</span>
        <div className="flex gap-2">
          <Button onClick={() => setModals({...modals, waitlist: true})} variant="ghost" className="h-10 px-4 text-[10px] uppercase rounded-xl bg-white border">Waitlist</Button>
          <Button onClick={() => setModals({...modals, create: true})} className="h-10 px-6 text-[10px] uppercase rounded-xl bg-[#e65100] text-white">Start Run</Button>
        </div>
      </div>

      <div className="space-y-4">
        {runs.length === 0 ? (
