import React, { useState, useEffect, useMemo, useRef } from 'react';
import { FoodRun, Order, WaitingOrder } from './types';
import { Button } from './components/Button';
import { sendToGoogleChat } from './services/googleChatService';

/**
 * GLOBAL CLOUD SYNC CONFIG
 * Uses a public Key-Value store to sync data between different computers.
 * The key is derived from the company domain (e.g., naturalint.com).
 */
const CLOUD_SYNC_URL = 'https://keyvalue.xyz/1'; 

const extractDomain = (email: string) => email.split('@')[1]?.toLowerCase() || 'public';

const extractNameFromEmail = (email: string): string => {
  if (!email) return 'User';
  const namePart = email.split('@')[0];
  return namePart
    .split(/[._-]/)
    .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(' ');
};

const App: React.FC = () => {
  const [user, setUser] = useState<{ name: string; email: string; isAdmin?: boolean } | null>(null);
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSyncTime, setLastSyncTime] = useState<number>(0);
  const [view, setView] = useState<'app' | 'admin'>('app');
  const [simulatorMode, setSimulatorMode] = useState(false);
  const [webhookUrl, setWebhookUrl] = useState<string>(localStorage.getItem('lunchrun_webhook') || '');

  // Derives a unique key for the company to sync across all employees
  const getSyncKey = () => {
    if (!user) return null;
    const domain = extractDomain(user.email);
    return `lunchrun_v3_${domain.replace(/[^a-zA-Z0-9]/g, '')}`;
  };

  // Pushes local state to the cloud
  const pushToCloud = async (currentRuns: FoodRun[], currentWait: WaitingOrder[], currentHistory: FoodRun[]) => {
    const key = getSyncKey();
    if (!key) return;
    setIsSyncing(true);
    try {
      const payload = { 
        runs: currentRuns, 
        waitlist: currentWait, 
        history: currentHistory, 
        lastUpdate: Date.now(),
        updatedBy: user?.email 
      };
      await fetch(`${CLOUD_SYNC_URL}/${key}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      setLastSyncTime(Date.now());
    } catch (e) {
      console.error("Cloud Push Error", e);
    } finally {
      setIsSyncing(false);
    }
  };

  // Pulls state from the cloud
  const pullFromCloud = async () => {
    const key = getSyncKey();
    if (!key) return;
    try {
      const res = await fetch(`${CLOUD_SYNC_URL}/${key}`);
      if (res.ok) {
        const text = await res.text();
        if (!text) return;
        const data = JSON.parse(text);

        // Only update if cloud data is newer than local state
        if (data.lastUpdate > lastSyncTime) {
          setRuns(data.runs || []);
          setWaitingOrders(data.waitlist || []);
          setHistory(data.history || []);
          setLastSyncTime(data.lastUpdate);
        }
      }
    } catch (e) {
      console.error("Cloud Pull Error", e);
    }
  };

  // Sync effect: Poll every 5 seconds for "Live" experience across computers
  useEffect(() => {
    if (!user) return;
    const interval = setInterval(pullFromCloud, 5000);
    pullFromCloud();
    return () => clearInterval(interval);
  }, [user?.email, lastSyncTime]);

  const updateAndSync = (newRuns: FoodRun[], newWait: WaitingOrder[], newHistory: FoodRun[]) => {
    setRuns(newRuns);
    setWaitingOrders(newWait);
    setHistory(newHistory);
    pushToCloud(newRuns, newWait, newHistory);
  };

  // Login Handler
  if (!user) {
    return (
      <div className="h-screen flex flex-col items-center justify-center p-8 bg-white">
        <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-3xl mb-6 shadow-xl shadow-indigo-100">
          <i className="fas fa-motorcycle"></i>
        </div>
        <h1 className="text-2xl font-black text-slate-800 tracking-tighter mb-8">LunchRun Login</h1>
        <form 
          onSubmit={(e) => { 
            e.preventDefault(); 
            const emailInput = (e.currentTarget.elements[0] as HTMLInputElement).value;
            setUser({ name: extractNameFromEmail(emailInput), email: emailInput, isAdmin: false });
          }} 
          className="w-full max-w-xs space-y-4"
        >
          <input required type="email" placeholder="Work Email" className="w-full p-4 bg-slate-50 border-0 rounded-2xl font-bold placeholder:text-slate-400 focus:bg-slate-100 outline-none transition-all" />
          <button type="submit" className="w-full h-14 bg-[#f4511e] hover:bg-[#e64a19] text-white font-black uppercase rounded-2xl shadow-xl transition-all">Enter App</button>
          <button type="button" onClick={() => setUser({ name: 'System Admin', email: 'admin@system.local', isAdmin: true })} className="w-full py-2 text-[9px] font-black text-slate-200 uppercase tracking-widest hover:text-slate-400 transition-colors">ADMIN OVERRIDE</button>
        </form>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white">
      {/* SYSTEM TOOLBAR - STRICTLY ADMIN ONLY */}
      {user.isAdmin && (
        <div className="bg-[#0f172a] text-white/70 px-6 py-2 flex justify-between items-center text-[10px] font-black uppercase tracking-[0.2em] sticky top-0 z-[100]">
          <div className="flex items-center gap-4">
            <div className={`w-2 h-2 rounded-full ${isSyncing ? 'bg-amber-400 animate-pulse' : 'bg-emerald-400'}`}></div>
            <span>LUNCHRUN FLEET CONTROL</span>
          </div>
          <div className="flex gap-4">
            <button onClick={() => setView(view === 'admin' ? 'app' : 'admin')} className={`px-4 py-1.5 rounded-full border transition-all ${view === 'admin' ? 'bg-indigo-600 text-white border-indigo-500' : 'border-slate-700'}`}>
              {view === 'admin' ? 'EXIT DASHBOARD' : 'DASHBOARD'}
            </button>
            <button onClick={() => setSimulatorMode(!simulatorMode)} className="px-4 py-1.5 rounded-full border border-slate-700 hover:text-white">SIMULATION MODE</button>
          </div>
        </div>
      )}

      {view === 'admin' ? (
        <AdminDashboard runs={runs} waitingOrders={waitingOrders} history={history} onReset={() => updateAndSync([], [], [])} />
      ) : (
        <div className={`max-w-4xl mx-auto px-4 py-8 ${simulatorMode ? 'flex flex-col md:flex-row gap-8 max-w-7xl' : ''}`}>
           {/* Normal Single View or Simulation Split View */}
           <div className="flex-1">
              <AppHeader user={user} isSyncing={isSyncing} />
              <AppInstance 
                user={user} 
                runs={runs} 
                history={history}
                waitingOrders={waitingOrders}
                updateAll={(r: any, w: any, h: any) => updateAndSync(r, w, h)}
                webhookUrl={webhookUrl}
                setWebhookUrl={(url: string) => { setWebhookUrl(url); localStorage.setItem('lunchrun_webhook', url); }}
              />
           </div>

           {simulatorMode && user.isAdmin && (
             <div className="flex-1 border-l border-slate-100 pl-8">
                <div className="bg-emerald-50 text-emerald-600 px-4 py-1 text-[9px] font-black uppercase rounded-full mb-6 text-center">Persona: External User</div>
                <AppHeader user={{ name: 'Niv Shtaif', email: 'niv.shtaif@naturalint.com' }} isSyncing={isSyncing} />
                <AppInstance 
                  user={{ name: 'Niv Shtaif', email: 'niv.shtaif@naturalint.com' }} 
                  runs={runs} 
                  history={history}
                  waitingOrders={waitingOrders}
                  updateAll={(r: any, w: any, h: any) => updateAndSync(r, w, h)}
                  webhookUrl={webhookUrl}
                  setWebhookUrl={() => {}}
                />
             </div>
           )}
        </div>
      )}
    </div>
  );
};

