              <div className="flex justify-between items-start mb-8">
                <div className="flex gap-5">
                  <div className="w-16 h-16 rounded-3xl bg-slate-50 flex items-center justify-center text-2xl text-slate-300">
                    <i className={`fas ${run.status === 'departed' ? 'fa-motorcycle text-[#6366f1]' : 'fa-hamburger'}`}></i>
                  </div>
                  <div>
                    <h4 className="text-2xl font-black text-slate-900 tracking-tight">{run.destination}</h4>
