import React, { useState, useEffect, useMemo, useRef } from 'react';
import { FoodRun, Order, WaitingOrder } from './types';
import { Button } from './components/Button';
import { sendToGoogleChat } from './services/googleChatService';

/**
 * GLOBAL CLOUD SYNC CONFIG
 * High-frequency polling and immediate push on change.
 */
const CLOUD_SYNC_URL = 'https://keyvalue.xyz/1'; 

const extractDomain = (email: string) => email.split('@')[1]?.toLowerCase() || 'public';

const extractNameFromEmail = (email: string): string => {
  if (!email) return 'User';
  const namePart = email.split('@')[0];
  return namePart
    .split(/[._-]/)
    .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(' ');
};

const App: React.FC = () => {
  const [user, setUser] = useState<{ name: string; email: string; isAdmin?: boolean } | null>(null);
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSyncJson, setLastSyncJson] = useState<string>('');
  const [view, setView] = useState<'app' | 'admin'>('app');
  const [simulatorMode, setSimulatorMode] = useState(false);
  const [webhookUrl, setWebhookUrl] = useState<string>(localStorage.getItem('lunchrun_webhook') || '');

  // Unique key for the whole company to share one "live" state
  const getSyncKey = () => {
    if (!user) return null;
    const domain = extractDomain(user.email);
    // Unique but shared across all colleagues
    return `lunchrun_v4_prod_${domain.replace(/[^a-zA-Z0-9]/g, '')}`;
  };

  // Immediate push to cloud on any local update
  const pushToCloud = async (currentRuns: FoodRun[], currentWait: WaitingOrder[], currentHistory: FoodRun[]) => {
    const key = getSyncKey();
    if (!key) return;
    setIsSyncing(true);
    try {
      const payload = { 
        runs: currentRuns, 
        waitlist: currentWait, 
        history: currentHistory, 
        lastUpdate: Date.now(),
        author: user?.email 
      };
      const json = JSON.stringify(payload);
      await fetch(`${CLOUD_SYNC_URL}/${key}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: json
      });
      setLastSyncJson(json);
    } catch (e) {
      console.error("Cloud Sync Error (Push):", e);
    } finally {
      setTimeout(() => setIsSyncing(false), 500);
    }
  };

  // Pull state from the cloud and detect changes
  const pullFromCloud = async () => {
    const key = getSyncKey();
    if (!key) return;
    try {
      const res = await fetch(`${CLOUD_SYNC_URL}/${key}`);
      if (res.ok) {
        const text = await res.text();
        if (!text || text === lastSyncJson) return;

        const data = JSON.parse(text);
        setRuns(data.runs || []);
        setWaitingOrders(data.waitlist || []);
        setHistory(data.history || []);
        setLastSyncJson(text);

        // Brief pulse for sync awareness
        setIsSyncing(true);
        setTimeout(() => setIsSyncing(false), 300);
      }
    } catch (e) {
      console.error("Cloud Sync Error (Pull):", e);
    }
  };

  // HIGH-FREQUENCY POLLING: 2.5 seconds for "Live" feel
  useEffect(() => {
    if (!user) return;
    const interval = setInterval(pullFromCloud, 2500);
    pullFromCloud();
    return () => clearInterval(interval);
  }, [user?.email, lastSyncJson]);

  const updateAndSync = (newRuns: FoodRun[], newWait: WaitingOrder[], newHistory: FoodRun[]) => {
    setRuns(newRuns);
    setWaitingOrders(newWait);
    setHistory(newHistory);
    // Explicitly stringify to prevent pull immediately overriding our update
    setLastSyncJson(JSON.stringify({ runs: newRuns, waitlist: newWait, history: newHistory, lastUpdate: Date.now() }));
    pushToCloud(newRuns, newWait, newHistory);
  };

  if (!user) {
    return (
      <div className="h-screen flex flex-col items-center justify-center p-8 bg-white">
        <div className="w-16 h-16 bg-indigo-600 rounded-3xl flex items-center justify-center text-white text-3xl mb-8 shadow-2xl shadow-indigo-200">
          <i className="fas fa-motorcycle"></i>
        </div>
        <h1 className="text-3xl font-black text-slate-800 tracking-tighter mb-8 italic uppercase">LunchRun</h1>
        <form 
          onSubmit={(e) => { 
            e.preventDefault(); 
            const emailInput = (e.currentTarget.elements[0] as HTMLInputElement).value;
            setUser({ name: extractNameFromEmail(emailInput), email: emailInput, isAdmin: false });
          }} 
          className="w-full max-w-xs space-y-4"
        >
          <input required type="email" placeholder="Corporate Email" className="w-full p-5 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-[1.5rem] font-bold outline-none transition-all" />
          <button type="submit" className="w-full h-16 bg-orange-600 hover:bg-orange-700 text-white font-black uppercase rounded-[1.5rem] shadow-xl shadow-orange-100 transition-all active:scale-95">GO LIVE</button>
          <button type="button" onClick={() => setUser({ name: 'System Admin', email: 'admin@system.local', isAdmin: true })} className="w-full py-2 text-[10px] font-black text-slate-300 uppercase tracking-widest hover:text-slate-500 transition-colors">Admin Access</button>
        </form>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white text-slate-900">
      {/* ADMIN CONTROL - ONLY VISIBLE TO AUTHENTICATED ADMINS */}
      {user.isAdmin && (
        <div className="bg-[#0f172a] text-white/50 px-6 py-2.5 flex justify-between items-center text-[10px] font-black uppercase tracking-widest sticky top-0 z-[100] border-b border-white/5">
          <div className="flex items-center gap-3">
            <div className={`w-2 h-2 rounded-full ${isSyncing ? 'bg-amber-400 animate-pulse' : 'bg-emerald-400'}`}></div>
            <span>FLEET CONTROL SYSTEM v4.0</span>
          </div>
          <div className="flex gap-4">
            <button onClick={() => setView(view === 'admin' ? 'app' : 'admin')} className={`px-4 py-1 rounded-full border transition-all ${view === 'admin' ? 'bg-indigo-600 text-white border-indigo-500' : 'border-slate-700 hover:text-white'}`}>
              {view === 'admin' ? 'Back to App' : 'Dashboard'}
            </button>
            <button onClick={() => setSimulatorMode(!simulatorMode)} className="px-4 py-1 rounded-full border border-slate-700 hover:text-white">Simulate</button>
          </div>
        </div>
      )}

      {view === 'admin' ? (
        <AdminDashboard runs={runs} waitingOrders={waitingOrders} history={history} onReset={() => updateAndSync([], [], [])} />
      ) : (
        <div className={`max-w-4xl mx-auto px-4 py-12 ${simulatorMode ? 'flex flex-col md:flex-row gap-12 max-w-7xl' : ''}`}>
           <div className="flex-1">
              <AppHeader user={user} isSyncing={isSyncing} />
              <AppInstance 
                user={user} 
                runs={runs} 
                history={history}
                waitingOrders={waitingOrders}
                updateAll={(r: any, w: any, h: any) => updateAndSync(r, w, h)}
                webhookUrl={webhookUrl}
                setWebhookUrl={(url: string) => { setWebhookUrl(url); localStorage.setItem('lunchrun_webhook', url); }}
              />
           </div>

           {simulatorMode && user.isAdmin && (
             <div className="flex-1 border-l border-slate-100 pl-12 bg-slate-50/50 p-8 rounded-[3rem]">
                <div className="text-[10px] font-black text-emerald-600 uppercase mb-8 text-center tracking-widest border-b border-emerald-100 pb-4">Live Persona: Colleague Test</div>
                <AppHeader user={{ name: 'Niv Shtaif', email: 'niv.shtaif@naturalint.com' }} isSyncing={isSyncing} />
                <AppInstance 
                  user={{ name: 'Niv Shtaif', email: 'niv.shtaif@naturalint.com' }} 
                  runs={runs} 
                  history={history}
                  waitingOrders={waitingOrders}
                  updateAll={(r: any, w: any, h: any) => updateAndSync(r, w, h)}
                  webhookUrl={webhookUrl}
                  setWebhookUrl={() => {}}
                />
             </div>
           )}
        </div>
      )}
    </div>
  );
};

const AppHeader: React.FC<{ user: any; isSyncing: boolean }> = ({ user, isSyncing }) => (
  <header className="flex justify-between items-center mb-12 px-2">
    <div className="flex items-center gap-5">
      <div className="w-14 h-14 rounded-[1.25rem] bg-[#6366f1] flex items-center justify-center text-white text-2xl shadow-2xl shadow-indigo-200 transition-transform hover:scale-105">
        <i className="fas fa-hamburger"></i>
      </div>
      <div className="flex flex-col">
