        <div className="flex items-center gap-2 mt-2">
          <span className="text-[11px] font-bold text-slate-400 uppercase tracking-widest">{user.email}</span>
          <div className={`w-2 h-2 rounded-full shadow-sm transition-all duration-300 ${isSyncing ? 'bg-amber-400 scale-125' : 'bg-emerald-400'}`}></div>
        </div>
      </div>
    </div>
  </header>
);

const AppInstance: React.FC<any> = ({ user, runs, history, waitingOrders, updateAll, webhookUrl, setWebhookUrl }) => {
  const [modals, setModals] = useState<{ [key: string]: any }>({ create: false, waitlist: false, join: null, cibus: null, arrive: null });
  const [inputs, setInputs] = useState({ dest: '', time: 20, max: 5, item: '', floor: '', cibus: '', loc: '' });

  const actions = {
    createRun: (e: React.FormEvent) => {
      e.preventDefault();
      const newRun: FoodRun = {
        id: Math.random().toString(36).substr(2, 9), runnerName: user.name, runnerEmail: user.email,
        destination: inputs.dest, departureTime: Date.now() + inputs.time * 60000, minutesUntilDeparture: inputs.time,
        maxOrders: inputs.max, status: 'active', orders: []
      };
      updateAll([newRun, ...runs], waitingOrders, history);
      setModals({ ...modals, create: false });
      sendToGoogleChat(webhookUrl, { title: "Mission Started", subtitle: inputs.dest, details: `Join within ${inputs.time} mins. Runner: ${user.name}`, prefix: "[LunchRun]" });
    },
    join: (runId: string) => {
      const order: Order = { id: Math.random().toString(36).substr(2, 9), userName: user.name, userEmail: user.email, itemDescription: inputs.item, floor: inputs.floor, cibusCode: '', timestamp: Date.now() };
      const newRuns = runs.map((r: any) => r.id === runId ? { ...r, orders: [...r.orders, order] } : r);
      updateAll(newRuns, waitingOrders, history);
      setModals({ ...modals, join: null });
    },
    depart: (runId: string) => {
      const newRuns = runs.map((r: any) => r.id === runId ? { ...r, status: 'departed' } : r);
      updateAll(newRuns, waitingOrders, history);
      sendToGoogleChat(webhookUrl, { title: "Departed!", subtitle: "Food is on the way", details: "Runner has left the building. Codes required.", prefix: "[LunchRun]" });
    },
    arrive: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      const finishedRun = { ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() };
      updateAll(runs.filter((r: any) => r.id !== runId), waitingOrders, [finishedRun, ...history]);
      setModals({ ...modals, arrive: null });
      sendToGoogleChat(webhookUrl, { title: "Arrived!", subtitle: inputs.loc, details: `Collect your ${run.destination} orders.`, prefix: "[LunchRun]" });
    }
  };

  return (
    <main className="space-y-8">
      {/* NETWORK STATUS BAR */}
      <div className="bg-[#f8fafc] p-2 rounded-[1.25rem] flex justify-between items-center border border-slate-100 shadow-sm">
        <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] pl-6 flex items-center gap-3">
          NETWORK STATUS: ONLINE
          <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 shadow-xl shadow-emerald-500/50"></div>
        </span>
        <div className="flex gap-2">
          <Button onClick={() => setModals({...modals, waitlist: true})} variant="ghost" className="h-11 px-5 text-[10px] font-black uppercase rounded-xl bg-white border border-slate-100 shadow-sm">Waitlist</Button>
          <Button onClick={() => setModals({...modals, create: true})} className="h-11 px-7 text-[10px] font-black uppercase rounded-xl bg-orange-600 text-white shadow-xl shadow-orange-100 transition-all hover:-translate-y-0.5">Start Run</Button>
        </div>
      </div>

      {/* ACTIVE RUNS FEED */}
      <div className="space-y-8">
        {runs.length === 0 ? (
          <div className="py-24 text-center opacity-30 animate-pulse">
            <i className="fas fa-ghost text-5xl mb-6 text-slate-200"></i>
            <p className="text-[11px] font-black uppercase tracking-[0.3em] text-slate-300">All Clear</p>
          </div>
        ) : runs.map((run: FoodRun) => {
          const isRunner = user.email === run.runnerEmail;
          const myOrder = run.orders.find(o => o.userEmail === user.email);
          return (
            <div key={run.id} className="bg-white rounded-[2.5rem] p-10 shadow-[0_30px_60px_-15px_rgba(0,0,0,0.08)] border border-slate-50 animate-in zoom-in-95 duration-500">
              <div className="flex justify-between items-start mb-8">
                <div className="flex gap-6">
                  <div className="w-16 h-16 rounded-[1.5rem] bg-slate-50 flex items-center justify-center text-3xl text-slate-300">
                    <i className={`fas ${run.status === 'departed' ? 'fa-motorcycle text-indigo-500 animate-bounce' : 'fa-hamburger'}`}></i>
                  </div>
                  <div>
                    <h4 className="text-3xl font-black text-slate-900 tracking-tighter italic uppercase">{run.destination}</h4>
                    <div className="flex items-center gap-2 mt-2">
                       <span className="text-[11px] font-black text-slate-400 uppercase tracking-widest">{run.runnerName}</span>
                       <span className={`text-[10px] font-black px-2.5 py-0.5 rounded-full uppercase tracking-widest ${run.status === 'departed' ? 'bg-indigo-50 text-indigo-600' : 'bg-emerald-50 text-emerald-600'}`}>
                         • {run.status}
                       </span>
                    </div>
                  </div>
                </div>
              </div>

              {run.orders.length > 0 && (
                <div className="space-y-3 mb-10">
                  {run.orders.map((o: any) => (
                    <div key={o.id} className="flex justify-between items-center p-5 rounded-[1.5rem] text-sm bg-slate-50/50 border border-slate-50/50">
                      <span className="font-bold text-slate-800">{o.userName}: <span className="font-normal text-slate-400 italic">"{o.itemDescription}"</span></span>
                      {o.cibusCode && <span className="text-[10px] font-black text-emerald-600 bg-emerald-50 px-4 py-1 rounded-full"><i className="fas fa-check-circle mr-1"></i> {o.cibusCode}</span>}
                    </div>
                  ))}
                </div>
              )}

              <div className="flex gap-4">
                {isRunner ? (
                  run.status === 'active' ? 
                    <Button onClick={() => actions.depart(run.id)} className="flex-1 h-16 bg-orange-600 hover:bg-orange-700 text-[13px] font-black uppercase rounded-[1.5rem] shadow-2xl shadow-orange-100">Depart Now</Button> :
                    <Button onClick={() => setModals({...modals, arrive: run.id})} className="flex-1 h-16 bg-emerald-600 hover:bg-emerald-700 text-[13px] font-black uppercase rounded-[1.5rem] text-white shadow-2xl shadow-emerald-100">Arrived & Pickup</Button>
                ) : !myOrder && run.status === 'active' && (
                  <Button onClick={() => setModals({...modals, join: run.id})} className="flex-1 h-16 bg-slate-900 hover:bg-black text-[13px] font-black uppercase rounded-[1.5rem] text-white">Join Run</Button>
                )}
                {myOrder && <div className="flex-1 text-center py-6 text-[11px] font-black uppercase text-indigo-400 tracking-widest bg-indigo-50/50 rounded-[1.5rem]"><i className="fas fa-check-circle mr-2"></i> On Manifest</div>}
              </div>
            </div>
          );
        })}
      </div>

      {/* OVERLAYS */}
      {modals.create && (
        <Overlay title="Start New Mission" onClose={() => setModals({...modals, create: false})}>
           <form onSubmit={actions.createRun} className="space-y-6">
              <input required autoFocus className="w-full p-5 bg-slate-50 rounded-[1.5rem] font-black text-lg border-2 border-transparent focus:border-indigo-500 outline-none transition-all" placeholder="Restaurant Name" value={inputs.dest} onChange={e => setInputs({...inputs, dest: e.target.value})} />
              <div className="grid grid-cols-2 gap-4">
                 <div className="space-y-2">
                    <label className="text-[9px] font-black uppercase text-slate-400 pl-4">Wait Time (Min)</label>
                    <input type="number" className="w-full p-5 bg-slate-50 rounded-[1.5rem] font-bold" value={inputs.time} onChange={e => setInputs({...inputs, time: Number(e.target.value)})} />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[9px] font-black uppercase text-slate-400 pl-4">Max Orders</label>
                    <input type="number" className="w-full p-5 bg-slate-50 rounded-[1.5rem] font-bold" value={inputs.max} onChange={e => setInputs({...inputs, max: Number(e.target.value)})} />
                 </div>
              </div>
              <Button type="submit" className="w-full h-16 bg-orange-600 text-[12px] font-black uppercase rounded-[1.5rem] shadow-2xl shadow-orange-100">Launch Mission</Button>
           </form>
        </Overlay>
      )}

      {modals.join && (
        <Overlay title="Add to Order" onClose={() => setModals({...modals, join: null})}>
           <form onSubmit={(e) => { e.preventDefault(); actions.join(modals.join); }} className="space-y-6">
              <input required autoFocus className="w-full p-5 bg-slate-50 rounded-[1.5rem] font-bold" placeholder="What are you ordering?" value={inputs.item} onChange={e => setInputs({...inputs, item: e.target.value})} />
              <input required className="w-full p-5 bg-slate-50 rounded-[1.5rem] font-bold" placeholder="Pickup Floor" value={inputs.floor} onChange={e => setInputs({...inputs, floor: e.target.value})} />
              <Button type="submit" className="w-full h-16 bg-indigo-600 text-[12px] font-black uppercase rounded-[1.5rem]">Manifest Order</Button>
           </form>
        </Overlay>
      )}

      {modals.arrive && (
        <Overlay title="Arrived!" onClose={() => setModals({...modals, arrive: null})}>
