import React, { useState, useEffect, useMemo, useRef } from 'react';
import { FoodRun, Order, WaitingOrder } from './types';
import { Button } from './components/Button';
import { sendToGoogleChat } from './services/googleChatService';

/**
 * GLOBAL CLOUD SYNC CONFIG
 * Key-value storage for cross-computer synchronization.
 */
const CLOUD_SYNC_URL = 'https://keyvalue.xyz/1'; 

const extractDomain = (email: string) => email.split('@')[1]?.toLowerCase() || 'public';

const extractNameFromEmail = (email: string): string => {
  if (!email) return 'User';
  const namePart = email.split('@')[0];
  return namePart
    .split(/[._-]/)
    .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(' ');
};

const App: React.FC = () => {
  const [user, setUser] = useState<{ name: string; email: string; isAdmin?: boolean } | null>(null);
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastUpdateTs, setLastUpdateTs] = useState<number>(0);
  const [view, setView] = useState<'app' | 'admin'>('app');
  const [simulatorMode, setSimulatorMode] = useState(false);
  const [webhookUrl, setWebhookUrl] = useState<string>(localStorage.getItem('lunchrun_webhook') || '');

  // Persistent Ref to track what we've already synced to avoid loops
  const lastKnownCloudTs = useRef<number>(0);

  const getSyncKey = () => {
    if (!user) return null;
    const domain = extractDomain(user.email);
    return `lunchrun_v5_live_${domain.replace(/[^a-zA-Z0-9]/g, '')}`;
  };

  const pushToCloud = async (currentRuns: FoodRun[], currentWait: WaitingOrder[], currentHistory: FoodRun[]) => {
    const key = getSyncKey();
    if (!key) return;

    const newTs = Date.now();
    lastKnownCloudTs.current = newTs;
    setLastUpdateTs(newTs);
    setIsSyncing(true);

    try {
      const payload = { 
        runs: currentRuns, 
        waitlist: currentWait, 
        history: currentHistory, 
        ts: newTs,
        sender: user?.email 
      };

      await fetch(`${CLOUD_SYNC_URL}/${key}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
    } catch (e) {
      console.error("Sync Push Error:", e);
    } finally {
      setTimeout(() => setIsSyncing(false), 400);
    }
  };

  const pullFromCloud = async () => {
    const key = getSyncKey();
    if (!key) return;

    try {
      const res = await fetch(`${CLOUD_SYNC_URL}/${key}`);
      if (res.ok) {
        const text = await res.text();
        if (!text) return;
        const data = JSON.parse(text);

        // ONLY update if the cloud has a strictly newer version than what we have locally
        if (data.ts > lastKnownCloudTs.current) {
          lastKnownCloudTs.current = data.ts;
          setRuns(data.runs || []);
          setWaitingOrders(data.waitlist || []);
          setHistory(data.history || []);
          setLastUpdateTs(data.ts);

          setIsSyncing(true);
          setTimeout(() => setIsSyncing(false), 300);
        }
      }
    } catch (e) {
      console.error("Sync Pull Error:", e);
    }
  };

  // AGGRESSIVE POLLING: Every 2 seconds for real-time feel between machines
  useEffect(() => {
    if (!user) return;
    const interval = setInterval(pullFromCloud, 2000);
    pullFromCloud();
    return () => clearInterval(interval);
  }, [user?.email]);

  const updateAndSync = (newRuns: FoodRun[], newWait: WaitingOrder[], newHistory: FoodRun[]) => {
    setRuns(newRuns);
    setWaitingOrders(newWait);
    setHistory(newHistory);
    pushToCloud(newRuns, newWait, newHistory);
  };

  if (!user) {
    return (
      <div className="h-screen flex flex-col items-center justify-center p-8 bg-white">
        <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-3xl mb-8 shadow-2xl shadow-indigo-100">
          <i className="fas fa-motorcycle"></i>
        </div>
        <h1 className="text-3xl font-black text-slate-800 tracking-tighter mb-8 italic uppercase">LunchRun</h1>
        <form 
          onSubmit={(e) => { 
            e.preventDefault(); 
            const emailInput = (e.currentTarget.elements[0] as HTMLInputElement).value;
            setUser({ name: extractNameFromEmail(emailInput), email: emailInput, isAdmin: false });
          }} 
          className="w-full max-w-xs space-y-4"
        >
          <input required type="email" placeholder="כתובת מייל של החברה" className="w-full p-5 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl font-bold outline-none transition-all text-center" />
          <button type="submit" className="w-full h-16 bg-orange-600 hover:bg-orange-700 text-white font-black uppercase rounded-2xl shadow-xl shadow-orange-100 transition-all active:scale-95">כניסה למערכת</button>
          <button type="button" onClick={() => setUser({ name: 'מנהל מערכת', email: 'admin@system.local', isAdmin: true })} className="w-full py-2 text-[10px] font-black text-slate-300 uppercase tracking-widest hover:text-slate-500 transition-colors">כניסת אדמין</button>
        </form>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white">
      {/* אדמין בלבד - לניהול וסימולציה */}
      {user.isAdmin && (
        <div className="bg-[#0f172a] text-white/50 px-6 py-2 flex justify-between items-center text-[10px] font-black uppercase tracking-widest sticky top-0 z-[100]">
          <div className="flex items-center gap-3">
            <div className={`w-2 h-2 rounded-full ${isSyncing ? 'bg-amber-400 animate-pulse' : 'bg-emerald-400'}`}></div>
            <span>מערכת שליטה ובקרה</span>
          </div>
          <div className="flex gap-4">
            <button onClick={() => setView(view === 'admin' ? 'app' : 'admin')} className={`px-4 py-1 rounded-full border transition-all ${view === 'admin' ? 'bg-indigo-600 text-white' : 'border-slate-700'}`}>
              {view === 'admin' ? 'חזרה לאפליקציה' : 'דאשבורד'}
            </button>
            <button onClick={() => setSimulatorMode(!simulatorMode)} className="px-4 py-1 rounded-full border border-slate-700">סימולציה</button>
          </div>
        </div>
      )}

      {view === 'admin' ? (
        <AdminDashboard runs={runs} waitingOrders={waitingOrders} history={history} onReset={() => updateAndSync([], [], [])} />
      ) : (
        <div className={`max-w-4xl mx-auto px-4 py-10 ${simulatorMode ? 'flex flex-col md:flex-row gap-12 max-w-7xl' : ''}`}>
           <div className="flex-1">
              <AppHeader user={user} isSyncing={isSyncing} />
              <AppInstance 
                user={user} 
                runs={runs} 
                history={history}
                waitingOrders={waitingOrders}
                updateAll={(r: any, w: any, h: any) => updateAndSync(r, w, h)}
                webhookUrl={webhookUrl}
                setWebhookUrl={(url: string) => { setWebhookUrl(url); localStorage.setItem('lunchrun_webhook', url); }}
              />
           </div>

           {simulatorMode && user.isAdmin && (
             <div className="flex-1 border-l border-slate-100 pl-12">
                <div className="text-[10px] font-black text-emerald-600 uppercase mb-8 text-center tracking-widest">מצב סימולציה: משתמש חיצוני</div>
                <AppHeader user={{ name: 'Niv Shtaif', email: 'niv.shtaif@naturalint.com' }} isSyncing={isSyncing} />
                <AppInstance 
                  user={{ name: 'Niv Shtaif', email: 'niv.shtaif@naturalint.com' }} 
                  runs={runs} 
                  history={history}
                  waitingOrders={waitingOrders}
                  updateAll={(r: any, w: any, h: any) => updateAndSync(r, w, h)}
                  webhookUrl={webhookUrl}
                  setWebhookUrl={() => {}}
                />
             </div>
           )}
        </div>
      )}
    </div>
  );
};

const AppHeader: React.FC<{ user: any; isSyncing: boolean }> = ({ user, isSyncing }) => (
  <header className="flex justify-between items-center mb-10 px-2">
    <div className="flex items-center gap-5">
      <div className="w-14 h-14 rounded-2xl bg-[#6366f1] flex items-center justify-center text-white text-2xl shadow-xl shadow-indigo-100">
