const AppInstance: React.FC<any> = ({ user, runs, history, waitingOrders, updateAll, webhookUrl, setWebhookUrl }) => {
  const [modals, setModals] = useState<{ [key: string]: any }>({ create: false, waitlist: false, join: null, arrive: null });
  const [inputs, setInputs] = useState({ dest: '', time: 20, max: 5, item: '', floor: '', loc: '' });

  const actions = {
    createRun: (e: React.FormEvent) => {
      e.preventDefault();
      const newRun: FoodRun = {
        id: Math.random().toString(36).substr(2, 9), runnerName: user.name, runnerEmail: user.email,
        destination: inputs.dest, departureTime: Date.now() + inputs.time * 60000, minutesUntilDeparture: inputs.time,
        maxOrders: inputs.max, status: 'active', orders: []
      };
      updateAll([newRun, ...runs], waitingOrders, history);
      setModals({ ...modals, create: false });
      sendToGoogleChat(webhookUrl, { title: "משלוח חדש יוצא!", subtitle: inputs.dest, details: `יציאה בעוד ${inputs.time} דקות. הרץ: ${user.name}`, prefix: "[LunchRun]" });
    },
    join: (runId: string) => {
      const order: Order = { id: Math.random().toString(36).substr(2, 9), userName: user.name, userEmail: user.email, itemDescription: inputs.item, floor: inputs.floor, cibusCode: '', timestamp: Date.now() };
      const newRuns = runs.map((r: any) => r.id === runId ? { ...r, orders: [...r.orders, order] } : r);
      updateAll(newRuns, waitingOrders, history);
      setModals({ ...modals, join: null });
    },
    depart: (runId: string) => {
      const newRuns = runs.map((r: any) => r.id === runId ? { ...r, status: 'departed' } : r);
      updateAll(newRuns, waitingOrders, history);
      sendToGoogleChat(webhookUrl, { title: "הרץ יצא לדרך!", subtitle: "האוכל בדרך אליכם", details: "נא להכין קודי סיבוס במידת הצורך.", prefix: "[LunchRun]" });
    },
    arrive: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      const finishedRun = { ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() };
      updateAll(runs.filter((r: any) => r.id !== runId), waitingOrders, [finishedRun, ...history]);
      setModals({ ...modals, arrive: null });
      sendToGoogleChat(webhookUrl, { title: "האוכל הגיע!", subtitle: inputs.loc, details: `ניתן לאסוף את ההזמנות מ${run.destination}`, prefix: "[LunchRun]" });
    }
  };

  return (
    <main className="space-y-6">
      <div className="bg-[#f8fafc] p-2 rounded-2xl flex justify-between items-center border border-slate-100 shadow-sm">
        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-4">NETWORK STATUS: ONLINE</span>
        <div className="flex gap-2">
          <Button onClick={() => setModals({...modals, waitlist: true})} variant="ghost" className="h-10 px-4 text-[10px] font-black uppercase rounded-xl bg-white border">WAITLIST</Button>
          <Button onClick={() => setModals({...modals, create: true})} className="h-10 px-6 text-[10px] font-black uppercase rounded-xl bg-orange-600 text-white shadow-lg shadow-orange-100">START RUN</Button>
        </div>
      </div>

      <div className="space-y-6">
        {runs.length === 0 ? (
          <div className="py-20 text-center opacity-30">
            <i className="fas fa-ghost text-4xl mb-4"></i>
            <p className="text-[11px] font-black uppercase tracking-[0.3em]">ALL CLEAR</p>
          </div>
        ) : runs.map((run: FoodRun) => {
          const isRunner = user.email === run.runnerEmail;
          const alreadyJoined = run.orders.some(o => o.userEmail === user.email);
          return (
            <div key={run.id} className="bg-white rounded-[2.5rem] p-8 shadow-2xl shadow-slate-200/60 border border-slate-50 animate-in fade-in zoom-in-95 duration-500">
              <div className="flex justify-between items-start mb-6">
                <div className="flex gap-5">
                  <div className="w-16 h-16 rounded-3xl bg-slate-50 flex items-center justify-center text-3xl text-slate-300">
                    <i className={`fas ${run.status === 'departed' ? 'fa-motorcycle text-indigo-500' : 'fa-hamburger'}`}></i>
                  </div>
                  <div>
                    <h4 className="text-2xl font-black text-slate-900 tracking-tight italic uppercase">{run.destination}</h4>
                    <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mt-1">
                      {run.runnerName} • <span className={run.status === 'departed' ? 'text-indigo-600' : 'text-emerald-500'}>{run.status.toUpperCase()}</span>
                    </p>
                  </div>
                </div>
              </div>

              {run.orders.length > 0 && (
                <div className="space-y-2 mb-8">
                  {run.orders.map((o: any) => (
                    <div key={o.id} className="flex justify-between items-center p-4 rounded-2xl text-sm bg-slate-50/50 border border-slate-50">
                      <span className="font-bold text-slate-700">{o.userName}: <span className="font-normal text-slate-400 italic">"{o.itemDescription}"</span></span>
                      {o.cibusCode && <span className="text-[10px] font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full">{o.cibusCode}</span>}
                    </div>
                  ))}
                </div>
              )}

              <div className="flex gap-4">
                {isRunner ? (
                  run.status === 'active' ? 
                    <Button onClick={() => actions.depart(run.id)} className="w-full h-16 bg-orange-600 hover:bg-orange-700 text-[13px] font-black uppercase rounded-2xl shadow-xl shadow-orange-100">DEPART NOW</Button> :
                    <Button onClick={() => setModals({...modals, arrive: run.id})} className="w-full h-16 bg-emerald-600 hover:bg-emerald-700 text-[13px] font-black uppercase rounded-2xl text-white">I HAVE ARRIVED</Button>
                ) : !alreadyJoined && run.status === 'active' && (
                  <Button onClick={() => setModals({...modals, join: run.id})} className="w-full h-16 bg-slate-900 text-[13px] font-black uppercase rounded-2xl">JOIN MISSION</Button>
                )}
                {alreadyJoined && <div className="w-full text-center py-5 text-[11px] font-black uppercase text-indigo-400 tracking-widest bg-indigo-50 rounded-2xl"><i className="fas fa-check-circle mr-2"></i> IN MANIFEST</div>}
              </div>
            </div>
          );
        })}
      </div>

      {/* מודלים */}
      {modals.create && (
        <Overlay title="משלוח חדש" onClose={() => setModals({...modals, create: false})}>
           <form onSubmit={actions.createRun} className="space-y-5">
              <input required autoFocus className="w-full p-4 bg-slate-50 rounded-2xl font-black text-lg border-2 border-transparent focus:border-indigo-500 outline-none" placeholder="שם המסעדה / מקום" value={inputs.dest} onChange={e => setInputs({...inputs, dest: e.target.value})} />
              <div className="grid grid-cols-2 gap-4">
                 <input type="number" className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="זמן המתנה" value={inputs.time} onChange={e => setInputs({...inputs, time: Number(e.target.value)})} />
                 <input type="number" className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="מקס' מנות" value={inputs.max} onChange={e => setInputs({...inputs, max: Number(e.target.value)})} />
              </div>
              <Button type="submit" className="w-full h-14 bg-orange-600 text-[12px] font-black uppercase rounded-2xl">פרסם לעובדים</Button>
           </form>
        </Overlay>
      )}

      {modals.join && (
        <Overlay title="הצטרפות להזמנה" onClose={() => setModals({...modals, join: null})}>
           <form onSubmit={(e) => { e.preventDefault(); actions.join(modals.join); }} className="space-y-5">
              <input required autoFocus className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="מה להזמין לך?" value={inputs.item} onChange={e => setInputs({...inputs, item: e.target.value})} />
              <input required className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="קומה לאיסוף" value={inputs.floor} onChange={e => setInputs({...inputs, floor: e.target.value})} />
              <Button type="submit" className="w-full h-14 bg-indigo-600 text-[12px] font-black uppercase rounded-2xl">אשר הזמנה</Button>
           </form>
        </Overlay>
      )}

      {modals.arrive && (
        <Overlay title="הגעה ליעד" onClose={() => setModals({...modals, arrive: null})}>
