import React, { useState, useEffect, useRef } from 'react';
import { FoodRun, Order, WaitingOrder } from './types';
import { Button } from './components/Button';
import { sendToGoogleChat } from './services/googleChatService';

/**
 * CONFIGURATION
 * Using JSONBlob for more stable CORS-friendly sync.
 */
const SYNC_SERVICE_BASE = 'https://jsonblob.com/api/jsonBlob';
// We use a fixed ID derived from the domain to keep everyone in the same company synced.
// For this demo, we'll use a fallback ID that represents the shared "company" space.
const DEFAULT_BLOB_ID = '1342417730990391296'; 

const extractDomain = (email: string) => email.split('@')[1]?.toLowerCase() || 'public';

const extractNameFromEmail = (email: string): string => {
  if (!email) return 'User';
  const namePart = email.split('@')[0];
  return namePart
    .split(/[._-]/)
    .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(' ');
};

const App: React.FC = () => {
  const [user, setUser] = useState<{ name: string; email: string; isAdmin?: boolean } | null>(null);
  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncError, setSyncError] = useState(false);
  const [view, setView] = useState<'app' | 'admin'>('app');
  const [simulatorMode, setSimulatorMode] = useState(false);
  const [webhookUrl, setWebhookUrl] = useState<string>(localStorage.getItem('lunchrun_webhook') || '');

  const lastUpdateRef = useRef<number>(0);

  // Sync Logic: Pushing local state to the cloud
  const pushToCloud = async (currentRuns: FoodRun[], currentWait: WaitingOrder[], currentHistory: FoodRun[]) => {
    setIsSyncing(true);
    const ts = Date.now();
    lastUpdateRef.current = ts;

    try {
      const payload = { 
        runs: currentRuns, 
        waitlist: currentWait, 
        history: currentHistory, 
        ts,
        sender: user?.email 
      };

      await fetch(`${SYNC_SERVICE_BASE}/${DEFAULT_BLOB_ID}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      setSyncError(false);
    } catch (e) {
      console.warn("Sync temporarily unavailable (Push)");
      setSyncError(true);
    } finally {
      setTimeout(() => setIsSyncing(false), 500);
    }
  };

  // Sync Logic: Pulling remote state
  const pullFromCloud = async () => {
    if (isSyncing) return;

    try {
      const res = await fetch(`${SYNC_SERVICE_BASE}/${DEFAULT_BLOB_ID}`);
      if (res.ok) {
        const data = await res.json();

        // Only update if remote data is newer than our last local action
        if (data.ts > lastUpdateRef.current) {
          setRuns(data.runs || []);
          setWaitingOrders(data.waitlist || []);
          setHistory(data.history || []);
          lastUpdateRef.current = data.ts;
          setSyncError(false);
        }
      }
    } catch (e) {
      // Silent fail to avoid UI spam shown in user's screenshot
      setSyncError(true);
    }
  };

  // Polling: Every 2.5 seconds for "Live" feel
  useEffect(() => {
    if (!user) return;
    const interval = setInterval(pullFromCloud, 2500);
    pullFromCloud();
    return () => clearInterval(interval);
  }, [user?.email]);

  const updateAndSync = (newRuns: FoodRun[], newWait: WaitingOrder[], newHistory: FoodRun[]) => {
    setRuns(newRuns);
    setWaitingOrders(newWait);
    setHistory(newHistory);
    pushToCloud(newRuns, newWait, newHistory);
  };

  if (!user) {
    return (
      <div className="h-screen flex flex-col items-center justify-center p-8 bg-white" dir="rtl">
        <div className="w-20 h-20 bg-[#6366f1] rounded-[2rem] flex items-center justify-center text-white text-4xl mb-8 shadow-2xl shadow-indigo-100">
          <i className="fas fa-burger"></i>
        </div>
        <h1 className="text-4xl font-black text-slate-800 tracking-tighter mb-8 italic uppercase">LunchRun</h1>
        <form 
          onSubmit={(e) => { 
            e.preventDefault(); 
            const emailInput = (e.currentTarget.elements[0] as HTMLInputElement).value;
            setUser({ name: extractNameFromEmail(emailInput), email: emailInput, isAdmin: false });
          }} 
          className="w-full max-w-xs space-y-4"
        >
          <input required type="email" placeholder="אימייל ארגוני" className="w-full p-5 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-3xl font-bold outline-none transition-all text-center" />
          <button type="submit" className="w-full h-16 bg-orange-600 hover:bg-orange-700 text-white font-black uppercase rounded-3xl shadow-xl shadow-orange-100 transition-all active:scale-95">כניסה למערכת</button>
          <button type="button" onClick={() => setUser({ name: 'מנהל מערכת', email: 'admin@system.local', isAdmin: true })} className="w-full py-2 text-[10px] font-black text-slate-300 uppercase tracking-widest hover:text-slate-500 transition-colors">כניסת מנהל</button>
        </form>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white font-sans" dir="rtl">
      {user.isAdmin && (
        <div className="bg-[#0f172a] text-white/50 px-6 py-2 flex justify-between items-center text-[10px] font-black uppercase tracking-widest sticky top-0 z-[100]" dir="ltr">
          <div className="flex items-center gap-3">
            <div className={`w-2 h-2 rounded-full ${syncError ? 'bg-red-500' : isSyncing ? 'bg-amber-400 animate-pulse' : 'bg-emerald-400'}`}></div>
            <span>FLEET COMMAND</span>
          </div>
          <div className="flex gap-4">
            <button onClick={() => setView(view === 'admin' ? 'app' : 'admin')} className="hover:text-white transition-colors">
              {view === 'admin' ? 'חזרה' : 'ניהול'}
            </button>
            <button onClick={() => setSimulatorMode(!simulatorMode)} className="hover:text-white transition-colors">סימולציה</button>
          </div>
        </div>
      )}

      {view === 'admin' ? (
        <AdminDashboard runs={runs} waitingOrders={waitingOrders} history={history} onReset={() => updateAndSync([], [], [])} />
      ) : (
        <div className={`max-w-4xl mx-auto px-6 py-12 ${simulatorMode ? 'flex flex-col md:flex-row gap-12 max-w-7xl' : ''}`}>
           <div className="flex-1">
              <AppHeader user={user} isSyncing={isSyncing} syncError={syncError} />
              <AppInstance 
                user={user} 
                runs={runs} 
                history={history}
                waitingOrders={waitingOrders}
                updateAll={(r: any, w: any, h: any) => updateAndSync(r, w, h)}
                webhookUrl={webhookUrl}
                setWebhookUrl={(url: string) => { setWebhookUrl(url); localStorage.setItem('lunchrun_webhook', url); }}
              />
           </div>

           {simulatorMode && user.isAdmin && (
             <div className="flex-1 border-r border-slate-100 pr-12">
                <div className="text-[10px] font-black text-emerald-600 uppercase mb-8 text-center tracking-widest opacity-50">מבט משתמש נוסף (Niv)</div>
                <AppHeader user={{ name: 'Niv Shtaif', email: 'niv.shtaif@naturalint.com' }} isSyncing={isSyncing} syncError={syncError} />
                <AppInstance 
                  user={{ name: 'Niv Shtaif', email: 'niv.shtaif@naturalint.com' }} 
                  runs={runs} 
                  history={history}
                  waitingOrders={waitingOrders}
                  updateAll={(r: any, w: any, h: any) => updateAndSync(r, w, h)}
                  webhookUrl={webhookUrl}
                  setWebhookUrl={() => {}}
                />
             </div>
           )}
        </div>
      )}
    </div>
  );
};

const AppHeader: React.FC<{ user: any; isSyncing: boolean; syncError: boolean }> = ({ user, isSyncing, syncError }) => (
  <header className="flex justify-between items-center mb-12">
    <div className="flex items-center gap-5">
      <div className="w-16 h-16 rounded-[1.5rem] bg-[#6366f1] flex items-center justify-center text-white text-3xl shadow-2xl shadow-indigo-100">
