);

const AppInstance: React.FC<any> = ({ user, runs, history, waitingOrders, updateAll, webhookUrl, setWebhookUrl }) => {
  const [modals, setModals] = useState<{ [key: string]: any }>({ create: false, waitlist: false, join: null, arrive: null });
  const [inputs, setInputs] = useState({ dest: '', time: 20, max: 5, item: '', floor: '', loc: '' });

  const actions = {
    createRun: (e: React.FormEvent) => {
      e.preventDefault();
      const newRun: FoodRun = {
        id: Math.random().toString(36).substr(2, 9), runnerName: user.name, runnerEmail: user.email,
        destination: inputs.dest, departureTime: Date.now() + inputs.time * 60000, minutesUntilDeparture: inputs.time,
        maxOrders: inputs.max, status: 'active', orders: []
      };
      updateAll([newRun, ...runs], waitingOrders, history);
      setModals({ ...modals, create: false });
      sendToGoogleChat(webhookUrl, { title: "משלוח חדש!", subtitle: inputs.dest, details: `יציאה בעוד ${inputs.time} דקות. באחריות: ${user.name}`, prefix: "[LunchRun]" });
    },
    join: (runId: string) => {
      const order: Order = { id: Math.random().toString(36).substr(2, 9), userName: user.name, userEmail: user.email, itemDescription: inputs.item, floor: inputs.floor, cibusCode: '', timestamp: Date.now() };
      const newRuns = runs.map((r: any) => r.id === runId ? { ...r, orders: [...r.orders, order] } : r);
      updateAll(newRuns, waitingOrders, history);
      setModals({ ...modals, join: null });
    },
    depart: (runId: string) => {
      const newRuns = runs.map((r: any) => r.id === runId ? { ...r, status: 'departed' } : r);
      updateAll(newRuns, waitingOrders, history);
      sendToGoogleChat(webhookUrl, { title: "יצאנו לדרך!", subtitle: "האוכל בדרך אליכם", details: "נא להכין קוד סיבוס אם צריך.", prefix: "[LunchRun]" });
    },
    arrive: (runId: string) => {
      const run = runs.find((r: any) => r.id === runId);
      const finishedRun = { ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() };
      updateAll(runs.filter((r: any) => r.id !== runId), waitingOrders, [finishedRun, ...history]);
      setModals({ ...modals, arrive: null });
      sendToGoogleChat(webhookUrl, { title: "האוכל הגיע!", subtitle: inputs.loc, details: `הזמנות מ-${run.destination} מחכות לכם.`, prefix: "[LunchRun]" });
    }
  };

  return (
    <main className="space-y-8">
      {/* STATUS BAR */}
      <div className="bg-slate-50/50 p-2.5 rounded-[1.5rem] flex justify-between items-center border border-slate-100">
        <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] pr-6">NETWORK STATUS: ONLINE</span>
        <div className="flex gap-2">
          <Button onClick={() => setModals({...modals, waitlist: true})} variant="ghost" className="h-11 px-6 text-[11px] font-black rounded-2xl bg-white border border-slate-100 shadow-sm">WAITLIST</Button>
          <Button onClick={() => setModals({...modals, create: true})} className="h-11 px-8 text-[11px] font-black rounded-2xl bg-orange-600 text-white shadow-xl shadow-orange-100">START RUN</Button>
        </div>
      </div>

      {/* ACTIVE RUNS */}
      <div className="space-y-10">
        {runs.length === 0 ? (
          <div className="py-28 text-center opacity-20 flex flex-col items-center">
            <i className="fas fa-ghost text-5xl mb-6"></i>
            <p className="text-[12px] font-black uppercase tracking-[0.4em]">ALL CLEAR</p>
          </div>
        ) : runs.map((run: FoodRun) => {
          const isRunner = user.email === run.runnerEmail;
          const joined = run.orders.some(o => o.userEmail === user.email);
          return (
            <div key={run.id} className="bg-white rounded-[3rem] p-10 shadow-[0_35px_70px_-15px_rgba(0,0,0,0.08)] border border-slate-50 transition-all">
              <div className="flex justify-between items-start mb-10">
                <div className="flex gap-6">
                  <div className="w-20 h-20 rounded-[1.75rem] bg-slate-50 flex items-center justify-center text-4xl text-slate-200">
                    <i className={`fas ${run.status === 'departed' ? 'fa-motorcycle text-indigo-400' : 'fa-burger'}`}></i>
                  </div>
                  <div>
                    <h4 className="text-3xl font-black text-slate-900 tracking-tighter italic uppercase">{run.destination}</h4>
                    <div className="flex items-center gap-3 mt-2">
                       <span className="text-[11px] font-black text-slate-400 uppercase tracking-widest">{run.runnerName}</span>
                       <span className={`text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-widest ${run.status === 'departed' ? 'bg-indigo-50 text-indigo-600' : 'bg-emerald-50 text-emerald-600'}`}>
                         • {run.status === 'active' ? 'פעיל' : 'בדרך'}
                       </span>
                    </div>
                  </div>
                </div>
              </div>

              {run.orders.length > 0 && (
                <div className="space-y-3 mb-12">
                  {run.orders.map((o: any) => (
                    <div key={o.id} className="flex justify-between items-center p-5 rounded-[1.5rem] bg-slate-50/50 border border-slate-100/50">
                      <span className="font-bold text-slate-700 text-sm">{o.userName}: <span className="font-normal text-slate-400 italic">"{o.itemDescription}"</span></span>
                      <span className="text-[10px] font-black text-slate-300">קומה {o.floor}</span>
                    </div>
                  ))}
                </div>
              )}

              {/* ACTION BUTTON - FULL WIDTH AND ORANGE AS REQUESTED */}
              <div className="w-full">
                {isRunner ? (
                  run.status === 'active' ? 
                    <Button onClick={() => actions.depart(run.id)} className="w-full h-20 bg-orange-600 hover:bg-orange-700 text-lg font-black uppercase rounded-[1.75rem] shadow-2xl shadow-orange-200">צא לדרך עכשיו</Button> :
                    <Button onClick={() => setModals({...modals, arrive: run.id})} className="w-full h-20 bg-emerald-600 hover:bg-emerald-700 text-lg font-black uppercase rounded-[1.75rem] text-white">הגעתי!</Button>
                ) : !joined && run.status === 'active' ? (
                  <Button onClick={() => setModals({...modals, join: run.id})} className="w-full h-20 bg-slate-900 hover:bg-black text-lg font-black uppercase rounded-[1.75rem] text-white">הצטרפות למשימה</Button>
                ) : joined && (
                  <div className="w-full py-8 text-center text-[13px] font-black uppercase text-indigo-400 tracking-[0.2em] bg-indigo-50/50 rounded-[1.75rem]">אתה ברשימה <i className="fas fa-check-circle ml-2"></i></div>
                )}
              </div>
            </div>
          );
        })}
      </div>

      {/* MODALS */}
      {modals.create && (
        <Overlay title="התחלת משלוח חדש" onClose={() => setModals({...modals, create: false})}>
           <form onSubmit={actions.createRun} className="space-y-6">
              <input required autoFocus className="w-full p-5 bg-slate-50 rounded-[1.5rem] font-black text-lg border-2 border-transparent focus:border-indigo-500 outline-none" placeholder="שם המסעדה / יעד" value={inputs.dest} onChange={e => setInputs({...inputs, dest: e.target.value})} />
