                 <input type="number" className="w-full p-5 bg-slate-50 rounded-[1.5rem] font-bold" placeholder="מקס' הזמנות" value={inputs.max} onChange={e => setInputs({...inputs, max: Number(e.target.value)})} />
              </div>
              <Button type="submit" className="w-full h-16 bg-orange-600 text-[12px] font-black uppercase rounded-[1.5rem] shadow-xl shadow-orange-100">פרסם לעובדים</Button>
           </form>
        </Overlay>
