           <form onSubmit={(e) => { e.preventDefault(); actions.join(modals.join); }} className="space-y-6">
              <input required autoFocus className="w-full p-5 bg-slate-50 rounded-[1.5rem] font-bold" placeholder="מה להזמין לך?" value={inputs.item} onChange={e => setInputs({...inputs, item: e.target.value})} />
              <input required className="w-full p-5 bg-slate-50 rounded-[1.5rem] font-bold" placeholder="באיזו קומה אתה?" value={inputs.floor} onChange={e => setInputs({...inputs, floor: e.target.value})} />
              <Button type="submit" className="w-full h-16 bg-indigo-600 text-[12px] font-black uppercase rounded-[1.5rem] text-white">אשר הזמנה</Button>
           </form>
        </Overlay>
      )}

      {modals.arrive && (
        <Overlay title="האוכל כאן!" onClose={() => setModals({...modals, arrive: null})}>
