/**
 * PRODUCTION-GRADE SYNC CONFIG
 * Using a more robust key-value store for near-real-time synchronization.
 */
const SYNC_SERVICE = 'https://keyvalue.xyz/8f8a1d2e/lunchrun_global_v2'; 

const extractNameFromEmail = (email: string): string => {
  if (!email) return 'User';
  const namePart = email.split('@')[0];
  return namePart
    .split(/[._-]/)
    .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(' ');
};

const App: React.FC = () => {
  const [user, setUser] = useState<{ name: string; email: string; isAdmin?: boolean } | null>(() => {
    const saved = localStorage.getItem('lunchrun_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'online' | 'syncing' | 'error'>('online');
  const [modals, setModals] = useState<{ [key: string]: any }>({ create: false, waitlist: false, join: null, arrive: null });
  const [inputs, setInputs] = useState({ dest: '', time: 20, max: 5, item: '', floor: '', loc: '' });

  const lastUpdateTs = useRef<number>(0);
  const isUpdatingRef = useRef<boolean>(false);

  // Persistence for user
  useEffect(() => {
    if (user) localStorage.setItem('lunchrun_user', JSON.stringify(user));
  }, [user]);

  // --- SYNC LOGIC ---
  const pushState = async (newRuns: FoodRun[], newWait: WaitingOrder[], newHistory: FoodRun[]) => {
    if (isUpdatingRef.current) return;
    isUpdatingRef.current = true;
    setSyncStatus('syncing');

    const ts = Date.now();
    lastUpdateTs.current = ts;

    try {
      const payload = { runs: newRuns, waitlist: newWait, history: newHistory, ts };
      await fetch(SYNC_SERVICE, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      setSyncStatus('online');
    } catch (e) {
      console.warn("Sync push failed", e);
      setSyncStatus('error');
    } finally {
      isUpdatingRef.current = false;
    }
  };

  const pullState = async () => {
    if (isUpdatingRef.current) return;

    try {
      const res = await fetch(SYNC_SERVICE);
      if (res.ok) {
        const text = await res.text();
        if (!text) return;
        const data = JSON.parse(text);

        // Only update if remote state is newer
        if (data.ts > lastUpdateTs.current) {
          setRuns(data.runs || []);
          setWaitingOrders(data.waitlist || []);
          setHistory(data.history || []);
          lastUpdateTs.current = data.ts;
          setSyncStatus('online');
        }
      }
    } catch (e) {
      setSyncStatus('error');
    }
  };

  // High-frequency polling for "Live" experience
  useEffect(() => {
    if (!user) return;
    const interval = setInterval(pullState, 1500);
    pullState();
    return () => clearInterval(interval);
  }, [user?.email]);

  const updateAll = (r: FoodRun[], w: WaitingOrder[], h: FoodRun[]) => {
    setRuns(r);
    setWaitingOrders(w);
    setHistory(h);
    pushState(r, w, h);
