  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [syncState, setSyncState] = useState<'idle' | 'syncing' | 'error'>('idle');
  const [modals, setModals] = useState<{ [key: string]: any }>({ create: false, join: null, arrive: null });
  const [inputs, setInputs] = useState({ dest: '', time: 15, max: 6, item: '', floor: '', loc: '' });

  const lastUpdateRef = useRef<number>(0);
  const isPushingRef = useRef<boolean>(false);

  // Derive workspace key from user domain
  const getWorkspaceKey = () => user ? `${CLOUD_API}${extractDomain(user.email)}` : null;

  // --- SYNC ENGINE ---
  const pushData = async (r: FoodRun[], w: WaitingOrder[], h: FoodRun[]) => {
    const url = getWorkspaceKey();
    if (!url || isPushingRef.current) return;

    isPushingRef.current = true;
    setSyncState('syncing');
    const ts = Date.now();
    lastUpdateRef.current = ts;

    try {
      await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ runs: r, waitlist: w, history: h, ts })
      });
      setSyncState('idle');
    } catch (e) {
      setSyncState('error');
    } finally {
      isPushingRef.current = false;
    }
  };

  const pullData = async () => {
    const url = getWorkspaceKey();
    if (!url || isPushingRef.current) return;

    try {
      const res = await fetch(url);
      if (res.ok) {
        const raw = await res.text();
        if (!raw) return;
        const data = JSON.parse(raw);

        // Only update if remote state is newer than our last action
        if (data.ts > lastUpdateRef.current) {
          setRuns(data.runs || []);
          setWaitingOrders(data.waitlist || []);
          setHistory(data.history || []);
          lastUpdateRef.current = data.ts;
          setSyncState('idle');
        }
      }
    } catch (e) {
      setSyncState('error');
    }
  };

  // Poll every 1 second for "Live" feel
  useEffect(() => {
    if (!user) return;
    const interval = setInterval(pullData, 1000);
    return () => clearInterval(interval);
  }, [user?.email]);

  const updateState = (r: FoodRun[], w: WaitingOrder[], h: FoodRun[]) => {
    setRuns(r);
    setWaitingOrders(w);
    setHistory(h);
    pushData(r, w, h);
  };

  // --- HANDLERS ---
  const onCreateRun = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: user.name,
      runnerEmail: user.email,
      destination: inputs.dest.toUpperCase(),
      departureTime: Date.now() + inputs.time * 60000,
      minutesUntilDeparture: inputs.time,
      maxOrders: inputs.max,
      status: 'active',
      orders: []
    };
    updateState([newRun, ...runs], waitingOrders, history);
    setModals({ ...modals, create: false });
    setInputs({ ...inputs, dest: '' });
  };

  const onJoinRun = (runId: string) => {
    if (!user) return;
    const order: Order = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      userEmail: user.email,
      itemDescription: inputs.item,
      floor: inputs.floor,
      cibusCode: '',
      timestamp: Date.now()
    };
    const updated = runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, order] } : r);
    updateState(updated, waitingOrders, history);
    setModals({ ...modals, join: null });
    setInputs({ ...inputs, item: '', floor: '' });
  };

  const onDepart = (runId: string) => {
    const updated = runs.map(r => r.id === runId ? { ...r, status: 'departed' } as FoodRun : r);
    updateState(updated, waitingOrders, history);
  };

  const onArrival = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run) return;
    const finished: FoodRun = { ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() };
    updateState(runs.filter(r => r.id !== runId), waitingOrders, [finished, ...history]);
    setModals({ ...modals, arrive: null });
  };

  if (!user) {
    return (
      <div className="min-h-screen bg-[#0a0c10] flex items-center justify-center p-6 text-white font-sans antialiased">
        <div className="w-full max-w-sm border border-slate-800 bg-slate-900/50 p-10 rounded-3xl shadow-2xl backdrop-blur-xl">
          <div className="w-12 h-12 bg-indigo-500 rounded-xl flex items-center justify-center mb-8 shadow-lg shadow-indigo-500/20">
            <i className="fas fa-terminal"></i>
          </div>
          <h1 className="text-2xl font-black italic tracking-tighter uppercase mb-2">LUNCHRUN // SYNC</h1>
          <p className="text-slate-500 text-xs font-bold uppercase tracking-widest mb-10">Access corporate workspace</p>
          <form onSubmit={(e) => {
            e.preventDefault();
            const email = (e.currentTarget.elements[0] as HTMLInputElement).value;
            const newUser = { name: extractName(email), email: email.toLowerCase() };
            setUser(newUser);
            localStorage.setItem('lr_session', JSON.stringify(newUser));
          }} className="space-y-4">
            <input required type="email" placeholder="Work Email" className="w-full h-14 px-6 bg-black/40 border border-slate-700 rounded-xl font-mono text-sm focus:border-indigo-500 outline-none transition-all" />
            <Button type="submit" className="w-full h-14 bg-indigo-600 hover:bg-indigo-500 text-white font-black uppercase tracking-widest rounded-xl">Initialize</Button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans antialiased">
      {/* PROFESSIONAL DASHBOARD HEADER */}
      <nav className="bg-white border-b border-slate-100 sticky top-0 z-40 px-6 py-4 shadow-sm">
        <div className="max-w-6xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 bg-indigo-600 rounded-lg flex items-center justify-center text-white text-lg">
              <i className="fas fa-satellite-dish"></i>
            </div>
            <div>
              <h1 className="text-sm font-black italic tracking-tighter uppercase leading-none">LUNCHRUN</h1>
              <span className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Workspace v2.0</span>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <div className="text-right hidden sm:block">
              <p className="text-xs font-black uppercase tracking-tight italic">{user.name}</p>
              <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{user.email}</p>
            </div>
            <div className={`w-2 h-2 rounded-full ${syncState === 'syncing' ? 'bg-amber-400 animate-pulse' : 'bg-emerald-500'}`}></div>
          </div>
        </div>
      </nav>

      <main className="max-w-4xl mx-auto px-6 py-10">
        {/* CONTROL PANEL */}
        <div className="flex flex-wrap gap-3 mb-12">
          <Button onClick={() => setModals({ ...modals, create: true })} className="h-12 px-8 bg-orange-600 text-white text-xs font-black uppercase tracking-widest rounded-xl shadow-lg shadow-orange-100">
            Launch Run
          </Button>
          <Button onClick={() => pullData()} variant="secondary" className="h-12 px-6 text-xs font-black uppercase tracking-widest rounded-xl">
            Refresh
          </Button>
          <div className="ml-auto flex items-center px-4 bg-slate-100 rounded-xl">
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
              Live Feed: <span className="text-emerald-600">Active</span>
            </span>
          </div>
        </div>

        {/* MISSIONS GRID */}
        <div className="space-y-6">
          {runs.length === 0 ? (
            <div className="py-32 border-2 border-dashed border-slate-200 rounded-3xl flex flex-col items-center justify-center text-center opacity-40">
              <i className="fas fa-radar text-4xl mb-4"></i>
              <p className="text-xs font-black uppercase tracking-[0.5em]">No Active Missions</p>
            </div>
          ) : (
            runs.map(run => {
              const isOwner = user.email === run.runnerEmail;
              const hasJoined = run.orders.some(o => o.userEmail === user.email);

              return (
                <div key={run.id} className="bg-white border border-slate-100 rounded-2xl overflow-hidden shadow-sm hover:shadow-md transition-shadow">
                  <div className="p-8">
                    <div className="flex justify-between items-start mb-8">
                      <div className="flex items-center gap-5">
                        <div className="w-14 h-14 bg-slate-50 border border-slate-100 rounded-xl flex items-center justify-center text-slate-300 text-2xl">
                          <i className={`fas ${run.status === 'departed' ? 'fa-truck-fast text-indigo-500' : 'fa-box-open'}`}></i>
                        </div>
                        <div>
                          <h3 className="text-2xl font-black italic tracking-tighter uppercase text-slate-900">{run.destination}</h3>
                          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
                            Officer: {run.runnerName} • <span className={run.status === 'active' ? 'text-emerald-500' : 'text-indigo-500'}>{run.status.toUpperCase()}</span>
                          </p>
                        </div>
                      </div>
                      {run.status === 'active' && (
                        <div className="bg-slate-50 px-4 py-2 rounded-lg border border-slate-100 text-center">
                           <p className="text-[9px] font-bold text-slate-400 uppercase mb-0.5">Payload</p>
                           <p className="text-xs font-black text-slate-900">{run.orders.length} / {run.maxOrders}</p>
                        </div>
                      )}
                    </div>

                    {run.orders.length > 0 && (
                      <div className="space-y-2 mb-8 border-l-2 border-slate-50 pl-6">
                        {run.orders.map(o => (
                          <div key={o.id} className="text-sm font-semibold text-slate-600 flex justify-between items-center group">
                            <span>{o.userName} <span className="text-slate-300 font-normal">ordered</span> {o.itemDescription}</span>
                            <span className="text-[9px] font-black uppercase text-slate-300 opacity-0 group-hover:opacity-100 transition-opacity">Floor {o.floor}</span>
                          </div>
                        ))}
                      </div>
                    )}

                    <div className="flex gap-3">
                      {isOwner ? (
                        run.status === 'active' ? (
                          <Button onClick={() => onDepart(run.id)} className="flex-1 h-14 bg-orange-600 text-white font-black uppercase tracking-widest rounded-xl">Depart Workspace</Button>
                        ) : (
                          <Button onClick={() => setModals({ ...modals, arrive: run.id })} className="flex-1 h-14 bg-indigo-600 text-white font-black uppercase tracking-widest rounded-xl">Signal Arrival</Button>
                        )
                      ) : (
                        !hasJoined && run.status === 'active' ? (
                          <Button onClick={() => setModals({ ...modals, join: run.id })} className="flex-1 h-14 bg-slate-900 text-white font-black uppercase tracking-widest rounded-xl">Join manifest</Button>
                        ) : (
                          <div className="flex-1 h-14 flex items-center justify-center bg-emerald-50 border border-emerald-100 text-emerald-600 text-[11px] font-black uppercase tracking-widest rounded-xl italic">
                            Manifest Confirmed
                          </div>
                        )
                      )}
                    </div>
                  </div>
                </div>
              );
            })
          )}
        </div>
      </main>

      {/* MODAL SYSTEM */}
      {modals.create && (
        <Overlay title="Initialize New Mission" onClose={() => setModals({ ...modals, create: false })}>
          <form onSubmit={onCreateRun} className="space-y-4">
             <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Objective (Restaurant)</label>
                <input required autoFocus className="w-full h-14 px-6 bg-slate-50 border border-slate-200 rounded-xl font-bold focus:border-indigo-500 outline-none uppercase" placeholder="e.g. Vitrina / Hummus" value={inputs.dest} onChange={e => setInputs({ ...inputs, dest: e.target.value })} />
             </div>
             <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Launch Delay (Min)</label>
                  <input type="number" className="w-full h-14 px-6 bg-slate-50 border border-slate-200 rounded-xl font-bold outline-none" value={inputs.time} onChange={e => setInputs({ ...inputs, time: Number(e.target.value) })} />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Max Capacity</label>
                  <input type="number" className="w-full h-14 px-6 bg-slate-50 border border-slate-200 rounded-xl font-bold outline-none" value={inputs.max} onChange={e => setInputs({ ...inputs, max: Number(e.target.value) })} />
                </div>
             </div>
             <Button type="submit" className="w-full h-14 bg-indigo-600 text-white font-black uppercase tracking-widest rounded-xl">Broadcast</Button>
          </form>
        </Overlay>
      )}

      {modals.join && (
        <Overlay title="Mission Request" onClose={() => setModals({ ...modals, join: null })}>
          <form onSubmit={(e) => { e.preventDefault(); onJoinRun(modals.join); }} className="space-y-4">
             <input required autoFocus className="w-full h-14 px-6 bg-slate-50 border border-slate-200 rounded-xl font-bold outline-none" placeholder="Your Order Description" value={inputs.item} onChange={e => setInputs({ ...inputs, item: e.target.value })} />
             <input required className="w-full h-14 px-6 bg-slate-50 border border-slate-200 rounded-xl font-bold outline-none" placeholder="Floor / Desk" value={inputs.floor} onChange={e => setInputs({ ...inputs, floor: e.target.value })} />
             <Button type="submit" className="w-full h-14 bg-slate-900 text-white font-black uppercase tracking-widest rounded-xl italic">Request Manifest Add</Button>
          </form>
        </Overlay>
      )}

      {modals.arrive && (
        <Overlay title="Mission Completion" onClose={() => setModals({ ...modals, arrive: null })}>
          <form onSubmit={(e) => { e.preventDefault(); onArrival(modals.arrive); }} className="space-y-6">
             <div className="text-center">
                <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-4">Final Drop Point</p>
                <input required autoFocus className="w-full h-16 bg-slate-50 border border-slate-200 rounded-xl font-black text-center text-xl outline-none focus:border-indigo-500" placeholder="e.g. Kitchen Floor 4" value={inputs.loc} onChange={e => setInputs({ ...inputs, loc: e.target.value })} />
             </div>
             <Button type="submit" className="w-full h-16 bg-emerald-600 text-white font-black uppercase tracking-widest rounded-xl">Signal Arrival</Button>
          </form>
        </Overlay>
      )}
    </div>
  );
};

const Overlay: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
  <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-50 flex items-center justify-center p-6 animate-in fade-in duration-300">
    <div className="bg-white rounded-2xl p-10 w-full max-w-md shadow-2xl relative border border-white">
      <div className="flex justify-between items-center mb-8">
         <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-indigo-600 italic">{title}</h3>
         <button onClick={onClose} className="w-8 h-8 rounded-full hover:bg-slate-50 flex items-center justify-center text-slate-300 hover:text-slate-900 transition-colors">
            <i className="fas fa-times"></i>
         </button>
      </div>
      {children}
    </div>
