);

export default App;

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center gap-2 font-bold transition-all duration-150 antialiased active:scale-[0.97] disabled:opacity-50 disabled:cursor-not-allowed";

  const variants = {
    primary: "bg-orange-600 text-white hover:brightness-110",
    secondary: "bg-white border border-slate-200 text-slate-900 hover:bg-slate-50 hover:border-slate-300",
    danger: "bg-red-500 text-white hover:bg-red-600",
    ghost: "text-slate-500 hover:text-slate-900 hover:bg-slate-100"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${className}`} 
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading ? <i className="fas fa-circle-notch fa-spin text-sm"></i> : children}
    </button>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { FoodRun, Order, WaitingOrder } from './types';
import { Button } from './components/Button';

// Global Sync Endpoint - Partitioned by domain for company-wide live updates
const SYNC_SERVICE = 'https://keyvalue.xyz/ad8f7b2c_lunchrun_v3_';

const extractDomain = (email: string) => {
  const domain = email.split('@')[1] || 'public';
  return domain.replace(/[^a-zA-Z0-9]/g, '_');
};

const extractName = (email: string) => {
  return email.split('@')[0]
    .split(/[._-]/)
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
};

const App: React.FC = () => {
  const [user, setUser] = useState<{ name: string; email: string } | null>(() => {
    const saved = localStorage.getItem('lr_session_v3');
    return saved ? JSON.parse(saved) : null;
  });

  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [syncStatus, setSyncStatus] = useState<'online' | 'syncing' | 'error'>('online');
  const [modals, setModals] = useState<{ [key: string]: any }>({ create: false, join: null, arrive: null });
  const [inputs, setInputs] = useState({ dest: '', time: 15, max: 6, item: '', floor: '', loc: '' });

  const lastUpdateRef = useRef<number>(0);
  const isUpdatingRef = useRef<boolean>(false);

  useEffect(() => {
    if (user) localStorage.setItem('lr_session_v3', JSON.stringify(user));
  }, [user]);

  const getSyncUrl = () => user ? `${SYNC_SERVICE}${extractDomain(user.email)}` : null;

  // --- SYNC ENGINE ---
  const pushState = async (newRuns: FoodRun[], newWait: WaitingOrder[], newHistory: FoodRun[]) => {
    const url = getSyncUrl();
    if (!url || isUpdatingRef.current) return;

    isUpdatingRef.current = true;
    setSyncStatus('syncing');
    const ts = Date.now();
    lastUpdateRef.current = ts;

    try {
      await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ runs: newRuns, waitlist: newWait, history: newHistory, ts })
      });
      setSyncStatus('online');
    } catch (e) {
      setSyncStatus('error');
    } finally {
      isUpdatingRef.current = false;
    }
  };

  const pullState = async () => {
    const url = getSyncUrl();
    if (!url || isUpdatingRef.current) return;

    try {
      const res = await fetch(url);
      if (res.ok) {
        const text = await res.text();
        if (!text) return;
        const data = JSON.parse(text);
        if (data.ts > lastUpdateRef.current) {
          setRuns(data.runs || []);
          setWaitingOrders(data.waitlist || []);
          setHistory(data.history || []);
          lastUpdateRef.current = data.ts;
          setSyncStatus('online');
        }
      }
    } catch (e) {
      setSyncStatus('error');
    }
  };

  // 1-second polling for "Live" experience
  useEffect(() => {
    if (!user) return;
    const interval = setInterval(pullState, 1000);
    pullState(); // Initial pull
    return () => clearInterval(interval);
  }, [user?.email]);

  const updateGlobalState = (r: FoodRun[], w: WaitingOrder[], h: FoodRun[]) => {
    setRuns(r);
    setWaitingOrders(w);
    setHistory(h);
    pushState(r, w, h);
  };

  // --- HANDLERS ---
  const handleCreate = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: user.name,
      runnerEmail: user.email,
      destination: inputs.dest.toUpperCase(),
      departureTime: Date.now() + (inputs.time * 60000),
      minutesUntilDeparture: inputs.time,
      maxOrders: inputs.max,
      status: 'active',
      orders: []
    };
    updateGlobalState([newRun, ...runs], waitingOrders, history);
    setModals({ ...modals, create: false });
    setInputs({ ...inputs, dest: '' });
  };

  const handleJoin = (runId: string) => {
    if (!user) return;
    const order: Order = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      userEmail: user.email,
      itemDescription: inputs.item,
      floor: inputs.floor,
      cibusCode: '',
      timestamp: Date.now()
    };
    const newRuns = runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, order] } : r);
    updateGlobalState(newRuns, waitingOrders, history);
    setModals({ ...modals, join: null });
    setInputs({ ...inputs, item: '', floor: '' });
  };

  const handleDepart = (runId: string) => {
    const newRuns = runs.map(r => r.id === runId ? { ...r, status: 'departed' } as FoodRun : r);
    updateGlobalState(newRuns, waitingOrders, history);
  };

  const handleArrival = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run) return;
    const finished: FoodRun = { ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() };
    updateGlobalState(runs.filter(r => r.id !== runId), waitingOrders, [finished, ...history]);
    setModals({ ...modals, arrive: null });
  };

  if (!user) {
    return (
      <div className="min-h-screen bg-white flex items-center justify-center p-6 font-sans">
        <div className="w-full max-w-sm text-center">
          <div className="w-14 h-14 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-xl mx-auto mb-6 shadow-xl shadow-indigo-100">
            <i className="fas fa-terminal"></i>
          </div>
          <h1 className="text-2xl font-black text-slate-900 tracking-tight uppercase italic mb-2">Initialize LunchRun</h1>
          <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest mb-10">Secure Workspace Sync v3.0</p>
          <form onSubmit={(e) => {
            e.preventDefault();
            const email = (e.currentTarget.elements[0] as HTMLInputElement).value;
            setUser({ name: extractName(email), email: email.toLowerCase() });
          }} className="space-y-4">
            <input required type="email" placeholder="Corporate Email" className="w-full h-14 px-6 bg-slate-50 border border-slate-200 rounded-xl font-semibold outline-none focus:border-indigo-500 transition-all text-center" />
            <Button type="submit" className="w-full h-14 bg-slate-900 text-white font-bold rounded-xl uppercase tracking-widest text-xs">Enter Hive</Button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white text-slate-900 font-sans selection:bg-indigo-100 antialiased">
      <div className="max-w-5xl mx-auto px-6 py-12">

        {/* HEADER: Matches the requested structure (Profile top right) */}
        <header className="flex justify-end items-center mb-6 gap-5">
          <div className="text-right">
            <h2 className="text-xl font-black text-slate-900 tracking-tighter uppercase italic leading-none">{user.name}</h2>
            <div className="flex items-center justify-end gap-2 mt-2">
              <span className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'online' ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-amber-400'}`}></span>
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{user.email}</span>
            </div>
          </div>
          <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-3xl shadow-2xl shadow-indigo-100">
            <i className="fas fa-burger"></i>
          </div>
        </header>

        {/* STATUS BAR: Matches requested structure (Buttons left, Status right) */}
        <div className="bg-white border border-slate-100 rounded-2xl p-2.5 mb-12 flex justify-between items-center shadow-[0_4px_20px_-4px_rgba(0,0,0,0.03)]">
          <div className="flex gap-2">
            <Button onClick={() => setModals({ ...modals, create: true })} className="h-11 px-8 bg-orange-600 text-white text-[11px] font-black uppercase tracking-widest rounded-xl shadow-lg shadow-orange-100 border-none">
              Start Run
            </Button>
            <Button onClick={() => setModals({ ...modals, waitlist: true })} className="h-11 px-6 bg-slate-50 border border-slate-100 text-slate-400 text-[11px] font-black uppercase tracking-widest rounded-xl">
              Waitlist
            </Button>
          </div>
          <div className="pr-6">
            <span className="text-[10px] font-black text-slate-300 uppercase tracking-[0.2em]">Network Status: <span className={syncStatus === 'online' ? 'text-emerald-500' : 'text-amber-500'}>{syncStatus.toUpperCase()}</span></span>
          </div>
        </div>

        {/* MAIN FEED */}
        <div className="max-w-2xl mx-auto space-y-12">
          {runs.length === 0 ? (
            <div className="py-40 flex flex-col items-center justify-center opacity-20 text-center select-none">
              <i className="fas fa-ghost text-5xl mb-6"></i>
              <p className="text-[12px] font-black uppercase tracking-[0.6em]">All Clear</p>
            </div>
          ) : (
            runs.map(run => {
              const isOwner = user.email.toLowerCase() === run.runnerEmail.toLowerCase();
              const hasJoined = run.orders.some(o => o.userEmail.toLowerCase() === user.email.toLowerCase());

              return (
                <div key={run.id} className="bg-white border border-slate-50 rounded-[2.5rem] p-12 shadow-[0_30px_60px_-12px_rgba(0,0,0,0.04)] transition-all animate-in fade-in slide-in-from-bottom-6">
                  <div className="flex justify-between items-start mb-10">
                    <div className="flex items-center gap-6">
                      <div className="w-16 h-16 bg-slate-50 border border-slate-100 rounded-2xl flex items-center justify-center text-slate-300 text-3xl">
                        <i className={`fas ${run.status === 'departed' ? 'fa-truck-fast text-indigo-500' : 'fa-utensils'}`}></i>
                      </div>
                      <div>
                        <h3 className="text-3xl font-black text-slate-900 tracking-tighter uppercase italic">{run.destination}</h3>
                        <div className="flex items-center gap-3 mt-1">
                          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{run.runnerName}</span>
                          <span className={`text-[9px] font-black px-2 py-0.5 rounded-full uppercase border ${run.status === 'active' ? 'border-emerald-100 text-emerald-500' : 'border-indigo-100 text-indigo-500'}`}>• {run.status}</span>
                        </div>
                      </div>
                    </div>
                  </div>

                  {run.orders.length > 0 && (
                    <div className="space-y-3 mb-12 border-l-2 border-slate-100 pl-8">
                      {run.orders.map(o => (
                        <div key={o.id} className="flex justify-between items-center py-1">
                          <span className="text-sm font-bold text-slate-700">{o.userName} <span className="text-slate-300 font-normal">ordered</span> {o.itemDescription}</span>
                          <span className="text-[9px] font-black text-slate-300 uppercase">Floor {o.floor}</span>
                        </div>
                      ))}
                    </div>
                  )}

                  <div className="w-full">
                    {isOwner ? (
                      run.status === 'active' ? (
                        <Button onClick={() => handleDepart(run.id)} className="w-full h-18 py-6 bg-orange-600 text-white text-lg font-black uppercase italic tracking-tighter rounded-2xl shadow-2xl shadow-orange-200">Depart Workspace Now</Button>
                      ) : (
                        <Button onClick={() => setModals({ ...modals, arrive: run.id })} className="w-full h-18 py-6 bg-emerald-500 text-white text-lg font-black uppercase tracking-widest rounded-2xl">Confirm Arrival</Button>
                      )
                    ) : (
                      !hasJoined && run.status === 'active' ? (
                        <Button onClick={() => setModals({ ...modals, join: run.id })} className="w-full h-18 py-6 bg-slate-900 text-white text-lg font-black uppercase rounded-2xl">Join Mission</Button>
                      ) : (
                        <div className="w-full py-6 text-center text-[12px] font-black uppercase text-indigo-400 tracking-[0.3em] bg-indigo-50/30 rounded-2xl border border-indigo-50 italic">Manifest Locked</div>
                      )
                    )}
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>

      {/* MODALS: Professional High-Tech Style */}
      {modals.create && (
        <Overlay title="Launch Operation" onClose={() => setModals({ ...modals, create: false })}>
          <form onSubmit={handleCreate} className="space-y-6">
            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Target Destination</label>
              <input required autoFocus className="w-full h-14 px-6 bg-slate-50 border border-slate-200 rounded-xl font-bold focus:border-indigo-500 outline-none uppercase" placeholder="e.g. Vitrina" value={inputs.dest} onChange={e => setInputs({ ...inputs, dest: e.target.value })} />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Time to T-0 (min)</label>
                <input type="number" className="w-full h-14 px-6 bg-slate-50 border border-slate-200 rounded-xl font-bold outline-none" value={inputs.time} onChange={e => setInputs({ ...inputs, time: Number(e.target.value) })} />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Capacity</label>
                <input type="number" className="w-full h-14 px-6 bg-slate-50 border border-slate-200 rounded-xl font-bold outline-none" value={inputs.max} onChange={e => setInputs({ ...inputs, max: Number(e.target.value) })} />
              </div>
            </div>
            <Button type="submit" className="w-full h-14 bg-indigo-600 text-white font-black uppercase rounded-xl">Initialize Broadcast</Button>
          </form>
        </Overlay>
      )}

      {modals.join && (
        <Overlay title="Manifest Entry" onClose={() => setModals({ ...modals, join: null })}>
          <form onSubmit={(e) => { e.preventDefault(); handleJoin(modals.join); }} className="space-y-5">
            <input required autoFocus className="w-full h-14 px-6 bg-slate-50 border border-slate-200 rounded-xl font-bold outline-none" placeholder="Item details" value={inputs.item} onChange={e => setInputs({ ...inputs, item: e.target.value })} />
            <input required className="w-full h-14 px-6 bg-slate-50 border border-slate-200 rounded-xl font-bold outline-none" placeholder="Target floor" value={inputs.floor} onChange={e => setInputs({ ...inputs, floor: e.target.value })} />
            <Button type="submit" className="w-full h-14 bg-slate-900 text-white font-black uppercase rounded-xl">Confirm Order</Button>
          </form>
        </Overlay>
      )}

      {modals.arrive && (
        <Overlay title="Final Signal" onClose={() => setModals({ ...modals, arrive: null })}>
          <form onSubmit={(e) => { e.preventDefault(); handleArrival(modals.arrive); }} className="space-y-6">
            <div className="text-center">
              <p className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em] mb-4">Drop-off Point</p>
              <input required autoFocus className="w-full h-16 px-6 bg-slate-50 border border-slate-200 rounded-xl font-black text-center text-xl outline-none focus:border-indigo-500" placeholder="e.g. Lobby Kitchen" value={inputs.loc} onChange={e => setInputs({ ...inputs, loc: e.target.value })} />
            </div>
            <Button type="submit" className="w-full h-16 bg-emerald-500 text-white font-black uppercase rounded-xl shadow-xl shadow-emerald-50">Signal Arrival</Button>
          </form>
        </Overlay>
      )}
    </div>
  );
};

const Overlay: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
  <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-50 flex items-center justify-center p-6 animate-in fade-in duration-300">
    <div className="bg-white rounded-[2rem] p-10 w-full max-w-md shadow-2xl relative border border-white animate-in zoom-in-95 duration-200">
      <div className="flex justify-between items-center mb-8">
         <h3 className="text-[11px] font-black uppercase tracking-[0.4em] text-indigo-600 italic">{title}</h3>
         <button onClick={onClose} className="w-8 h-8 rounded-full hover:bg-slate-50 flex items-center justify-center text-slate-300 hover:text-slate-900 transition-colors">
            <i className="fas fa-times"></i>
         </button>
      </div>
      {children}
    </div>
  </div>
);

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { FoodRun, Order, WaitingOrder } from './types';
import { Button } from './components/Button';

// STABLE SYNC SERVICE (JSONBin for high reliability)
const SYNC_SERVICE = 'https://keyvalue.xyz/8f8a1d2e/lunchrun_hq_';

const extractDomain = (email: string) => {
  const domain = email.split('@')[1] || 'default';
  return domain.replace(/[^a-zA-Z0-9]/g, '_');
};

const extractName = (email: string) => {
  return email.split('@')[0]
    .split(/[._-]/)
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
};

const App: React.FC = () => {
  const [user, setUser] = useState<{ name: string; email: string } | null>(() => {
    const saved = localStorage.getItem('lr_v4_session');
    return saved ? JSON.parse(saved) : null;
  });

  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [syncStatus, setSyncStatus] = useState<'online' | 'syncing' | 'error'>('online');
  const [modals, setModals] = useState<{ [key: string]: any }>({ create: false, join: null, arrive: null, waitlist: false });
  const [inputs, setInputs] = useState({ dest: '', time: 15, max: 6, item: '', floor: '', loc: '' });

  const lastUpdateRef = useRef<number>(0);
  const isUpdatingRef = useRef<boolean>(false);

  useEffect(() => {
    if (user) localStorage.setItem('lr_v4_session', JSON.stringify(user));
  }, [user]);

  const getSyncUrl = () => user ? `${SYNC_SERVICE}${extractDomain(user.email)}` : null;

  // --- ENGINE: LIVE STATE SYNC ---
  const pushState = async (newRuns: FoodRun[], newWait: WaitingOrder[], newHistory: FoodRun[]) => {
    const url = getSyncUrl();
    if (!url || isUpdatingRef.current) return;

    isUpdatingRef.current = true;
    setSyncStatus('syncing');
    const ts = Date.now();
    lastUpdateRef.current = ts;

    try {
      await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ runs: newRuns, waitlist: newWait, history: newHistory, ts })
      });
      setSyncStatus('online');
    } catch (e) {
      console.warn("Sync sync failed, retrying...");
      setSyncStatus('error');
    } finally {
      isUpdatingRef.current = false;
    }
  };

  const pullState = async () => {
    const url = getSyncUrl();
    if (!url || isUpdatingRef.current) return;

    try {
      const res = await fetch(url);
      if (res.ok) {
        const text = await res.text();
        if (!text) return;
        const data = JSON.parse(text);
        if (data.ts > lastUpdateRef.current) {
          setRuns(data.runs || []);
          setWaitingOrders(data.waitlist || []);
          setHistory(data.history || []);
          lastUpdateRef.current = data.ts;
          setSyncStatus('online');
        }
      }
    } catch (e) {
      // Silent error to prevent UI flickering
      console.debug("Background poll failed");
    }
  };

  // High-performance 1.5s polling for shared workspace
  useEffect(() => {
    if (!user) return;
    const interval = setInterval(pullState, 1500);
    pullState();
    return () => clearInterval(interval);
  }, [user?.email]);

  const updateAll = (r: FoodRun[], w: WaitingOrder[], h: FoodRun[]) => {
    setRuns(r);
    setWaitingOrders(w);
    setHistory(h);
    pushState(r, w, h);
  };

  // --- HANDLERS ---
  const handleCreate = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: user.name,
      runnerEmail: user.email,
      destination: inputs.dest.toUpperCase(),
      departureTime: Date.now() + (inputs.time * 60000),
      minutesUntilDeparture: inputs.time,
      maxOrders: inputs.max,
      status: 'active',
      orders: []
    };
    updateAll([newRun, ...runs], waitingOrders, history);
    setModals({ ...modals, create: false });
    setInputs({ ...inputs, dest: '' });
  };

  const handleJoin = (runId: string) => {
    if (!user) return;
    const order: Order = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      userEmail: user.email,
      itemDescription: inputs.item,
      floor: inputs.floor,
      cibusCode: '',
      timestamp: Date.now()
    };
    const newRuns = runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, order] } : r);
    updateAll(newRuns, waitingOrders, history);
    setModals({ ...modals, join: null });
    setInputs({ ...inputs, item: '', floor: '' });
  };

  const handleDepart = (runId: string) => {
    const newRuns = runs.map(r => r.id === runId ? { ...r, status: 'departed' } as FoodRun : r);
    updateAll(newRuns, waitingOrders, history);
  };

  const handleArrival = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run) return;
    const finished: FoodRun = { ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() };
    updateAll(runs.filter(r => r.id !== runId), waitingOrders, [finished, ...history]);
    setModals({ ...modals, arrive: null });
  };

  if (!user) {
    return (
      <div className="min-h-screen bg-[#0f1115] flex items-center justify-center p-6 text-white font-sans selection:bg-indigo-500/30">
        <div className="w-full max-w-sm border border-slate-800 bg-slate-900/40 p-12 rounded-[2rem] shadow-2xl backdrop-blur-xl">
          <div className="w-14 h-14 bg-indigo-500 rounded-2xl flex items-center justify-center mb-8 shadow-lg shadow-indigo-500/20">
            <i className="fas fa-satellite"></i>
          </div>
          <h1 className="text-3xl font-black italic tracking-tighter uppercase mb-2">LUNCHRUN</h1>
          <p className="text-slate-500 text-[11px] font-bold uppercase tracking-[0.2em] mb-10">Deploy Workplace Fleet</p>
          <form onSubmit={(e) => {
            e.preventDefault();
            const email = (e.currentTarget.elements[0] as HTMLInputElement).value;
            setUser({ name: extractName(email), email: email.toLowerCase() });
          }} className="space-y-4">
            <input required type="email" placeholder="Corporate ID" className="w-full h-16 px-6 bg-black/40 border border-slate-700 rounded-2xl font-bold text-sm focus:border-indigo-500 outline-none transition-all placeholder:text-slate-600" />
            <Button type="submit" className="w-full h-16 bg-indigo-600 hover:bg-indigo-500 text-white font-black uppercase tracking-widest rounded-2xl">Connect Hive</Button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white text-slate-900 font-sans antialiased">
      <div className="max-w-5xl mx-auto px-6 py-12">

        {/* HEADER: AS REQUESTED (Name & Icon top right) */}
        <header className="flex justify-end items-center mb-10 gap-6">
          <div className="text-right">
            <h2 className="text-2xl font-black text-slate-900 tracking-tighter uppercase italic leading-none">{user.name}</h2>
            <div className="flex items-center justify-end gap-2 mt-2">
              <span className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'online' ? 'bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.4)]' : 'bg-amber-400'}`}></span>
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{user.email}</span>
            </div>
          </div>
          <div className="w-18 h-18 bg-indigo-600 rounded-3xl flex items-center justify-center text-white text-4xl shadow-2xl shadow-indigo-100">
            <i className="fas fa-hamburger"></i>
          </div>
        </header>

        {/* STATUS BAR: AS REQUESTED (Buttons left, Status right) */}
        <div className="bg-white border border-slate-100 rounded-2xl p-2.5 mb-14 flex justify-between items-center shadow-[0_10px_40px_-10px_rgba(0,0,0,0.05)]">
          <div className="flex gap-2">
            <Button onClick={() => setModals({ ...modals, create: true })} className="h-12 px-8 bg-orange-600 text-white text-[11px] font-black uppercase tracking-widest rounded-xl shadow-lg shadow-orange-100">
              Start Run
            </Button>
            <Button onClick={() => setModals({ ...modals, waitlist: true })} variant="ghost" className="h-12 px-8 bg-slate-50 border border-slate-100 text-slate-400 text-[11px] font-black uppercase tracking-widest rounded-xl">
              Waitlist
            </Button>
          </div>
          <div className="pr-8">
            <span className="text-[10px] font-black text-slate-300 uppercase tracking-[0.3em]">
              Network Status: <span className={syncStatus === 'online' ? 'text-emerald-500' : 'text-amber-500'}>{syncStatus.toUpperCase()}</span>
            </span>
          </div>
        </div>

        {/* MAIN MISSIONS FEED */}
        <div className="max-w-3xl mx-auto space-y-12">
          {runs.length === 0 ? (
            <div className="py-44 flex flex-col items-center justify-center text-center opacity-20 select-none">
              <i className="fas fa-radar text-6xl mb-8"></i>
              <p className="text-[13px] font-black uppercase tracking-[0.8em]">All Clear // No Active Missions</p>
            </div>
          ) : (
            runs.map(run => {
              const isOwner = user.email.toLowerCase() === run.runnerEmail.toLowerCase();
              const hasJoined = run.orders.some(o => o.userEmail.toLowerCase() === user.email.toLowerCase());

              return (
                <div key={run.id} className="bg-white border border-slate-50 rounded-[3rem] p-12 shadow-[0_40px_80px_-20px_rgba(0,0,0,0.06)] animate-in fade-in slide-in-from-bottom-8 duration-500">
                  <div className="flex justify-between items-start mb-12">
                    <div className="flex items-center gap-8">
                      <div className="w-20 h-20 bg-slate-50 border border-slate-100 rounded-[1.75rem] flex items-center justify-center text-slate-200 text-4xl">
                        <i className={`fas ${run.status === 'departed' ? 'fa-motorcycle text-indigo-400' : 'fa-pizza-slice'}`}></i>
                      </div>
                      <div>
                        <h3 className="text-4xl font-black text-slate-900 tracking-tighter uppercase italic leading-none">{run.destination}</h3>
                        <div className="flex items-center gap-4 mt-3">
                          <span className="text-[11px] font-black text-slate-400 uppercase tracking-widest">Op: {run.runnerName}</span>
                          <span className={`text-[10px] font-black px-3 py-1 rounded-full uppercase border ${run.status === 'active' ? 'border-emerald-100 text-emerald-500 bg-emerald-50/50' : 'border-indigo-100 text-indigo-500 bg-indigo-50/50'}`}>• {run.status}</span>
                        </div>
                      </div>
                    </div>
                  </div>

                  {run.orders.length > 0 && (
                    <div className="space-y-3 mb-12 border-l-4 border-slate-50 pl-10 py-2">
                      {run.orders.map(o => (
                        <div key={o.id} className="flex justify-between items-center py-2 group">
                          <span className="text-base font-bold text-slate-700">{o.userName} <span className="text-slate-300 font-normal italic">expects</span> {o.itemDescription}</span>
                          <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest group-hover:text-indigo-400 transition-colors">Floor {o.floor}</span>
                        </div>
                      ))}
                    </div>
                  )}

                  <div className="w-full">
                    {isOwner ? (
                      run.status === 'active' ? (
                        <Button onClick={() => handleDepart(run.id)} className="w-full h-20 bg-orange-600 text-white text-xl font-black uppercase italic tracking-tight rounded-3xl shadow-2xl shadow-orange-200 hover:scale-[1.02]">Depart Now</Button>
                      ) : (
                        <Button onClick={() => setModals({ ...modals, arrive: run.id })} className="w-full h-20 bg-emerald-600 text-white text-xl font-black uppercase tracking-widest rounded-3xl">Signal Mission Complete</Button>
                      )
                    ) : (
                      !hasJoined && run.status === 'active' ? (
                        <Button onClick={() => setModals({ ...modals, join: run.id })} className="w-full h-20 bg-slate-900 text-white text-xl font-black uppercase rounded-3xl shadow-xl shadow-slate-200">Request Manifest Entry</Button>
                      ) : (
                        <div className="w-full py-8 text-center text-[13px] font-black uppercase text-indigo-500 tracking-[0.4em] bg-indigo-50/50 rounded-3xl border border-indigo-100/50 italic">Deployment In Progress</div>
                      )
                    )}
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>

      {/* MODAL ARCHITECTURE */}
      {modals.create && (
        <Overlay title="Launch New Operation" onClose={() => setModals({ ...modals, create: false })}>
          <form onSubmit={handleCreate} className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-1">Target Merchant</label>
              <input required autoFocus className="w-full h-16 px-6 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl font-black text-lg outline-none uppercase placeholder:text-slate-300" placeholder="e.g. VITRINA" value={inputs.dest} onChange={e => setInputs({ ...inputs, dest: e.target.value })} />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-1">T-Minus (min)</label>
                <input type="number" className="w-full h-16 px-6 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl font-black text-lg outline-none" value={inputs.time} onChange={e => setInputs({ ...inputs, time: Number(e.target.value) })} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-1">Max Payload</label>
                <input type="number" className="w-full h-16 px-6 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl font-black text-lg outline-none" value={inputs.max} onChange={e => setInputs({ ...inputs, max: Number(e.target.value) })} />
              </div>
            </div>
            <Button type="submit" className="w-full h-16 bg-indigo-600 text-white font-black uppercase rounded-2xl shadow-xl shadow-indigo-100">Broadcast Mission</Button>
          </form>
        </Overlay>
      )}

      {modals.join && (
        <Overlay title="Manifest Submission" onClose={() => setModals({ ...modals, join: null })}>
          <form onSubmit={(e) => { e.preventDefault(); handleJoin(modals.join); }} className="space-y-6">
            <input required autoFocus className="w-full h-16 px-6 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl font-bold outline-none" placeholder="Food item / Details" value={inputs.item} onChange={e => setInputs({ ...inputs, item: e.target.value })} />
            <input required className="w-full h-16 px-6 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl font-bold outline-none" placeholder="Drop-off floor" value={inputs.floor} onChange={e => setInputs({ ...inputs, floor: e.target.value })} />
            <Button type="submit" className="w-full h-16 bg-slate-900 text-white font-black uppercase rounded-2xl italic tracking-widest">Confirm Entry</Button>
          </form>
        </Overlay>
      )}

      {modals.arrive && (
        <Overlay title="Drop-Off Signal" onClose={() => setModals({ ...modals, arrive: null })}>
          <form onSubmit={(e) => { e.preventDefault(); handleArrival(modals.arrive); }} className="space-y-8 text-center">
            <div>
              <p className="text-[11px] font-black uppercase text-slate-400 tracking-[0.3em] mb-6 italic">Secure Location Identified</p>
              <input required autoFocus className="w-full h-20 bg-slate-50 border-2 border-transparent focus:border-emerald-500 rounded-3xl font-black text-center text-2xl outline-none" placeholder="e.g. Floor 3 Kitchen" value={inputs.loc} onChange={e => setInputs({ ...inputs, loc: e.target.value })} />
            </div>
            <Button type="submit" className="w-full h-16 bg-emerald-600 text-white font-black uppercase rounded-2xl shadow-xl shadow-emerald-50">Signal Arrival</Button>
          </form>
        </Overlay>
      )}

      {modals.waitlist && (
        <Overlay title="System Backlog" onClose={() => setModals({ ...modals, waitlist: false })}>
          <div className="py-10 space-y-4">
            {waitingOrders.length === 0 ? (
              <p className="text-center text-slate-300 text-xs font-black uppercase tracking-[0.4em] italic">No pending requests</p>
