      userEmail: user.email,
      itemDescription: inputs.item,
      floor: inputs.floor,
      cibusCode: '',
      timestamp: Date.now()
    };
    const updated = runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, order] } : r);
    commit(updated, waitingOrders, history);
    setModals({ ...modals, join: null });
    setInputs({ ...inputs, item: '', floor: '' });
  };

  const depart = (runId: string) => {
    const updated = runs.map(r => r.id === runId ? { ...r, status: 'departed' } as FoodRun : r);
    commit(updated, waitingOrders, history);
  };

  const arrive = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run) return;
    const finished: FoodRun = { ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() };
    commit(runs.filter(r => r.id !== runId), waitingOrders, [finished, ...history]);
    setModals({ ...modals, arrive: null });
    setInputs({ ...inputs, loc: '' });
  };

  if (!user) {
    return (
      <div className="min-h-screen bg-white flex items-center justify-center font-sans p-6">
