          }} className="space-y-4">
            <input required type="email" placeholder="Work Email" className="w-full h-16 px-6 bg-slate-50 border border-slate-200 rounded-2xl font-bold text-center outline-none focus:border-indigo-500" />
            <Button type="submit" className="w-full h-16 bg-slate-900 text-white rounded-2xl font-black uppercase tracking-widest text-xs">Enter Workspace</Button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white text-slate-900 font-sans antialiased">
      <div className="max-w-5xl mx-auto px-6 py-10">

