            <div className="flex items-center justify-end gap-2 mt-1">
              <span className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'ONLINE' ? 'bg-emerald-500' : 'bg-orange-500'}`}></span>
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{user.email}</span>
            </div>
          </div>
          <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-3xl shadow-xl shadow-indigo-100">
            <i className="fas fa-hamburger"></i>
          </div>
        </div>

        {/* ACTIONS BAR: Buttons on Left, Status on Right */}
        <div className="border border-slate-100 rounded-2xl p-2 mb-16 flex justify-between items-center bg-white/50 backdrop-blur-sm shadow-sm">
