                      )
                    ) : (
                      !hasJoined && run.status === 'active' ? (
                        <Button onClick={() => setModals({ ...modals, join: run.id })} className="w-full h-18 bg-slate-900 text-white text-lg font-black uppercase rounded-2xl">JOIN RUN</Button>
