                          </div>
                        )
                      )}
                    </div>
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>

      {/* MODAL SYSTEM - Beautiful Overlays */}
      {modals.create && (
        <Overlay title="Launch Operation" onClose={() => setModals({ ...modals, create: false })}>
          <form onSubmit={startRun} className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Destination</label>
              <input required autoFocus className="w-full h-16 px-8 bg-slate-50 border-2 border-transparent focus:border-orange-500 rounded-2xl font-bold uppercase outline-none transition-all placeholder:text-slate-300" placeholder="e.g. VITRINA / HUMMUS" value={inputs.dest} onChange={e => setInputs({ ...inputs, dest: e.target.value })} />
            </div>
            <div className="grid grid-cols-2 gap-6">
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Wait Time (min)</label>
                 <input type="number" className="w-full h-16 px-8 bg-slate-50 border-2 border-transparent focus:border-orange-500 rounded-2xl font-bold outline-none" value={inputs.time} onChange={e => setInputs({ ...inputs, time: Number(e.target.value) })} />
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Max Orders</label>
                 <input type="number" className="w-full h-16 px-8 bg-slate-50 border-2 border-transparent focus:border-orange-500 rounded-2xl font-bold outline-none" value={inputs.max} onChange={e => setInputs({ ...inputs, max: Number(e.target.value) })} />
              </div>
            </div>
            <Button type="submit" className="w-full h-20 bg-orange-600 text-white font-black uppercase rounded-[2rem] shadow-2xl shadow-orange-100">BROADCAST MISSION</Button>
          </form>
        </Overlay>
      )}

      {modals.join && (
        <Overlay title="Manifest Entry" onClose={() => setModals({ ...modals, join: null })}>
          <form onSubmit={(e) => { e.preventDefault(); joinRun(modals.join); }} className="space-y-6">
            <input required autoFocus className="w-full h-16 px-8 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl font-bold outline-none" placeholder="What are you eating?" value={inputs.item} onChange={e => setInputs({ ...inputs, item: e.target.value })} />
            <input required className="w-full h-16 px-8 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl font-bold outline-none" placeholder="Floor / Desk Number" value={inputs.floor} onChange={e => setInputs({ ...inputs, floor: e.target.value })} />
            <Button type="submit" className="w-full h-20 bg-slate-900 text-white font-black uppercase rounded-[2rem] shadow-xl shadow-slate-100">CONFIRM MY FOOD</Button>
          </form>
        </Overlay>
      )}

      {modals.arrive && (
        <Overlay title="Signal Arrival" onClose={() => setModals({ ...modals, arrive: null })}>
          <form onSubmit={(e) => { e.preventDefault(); arrive(modals.arrive); }} className="space-y-8 text-center">
            <div className="space-y-4">
              <p className="text-slate-400 text-xs font-bold uppercase tracking-[0.2em] italic">Drop-off point identified?</p>
              <input required autoFocus className="w-full h-24 bg-slate-50 border-2 border-transparent focus:border-emerald-500 rounded-[2.5rem] font-black text-center text-3xl outline-none" placeholder="e.g. KITCHEN 3" value={inputs.loc} onChange={e => setInputs({ ...inputs, loc: e.target.value })} />
            </div>
            <Button type="submit" className="w-full h-18 bg-emerald-500 text-white font-black uppercase rounded-2xl shadow-2xl shadow-emerald-50">FINISH & NOTIFY TEAM</Button>
          </form>
        </Overlay>
      )}
    </div>
  );
};

const Overlay: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
  <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-50 flex items-center justify-center p-6 animate-in fade-in duration-300">
