export default App;

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center gap-2 font-black transition-all duration-200 antialiased active:scale-[0.96] disabled:opacity-50 disabled:cursor-not-allowed";

  const variants = {
    primary: "bg-orange-600 text-white hover:bg-orange-500 hover:shadow-xl hover:shadow-orange-500/20",
    secondary: "bg-white border-2 border-slate-100 text-slate-900 hover:bg-slate-50 hover:border-slate-200",
    danger: "bg-red-500 text-white hover:bg-red-600",
    ghost: "text-slate-400 hover:text-slate-900 hover:bg-slate-100"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${className}`} 
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading ? <i className="fas fa-circle-notch fa-spin"></i> : children}
    </button>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { FoodRun, Order, WaitingOrder } from './types';
import { Button } from './components/Button';

// Refined Sync Engine - Professional grade
const SYNC_ROOT = 'https://keyvalue.xyz/8f8a1d2e/lr_v7_';

const extractDomain = (email: string) => {
  const domain = email.split('@')[1] || 'default';
  return domain.replace(/[^a-zA-Z0-9]/g, '_');
};

const extractName = (email: string) => {
  return email.split('@')[0]
    .split(/[._-]/)
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
};

const App: React.FC = () => {
  const [user, setUser] = useState<{ name: string; email: string } | null>(() => {
    const saved = localStorage.getItem('lr_v7_session');
    return saved ? JSON.parse(saved) : null;
  });

  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [syncStatus, setSyncStatus] = useState<'ONLINE' | 'SYNCING' | 'LOCAL'>('ONLINE');
  const [modals, setModals] = useState<{ [key: string]: any }>({ create: false, join: null, arrive: null });
  const [inputs, setInputs] = useState({ dest: '', time: 15, max: 6, item: '', floor: '', loc: '' });

  const lastUpdateRef = useRef<number>(0);
  const isSyncingRef = useRef<boolean>(false);

  useEffect(() => {
    if (user) localStorage.setItem('lr_v7_session', JSON.stringify(user));
  }, [user]);

  const getSyncUrl = () => user ? `${SYNC_ROOT}${extractDomain(user.email)}` : null;

  // --- ENGINE: COLLABORATIVE SYNC ---
  const pushState = async (newRuns: FoodRun[], newWait: WaitingOrder[], newHistory: FoodRun[]) => {
    const url = getSyncUrl();
    if (!url) return;

    isSyncingRef.current = true;
    setSyncStatus('SYNCING');
    const ts = Date.now();
    lastUpdateRef.current = ts;

    try {
      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify({ runs: newRuns, waitlist: newWait, history: newHistory, ts })
      });
      if (response.ok) {
        setSyncStatus('ONLINE');
      } else {
        throw new Error("Push failed");
      }
    } catch (e) {
      console.warn("Sync failed, retrying in next cycle...");
      setSyncStatus('LOCAL');
    } finally {
      isSyncingRef.current = false;
    }
  };

  const pullState = async () => {
    const url = getSyncUrl();
    if (!url || isSyncingRef.current) return;

    try {
      const res = await fetch(url);
      if (res.ok) {
        const text = await res.text();
        if (!text || text.trim() === "") return;
        const data = JSON.parse(text);

        if (data.ts && data.ts > lastUpdateRef.current) {
          setRuns(data.runs || []);
          setWaitingOrders(data.waitlist || []);
          setHistory(data.history || []);
          lastUpdateRef.current = data.ts;
          setSyncStatus('ONLINE');
        }
      }
    } catch (e) {
      // Keep existing state, don't flicker error
    }
  };

  useEffect(() => {
    if (!user) return;
    const interval = setInterval(pullState, 1500);
    pullState();
    return () => clearInterval(interval);
  }, [user?.email]);

  const updateState = (r: FoodRun[], w: WaitingOrder[], h: FoodRun[]) => {
    setRuns(r);
    setWaitingOrders(w);
    setHistory(h);
    pushState(r, w, h);
  };

  // --- BUSINESS LOGIC ---
  const handleCreate = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: user.name,
      runnerEmail: user.email,
      destination: inputs.dest.toUpperCase(),
      departureTime: Date.now() + (inputs.time * 60000),
      minutesUntilDeparture: inputs.time,
      maxOrders: inputs.max,
      status: 'active',
      orders: []
    };
    updateState([newRun, ...runs], waitingOrders, history);
    setModals({ ...modals, create: false });
    setInputs({ ...inputs, dest: '' });
  };

  const handleJoin = (runId: string) => {
    if (!user) return;
    const order: Order = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      userEmail: user.email,
      itemDescription: inputs.item,
      floor: inputs.floor,
      cibusCode: '',
      timestamp: Date.now()
    };
    const newRuns = runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, order] } : r);
    updateState(newRuns, waitingOrders, history);
    setModals({ ...modals, join: null });
    setInputs({ ...inputs, item: '', floor: '' });
  };

  const handleDepart = (runId: string) => {
    const newRuns = runs.map(r => r.id === runId ? { ...r, status: 'departed' } as FoodRun : r);
    updateState(newRuns, waitingOrders, history);
  };

  const handleArrival = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run) return;
    const finished: FoodRun = { ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() };
    updateState(runs.filter(r => r.id !== runId), waitingOrders, [finished, ...history]);
    setModals({ ...modals, arrive: null });
    setInputs({ ...inputs, loc: '' });
  };

  if (!user) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-6 text-white font-sans">
        <div className="w-full max-w-sm border border-slate-800 bg-slate-800/50 p-10 rounded-2xl shadow-2xl backdrop-blur-md">
          <h1 className="text-2xl font-black italic tracking-tight uppercase mb-8">LunchRun Terminal</h1>
          <form onSubmit={(e) => {
            e.preventDefault();
            const email = (e.currentTarget.elements[0] as HTMLInputElement).value;
            setUser({ name: extractName(email), email: email.toLowerCase() });
          }} className="space-y-4">
            <input required type="email" placeholder="Corporate Email" className="w-full h-14 px-6 bg-black/20 border border-slate-700 rounded-lg font-bold text-sm outline-none focus:border-orange-500 transition-colors" />
            <Button type="submit" className="w-full h-14 bg-orange-600 text-white font-black uppercase tracking-widest text-xs rounded-lg">Authenticate</Button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white text-slate-900 font-sans selection:bg-orange-100">
      <div className="max-w-5xl mx-auto px-8 py-12">

        {/* TOP HEADER: User Info on Right (Exact per Screenshot) */}
        <header className="flex justify-end items-center mb-8 gap-6">
          <div className="text-right">
            <h2 className="text-3xl font-black text-slate-900 tracking-tighter uppercase italic leading-none">{user.name}</h2>
            <div className="flex items-center justify-end gap-2 mt-2">
              <span className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'ONLINE' ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-amber-400'}`}></span>
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{user.email}</span>
            </div>
          </div>
          <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-4xl shadow-2xl shadow-indigo-100">
            <i className="fas fa-hamburger"></i>
          </div>
        </header>

        {/* STATUS BAR: Actions Left, Network Right (Exact per Screenshot) */}
        <div className="bg-white border border-slate-100 rounded-2xl p-2.5 mb-16 flex justify-between items-center shadow-[0_10px_40px_-10px_rgba(0,0,0,0.05)]">
          <div className="flex gap-2">
            <Button onClick={() => setModals({ ...modals, create: true })} className="h-12 px-10 bg-orange-600 text-white text-[11px] font-black uppercase tracking-widest rounded-xl shadow-lg shadow-orange-100">
              START RUN
            </Button>
            <Button className="h-12 px-10 bg-slate-50 border border-slate-100 text-slate-400 text-[11px] font-black uppercase tracking-widest rounded-xl hover:bg-slate-100 transition-colors">
              WAITLIST
            </Button>
          </div>
          <div className="pr-8">
            <span className="text-[10px] font-black text-slate-300 uppercase tracking-[0.3em]">
              NETWORK STATUS: <span className={syncStatus === 'ONLINE' ? 'text-emerald-500' : 'text-amber-500'}>{syncStatus}</span>
            </span>
          </div>
        </div>

        {/* MISSIONS FEED */}
        <div className="max-w-3xl mx-auto space-y-12">
          {runs.length === 0 ? (
            <div className="py-44 flex flex-col items-center justify-center text-center opacity-20 select-none">
              <p className="text-[13px] font-black uppercase tracking-[0.8em]">ALL CLEAR // NO ACTIVE MISSIONS</p>
            </div>
          ) : (
            runs.map(run => {
              const isOwner = user.email.toLowerCase() === run.runnerEmail.toLowerCase();
              const hasJoined = run.orders.some(o => o.userEmail.toLowerCase() === user.email.toLowerCase());
              const spotsLeft = run.maxOrders - run.orders.length;

              return (
                <div key={run.id} className="bg-white border border-slate-100 rounded-[2.5rem] p-12 shadow-[0_30px_70px_-20px_rgba(0,0,0,0.06)] animate-in fade-in slide-in-from-bottom-6 duration-500">
                  <div className="flex justify-between items-start mb-12">
                    <div className="flex items-center gap-8">
                      <div className="w-16 h-16 bg-slate-50 border border-slate-100 rounded-2xl flex items-center justify-center text-slate-200 text-3xl">
                        <i className={`fas ${run.status === 'departed' ? 'fa-truck-fast text-indigo-400' : 'fa-utensils'}`}></i>
                      </div>
                      <div>
                        <h3 className="text-4xl font-black text-slate-900 tracking-tighter uppercase italic leading-none">{run.destination}</h3>
                        <div className="flex items-center gap-4 mt-3">
                          <span className="text-[11px] font-black text-slate-400 uppercase tracking-widest">OP: {run.runnerName}</span>
                          <span className={`text-[10px] font-black px-3 py-1 rounded-md uppercase ${run.status === 'active' ? 'bg-emerald-50 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}>• {run.status}</span>
                        </div>
                      </div>
                    </div>
                    <div className="text-right">
                       <div className="text-3xl font-black text-slate-900 leading-none">{spotsLeft}</div>
                       <div className="text-[9px] font-black text-slate-300 uppercase tracking-widest mt-1">Free Slots</div>
                    </div>
                  </div>

                  {run.orders.length > 0 && (
                    <div className="mb-12 space-y-3 border-l-4 border-slate-50 pl-10">
                      <p className="text-[10px] font-black text-slate-300 uppercase tracking-[0.3em] mb-4">THE MANIFEST</p>
                      {run.orders.map(o => (
                        <div key={o.id} className="flex justify-between items-center">
                          <span className="text-sm font-bold text-slate-700">{o.userName} <span className="text-slate-300 font-normal italic">expects</span> {o.itemDescription}</span>
                          <span className="text-[10px] font-black text-indigo-400 bg-indigo-50 px-3 py-1 rounded">FL {o.floor}</span>
                        </div>
                      ))}
                    </div>
                  )}

                  <div className="w-full">
                    {isOwner ? (
                      run.status === 'active' ? (
                        <Button onClick={() => handleDepart(run.id)} className="w-full h-18 bg-orange-600 text-white text-xl font-black uppercase italic tracking-tighter rounded-2xl shadow-2xl shadow-orange-100 transition-transform active:scale-95">DEPART NOW</Button>
                      ) : (
                        <Button onClick={() => setModals({ ...modals, arrive: run.id })} className="w-full h-18 bg-emerald-500 text-white text-xl font-black uppercase rounded-2xl shadow-2xl shadow-emerald-50">SIGNAL ARRIVAL</Button>
                      )
                    ) : (
                      !hasJoined && run.status === 'active' && spotsLeft > 0 ? (
                        <Button onClick={() => setModals({ ...modals, join: run.id })} className="w-full h-18 bg-slate-900 text-white text-xl font-black uppercase rounded-2xl shadow-xl shadow-slate-200 transition-transform active:scale-95">JOIN THE MISSION</Button>
                      ) : (
                        <div className="w-full py-6 text-center text-[11px] font-black uppercase text-indigo-400 tracking-[0.4em] bg-indigo-50/30 rounded-2xl border border-indigo-50/50 italic">MANIFEST LOCKED</div>
                      )
                    )}
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>

      {/* MODAL SYSTEM */}
      {modals.create && (
        <Overlay title="Mission Parameters" onClose={() => setModals({ ...modals, create: false })}>
          <form onSubmit={handleCreate} className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-1">Target Merchant</label>
              <input required autoFocus className="w-full h-16 px-6 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-xl font-black text-lg outline-none uppercase placeholder:text-slate-300" placeholder="e.g. VITRINA" value={inputs.dest} onChange={e => setInputs({ ...inputs, dest: e.target.value })} />
            </div>
            <div className="grid grid-cols-2 gap-4">
               <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-1">T-Minus (min)</label>
                 <input type="number" className="w-full h-16 px-6 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-xl font-black text-lg outline-none" value={inputs.time} onChange={e => setInputs({ ...inputs, time: Number(e.target.value) })} />
               </div>
               <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-1">Max Payload</label>
                 <input type="number" className="w-full h-16 px-6 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-xl font-black text-lg outline-none" value={inputs.max} onChange={e => setInputs({ ...inputs, max: Number(e.target.value) })} />
               </div>
            </div>
            <Button type="submit" className="w-full h-18 bg-indigo-600 text-white font-black uppercase rounded-xl shadow-xl shadow-indigo-100">BROADCAST MISSION</Button>
          </form>
        </Overlay>
      )}

      {modals.join && (
        <Overlay title="Manifest Submission" onClose={() => setModals({ ...modals, join: null })}>
          <form onSubmit={(e) => { e.preventDefault(); handleJoin(modals.join); }} className="space-y-6">
            <input required autoFocus className="w-full h-16 px-6 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-xl font-bold outline-none" placeholder="What are you eating?" value={inputs.item} onChange={e => setInputs({ ...inputs, item: e.target.value })} />
            <input required className="w-full h-16 px-6 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-xl font-bold outline-none" placeholder="Floor / Desk Number" value={inputs.floor} onChange={e => setInputs({ ...inputs, floor: e.target.value })} />
            <Button type="submit" className="w-full h-18 bg-slate-900 text-white font-black uppercase rounded-xl italic tracking-widest">CONFIRM ENTRY</Button>
          </form>
        </Overlay>
      )}

      {modals.arrive && (
        <Overlay title="Arrival Signal" onClose={() => setModals({ ...modals, arrive: null })}>
          <form onSubmit={(e) => { e.preventDefault(); handleArrival(modals.arrive); }} className="space-y-8 text-center">
            <div className="space-y-4">
              <p className="text-[11px] font-black uppercase text-slate-400 tracking-[0.3em] mb-4 italic">Drop-off point identified?</p>
              <input required autoFocus className="w-full h-20 bg-slate-50 border-2 border-transparent focus:border-emerald-500 rounded-2xl font-black text-center text-2xl outline-none" placeholder="e.g. KITCHEN 3" value={inputs.loc} onChange={e => setInputs({ ...inputs, loc: e.target.value })} />
            </div>
            <Button type="submit" className="w-full h-18 bg-emerald-600 text-white font-black uppercase rounded-xl shadow-2xl shadow-emerald-50">FINISH & NOTIFY TEAM</Button>
          </form>
        </Overlay>
      )}
    </div>
  );
};

