import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center gap-2 font-black transition-all duration-150 antialiased active:scale-[0.97] disabled:opacity-50 disabled:cursor-not-allowed border-none";

  const variants = {
    primary: "bg-orange-600 text-white hover:brightness-110",
    secondary: "bg-slate-50 border border-slate-200 text-slate-900 hover:bg-slate-100",
    danger: "bg-red-600 text-white hover:bg-red-700",
    ghost: "text-slate-400 hover:text-slate-900 hover:bg-slate-50"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${className}`} 
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading ? <i className="fas fa-circle-notch fa-spin"></i> : children}
    </button>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { FoodRun, Order, WaitingOrder } from './types';
import { Button } from './components/Button';

// Robust Sync Key - Improved reliability
const SYNC_ROOT = 'https://keyvalue.xyz/v1/lr-sync-final-';

const extractDomain = (email: string) => {
  const domain = email.split('@')[1] || 'public';
  return domain.replace(/[^a-zA-Z0-9]/g, '-');
};

const extractName = (email: string) => {
  return email.split('@')[0]
    .split(/[._-]/)
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
};

const App: React.FC = () => {
  const [user, setUser] = useState<{ name: string; email: string } | null>(() => {
    const saved = localStorage.getItem('lr_final_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [syncStatus, setSyncStatus] = useState<'ONLINE' | 'SYNCING' | 'LOCAL'>('ONLINE');
  const [modals, setModals] = useState<{ [key: string]: any }>({ create: false, join: null, arrive: null });
  const [inputs, setInputs] = useState({ dest: '', time: 15, max: 6, item: '', floor: '', loc: '' });

  const lastUpdateRef = useRef<number>(0);
  const isSyncingRef = useRef<boolean>(false);

  useEffect(() => {
    if (user) localStorage.setItem('lr_final_user', JSON.stringify(user));
  }, [user]);

  const getSyncUrl = () => user ? `${SYNC_ROOT}${extractDomain(user.email)}` : null;

  // --- RESILIENT SYNC ENGINE ---
  const pushState = async (newRuns: FoodRun[], newWait: WaitingOrder[], newHistory: FoodRun[]) => {
    const url = getSyncUrl();
    if (!url) return;

    isSyncingRef.current = true;
    setSyncStatus('SYNCING');
    const ts = Date.now();
    lastUpdateRef.current = ts;

    try {
      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify({ runs: newRuns, waitlist: newWait, history: newHistory, ts })
      });
      if (response.ok) {
        setSyncStatus('ONLINE');
      } else {
        // Retry silently instead of failing to LOCAL immediately
        setTimeout(() => pushState(newRuns, newWait, newHistory), 2000);
      }
    } catch (e) {
      setSyncStatus('LOCAL');
    } finally {
      isSyncingRef.current = false;
    }
  };

  const pullState = async () => {
    const url = getSyncUrl();
    if (!url || isSyncingRef.current) return;

    try {
      const res = await fetch(url);
      if (res.ok) {
        const text = await res.text();
        if (!text || text.trim() === "") return;
        const data = JSON.parse(text);

        if (data.ts && data.ts > lastUpdateRef.current) {
          setRuns(data.runs || []);
          setWaitingOrders(data.waitlist || []);
          setHistory(data.history || []);
          lastUpdateRef.current = data.ts;
          setSyncStatus('ONLINE');
        }
      }
    } catch (e) {
      // Keep state, don't show error
    }
  };

  useEffect(() => {
    if (!user) return;
    const interval = setInterval(pullState, 2000);
    pullState();
    return () => clearInterval(interval);
  }, [user?.email]);

  const updateAndSync = (r: FoodRun[], w: WaitingOrder[], h: FoodRun[]) => {
    setRuns(r);
    setWaitingOrders(w);
    setHistory(h);
    pushState(r, w, h);
  };

  // --- HANDLERS ---
  const startRun = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: user.name,
      runnerEmail: user.email,
      destination: inputs.dest.toUpperCase(),
      departureTime: Date.now() + (inputs.time * 60000),
      minutesUntilDeparture: inputs.time,
      maxOrders: inputs.max,
      status: 'active',
      orders: []
    };
    updateAndSync([newRun, ...runs], waitingOrders, history);
    setModals({ ...modals, create: false });
    setInputs({ ...inputs, dest: '' });
  };

  const joinRun = (runId: string) => {
    if (!user) return;
    const order: Order = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      userEmail: user.email,
      itemDescription: inputs.item,
      floor: inputs.floor,
      cibusCode: '',
      timestamp: Date.now()
    };
    const updated = runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, order] } : r);
    updateAndSync(updated, waitingOrders, history);
    setModals({ ...modals, join: null });
    setInputs({ ...inputs, item: '', floor: '' });
  };

  if (!user) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6">
        <div className="w-full max-w-sm bg-white p-12 rounded-[3.5rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.1)] text-center">
          <div className="w-20 h-20 bg-orange-500 rounded-[2rem] flex items-center justify-center text-white text-4xl mx-auto mb-10 shadow-2xl shadow-orange-200">
            <i className="fas fa-pizza-slice"></i>
          </div>
          <h1 className="text-4xl font-black tracking-tighter mb-4 text-slate-900 italic uppercase">LunchRun</h1>
          <form onSubmit={(e) => {
            e.preventDefault();
            const email = (e.currentTarget.elements[0] as HTMLInputElement).value;
            setUser({ name: extractName(email), email: email.toLowerCase() });
          }} className="space-y-4">
            <input required type="email" placeholder="Work Email" className="w-full h-16 px-8 bg-slate-50 border-2 border-transparent focus:border-orange-500 rounded-2xl font-bold text-center outline-none transition-all" />
            <Button type="submit" className="w-full h-16 bg-orange-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-orange-100">Connect</Button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50/50 text-slate-900 font-sans selection:bg-orange-100">
      <div className="max-w-5xl mx-auto px-6 py-12">

        {/* TOP HEADER: Profile on Right (Exact per Screenshot) */}
        <header className="flex justify-end items-center mb-10 gap-8">
          <div className="text-right">
            <h2 className="text-3xl font-black tracking-tight uppercase italic leading-none text-slate-900">{user.name}</h2>
            <div className="flex items-center justify-end gap-2 mt-2">
              <span className={`w-2 h-2 rounded-full ${syncStatus === 'ONLINE' ? 'bg-emerald-500 shadow-[0_0_10px_#10b981]' : 'bg-orange-400'}`}></span>
              <span className="text-[11px] font-black text-slate-300 uppercase tracking-[0.2em]">{user.email}</span>
            </div>
          </div>
          <div className="w-20 h-20 bg-indigo-600 rounded-[2rem] flex items-center justify-center text-white text-4xl shadow-[0_20px_40px_-10px_rgba(79,70,229,0.3)]">
            <i className="fas fa-hamburger"></i>
          </div>
        </header>

        {/* ACTION BAR: Left Buttons, Right Status (Exact per Screenshot) */}
        <div className="bg-white border border-white rounded-[2rem] p-3 mb-20 flex justify-between items-center shadow-[0_20px_50px_-15px_rgba(0,0,0,0.05)]">
          <div className="flex gap-3">
            <Button onClick={() => setModals({ ...modals, create: true })} className="h-14 px-10 bg-orange-600 text-white text-[12px] font-black uppercase tracking-widest rounded-2xl shadow-xl shadow-orange-100">
              START RUN
            </Button>
            <Button className="h-14 px-10 bg-slate-50 border border-slate-100 text-slate-400 text-[12px] font-black uppercase tracking-widest rounded-2xl hover:bg-slate-100">
              WAITLIST
            </Button>
          </div>
          <div className="pr-10">
            <span className={`text-[11px] font-black uppercase tracking-[0.3em] ${syncStatus === 'ONLINE' ? 'text-emerald-500' : 'text-orange-400'}`}>
              NETWORK STATUS: {syncStatus}
            </span>
          </div>
        </div>

        {/* FEED */}
        <div className="max-w-3xl mx-auto space-y-16">
          {runs.length === 0 ? (
            <div className="py-52 text-center opacity-20">
              <p className="text-[14px] font-black uppercase tracking-[0.6em] text-slate-400">ALL CLEAR // NO ACTIVE MISSIONS</p>
            </div>
          ) : (
            runs.map(run => {
              const isOwner = user.email.toLowerCase() === run.runnerEmail.toLowerCase();
              const hasJoined = run.orders.some(o => o.userEmail.toLowerCase() === user.email.toLowerCase());
              const spotsLeft = run.maxOrders - run.orders.length;

              return (
                <div key={run.id} className="bg-white border border-slate-50 rounded-[3.5rem] p-14 shadow-[0_40px_100px_-20px_rgba(0,0,0,0.08)] transform hover:-translate-y-2 transition-all duration-500">
                  <div className="flex justify-between items-start mb-14">
                    <div className="flex items-center gap-10">
                      <div className="w-20 h-20 bg-slate-50 border border-slate-100 rounded-[2rem] flex items-center justify-center text-4xl text-slate-200">
                        <i className={`fas ${run.status === 'departed' ? 'fa-truck-fast text-indigo-400' : 'fa-pizza-slice text-orange-400'}`}></i>
                      </div>
                      <div>
                        <h3 className="text-5xl font-black text-slate-900 tracking-tighter uppercase italic leading-none">{run.destination}</h3>
                        <div className="flex items-center gap-4 mt-4">
                          <span className="text-[12px] font-black text-slate-300 uppercase tracking-widest">OP: {run.runnerName}</span>
                          <span className={`text-[10px] font-black px-3 py-1 rounded-lg uppercase ${run.status === 'active' ? 'bg-emerald-50 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}>• {run.status}</span>
                        </div>
                      </div>
                    </div>
                    <div className="text-right">
                       <div className="text-4xl font-black text-slate-900">{spotsLeft}</div>
                       <div className="text-[10px] font-black text-slate-200 uppercase tracking-widest">SLOTS</div>
                    </div>
                  </div>

                  {run.orders.length > 0 && (
                    <div className="mb-14 space-y-4 border-l-4 border-slate-100 pl-12">
                      <p className="text-[11px] font-black text-slate-200 uppercase tracking-[0.4em] mb-6 italic">THE MANIFEST</p>
                      {run.orders.map(o => (
                        <div key={o.id} className="flex justify-between items-center group/item">
                          <span className="text-lg font-bold text-slate-700">
                            {o.userName} <span className="text-slate-300 font-medium lowercase">wants</span> {o.itemDescription}
                          </span>
                          <span className="text-[11px] font-black text-indigo-400 bg-indigo-50 px-3 py-1.5 rounded-xl">FL {o.floor}</span>
                        </div>
                      ))}
                    </div>
                  )}

                  <div className="w-full">
                    {isOwner ? (
                      run.status === 'active' ? (
                        <Button onClick={() => updateAndSync(runs.map(r => r.id === run.id ? {...r, status: 'departed'} : r), waitingOrders, history)} className="w-full h-22 bg-orange-600 text-white text-2xl font-black uppercase italic tracking-tighter rounded-[2rem] shadow-2xl shadow-orange-200">DEPART NOW</Button>
                      ) : (
                        <Button onClick={() => setModals({ ...modals, arrive: run.id })} className="w-full h-22 bg-emerald-500 text-white text-2xl font-black uppercase rounded-[2rem] shadow-2xl shadow-emerald-100">ARRIVED</Button>
                      )
                    ) : (
                      !hasJoined && run.status === 'active' && spotsLeft > 0 ? (
                        <Button onClick={() => setModals({ ...modals, join: run.id })} className="w-full h-22 bg-slate-900 text-white text-2xl font-black uppercase rounded-[2rem] shadow-2xl shadow-slate-200">JOIN RUN</Button>
                      ) : (
                        <div className="w-full py-8 text-center text-[12px] font-black uppercase text-indigo-400 tracking-[0.5em] bg-indigo-50/50 rounded-[2rem] border border-indigo-100/50 italic">MISSION LOCKED</div>
                      )
                    )}
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>

      {/* MODALS: Beautiful & Clean */}
      {modals.create && (
        <Overlay title="Launch Run" onClose={() => setModals({ ...modals, create: false })}>
          <form onSubmit={startRun} className="space-y-8">
            <div className="space-y-3">
              <label className="text-[11px] font-black text-slate-300 uppercase tracking-widest ml-1">Destination</label>
              <input required autoFocus className="w-full h-18 px-8 bg-slate-50 border-2 border-transparent focus:border-orange-500 rounded-3xl font-black text-2xl uppercase outline-none transition-all" placeholder="e.g. VITRINA" value={inputs.dest} onChange={e => setInputs({ ...inputs, dest: e.target.value })} />
            </div>
            <div className="grid grid-cols-2 gap-6">
               <input type="number" className="h-18 px-8 bg-slate-50 border-2 border-transparent focus:border-orange-500 rounded-3xl font-black text-xl outline-none" value={inputs.time} onChange={e => setInputs({ ...inputs, time: Number(e.target.value) })} />
               <input type="number" className="h-18 px-8 bg-slate-50 border-2 border-transparent focus:border-orange-500 rounded-3xl font-black text-xl outline-none" value={inputs.max} onChange={e => setInputs({ ...inputs, max: Number(e.target.value) })} />
            </div>
            <Button type="submit" className="w-full h-20 bg-orange-600 text-white font-black uppercase rounded-[2rem] shadow-2xl shadow-orange-100">BROADCAST</Button>
          </form>
        </Overlay>
      )}

      {modals.join && (
        <Overlay title="Join Manifest" onClose={() => setModals({ ...modals, join: null })}>
          <form onSubmit={(e) => { e.preventDefault(); joinRun(modals.join); }} className="space-y-6">
            <input required autoFocus className="w-full h-18 px-8 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-3xl font-bold text-lg outline-none" placeholder="What food do you want?" value={inputs.item} onChange={e => setInputs({ ...inputs, item: e.target.value })} />
            <input required className="w-full h-18 px-8 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-3xl font-bold text-lg outline-none" placeholder="Floor / Desk" value={inputs.floor} onChange={e => setInputs({ ...inputs, floor: e.target.value })} />
            <Button type="submit" className="w-full h-20 bg-slate-900 text-white font-black uppercase rounded-[2rem]">CONFIRM ORDER</Button>
          </form>
        </Overlay>
      )}
    </div>
  );
};

const Overlay: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
  <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-xl z-50 flex items-center justify-center p-6 animate-in fade-in duration-300">
    <div className="bg-white rounded-[4rem] p-14 w-full max-w-lg shadow-[0_50px_100px_-20px_rgba(0,0,0,0.3)] relative animate-in zoom-in-95 duration-200">
      <div className="flex justify-between items-center mb-12">
         <h3 className="text-[12px] font-black uppercase tracking-[0.5em] text-orange-600 italic underline decoration-4 underline-offset-8 decoration-orange-100">{title}</h3>
         <button onClick={onClose} className="w-12 h-12 rounded-full hover:bg-slate-50 flex items-center justify-center text-slate-200 hover:text-slate-900 transition-all">
            <i className="fas fa-times text-xl"></i>
         </button>
      </div>
      {children}
    </div>
  </div>
);

export default App;

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center gap-2 font-black transition-all duration-300 antialiased active:scale-[0.95] disabled:opacity-50 disabled:cursor-not-allowed border-none";

  const variants = {
    primary: "bg-gradient-to-br from-orange-500 to-orange-600 text-white hover:shadow-2xl hover:shadow-orange-500/30",
    secondary: "bg-white border-2 border-slate-50 text-slate-400 hover:text-slate-900 hover:bg-slate-50 hover:border-slate-100 shadow-sm",
    danger: "bg-red-500 text-white hover:bg-red-600 shadow-lg shadow-red-100",
    ghost: "text-slate-400 hover:text-slate-900 hover:bg-slate-50 rounded-xl"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${className}`} 
