  );
};

import React, { useState, useEffect, useRef } from 'react';
import { FoodRun, Order, WaitingOrder } from './types';
import { Button } from './components/Button';

// Optimized Sync Engine - Using a cleaner key for better reliability
const SYNC_ROOT = 'https://keyvalue.xyz/v1/lr-v8-sync-';

const extractDomain = (email: string) => {
  const domain = email.split('@')[1] || 'public';
  return domain.replace(/[^a-zA-Z0-9]/g, '-');
};

const extractName = (email: string) => {
  return email.split('@')[0]
    .split(/[._-]/)
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
};

const App: React.FC = () => {
  const [user, setUser] = useState<{ name: string; email: string } | null>(() => {
    const saved = localStorage.getItem('lr_v8_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [waitingOrders, setWaitingOrders] = useState<WaitingOrder[]>([]);
  const [history, setHistory] = useState<FoodRun[]>([]);
  const [syncStatus, setSyncStatus] = useState<'ONLINE' | 'SYNCING' | 'LOCAL'>('ONLINE');
  const [modals, setModals] = useState<{ [key: string]: any }>({ create: false, join: null, arrive: null });
  const [inputs, setInputs] = useState({ dest: '', time: 15, max: 6, item: '', floor: '', loc: '' });

  const lastUpdateRef = useRef<number>(0);
  const syncLock = useRef<boolean>(false);
  const errorCount = useRef<number>(0);

  useEffect(() => {
    if (user) localStorage.setItem('lr_v8_user', JSON.stringify(user));
  }, [user]);

  const getSyncUrl = () => user ? `${SYNC_ROOT}${extractDomain(user.email)}` : null;

  // --- OPTIMIZED SYNC ENGINE ---
  const pushState = async (currentRuns: FoodRun[], currentWait: WaitingOrder[], currentHistory: FoodRun[]) => {
    const url = getSyncUrl();
    if (!url || syncLock.current) return;

    syncLock.current = true;
    setSyncStatus('SYNCING');

    // PAYLOAD OPTIMIZATION: Only sync active runs and very recent history to avoid server limits
    const optimizedHistory = currentHistory.slice(0, 3); 
    const ts = Date.now();
    lastUpdateRef.current = ts;

    try {
      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify({ runs: currentRuns, waitlist: currentWait, history: optimizedHistory, ts })
      });

      if (response.ok) {
        setSyncStatus('ONLINE');
        errorCount.current = 0;
      } else {
        throw new Error("Server error");
      }
    } catch (e) {
      errorCount.current++;
      // Only drop to LOCAL if it fails consistently
      if (errorCount.current > 3) {
        setSyncStatus('LOCAL');
      }
    } finally {
      syncLock.current = false;
    }
  };

  const pullState = async () => {
    const url = getSyncUrl();
    if (!url || syncLock.current) return;

    try {
      const res = await fetch(url);
      if (res.ok) {
        const text = await res.text();
        if (!text || text.trim() === "") return;
        const data = JSON.parse(text);

        if (data.ts && data.ts > lastUpdateRef.current) {
          setRuns(data.runs || []);
          setWaitingOrders(data.waitlist || []);
          // Merge remote recent history with local full history
          setHistory(prev => {
            const combined = [...(data.history || []), ...prev];
            const unique = Array.from(new Map(combined.map(item => [item.id, item])).values());
            return unique.slice(0, 50); // Keep 50 locally
          });
          lastUpdateRef.current = data.ts;
          setSyncStatus('ONLINE');
          errorCount.current = 0;
        }
      }
    } catch (e) {
      // Silent fail
    }
  };

  useEffect(() => {
    if (!user) return;
    const interval = setInterval(pullState, 2500);
    pullState();
    return () => clearInterval(interval);
  }, [user?.email]);

  const updateAndSync = (r: FoodRun[], w: WaitingOrder[], h: FoodRun[]) => {
    setRuns(r);
    setWaitingOrders(w);
    setHistory(h);
    pushState(r, w, h);
  };

  // --- ACTION HANDLERS ---
  const handleStartRun = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: user.name,
      runnerEmail: user.email,
      destination: inputs.dest.toUpperCase(),
      departureTime: Date.now() + (inputs.time * 60000),
      minutesUntilDeparture: inputs.time,
      maxOrders: inputs.max,
      status: 'active',
      orders: []
    };
    updateAndSync([newRun, ...runs], waitingOrders, history);
    setModals({ ...modals, create: false });
    setInputs({ ...inputs, dest: '' });
  };

  const handleJoinRun = (runId: string) => {
    if (!user) return;
    const order: Order = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      userEmail: user.email,
      itemDescription: inputs.item,
      floor: inputs.floor,
      cibusCode: '',
      timestamp: Date.now()
    };
    const updated = runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, order] } : r);
    updateAndSync(updated, waitingOrders, history);
    setModals({ ...modals, join: null });
    setInputs({ ...inputs, item: '', floor: '' });
  };

  const handleArrive = (runId: string) => {
    const run = runs.find(r => r.id === runId);
    if (!run) return;
    const finished: FoodRun = { ...run, status: 'arrived', arrivalLocation: inputs.loc, arrivalTime: Date.now() };
    const remainingRuns = runs.filter(r => r.id !== runId);
    updateAndSync(remainingRuns, waitingOrders, [finished, ...history]);
    setModals({ ...modals, arrive: null });
    setInputs({ ...inputs, loc: '' });
  };

  if (!user) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6">
        <div className="w-full max-w-sm bg-white p-12 rounded-[4rem] shadow-[0_40px_100px_-20px_rgba(0,0,0,0.1)] text-center">
          <div className="w-24 h-24 bg-orange-500 rounded-[2.5rem] flex items-center justify-center text-white text-5xl mx-auto mb-10 shadow-2xl shadow-orange-200">
            <i className="fas fa-pizza-slice"></i>
          </div>
          <h1 className="text-4xl font-black tracking-tighter mb-4 text-slate-900 italic uppercase">LunchRun</h1>
          <form onSubmit={(e) => {
            e.preventDefault();
            const email = (e.currentTarget.elements[0] as HTMLInputElement).value;
            setUser({ name: extractName(email), email: email.toLowerCase() });
          }} className="space-y-4">
            <input required type="email" placeholder="work@company.com" className="w-full h-18 px-8 bg-slate-50 border-2 border-transparent focus:border-orange-500 rounded-2xl font-bold text-center outline-none transition-all" />
            <Button type="submit" className="w-full h-18 bg-orange-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-orange-100">Enter Terminal</Button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50/50 text-slate-900 font-sans selection:bg-orange-100 antialiased">
      <div className="max-w-5xl mx-auto px-6 py-12">

        {/* HEADER: Profile Right */}
        <header className="flex justify-end items-center mb-12 gap-10 animate-in fade-in duration-700">
          <div className="text-right">
            <h2 className="text-4xl font-black tracking-tight uppercase italic leading-none text-slate-900">{user.name}</h2>
            <div className="flex items-center justify-end gap-2 mt-3">
              <span className={`w-2.5 h-2.5 rounded-full ${syncStatus === 'ONLINE' ? 'bg-emerald-500 shadow-[0_0_12px_#10b981]' : 'bg-orange-400'}`}></span>
              <span className="text-[12px] font-black text-slate-300 uppercase tracking-[0.3em]">{user.email}</span>
            </div>
          </div>
          <div className="w-24 h-24 bg-indigo-600 rounded-[2.5rem] flex items-center justify-center text-white text-5xl shadow-[0_30px_60px_-15px_rgba(79,70,229,0.4)] transform hover:rotate-3 transition-transform">
            <i className="fas fa-hamburger"></i>
          </div>
        </header>

        {/* ACTIONS: Left Buttons, Right Status */}
        <div className="bg-white/90 backdrop-blur-md border border-white rounded-[2.5rem] p-4 mb-24 flex justify-between items-center shadow-[0_25px_60px_-15px_rgba(0,0,0,0.06)]">
          <div className="flex gap-4">
            <Button onClick={() => setModals({ ...modals, create: true })} className="h-16 px-12 bg-orange-600 text-white text-[13px] font-black uppercase tracking-widest rounded-3xl shadow-2xl shadow-orange-100 hover:scale-105 active:scale-95">
              START RUN
            </Button>
            <Button className="h-16 px-12 bg-white border-2 border-slate-50 text-slate-400 text-[13px] font-black uppercase tracking-widest rounded-3xl hover:bg-slate-50 hover:text-slate-600">
              WAITLIST
            </Button>
          </div>
          <div className="pr-12 text-right">
            <span className={`text-[11px] font-black uppercase tracking-[0.4em] ${syncStatus === 'ONLINE' ? 'text-emerald-500' : 'text-orange-400'}`}>
              STATUS: {syncStatus}
            </span>
          </div>
        </div>

        {/* FEED */}
        <div className="max-w-3xl mx-auto space-y-20">
          {runs.length === 0 ? (
            <div className="py-64 text-center opacity-20 select-none">
              <p className="text-[16px] font-black uppercase tracking-[0.8em] text-slate-400 italic">No Missions Active</p>
            </div>
          ) : (
            runs.map(run => {
              const isOwner = user.email.toLowerCase() === run.runnerEmail.toLowerCase();
              const hasJoined = run.orders.some(o => o.userEmail.toLowerCase() === user.email.toLowerCase());
              const spotsLeft = run.maxOrders - run.orders.length;

              return (
                <div key={run.id} className="bg-white border border-slate-50 rounded-[4rem] p-16 shadow-[0_50px_120px_-30px_rgba(0,0,0,0.08)] transition-all duration-500 hover:shadow-[0_60px_140px_-35px_rgba(0,0,0,0.12)]">
                  <div className="flex justify-between items-start mb-16">
                    <div className="flex items-center gap-12">
