    if (user) localStorage.setItem('lr_v9_session', JSON.stringify(user));
  }, [user]);

  const getSyncUrl = () => user ? `${SYNC_ROOT}${extractDomain(user.email)}` : null;

  // --- COMPACT SYNC ENGINE (Fixed LOCAL issue) ---
  const syncToCloud = async (activeRuns: FoodRun[]) => {
    const url = getSyncUrl();
    if (!url || syncInProgress.current) return;

    syncInProgress.current = true;
    setSyncStatus('SYNCING');
    const ts = Date.now();
    lastUpdateRef.current = ts;

    try {
      // We only sync ACTIVE runs to keep payload small and avoid "LOCAL" fallback
      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify({ runs: activeRuns, ts })
      });

      if (response.ok) {
        setSyncStatus('ONLINE');
      } else {
        throw new Error("Sync limit hit");
      }
    } catch (e) {
      console.warn("Sync failed, will retry...");
      setSyncStatus('LOCAL');
    } finally {
      syncInProgress.current = false;
    }
  };

  const syncFromCloud = async () => {
    const url = getSyncUrl();
    if (!url || syncInProgress.current) return;

    try {
      const res = await fetch(url);
      if (res.ok) {
        const text = await res.text();
        if (!text) return;
        const data = JSON.parse(text);

        if (data.ts && data.ts > lastUpdateRef.current) {
          setRuns(data.runs || []);
          lastUpdateRef.current = data.ts;
          setSyncStatus('ONLINE');
        }
      }
    } catch (e) {
      // Silent
    }
  };

  useEffect(() => {
    if (!user) return;
    const interval = setInterval(syncFromCloud, 3000);
    syncFromCloud();
    return () => clearInterval(interval);
