            <Button type="submit" className="w-full h-14 bg-indigo-600 text-white font-bold rounded-xl shadow-lg shadow-indigo-100">Continue</Button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] text-slate-900 font-sans antialiased">
      {/* NAV BAR */}
      <nav className="sticky top-0 z-30 bg-white/80 backdrop-blur-md border-b border-slate-200 shadow-sm">
        <div className="max-w-6xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white text-xl">
              <i className="fas fa-hamburger"></i>
            </div>
            <span className="text-xl font-black tracking-tighter uppercase italic text-slate-900">LunchRun</span>
          </div>

          <div className="flex items-center gap-6">
            <div className="text-right hidden sm:block">
              <div className="text-sm font-bold text-slate-900 leading-none">{user.name}</div>
              <div className="text-[10px] font-medium text-slate-400 uppercase tracking-wider mt-1">{user.email}</div>
            </div>
            <div className="w-12 h-12 bg-slate-100 rounded-full flex items-center justify-center text-slate-400 border border-slate-200">
              <i className="fas fa-user"></i>
            </div>
          </div>
        </div>
      </nav>

      <main className="max-w-5xl mx-auto px-6 py-12">
        {/* ACTION PANEL */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-12">
          <div className="flex gap-2">
            <Button onClick={() => setModals({ ...modals, create: true })} className="h-12 px-8 bg-indigo-600 text-white rounded-xl font-bold text-sm shadow-md hover:bg-indigo-700">
              <i className="fas fa-plus mr-2"></i> Create Run
            </Button>
            <Button variant="secondary" className="h-12 px-8 rounded-xl font-bold text-sm">
              Waitlist
            </Button>
          </div>

          <div className="flex items-center gap-3 px-4 py-2 bg-white rounded-full border border-slate-200 shadow-sm">
            <span className={`w-2 h-2 rounded-full ${syncStatus === 'ONLINE' ? 'bg-emerald-500' : 'bg-amber-400 animate-pulse'}`}></span>
            <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{syncStatus} MODE</span>
          </div>
        </div>

        {/* FEED */}
        <div className="grid grid-cols-1 gap-8">
          {runs.length === 0 ? (
            <div className="py-32 flex flex-col items-center justify-center text-center bg-white border border-dashed border-slate-200 rounded-3xl">
              <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center text-slate-200 text-2xl mb-4">
                <i className="fas fa-map-marker-alt"></i>
              </div>
              <p className="text-slate-400 font-medium italic">No active food runs at the moment.</p>
            </div>
          ) : (
            runs.map(run => {
              const isOwner = user.email.toLowerCase() === run.runnerEmail.toLowerCase();
              const hasJoined = run.orders.some(o => o.userEmail.toLowerCase() === user.email.toLowerCase());
              const spotsLeft = run.maxOrders - run.orders.length;

              return (
                <div key={run.id} className="bg-white border border-slate-200 rounded-2xl overflow-hidden shadow-sm hover:shadow-md transition-shadow duration-300">
                  <div className="p-8 md:p-10 flex flex-col md:flex-row gap-8">
                    <div className="flex-1">
                      <div className="flex items-center gap-3 mb-4">
                        <span className={`text-[10px] font-bold px-3 py-1 rounded-full uppercase tracking-widest ${run.status === 'active' ? 'bg-emerald-50 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}>
                          {run.status}
                        </span>
                        <span className="text-slate-300 text-xs">•</span>
                        <span className="text-xs font-medium text-slate-400">Runner: {run.runnerName}</span>
                      </div>

                      <h3 className="text-3xl font-extrabold text-slate-900 tracking-tight uppercase italic mb-6">{run.destination}</h3>

                      {run.orders.length > 0 && (
                        <div className="space-y-3 mb-8">
                          <div className="text-[10px] font-bold text-slate-300 uppercase tracking-widest mb-4">Current Orders ({run.orders.length})</div>
                          {run.orders.map(o => (
                            <div key={o.id} className="flex justify-between items-center text-sm">
                              <span className="font-semibold text-slate-700">{o.userName} <span className="text-slate-400 font-normal">ordered</span> {o.itemDescription}</span>
                              <span className="text-[10px] font-bold text-indigo-500 bg-indigo-50 px-2 py-1 rounded-md">FL {o.floor}</span>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>

                    <div className="w-full md:w-56 flex flex-col justify-between border-t md:border-t-0 md:border-l border-slate-100 pt-8 md:pt-0 md:pl-10">
                      <div className="mb-8">
                         <div className="text-4xl font-black text-slate-900 tabular-nums">{spotsLeft}</div>
                         <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Free Slots</div>
                      </div>

                      <div className="space-y-3">
                        {isOwner ? (
                          run.status === 'active' ? (
                            <Button onClick={() => updateState(runs.map(r => r.id === run.id ? {...r, status: 'departed'} : r))} className="w-full h-12 bg-orange-600 text-white rounded-xl font-bold">I'm Departing</Button>
                          ) : (
                            <Button onClick={() => setModals({...modals, arrive: run.id})} className="w-full h-12 bg-emerald-500 text-white rounded-xl font-bold">Confirm Arrival</Button>
                          )
                        ) : (
                          !hasJoined && run.status === 'active' && spotsLeft > 0 ? (
                            <Button onClick={() => setModals({ ...modals, join: run.id })} className="w-full h-12 bg-slate-900 text-white rounded-xl font-bold">Join Run</Button>
                          ) : (
                            <div className="text-center py-3 bg-slate-50 text-[11px] font-bold text-slate-400 rounded-xl border border-slate-100 uppercase italic">Run Locked</div>
                          )
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              );
            })
          )}
        </div>
      </main>

      {/* MODAL SYSTEM (Professional Styling) */}
      {modals.create && (
        <Modal title="Launch New Food Run" onClose={() => setModals({ ...modals, create: false })}>
          <form onSubmit={handleStart} className="space-y-6">
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Destination</label>
              <input required autoFocus className="w-full h-14 px-5 bg-slate-50 border border-slate-200 rounded-xl font-bold text-lg outline-none focus:border-indigo-500 transition-colors uppercase" placeholder="e.g. VITRINA" value={inputs.dest} onChange={e => setInputs({ ...inputs, dest: e.target.value })} />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Mins to Start</label>
                <input type="number" className="w-full h-14 px-5 bg-slate-50 border border-slate-200 rounded-xl font-bold text-lg outline-none" value={inputs.time} onChange={e => setInputs({ ...inputs, time: Number(e.target.value) })} />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Max Slots</label>
                <input type="number" className="w-full h-14 px-5 bg-slate-50 border border-slate-200 rounded-xl font-bold text-lg outline-none" value={inputs.max} onChange={e => setInputs({ ...inputs, max: Number(e.target.value) })} />
              </div>
            </div>
            <Button type="submit" className="w-full h-14 bg-indigo-600 text-white font-bold rounded-xl shadow-lg shadow-indigo-100">Broadcast Mission</Button>
          </form>
        </Modal>
      )}

      {modals.join && (
        <Modal title="Place Your Order" onClose={() => setModals({ ...modals, join: null })}>
          <form onSubmit={(e) => { e.preventDefault(); handleJoin(modals.join); }} className="space-y-6">
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Food / Item Name</label>
              <input required autoFocus className="w-full h-14 px-5 bg-slate-50 border border-slate-200 rounded-xl font-medium text-lg outline-none focus:border-indigo-500 transition-colors" placeholder="Double Cheeseburger" value={inputs.item} onChange={e => setInputs({ ...inputs, item: e.target.value })} />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Drop-off Location</label>
              <input required className="w-full h-14 px-5 bg-slate-50 border border-slate-200 rounded-xl font-medium text-lg outline-none focus:border-indigo-500 transition-colors" placeholder="Floor 4 / Desk 102" value={inputs.floor} onChange={e => setInputs({ ...inputs, floor: e.target.value })} />
            </div>
            <Button type="submit" className="w-full h-14 bg-slate-900 text-white font-bold rounded-xl">Confirm Entry</Button>
          </form>
        </Modal>
      )}

      {modals.arrive && (
        <Modal title="Signal Arrival" onClose={() => setModals({ ...modals, arrive: null })}>
          <form onSubmit={(e) => { e.preventDefault(); updateState(runs.filter(r => r.id !== modals.arrive)); setModals({...modals, arrive: null}); }} className="space-y-6">
            <div className="text-center py-4">
              <p className="text-slate-500 mb-6">Where did you leave the food?</p>
              <input required autoFocus className="w-full h-16 bg-slate-50 border border-slate-200 rounded-xl font-bold text-center text-2xl outline-none mb-6" placeholder="KITCHEN 4" value={inputs.loc} onChange={e => setInputs({ ...inputs, loc: e.target.value })} />
            </div>
            <Button type="submit" className="w-full h-14 bg-emerald-600 text-white font-bold rounded-xl shadow-lg shadow-emerald-100">Finish Mission</Button>
          </form>
        </Modal>
      )}
    </div>
  );
};

const Modal: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
  <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-center justify-center p-6">
    <div className="bg-white rounded-3xl w-full max-w-lg shadow-2xl border border-slate-200 overflow-hidden">
      <div className="px-8 py-6 border-b border-slate-100 flex justify-between items-center">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        <button onClick={onClose} className="w-10 h-10 rounded-full flex items-center justify-center text-slate-300 hover:text-slate-900 hover:bg-slate-50 transition-colors">
          <i className="fas fa-times"></i>
        </button>
      </div>
      <div className="p-8">
        {children}
      </div>
    </div>
  </div>
);

export default App;

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center gap-2 font-bold transition-all duration-200 antialiased active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer";

  const variants = {
    primary: "bg-indigo-600 text-white hover:bg-indigo-700",
    secondary: "bg-white border border-slate-200 text-slate-600 hover:bg-slate-50 hover:text-slate-900 hover:border-slate-300 shadow-sm",
    danger: "bg-red-500 text-white hover:bg-red-600",
    ghost: "text-slate-400 hover:text-slate-900 hover:bg-slate-50"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${className}`} 
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading ? <i className="fas fa-circle-notch fa-spin"></i> : children}
    </button>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { FoodRun, Order, WaitingOrder } from './types';
import { Button } from './components/Button';

const SYNC_KEY = 'lr_v10_final';
const SYNC_ROOT = `https://keyvalue.xyz/v1/${SYNC_KEY}_`;

const extractDomain = (email: string) => {
  const domain = email.split('@')[1] || 'public';
  return domain.replace(/[^a-zA-Z0-9]/g, '_');
};

const extractName = (email: string) => {
  return email.split('@')[0]
    .split(/[._-]/)
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
};

const App: React.FC = () => {
  const [user, setUser] = useState<{ name: string; email: string } | null>(() => {
    const saved = localStorage.getItem('lr_v10_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [waitlist, setWaitlist] = useState<WaitingOrder[]>([]);
  const [syncStatus, setSyncStatus] = useState<'ONLINE' | 'SYNCING' | 'LOCAL'>('ONLINE');
  const [view, setView] = useState<'runs' | 'waitlist'>('runs');
  const [modals, setModals] = useState<{ [key: string]: any }>({ create: false, join: null, wait: false, arrive: null });
  const [inputs, setInputs] = useState({ dest: '', time: 15, max: 6, item: '', floor: '', loc: '' });

  const lastUpdateRef = useRef<number>(0);
  const syncLock = useRef<boolean>(false);

  useEffect(() => {
    if (user) localStorage.setItem('lr_v10_user', JSON.stringify(user));
  }, [user]);

  const getSyncUrl = () => user ? `${SYNC_ROOT}${extractDomain(user.email)}` : null;

  // --- SYNC ENGINE ---
  const sync = async (forcePush: boolean = false, dataToPush?: { runs: FoodRun[], waitlist: WaitingOrder[] }) => {
    const url = getSyncUrl();
    if (!url || syncLock.current) return;
    syncLock.current = true;

    try {
      if (forcePush && dataToPush) {
        setSyncStatus('SYNCING');
        const ts = Date.now();
        await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'text/plain' },
          body: JSON.stringify({ ...dataToPush, ts })
        });
        lastUpdateRef.current = ts;
        setSyncStatus('ONLINE');
      } else {
        const res = await fetch(url);
        if (res.ok) {
          const text = await res.text();
          if (text) {
            const data = JSON.parse(text);
            if (data.ts && data.ts > lastUpdateRef.current) {
              setRuns(data.runs || []);
              setWaitlist(data.waitlist || []);
              lastUpdateRef.current = data.ts;
              setSyncStatus('ONLINE');
            }
          }
        }
      }
    } catch (e) {
      setSyncStatus('LOCAL');
    } finally {
      syncLock.current = false;
    }
  };

  useEffect(() => {
    if (!user) return;
    const interval = setInterval(() => sync(), 3000);
    sync();
    return () => clearInterval(interval);
  }, [user?.email]);

  const updateAndSync = (newRuns: FoodRun[], newWait: WaitingOrder[]) => {
    setRuns(newRuns);
    setWaitlist(newWait);
    sync(true, { runs: newRuns, waitlist: newWait });
  };

  // --- HANDLERS ---
  const startRun = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: user.name,
      runnerEmail: user.email,
      destination: inputs.dest.toUpperCase(),
      departureTime: Date.now() + (inputs.time * 60000),
      minutesUntilDeparture: inputs.time,
      maxOrders: inputs.max,
      status: 'active',
      orders: []
    };
    updateAndSync([newRun, ...runs], waitlist);
    setModals({ ...modals, create: false });
    setInputs({ ...inputs, dest: '' });
  };

  const joinRun = (runId: string) => {
    if (!user) return;
    const order: Order = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      userEmail: user.email,
      itemDescription: inputs.item,
      floor: inputs.floor,
      cibusCode: '',
      timestamp: Date.now()
    };
    const updated = runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, order] } : r);
    updateAndSync(updated, waitlist);
    setModals({ ...modals, join: null });
    setInputs({ ...inputs, item: '', floor: '' });
  };

  const addToWaitlist = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newItem: WaitingOrder = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      userEmail: user.email,
      destination: inputs.dest.toUpperCase(),
      itemDescription: inputs.item,
      floor: inputs.floor,
      timestamp: Date.now()
    };
    updateAndSync(runs, [newItem, ...waitlist]);
    setModals({ ...modals, wait: false });
    setInputs({ ...inputs, dest: '', item: '', floor: '' });
    setView('waitlist');
  };

  const promoteFromWaitlist = (runId: string, waitId: string) => {
    const waiter = waitlist.find(w => w.id === waitId);
    if (!waiter) return;
    const order: Order = {
      id: waiter.id,
      userName: waiter.userName,
      userEmail: waiter.userEmail,
      itemDescription: waiter.itemDescription,
      floor: waiter.floor,
      cibusCode: '',
      timestamp: Date.now()
    };
    const updatedRuns = runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, order] } : r);
    const updatedWait = waitlist.filter(w => w.id !== waitId);
    updateAndSync(updatedRuns, updatedWait);
  };

  if (!user) {
    return (
      <div className="min-h-screen bg-[#FDFDFF] flex items-center justify-center p-6">
        <div className="w-full max-w-md bg-white p-12 rounded-[3rem] shadow-[0_40px_100px_-20px_rgba(0,0,0,0.1)] text-center border border-slate-50">
          <div className="w-20 h-20 bg-indigo-600 rounded-[1.8rem] flex items-center justify-center text-white text-4xl mx-auto mb-10 shadow-2xl shadow-indigo-100">
            <i className="fas fa-paper-plane"></i>
          </div>
          <h1 className="text-4xl font-black tracking-tighter mb-4 text-slate-900 italic uppercase">LunchRun</h1>
          <p className="text-slate-400 mb-10 font-medium">Coordinate office food runs in real-time.</p>
          <form onSubmit={(e) => {
            e.preventDefault();
            const email = (e.currentTarget.elements[0] as HTMLInputElement).value;
            setUser({ name: extractName(email), email: email.toLowerCase() });
          }} className="space-y-4 text-left">
            <label className="text-[10px] font-black uppercase tracking-widest text-slate-300 ml-2">Work Email</label>
            <input required type="email" placeholder="name@company.com" className="w-full h-16 px-8 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl font-bold outline-none transition-all" />
            <Button type="submit" className="w-full h-16 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest">Identify Yourself</Button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] text-slate-900 font-sans selection:bg-indigo-100 antialiased">
      {/* HEADER SECTION */}
      <header className="max-w-6xl mx-auto px-6 pt-12 pb-8 flex justify-between items-center">
        <div className="flex items-center gap-4 group cursor-pointer" onClick={() => setView('runs')}>
          <div className="w-14 h-14 bg-indigo-600 rounded-[1.2rem] flex items-center justify-center text-white text-2xl shadow-xl shadow-indigo-100 group-hover:scale-110 transition-transform">
            <i className="fas fa-hamburger"></i>
          </div>
          <h1 className="text-2xl font-black tracking-tighter uppercase italic text-slate-900">LunchRun</h1>
        </div>

        <div className="flex items-center gap-6">
          <div className="text-right hidden sm:block">
            <div className="text-lg font-black text-slate-900 leading-none">{user.name}</div>
            <div className="flex items-center justify-end gap-2 mt-2">
               <span className={`w-2 h-2 rounded-full ${syncStatus === 'ONLINE' ? 'bg-emerald-500 shadow-[0_0_8px_#10b981]' : 'bg-amber-400'}`}></span>
               <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">{user.email}</span>
            </div>
          </div>
          <div className="w-14 h-14 bg-white border border-slate-100 rounded-2xl flex items-center justify-center text-slate-300 text-xl shadow-sm">
            <i className="fas fa-user-ninja"></i>
          </div>
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-6 pb-24">
        {/* NAVIGATION BAR */}
        <div className="bg-white border border-white rounded-3xl p-3 mb-16 flex justify-between items-center shadow-[0_20px_50px_-15px_rgba(0,0,0,0.05)]">
          <div className="flex gap-2">
            <Button onClick={() => setView('runs')} variant={view === 'runs' ? 'primary' : 'ghost'} className={`h-14 px-10 rounded-2xl text-[12px] font-black uppercase tracking-widest ${view === 'runs' ? 'shadow-xl shadow-indigo-100' : ''}`}>
              Active Runs
            </Button>
            <Button onClick={() => setView('waitlist')} variant={view === 'waitlist' ? 'primary' : 'ghost'} className={`h-14 px-10 rounded-2xl text-[12px] font-black uppercase tracking-widest ${view === 'waitlist' ? 'shadow-xl shadow-indigo-100' : ''}`}>
              Waitlist ({waitlist.length})
            </Button>
          </div>
          <div className="pr-4 flex gap-4">
             <Button onClick={() => setModals({ ...modals, create: true })} className="h-14 px-8 bg-indigo-600 text-white rounded-2xl text-[11px] font-black uppercase tracking-widest shadow-lg shadow-indigo-50">
               <i className="fas fa-plus mr-2"></i> Start Run
             </Button>
             <Button onClick={() => setModals({ ...modals, wait: true })} className="h-14 px-8 bg-slate-900 text-white rounded-2xl text-[11px] font-black uppercase tracking-widest shadow-lg shadow-slate-200">
               <i className="fas fa-hourglass-half mr-2"></i> I Want Food
             </Button>
          </div>
        </div>

        {/* FEED CONTENT */}
        <div className="space-y-12">
          {view === 'runs' ? (
            runs.length === 0 ? (
              <EmptyState icon="fa-ghost" title="The sky is empty" subtitle="No missions currently in progress." />
            ) : (
              runs.map(run => (
                <RunCard key={run.id} run={run} userEmail={user.email} onJoin={() => setModals({ ...modals, join: run.id })} onArrive={() => setModals({ ...modals, arrive: run.id })} onDepart={() => updateAndSync(runs.map(r => r.id === run.id ? { ...r, status: 'departed' } : r), waitlist)} waitlist={waitlist} onPromote={(waitId) => promoteFromWaitlist(run.id, waitId)} />
              ))
            )
          ) : (
            waitlist.length === 0 ? (
              <EmptyState icon="fa-couch" title="Quiet in the lobby" subtitle="Everyone seems satisfied... for now." />
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {waitlist.map(item => (
                  <WaitCard key={item.id} item={item} />
                ))}
              </div>
            )
          )}
        </div>
      </main>

      {/* MODALS */}
      {modals.create && (
        <Overlay title="Launch Operation" onClose={() => setModals({ ...modals, create: false })}>
          <form onSubmit={startRun} className="space-y-8">
            <div className="space-y-3 text-left">
              <label className="text-[10px] font-black text-slate-300 uppercase tracking-[0.2em] ml-2">Target Destination</label>
              <input required autoFocus className="w-full h-18 px-8 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-[1.5rem] font-black text-2xl uppercase outline-none transition-all" placeholder="E.G. VITRINA" value={inputs.dest} onChange={e => setInputs({ ...inputs, dest: e.target.value })} />
            </div>
            <div className="grid grid-cols-2 gap-6">
              <div className="space-y-3 text-left">
                <label className="text-[10px] font-black text-slate-300 uppercase tracking-[0.2em] ml-2">Mins to Start</label>
                <input type="number" className="w-full h-18 px-8 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-[1.5rem] font-black text-2xl outline-none" value={inputs.time} onChange={e => setInputs({ ...inputs, time: Number(e.target.value) })} />
              </div>
              <div className="space-y-3 text-left">
                <label className="text-[10px] font-black text-slate-300 uppercase tracking-[0.2em] ml-2">Max Slots</label>
                <input type="number" className="w-full h-18 px-8 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-[1.5rem] font-black text-2xl outline-none" value={inputs.max} onChange={e => setInputs({ ...inputs, max: Number(e.target.value) })} />
              </div>
            </div>
            <Button type="submit" className="w-full h-20 bg-indigo-600 text-white font-black uppercase tracking-widest rounded-[1.8rem] shadow-2xl shadow-indigo-100">Broadcast Run</Button>
          </form>
        </Overlay>
      )}

      {modals.wait && (
        <Overlay title="Signal Hunger" onClose={() => setModals({ ...modals, wait: false })}>
          <form onSubmit={addToWaitlist} className="space-y-6">
            <input required autoFocus className="w-full h-18 px-8 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl font-bold text-lg outline-none" placeholder="Where do you want food from?" value={inputs.dest} onChange={e => setInputs({ ...inputs, dest: e.target.value })} />
            <input required className="w-full h-18 px-8 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl font-bold text-lg outline-none" placeholder="Specific items?" value={inputs.item} onChange={e => setInputs({ ...inputs, item: e.target.value })} />
            <input required className="w-full h-18 px-8 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl font-bold text-lg outline-none" placeholder="Floor / Desk Num" value={inputs.floor} onChange={e => setInputs({ ...inputs, floor: e.target.value })} />
            <Button type="submit" className="w-full h-20 bg-slate-900 text-white font-black uppercase rounded-[1.8rem]">Add to Waitlist</Button>
          </form>
        </Overlay>
      )}

      {modals.join && (
        <Overlay title="Add to Manifest" onClose={() => setModals({ ...modals, join: null })}>
          <form onSubmit={(e) => { e.preventDefault(); joinRun(modals.join); }} className="space-y-6">
            <input required autoFocus className="w-full h-18 px-8 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl font-bold text-lg outline-none" placeholder="What are you ordering?" value={inputs.item} onChange={e => setInputs({ ...inputs, item: e.target.value })} />
            <input required className="w-full h-18 px-8 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl font-bold text-lg outline-none" placeholder="Floor / Desk Num" value={inputs.floor} onChange={e => setInputs({ ...inputs, floor: e.target.value })} />
            <Button type="submit" className="w-full h-20 bg-indigo-600 text-white font-black uppercase rounded-[1.8rem]">Confirm Order</Button>
          </form>
        </Overlay>
      )}

      {modals.arrive && (
        <Overlay title="Signal Arrival" onClose={() => setModals({ ...modals, arrive: null })}>
          <form onSubmit={(e) => { e.preventDefault(); updateAndSync(runs.filter(r => r.id !== modals.arrive), waitlist); setModals({ ...modals, arrive: null }); }} className="space-y-8">
            <input required autoFocus className="w-full h-20 px-8 bg-slate-50 border-2 border-transparent focus:border-emerald-500 rounded-2xl font-black text-center text-3xl outline-none" placeholder="DROP-OFF POINT" value={inputs.loc} onChange={e => setInputs({ ...inputs, loc: e.target.value })} />
            <Button type="submit" className="w-full h-20 bg-emerald-500 text-white font-black uppercase rounded-[1.8rem] shadow-2xl shadow-emerald-100">Finish Mission</Button>
          </form>
        </Overlay>
      )}
    </div>
  );
};

const RunCard: React.FC<{ run: FoodRun, userEmail: string, onJoin: () => void, onArrive: () => void, onDepart: () => void, waitlist: WaitingOrder[], onPromote: (id: string) => void }> = ({ run, userEmail, onJoin, onArrive, onDepart, waitlist, onPromote }) => {
  const isOwner = userEmail.toLowerCase() === run.runnerEmail.toLowerCase();
  const hasJoined = run.orders.some(o => o.userEmail.toLowerCase() === userEmail.toLowerCase());
  const spotsLeft = run.maxOrders - run.orders.length;

  // Find people on waitlist looking for this destination
  const relevantWaiters = waitlist.filter(w => w.destination.toUpperCase() === run.destination.toUpperCase());

  return (
    <div className="bg-white border border-slate-50 rounded-[3rem] p-12 shadow-[0_40px_100px_-30px_rgba(0,0,0,0.06)] hover:shadow-[0_50px_120px_-30px_rgba(0,0,0,0.1)] transition-all transform hover:-translate-y-1">
      <div className="flex justify-between items-start mb-12">
        <div className="flex items-center gap-8">
           <div className="w-20 h-20 bg-slate-50 rounded-[1.5rem] flex items-center justify-center text-4xl">
              <i className={`fas ${run.status === 'departed' ? 'fa-truck-fast text-indigo-400' : 'fa-pizza-slice text-orange-400'}`}></i>
           </div>
           <div>
              <h3 className="text-5xl font-black text-slate-900 tracking-tighter uppercase italic leading-none mb-3">{run.destination}</h3>
              <div className="flex items-center gap-4">
                 <span className="text-[11px] font-black text-slate-300 uppercase tracking-widest">OP: {run.runnerName}</span>
                 <span className={`text-[9px] font-black px-3 py-1 rounded-lg uppercase tracking-widest ${run.status === 'active' ? 'bg-emerald-50 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}>• {run.status}</span>
              </div>
           </div>
        </div>
        <div className="text-right pt-2">
           <div className="text-4xl font-black text-slate-900 tabular-nums">{spotsLeft}</div>
           <div className="text-[10px] font-black text-slate-200 uppercase tracking-widest mt-1">Free Slots</div>
        </div>
      </div>

      {run.orders.length > 0 && (
        <div className="mb-12 space-y-4 border-l-4 border-slate-50 pl-10 py-2">
           <p className="text-[11px] font-black text-slate-200 uppercase tracking-[0.4em] mb-6 italic">Current Manifest</p>
           {run.orders.map(o => (
             <div key={o.id} className="flex justify-between items-center group">
                <span className="text-lg font-bold text-slate-700">{o.userName} <span className="text-slate-300 font-medium">wants</span> {o.itemDescription}</span>
                <span className="text-[11px] font-black text-indigo-400 bg-indigo-50/50 px-3 py-1.5 rounded-xl opacity-0 group-hover:opacity-100 transition-opacity">LEVEL {o.floor}</span>
             </div>
           ))}
        </div>
      )}

      {/* WAITLIST SUGGESTION FOR RUNNERS */}
      {isOwner && relevantWaiters.length > 0 && spotsLeft > 0 && (
        <div className="mb-12 p-6 bg-indigo-50/50 rounded-2xl border border-indigo-100 border-dashed">
          <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-4">Hungry People Waiting for {run.destination}:</p>
          <div className="flex flex-wrap gap-2">
            {relevantWaiters.map(w => (
              <button key={w.id} onClick={() => onPromote(w.id)} className="px-4 py-2 bg-white border border-indigo-100 rounded-xl text-xs font-bold text-indigo-600 hover:bg-indigo-600 hover:text-white transition-all">
                + Add {w.userName} ({w.itemDescription})
              </button>
            ))}
          </div>
        </div>
      )}

      <div className="w-full">
        {isOwner ? (
          run.status === 'active' ? (
            <Button onClick={onDepart} className="w-full h-20 bg-indigo-600 text-white text-xl font-black uppercase italic tracking-tighter rounded-[1.8rem] shadow-xl shadow-indigo-100">Commence Departure</Button>
          ) : (
            <Button onClick={onArrive} className="w-full h-20 bg-emerald-500 text-white text-xl font-black uppercase rounded-[1.8rem] shadow-xl shadow-emerald-100">Confirm Arrival</Button>
          )
        ) : (
          !hasJoined && run.status === 'active' && spotsLeft > 0 ? (
            <Button onClick={onJoin} className="w-full h-20 bg-slate-900 text-white text-xl font-black uppercase rounded-[1.8rem]">Join Mission</Button>
          ) : (
            <div className="w-full py-8 text-center text-[12px] font-black uppercase text-slate-300 tracking-[0.5em] bg-slate-50/50 rounded-[1.8rem] border border-slate-100 italic">Mission Locked</div>
          )
        )}
      </div>
    </div>
  );
};

