import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center gap-2 font-bold transition-all duration-300 antialiased active:scale-[0.97] disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer border-none outline-none";

  const variants = {
    primary: "bg-indigo-600 text-white hover:bg-indigo-700 hover:shadow-2xl hover:shadow-indigo-500/30",
    secondary: "bg-white border-2 border-slate-50 text-slate-500 hover:text-slate-900 hover:bg-slate-50 shadow-sm",
    danger: "bg-rose-500 text-white hover:bg-rose-600 shadow-lg shadow-rose-100",
    ghost: "text-slate-400 hover:text-indigo-600 hover:bg-indigo-50/50"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${className}`} 
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading ? <i className="fas fa-circle-notch fa-spin"></i> : children}
    </button>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { FoodRun, Order, WaitingOrder } from './types';
import { Button } from './components/Button';

// Robust Sync Configuration
const SYNC_ROOT = 'https://keyvalue.xyz/v1/lunchrun_v11_';

const extractDomain = (email: string) => {
  const domain = email.split('@')[1] || 'public';
  return domain.replace(/[^a-zA-Z0-9]/g, '_');
};

const extractName = (email: string) => {
  return email.split('@')[0]
    .split(/[._-]/)
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
};

const App: React.FC = () => {
  const [user, setUser] = useState<{ name: string; email: string } | null>(() => {
    const saved = localStorage.getItem('lr_v11_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [waitlist, setWaitlist] = useState<WaitingOrder[]>([]);
  const [syncStatus, setSyncStatus] = useState<'ONLINE' | 'SYNCING' | 'LOCAL'>('ONLINE');
  const [view, setView] = useState<'runs' | 'waitlist'>('runs');
  const [modals, setModals] = useState<{ [key: string]: any }>({ create: false, join: null, wait: false, arrive: null });
  const [inputs, setInputs] = useState({ dest: '', time: 15, max: 6, item: '', floor: '', loc: '' });

  const lastUpdateRef = useRef<number>(0);
  const syncLock = useRef<boolean>(false);

  useEffect(() => {
    if (user) localStorage.setItem('lr_v11_user', JSON.stringify(user));
  }, [user]);

  const getSyncUrl = () => user ? `${SYNC_ROOT}${extractDomain(user.email)}` : null;

  // --- SYNC ENGINE ---
  const sync = async (forcePush: boolean = false, dataToPush?: { runs: FoodRun[], waitlist: WaitingOrder[] }) => {
    const url = getSyncUrl();
    if (!url || syncLock.current) return;
    syncLock.current = true;

    try {
      if (forcePush && dataToPush) {
        setSyncStatus('SYNCING');
        const ts = Date.now();
        // Optimizing payload: Sync only necessary active data
        const body = JSON.stringify({ runs: dataToPush.runs, waitlist: dataToPush.waitlist, ts });
        await fetch(url, { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body });
        lastUpdateRef.current = ts;
        setSyncStatus('ONLINE');
      } else {
        const res = await fetch(url);
        if (res.ok) {
          const text = await res.text();
          if (text) {
            const data = JSON.parse(text);
            if (data.ts && data.ts > lastUpdateRef.current) {
              setRuns(data.runs || []);
              setWaitlist(data.waitlist || []);
              lastUpdateRef.current = data.ts;
              setSyncStatus('ONLINE');
            }
          }
        }
      }
    } catch (e) {
      setSyncStatus('LOCAL');
    } finally {
      syncLock.current = false;
    }
  };

  useEffect(() => {
    if (!user) return;
    const interval = setInterval(() => sync(), 3000);
    sync();
    return () => clearInterval(interval);
  }, [user?.email]);

  const updateAndSync = (newRuns: FoodRun[], newWait: WaitingOrder[]) => {
    setRuns(newRuns);
    setWaitlist(newWait);
    sync(true, { runs: newRuns, waitlist: newWait });
  };

  // --- ACTIONS ---
  const handleStartRun = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: user.name,
      runnerEmail: user.email,
      destination: inputs.dest.toUpperCase(),
      departureTime: Date.now() + (inputs.time * 60000),
      minutesUntilDeparture: inputs.time,
      maxOrders: inputs.max,
      status: 'active',
      orders: []
    };
    updateAndSync([newRun, ...runs], waitlist);
    setModals({ ...modals, create: false });
    setInputs({ ...inputs, dest: '' });
  };

  const handleJoinRun = (runId: string) => {
    if (!user) return;
    const order: Order = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      userEmail: user.email,
      itemDescription: inputs.item,
      floor: inputs.floor,
      cibusCode: '',
      timestamp: Date.now()
    };
    const updated = runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, order] } : r);
    updateAndSync(updated, waitlist);
    setModals({ ...modals, join: null });
    setInputs({ ...inputs, item: '', floor: '' });
  };

  const handleWaitlistAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newItem: WaitingOrder = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      userEmail: user.email,
      destination: inputs.dest.toUpperCase(),
      itemDescription: inputs.item,
      floor: inputs.floor,
      timestamp: Date.now()
    };
    updateAndSync(runs, [newItem, ...waitlist]);
    setModals({ ...modals, wait: false });
    setInputs({ ...inputs, dest: '', item: '', floor: '' });
    setView('waitlist');
  };

  const promoteFromWaitlist = (runId: string, waitId: string) => {
    const waiter = waitlist.find(w => w.id === waitId);
    if (!waiter) return;
    const order: Order = {
      id: waiter.id,
      userName: waiter.userName,
      userEmail: waiter.userEmail,
      itemDescription: waiter.itemDescription,
      floor: waiter.floor,
      cibusCode: '',
      timestamp: Date.now()
    };
    const updatedRuns = runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, order] } : r);
    const updatedWait = waitlist.filter(w => w.id !== waitId);
    updateAndSync(updatedRuns, updatedWait);
  };

  if (!user) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6">
        <div className="w-full max-w-sm bg-white p-12 rounded-[4rem] shadow-[0_40px_100px_-20px_rgba(0,0,0,0.1)] text-center">
          <div className="w-24 h-24 bg-indigo-600 rounded-[2.5rem] flex items-center justify-center text-white text-5xl mx-auto mb-10 shadow-2xl shadow-indigo-100">
            <i className="fas fa-pizza-slice"></i>
          </div>
          <h1 className="text-4xl font-black tracking-tighter mb-4 text-slate-900 italic uppercase">LunchRun</h1>
          <form onSubmit={(e) => {
            e.preventDefault();
            const email = (e.currentTarget.elements[0] as HTMLInputElement).value;
            setUser({ name: extractName(email), email: email.toLowerCase() });
          }} className="space-y-4">
            <input required type="email" placeholder="work@company.com" className="w-full h-18 px-8 bg-slate-50 border-2 border-transparent focus:border-indigo-600 rounded-2xl font-bold text-center outline-none transition-all" />
            <Button type="submit" className="w-full h-18 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-indigo-100">Enter Terminal</Button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50/50 text-slate-900 font-sans selection:bg-indigo-100 antialiased">
      <div className="max-w-5xl mx-auto px-6 py-12">

        {/* HEADER: Profile Right - Beautiful v6 Style */}
        <header className="flex justify-end items-center mb-16 gap-10 animate-in fade-in slide-in-from-top-4 duration-700">
          <div className="text-right">
            <h2 className="text-4xl font-black tracking-tight uppercase italic leading-none text-slate-900">{user.name}</h2>
            <div className="flex items-center justify-end gap-2 mt-3">
              <span className={`w-2.5 h-2.5 rounded-full ${syncStatus === 'ONLINE' ? 'bg-emerald-500 shadow-[0_0_12px_#10b981]' : 'bg-orange-400'}`}></span>
              <span className="text-[12px] font-black text-slate-300 uppercase tracking-[0.3em]">{user.email}</span>
            </div>
          </div>
          <div className="w-24 h-24 bg-indigo-600 rounded-[2.5rem] flex items-center justify-center text-white text-5xl shadow-[0_30px_60px_-15px_rgba(79,70,229,0.4)] transform hover:rotate-3 transition-transform">
            <i className="fas fa-hamburger"></i>
          </div>
        </header>

        {/* ACTION BAR: Buttons Left - Beautiful v6 Style */}
        <div className="bg-white/90 backdrop-blur-md border border-white rounded-[2.5rem] p-4 mb-24 flex justify-between items-center shadow-[0_25px_60px_-15px_rgba(0,0,0,0.06)]">
          <div className="flex gap-4">
            <Button onClick={() => setModals({ ...modals, create: true })} className="h-16 px-12 bg-indigo-600 text-white text-[13px] font-black uppercase tracking-widest rounded-3xl shadow-2xl shadow-indigo-100 hover:scale-105 transition-transform">
              START RUN
            </Button>
            <div className="flex bg-slate-50 p-1 rounded-3xl">
              <button onClick={() => setView('runs')} className={`h-14 px-8 rounded-[1.4rem] text-[11px] font-black uppercase tracking-widest transition-all ${view === 'runs' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-300 hover:text-slate-500'}`}>
                Active Runs
              </button>
              <button onClick={() => setView('waitlist')} className={`h-14 px-8 rounded-[1.4rem] text-[11px] font-black uppercase tracking-widest transition-all ${view === 'waitlist' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-300 hover:text-slate-500'}`}>
                Waitlist ({waitlist.length})
              </button>
            </div>
          </div>
          <div className="pr-12">
            <Button onClick={() => setModals({ ...modals, wait: true })} variant="ghost" className="text-[11px] font-black tracking-widest text-slate-400">
              <i className="fas fa-plus mr-2"></i> I'M HUNGRY
            </Button>
          </div>
        </div>

        {/* FEED CONTENT */}
        <div className="max-w-3xl mx-auto space-y-20">
          {view === 'runs' ? (
            runs.length === 0 ? (
              <EmptyState icon="fa-ghost" title="Zero Missions" subtitle="No food runs are currently broadcasted." />
            ) : (
              runs.map(run => (
                <RunCard key={run.id} run={run} userEmail={user.email} onJoin={() => setModals({ ...modals, join: run.id })} onArrive={() => setModals({ ...modals, arrive: run.id })} onDepart={() => updateAndSync(runs.map(r => r.id === run.id ? { ...r, status: 'departed' } : r), waitlist)} waitlist={waitlist} onPromote={(waitId) => promoteFromWaitlist(run.id, waitId)} />
              ))
            )
          ) : (
            waitlist.length === 0 ? (
              <EmptyState icon="fa-couch" title="Empty Lobby" subtitle="Looks like everyone's full." />
            ) : (
              <div className="grid grid-cols-1 gap-8">
                {waitlist.map(item => (
                  <WaitCard key={item.id} item={item} />
                ))}
              </div>
            )
          )}
        </div>
      </div>

      {/* MODALS: Large & Beautiful */}
      {modals.create && (
        <Overlay title="Launch Operation" onClose={() => setModals({ ...modals, create: false })}>
          <form onSubmit={handleStartRun} className="space-y-10">
            <div className="space-y-4">
              <label className="text-[12px] font-black text-slate-300 uppercase tracking-widest ml-1">Destination</label>
              <input required autoFocus className="w-full h-20 px-10 bg-slate-50 border-4 border-transparent focus:border-indigo-500/20 rounded-[2rem] font-black text-3xl uppercase outline-none transition-all" placeholder="E.G. VITRINA" value={inputs.dest} onChange={e => setInputs({ ...inputs, dest: e.target.value })} />
            </div>
            <div className="grid grid-cols-2 gap-8">
               <input type="number" className="h-20 px-10 bg-slate-50 border-4 border-transparent focus:border-indigo-500/20 rounded-[2rem] font-black text-2xl outline-none" value={inputs.time} onChange={e => setInputs({ ...inputs, time: Number(e.target.value) })} />
               <input type="number" className="h-20 px-10 bg-slate-50 border-4 border-transparent focus:border-indigo-500/20 rounded-[2rem] font-black text-2xl outline-none" value={inputs.max} onChange={e => setInputs({ ...inputs, max: Number(e.target.value) })} />
            </div>
            <Button type="submit" className="w-full h-24 bg-indigo-600 text-white font-black uppercase text-xl rounded-[2.5rem] shadow-2xl shadow-indigo-100">BROADCAST MISSION</Button>
          </form>
        </Overlay>
      )}

      {modals.wait && (
        <Overlay title="Manifest Entry" onClose={() => setModals({ ...modals, wait: false })}>
          <form onSubmit={handleWaitlistAdd} className="space-y-8">
            <input required autoFocus className="w-full h-20 px-10 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-[2rem] font-bold text-xl outline-none" placeholder="Target Destination?" value={inputs.dest} onChange={e => setInputs({ ...inputs, dest: e.target.value })} />
            <input required className="w-full h-20 px-10 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-[2rem] font-bold text-xl outline-none" placeholder="What item?" value={inputs.item} onChange={e => setInputs({ ...inputs, item: e.target.value })} />
            <input required className="w-full h-20 px-10 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-[2rem] font-bold text-xl outline-none" placeholder="Floor Num" value={inputs.floor} onChange={e => setInputs({ ...inputs, floor: e.target.value })} />
            <Button type="submit" className="w-full h-24 bg-slate-900 text-white font-black uppercase text-xl rounded-[2.5rem]">SIGNAL HUNGER</Button>
          </form>
        </Overlay>
      )}

      {modals.join && (
        <Overlay title="Add to Flight" onClose={() => setModals({ ...modals, join: null })}>
          <form onSubmit={(e) => { e.preventDefault(); handleJoinRun(modals.join); }} className="space-y-8">
            <input required autoFocus className="w-full h-20 px-10 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-[2rem] font-bold text-xl outline-none" placeholder="What are you ordering?" value={inputs.item} onChange={e => setInputs({ ...inputs, item: e.target.value })} />
            <input required className="w-full h-20 px-10 bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-[2rem] font-bold text-xl outline-none" placeholder="Floor / Desk Num" value={inputs.floor} onChange={e => setInputs({ ...inputs, floor: e.target.value })} />
            <Button type="submit" className="w-full h-24 bg-indigo-600 text-white font-black uppercase text-xl rounded-[2.5rem]">CONFIRM ORDER</Button>
          </form>
        </Overlay>
      )}

      {modals.arrive && (
        <Overlay title="Signal Arrival" onClose={() => setModals({ ...modals, arrive: null })}>
          <form onSubmit={(e) => { e.preventDefault(); updateAndSync(runs.filter(r => r.id !== modals.arrive), waitlist); setModals({ ...modals, arrive: null }); }} className="space-y-10">
            <input required autoFocus className="w-full h-24 bg-slate-50 border-4 border-transparent focus:border-emerald-500 rounded-[2.5rem] font-black text-center text-3xl outline-none" placeholder="DROP-OFF POINT" value={inputs.loc} onChange={e => setInputs({ ...inputs, loc: e.target.value })} />
            <Button type="submit" className="w-full h-24 bg-emerald-500 text-white font-black uppercase text-xl rounded-[2.5rem] shadow-2xl shadow-emerald-100">MISSION COMPLETE</Button>
          </form>
        </Overlay>
      )}
    </div>
  );
};

const RunCard: React.FC<{ run: FoodRun, userEmail: string, onJoin: () => void, onArrive: () => void, onDepart: () => void, waitlist: WaitingOrder[], onPromote: (id: string) => void }> = ({ run, userEmail, onJoin, onArrive, onDepart, waitlist, onPromote }) => {
  const isOwner = userEmail.toLowerCase() === run.runnerEmail.toLowerCase();
  const hasJoined = run.orders.some(o => o.userEmail.toLowerCase() === userEmail.toLowerCase());
  const spotsLeft = run.maxOrders - run.orders.length;
  const relevantWaiters = waitlist.filter(w => w.destination.toUpperCase() === run.destination.toUpperCase());

  return (
    <div className="bg-white border border-slate-50 rounded-[4rem] p-16 shadow-[0_50px_120px_-30px_rgba(0,0,0,0.08)] transition-all duration-500 hover:shadow-[0_60px_140px_-35px_rgba(0,0,0,0.12)] transform hover:-translate-y-2">
      <div className="flex justify-between items-start mb-16">
        <div className="flex items-center gap-12">
           <div className="w-24 h-24 bg-slate-50 border border-slate-100 rounded-[2.5rem] flex items-center justify-center text-5xl">
              <i className={`fas ${run.status === 'departed' ? 'fa-truck-fast text-indigo-400' : 'fa-pizza-slice text-orange-400'}`}></i>
           </div>
           <div>
              <h3 className="text-6xl font-black text-slate-900 tracking-tighter uppercase italic leading-none mb-4">{run.destination}</h3>
              <div className="flex items-center gap-6">
                 <span className="text-[13px] font-black text-slate-300 uppercase tracking-widest">RUNNER: {run.runnerName}</span>
                 <span className={`text-[11px] font-black px-4 py-1.5 rounded-xl uppercase ${run.status === 'active' ? 'bg-emerald-50 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}>• {run.status}</span>
              </div>
           </div>
        </div>
        <div className="text-right pt-2">
           <div className="text-5xl font-black text-slate-900 tabular-nums">{spotsLeft}</div>
           <div className="text-[12px] font-black text-slate-200 uppercase tracking-widest mt-2">FREE SLOTS</div>
        </div>
      </div>

      {run.orders.length > 0 && (
        <div className="mb-16 space-y-5 border-l-8 border-slate-50 pl-16 py-2">
           <p className="text-[12px] font-black text-slate-200 uppercase tracking-[0.5em] mb-8 italic">MANIFEST ENTRY</p>
           {run.orders.map(o => (
             <div key={o.id} className="flex justify-between items-center group">
                <span className="text-xl font-bold text-slate-700">{o.userName} <span className="text-slate-300 font-medium">needs</span> {o.itemDescription}</span>
                <span className="text-[12px] font-black text-indigo-400 bg-indigo-50 px-4 py-2 rounded-2xl opacity-0 group-hover:opacity-100 transition-opacity">LEVEL {o.floor}</span>
             </div>
           ))}
        </div>
      )}

      {isOwner && relevantWaiters.length > 0 && spotsLeft > 0 && (
        <div className="mb-12 p-8 bg-indigo-50/30 rounded-[2.5rem] border-4 border-indigo-50 border-dashed">
          <p className="text-[11px] font-black text-indigo-300 uppercase tracking-[0.3em] mb-6">Suggestions from Waitlist:</p>
          <div className="flex flex-wrap gap-3">
            {relevantWaiters.map(w => (
              <button key={w.id} onClick={() => onPromote(w.id)} className="px-6 py-3 bg-white rounded-2xl text-sm font-black text-indigo-600 shadow-sm hover:bg-indigo-600 hover:text-white transition-all border border-indigo-100">
                + Add {w.userName}
              </button>
            ))}
          </div>
        </div>
      )}

      <div className="w-full">
        {isOwner ? (
          run.status === 'active' ? (
            <Button onClick={onDepart} className="w-full h-24 bg-indigo-600 text-white text-3xl font-black uppercase italic tracking-tighter rounded-[2.5rem] shadow-[0_25px_50px_-15px_rgba(79,70,229,0.4)]">DEPART NOW</Button>
          ) : (
            <Button onClick={onArrive} className="w-full h-24 bg-emerald-500 text-white text-3xl font-black uppercase rounded-[2.5rem] shadow-[0_25px_50px_-15px_rgba(16,185,129,0.4)]">SIGNAL ARRIVAL</Button>
          )
        ) : (
          !hasJoined && run.status === 'active' && spotsLeft > 0 ? (
            <Button onClick={onJoin} className="w-full h-24 bg-slate-900 text-white text-3xl font-black uppercase rounded-[2.5rem] shadow-2xl">JOIN MISSION</Button>
          ) : (
            <div className="w-full py-10 text-center text-[13px] font-black uppercase text-slate-300 tracking-[0.6em] bg-slate-50/50 rounded-[2.5rem] border border-slate-100 italic">MANIFEST LOCKED</div>
          )
        )}
      </div>
    </div>
  );
};

