import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center gap-2 font-bold transition-all duration-300 antialiased active:scale-[0.96] disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer border-none outline-none";

  const variants = {
    primary: "bg-indigo-600 text-white hover:bg-indigo-700 hover:shadow-2xl hover:shadow-indigo-500/30",
    secondary: "bg-white border-2 border-slate-50 text-slate-400 hover:text-slate-900 hover:bg-slate-50 shadow-sm",
    danger: "bg-rose-500 text-white hover:bg-rose-600 shadow-xl shadow-rose-100",
    ghost: "text-slate-300 hover:text-indigo-600 hover:bg-indigo-50/50"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${className}`} 
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading ? <i className="fas fa-circle-notch fa-spin"></i> : children}
    </button>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { FoodRun, Order, WaitingOrder } from './types';
import { Button } from './components/Button';

const SYNC_ROOT = 'https://keyvalue.xyz/v1/lunchrun_v12_';

const extractDomain = (email: string) => {
  const domain = email.split('@')[1] || 'public';
  return domain.replace(/[^a-zA-Z0-9]/g, '_');
};

const extractName = (email: string) => {
  return email.split('@')[0]
    .split(/[._-]/)
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
};

const App: React.FC = () => {
  const [user, setUser] = useState<{ name: string; email: string } | null>(() => {
    const saved = localStorage.getItem('lr_v12_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [waitlist, setWaitlist] = useState<WaitingOrder[]>([]);
  const [syncStatus, setSyncStatus] = useState<'ONLINE' | 'SYNCING' | 'LOCAL'>('ONLINE');
  const [view, setView] = useState<'runs' | 'waitlist'>('runs');
  const [modals, setModals] = useState<{ [key: string]: any }>({ create: false, join: null, wait: false, arrive: null });
  const [inputs, setInputs] = useState({ dest: '', time: 15, max: 6, item: '', floor: '', loc: '' });

  const lastUpdateRef = useRef<number>(0);
  const syncLock = useRef<boolean>(false);

  useEffect(() => {
    if (user) localStorage.setItem('lr_v12_user', JSON.stringify(user));
  }, [user]);

  const getSyncUrl = () => user ? `${SYNC_ROOT}${extractDomain(user.email)}` : null;

  const sync = async (forcePush: boolean = false, dataToPush?: { runs: FoodRun[], waitlist: WaitingOrder[] }) => {
    const url = getSyncUrl();
    if (!url || syncLock.current) return;
    syncLock.current = true;

    try {
      if (forcePush && dataToPush) {
        setSyncStatus('SYNCING');
        const ts = Date.now();
        const body = JSON.stringify({ runs: dataToPush.runs, waitlist: dataToPush.waitlist, ts });
        await fetch(url, { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body });
        lastUpdateRef.current = ts;
        setSyncStatus('ONLINE');
      } else {
        const res = await fetch(url);
        if (res.ok) {
          const text = await res.text();
          if (text) {
            const data = JSON.parse(text);
            if (data.ts && data.ts > lastUpdateRef.current) {
              setRuns(data.runs || []);
              setWaitlist(data.waitlist || []);
              lastUpdateRef.current = data.ts;
              setSyncStatus('ONLINE');
            }
          }
        }
      }
    } catch (e) {
      setSyncStatus('LOCAL');
    } finally {
      syncLock.current = false;
    }
  };

  useEffect(() => {
    if (!user) return;
    const interval = setInterval(() => sync(), 3000);
    sync();
    return () => clearInterval(interval);
  }, [user?.email]);

  const updateAndSync = (newRuns: FoodRun[], newWait: WaitingOrder[]) => {
    setRuns(newRuns);
    setWaitlist(newWait);
    sync(true, { runs: newRuns, waitlist: newWait });
  };

  const handleStartRun = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: user.name,
      runnerEmail: user.email,
      destination: inputs.dest.toUpperCase(),
      departureTime: Date.now() + (inputs.time * 60000),
      minutesUntilDeparture: inputs.time,
      maxOrders: inputs.max,
      status: 'active',
      orders: []
    };
    updateAndSync([newRun, ...runs], waitlist);
    setModals({ ...modals, create: false });
    setInputs({ ...inputs, dest: '' });
  };

  const handleJoinRun = (runId: string) => {
    if (!user) return;
    const order: Order = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      userEmail: user.email,
      itemDescription: inputs.item,
      floor: inputs.floor,
      cibusCode: '',
      timestamp: Date.now()
    };
    const updated = runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, order] } : r);
    updateAndSync(updated, waitlist);
    setModals({ ...modals, join: null });
    setInputs({ ...inputs, item: '', floor: '' });
  };

  const promoteFromWaitlist = (runId: string, waitId: string) => {
    const waiter = waitlist.find(w => w.id === waitId);
    if (!waiter) return;
    const order: Order = {
      id: waiter.id,
      userName: waiter.userName,
      userEmail: waiter.userEmail,
      itemDescription: waiter.itemDescription,
      floor: waiter.floor,
      cibusCode: '',
      timestamp: Date.now()
    };
    const updatedRuns = runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, order] } : r);
    const updatedWait = waitlist.filter(w => w.id !== waitId);
    updateAndSync(updatedRuns, updatedWait);
  };

  if (!user) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6">
        <div className="w-full max-w-sm bg-white p-8 rounded-2xl shadow-xl border border-slate-200">
          <div className="w-12 h-12 bg-indigo-600 rounded-xl flex items-center justify-center text-white text-xl mb-6">
            <i className="fas fa-bolt"></i>
          </div>
          <h1 className="text-xl font-bold text-slate-900 mb-1">Welcome to LunchRun</h1>
          <p className="text-sm text-slate-500 mb-6">Enter your email to start coordinating.</p>
          <form onSubmit={(e) => {
            e.preventDefault();
            const email = (e.currentTarget.elements[0] as HTMLInputElement).value;
            setUser({ name: extractName(email), email: email.toLowerCase() });
          }} className="space-y-4">
            <input required type="email" placeholder="Email address" className="w-full h-11 px-4 bg-white border border-slate-300 rounded-lg text-sm outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 transition-all" />
            <Button type="submit" className="w-full h-11 bg-indigo-600 text-white rounded-lg font-semibold text-sm">Continue</Button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#F9FAFB] text-slate-900 font-sans antialiased">
      {/* PROFESSIONAL NAV */}
      <nav className="sticky top-0 z-40 bg-white border-b border-slate-200">
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2 cursor-pointer" onClick={() => setView('runs')}>
            <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white text-sm">
              <i className="fas fa-hamburger"></i>
            </div>
            <span className="font-bold tracking-tight text-slate-900">LunchRun</span>
          </div>

          <div className="flex items-center gap-4">
            <div className="text-right hidden sm:block">
              <div className="text-sm font-semibold text-slate-900 leading-none">{user.name}</div>
              <div className="text-[10px] text-slate-400 font-medium mt-1 uppercase tracking-tighter">{user.email}</div>
            </div>
            <div className="w-8 h-8 bg-slate-100 rounded-full border border-slate-200 flex items-center justify-center text-slate-400">
              <i className="fas fa-user text-xs"></i>
            </div>
          </div>
        </div>
      </nav>

      <main className="max-w-5xl mx-auto px-6 py-10">
        {/* SUB-HEADER / ACTIONS */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-8">
          <div className="flex gap-1 p-1 bg-slate-200/50 rounded-xl">
            <button onClick={() => setView('runs')} className={`px-5 py-2 rounded-lg text-xs font-semibold transition-all ${view === 'runs' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>
              Active Runs
            </button>
            <button onClick={() => setView('waitlist')} className={`px-5 py-2 rounded-lg text-xs font-semibold transition-all ${view === 'waitlist' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>
              Waitlist ({waitlist.length})
            </button>
          </div>

          <div className="flex gap-2 w-full md:w-auto">
            <Button onClick={() => setModals({ ...modals, create: true })} className="h-10 px-6 bg-indigo-600 text-white rounded-lg text-xs font-bold shadow-sm">
              <i className="fas fa-plus mr-2"></i> Start Run
            </Button>
            <Button onClick={() => setModals({ ...modals, wait: true })} variant="secondary" className="h-10 px-6 rounded-lg text-xs font-bold">
              I'm Hungry
            </Button>
          </div>
        </div>

        {/* FEED SECTION */}
        <div className="space-y-6">
          {view === 'runs' ? (
            runs.length === 0 ? (
              <EmptyState title="No active missions" subtitle="Be the first to start a food run today." />
            ) : (
              runs.map(run => (
                <RunCard key={run.id} run={run} userEmail={user.email} onJoin={() => setModals({ ...modals, join: run.id })} onArrive={() => setModals({ ...modals, arrive: run.id })} onDepart={() => updateAndSync(runs.map(r => r.id === run.id ? { ...r, status: 'departed' } : r), waitlist)} waitlist={waitlist} onPromote={(waitId) => promoteFromWaitlist(run.id, waitId)} />
              ))
            )
          ) : (
            waitlist.length === 0 ? (
              <EmptyState title="Waitlist is empty" subtitle="Looks like everyone is satisfied." />
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {waitlist.map(item => (
                  <WaitCard key={item.id} item={item} />
                ))}
              </div>
            )
          )}
        </div>
      </main>

      {/* COMPACT MODALS */}
      {modals.create && (
        <Modal title="Start New Run" onClose={() => setModals({ ...modals, create: false })}>
          <form onSubmit={handleStartRun} className="space-y-5">
            <div>
              <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1.5 ml-1">Destination</label>
              <input required autoFocus className="w-full h-11 px-4 bg-slate-50 border border-slate-200 rounded-lg text-sm font-semibold outline-none focus:border-indigo-600 transition-colors uppercase" placeholder="e.g. VITRINA" value={inputs.dest} onChange={e => setInputs({ ...inputs, dest: e.target.value })} />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1.5 ml-1">Mins to Start</label>
                <input type="number" className="w-full h-11 px-4 bg-slate-50 border border-slate-200 rounded-lg text-sm font-semibold outline-none" value={inputs.time} onChange={e => setInputs({ ...inputs, time: Number(e.target.value) })} />
              </div>
              <div>
                <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1.5 ml-1">Max Orders</label>
                <input type="number" className="w-full h-11 px-4 bg-slate-50 border border-slate-200 rounded-lg text-sm font-semibold outline-none" value={inputs.max} onChange={e => setInputs({ ...inputs, max: Number(e.target.value) })} />
              </div>
            </div>
            <Button type="submit" className="w-full h-11 bg-indigo-600 text-white rounded-lg font-bold text-sm shadow-md">Broadcast Run</Button>
          </form>
        </Modal>
      )}

      {modals.wait && (
        <Modal title="I'm Hungry" onClose={() => setModals({ ...modals, wait: false })}>
          <form onSubmit={(e) => { e.preventDefault(); const newItem: WaitingOrder = { id: Math.random().toString(36).substr(2, 9), userName: user!.name, userEmail: user!.email, destination: inputs.dest.toUpperCase(), itemDescription: inputs.item, floor: inputs.floor, timestamp: Date.now() }; updateAndSync(runs, [newItem, ...waitlist]); setModals({ ...modals, wait: false }); setInputs({ ...inputs, dest: '', item: '', floor: '' }); setView('waitlist'); }} className="space-y-4">
            <input required className="w-full h-11 px-4 bg-slate-50 border border-slate-200 rounded-lg text-sm outline-none" placeholder="Where from?" value={inputs.dest} onChange={e => setInputs({ ...inputs, dest: e.target.value })} />
            <input required className="w-full h-11 px-4 bg-slate-50 border border-slate-200 rounded-lg text-sm outline-none" placeholder="What item?" value={inputs.item} onChange={e => setInputs({ ...inputs, item: e.target.value })} />
            <input required className="w-full h-11 px-4 bg-slate-50 border border-slate-200 rounded-lg text-sm outline-none" placeholder="Floor / Desk" value={inputs.floor} onChange={e => setInputs({ ...inputs, floor: e.target.value })} />
            <Button type="submit" className="w-full h-11 bg-indigo-600 text-white rounded-lg font-bold">Add to Waitlist</Button>
          </form>
        </Modal>
      )}

      {modals.join && (
        <Modal title="Join Run" onClose={() => setModals({ ...modals, join: null })}>
          <form onSubmit={(e) => { e.preventDefault(); handleJoinRun(modals.join); }} className="space-y-4">
            <input required autoFocus className="w-full h-11 px-4 bg-slate-50 border border-slate-200 rounded-lg text-sm outline-none" placeholder="Item details" value={inputs.item} onChange={e => setInputs({ ...inputs, item: e.target.value })} />
            <input required className="w-full h-11 px-4 bg-slate-50 border border-slate-200 rounded-lg text-sm outline-none" placeholder="Drop-off point" value={inputs.floor} onChange={e => setInputs({ ...inputs, floor: e.target.value })} />
            <Button type="submit" className="w-full h-11 bg-indigo-600 text-white rounded-lg font-bold">Confirm Join</Button>
          </form>
        </Modal>
      )}

      {modals.arrive && (
        <Modal title="Arrival Info" onClose={() => setModals({ ...modals, arrive: null })}>
          <form onSubmit={(e) => { e.preventDefault(); updateAndSync(runs.filter(r => r.id !== modals.arrive), waitlist); setModals({ ...modals, arrive: null }); }} className="space-y-6">
            <input required autoFocus className="w-full h-14 px-4 bg-slate-50 border border-slate-200 rounded-lg text-center text-xl font-bold outline-none" placeholder="Drop-off point" value={inputs.loc} onChange={e => setInputs({ ...inputs, loc: e.target.value })} />
            <Button type="submit" className="w-full h-11 bg-emerald-600 text-white rounded-lg font-bold">Confirm & Finish</Button>
          </form>
        </Modal>
      )}
    </div>
  );
};

const RunCard: React.FC<{ run: FoodRun, userEmail: string, onJoin: () => void, onArrive: () => void, onDepart: () => void, waitlist: WaitingOrder[], onPromote: (id: string) => void }> = ({ run, userEmail, onJoin, onArrive, onDepart, waitlist, onPromote }) => {
  const isOwner = userEmail.toLowerCase() === run.runnerEmail.toLowerCase();
  const hasJoined = run.orders.some(o => o.userEmail.toLowerCase() === userEmail.toLowerCase());
  const spotsLeft = run.maxOrders - run.orders.length;
  const relevantWaiters = waitlist.filter(w => w.destination.toUpperCase() === run.destination.toUpperCase());

  return (
    <div className="bg-white border border-slate-200 rounded-xl overflow-hidden shadow-sm hover:border-slate-300 transition-all">
      <div className="p-6 md:p-8 flex flex-col md:flex-row gap-8">
        <div className="flex-1">
          <div className="flex items-center gap-2 mb-4">
            <span className={`text-[9px] font-bold px-2 py-0.5 rounded uppercase tracking-wider ${run.status === 'active' ? 'bg-emerald-100 text-emerald-700' : 'bg-indigo-100 text-indigo-700'}`}>
              {run.status}
            </span>
            <span className="text-slate-300">•</span>
            <span className="text-[10px] font-semibold text-slate-400 uppercase tracking-tight">Runner: {run.runnerName}</span>
          </div>

          <h3 className="text-2xl font-bold text-slate-900 tracking-tight mb-6">{run.destination}</h3>

          {run.orders.length > 0 && (
            <div className="space-y-3 mb-6">
              <div className="text-[10px] font-bold text-slate-300 uppercase tracking-widest border-b border-slate-100 pb-2 mb-2">Orders ({run.orders.length})</div>
              {run.orders.map(o => (
                <div key={o.id} className="flex justify-between items-center text-sm">
                  <span className="font-medium text-slate-600"><span className="text-slate-400">{o.userName}:</span> {o.itemDescription}</span>
                  <span className="text-[10px] font-bold text-slate-400 bg-slate-50 px-2 py-0.5 rounded border border-slate-100">FL {o.floor}</span>
                </div>
              ))}
            </div>
          )}

          {isOwner && relevantWaiters.length > 0 && spotsLeft > 0 && (
            <div className="bg-indigo-50/50 rounded-lg p-4 border border-indigo-100/50 mt-4">
              <div className="text-[10px] font-bold text-indigo-400 uppercase tracking-wider mb-3">Waitlist Matches:</div>
              <div className="flex flex-wrap gap-2">
                {relevantWaiters.map(w => (
                  <button key={w.id} onClick={() => onPromote(w.id)} className="px-3 py-1.5 bg-white border border-indigo-100 rounded-md text-[10px] font-bold text-indigo-600 hover:bg-indigo-600 hover:text-white transition-all">
                    + {w.userName}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="w-full md:w-48 flex flex-col justify-between border-t md:border-t-0 md:border-l border-slate-100 pt-6 md:pt-0 md:pl-8">
          <div>
            <div className="text-3xl font-bold text-slate-900 tabular-nums">{spotsLeft}</div>
            <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Spots Remaining</div>
          </div>

          <div className="mt-6">
            {isOwner ? (
              run.status === 'active' ? (
                <Button onClick={onDepart} className="w-full h-10 bg-indigo-600 text-white rounded-lg text-xs font-bold">Depart Now</Button>
              ) : (
                <Button onClick={onArrive} className="w-full h-10 bg-emerald-600 text-white rounded-lg text-xs font-bold">Arrived</Button>
              )
            ) : (
              !hasJoined && run.status === 'active' && spotsLeft > 0 ? (
                <Button onClick={onJoin} className="w-full h-10 bg-slate-900 text-white rounded-lg text-xs font-bold">Join Run</Button>
              ) : (
                <div className="w-full py-2 text-center text-[10px] font-bold text-slate-400 bg-slate-50 rounded-lg border border-slate-100 uppercase italic">Locked</div>
              )
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

const WaitCard: React.FC<{ item: WaitingOrder }> = ({ item }) => (
  <div className="bg-white border border-slate-200 rounded-xl p-5 shadow-sm hover:border-slate-300 transition-all flex justify-between items-center">
