import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center gap-2 transition-all duration-200 antialiased active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer border-none outline-none";

  const variants = {
    primary: "bg-indigo-600 text-white hover:bg-indigo-700 shadow-sm",
    secondary: "bg-white border border-slate-200 text-slate-600 hover:text-slate-900 hover:bg-slate-50 shadow-sm",
    danger: "bg-red-600 text-white hover:bg-red-700 shadow-sm",
    ghost: "text-slate-400 hover:text-indigo-600 hover:bg-indigo-50/50"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${className}`} 
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading ? <i className="fas fa-circle-notch fa-spin text-xs"></i> : children}
    </button>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { FoodRun, Order, WaitingOrder } from './types';
import { Button } from './components/Button';

const SYNC_ROOT = 'https://keyvalue.xyz/v1/lunchrun_v12_';

const extractDomain = (email: string) => {
  const domain = email.split('@')[1] || 'public';
  return domain.replace(/[^a-zA-Z0-9]/g, '_');
};

const extractName = (email: string) => {
  return email.split('@')[0]
    .split(/[._-]/)
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
};

const App: React.FC = () => {
  const [user, setUser] = useState<{ name: string; email: string } | null>(() => {
    const saved = localStorage.getItem('lr_v12_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [waitlist, setWaitlist] = useState<WaitingOrder[]>([]);
  const [syncStatus, setSyncStatus] = useState<'ONLINE' | 'SYNCING' | 'LOCAL'>('ONLINE');
  const [view, setView] = useState<'runs' | 'waitlist'>('runs');
  const [modals, setModals] = useState<{ [key: string]: any }>({ create: false, join: null, wait: false, arrive: null });
  const [inputs, setInputs] = useState({ dest: '', time: 15, max: 6, item: '', floor: '', loc: '' });

  const lastUpdateRef = useRef<number>(0);
  const syncLock = useRef<boolean>(false);

  useEffect(() => {
    if (user) localStorage.setItem('lr_v12_user', JSON.stringify(user));
  }, [user]);

  const getSyncUrl = () => user ? `${SYNC_ROOT}${extractDomain(user.email)}` : null;

  const sync = async (forcePush: boolean = false, dataToPush?: { runs: FoodRun[], waitlist: WaitingOrder[] }) => {
    const url = getSyncUrl();
    if (!url || syncLock.current) return;
    syncLock.current = true;

    try {
      if (forcePush && dataToPush) {
        setSyncStatus('SYNCING');
        const ts = Date.now();
        const body = JSON.stringify({ runs: dataToPush.runs, waitlist: dataToPush.waitlist, ts });
        await fetch(url, { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body });
        lastUpdateRef.current = ts;
        setSyncStatus('ONLINE');
      } else {
        const res = await fetch(url);
        if (res.ok) {
          const text = await res.text();
          if (text) {
            const data = JSON.parse(text);
            if (data.ts && data.ts > lastUpdateRef.current) {
              setRuns(data.runs || []);
              setWaitlist(data.waitlist || []);
              lastUpdateRef.current = data.ts;
              setSyncStatus('ONLINE');
            }
          }
        }
      }
    } catch (e) {
      setSyncStatus('LOCAL');
    } finally {
      syncLock.current = false;
    }
  };

  useEffect(() => {
    if (!user) return;
    const interval = setInterval(() => sync(), 3000);
    sync();
    return () => clearInterval(interval);
  }, [user?.email]);

  const updateAndSync = (newRuns: FoodRun[], newWait: WaitingOrder[]) => {
    setRuns(newRuns);
    setWaitlist(newWait);
    sync(true, { runs: newRuns, waitlist: newWait });
  };

  const handleStartRun = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: user.name,
      runnerEmail: user.email,
      destination: inputs.dest.toUpperCase(),
      departureTime: Date.now() + (inputs.time * 60000),
      minutesUntilDeparture: inputs.time,
      maxOrders: inputs.max,
      status: 'active',
      orders: []
    };
    updateAndSync([newRun, ...runs], waitlist);
    setModals({ ...modals, create: false });
    setInputs({ ...inputs, dest: '' });
  };

  const handleJoinRun = (runId: string) => {
    if (!user) return;
    const order: Order = {
      id: Math.random().toString(36).substr(2, 9),
      userName: user.name,
      userEmail: user.email,
      itemDescription: inputs.item,
      floor: inputs.floor,
      cibusCode: '',
      timestamp: Date.now()
    };
    const updated = runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, order] } : r);
    updateAndSync(updated, waitlist);
    setModals({ ...modals, join: null });
    setInputs({ ...inputs, item: '', floor: '' });
  };

  const promoteFromWaitlist = (runId: string, waitId: string) => {
    const waiter = waitlist.find(w => w.id === waitId);
    if (!waiter) return;
    const order: Order = {
      id: waiter.id,
      userName: waiter.userName,
      userEmail: waiter.userEmail,
      itemDescription: waiter.itemDescription,
      floor: waiter.floor,
      cibusCode: '',
      timestamp: Date.now()
    };
    const updatedRuns = runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, order] } : r);
    const updatedWait = waitlist.filter(w => w.id !== waitId);
    updateAndSync(updatedRuns, updatedWait);
  };

  if (!user) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-sm">
          <div className="w-10 h-10 bg-indigo-600 rounded-lg flex items-center justify-center text-white mb-8">
            <i className="fas fa-bolt text-lg"></i>
          </div>
          <h1 className="text-2xl font-bold text-slate-900 mb-2">Sign in to LunchRun</h1>
          <p className="text-slate-500 mb-8 text-sm">Coordinate lunch runs with your team seamlessly.</p>
          <form onSubmit={(e) => {
            e.preventDefault();
            const email = (e.currentTarget.elements[0] as HTMLInputElement).value;
            setUser({ name: extractName(email), email: email.toLowerCase() });
          }} className="space-y-4">
            <div className="space-y-1">
              <label className="text-xs font-semibold text-slate-700">Email Address</label>
              <input required type="email" placeholder="name@company.com" className="w-full h-10 px-3 bg-white border border-slate-200 rounded-md text-sm outline-none focus:ring-2 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all" />
            </div>
            <Button type="submit" className="w-full h-10 bg-slate-900 text-white rounded-md font-medium text-sm">Continue</Button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#FBFBFC] text-slate-900 font-sans antialiased selection:bg-indigo-100">
      {/* APP HEADER */}
      <nav className="sticky top-0 z-40 bg-white/80 backdrop-blur-md border-b border-slate-200/60 px-6">
        <div className="max-w-5xl mx-auto h-14 flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => setView('runs')}>
            <div className="w-7 h-7 bg-slate-900 rounded flex items-center justify-center text-white text-xs">
              <i className="fas fa-hamburger"></i>
            </div>
            <span className="font-bold text-sm tracking-tight">LunchRun</span>
          </div>

          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2">
              <div className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'ONLINE' ? 'bg-emerald-500' : 'bg-amber-400'}`}></div>
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">{syncStatus}</span>
            </div>
            <div className="h-6 w-px bg-slate-200"></div>
            <div className="flex items-center gap-2">
               <span className="text-xs font-semibold text-slate-700">{user.name}</span>
               <div className="w-7 h-7 bg-indigo-50 border border-indigo-100 rounded-full flex items-center justify-center text-indigo-600 text-[10px] font-bold">
                 {user.name.charAt(0)}
               </div>
            </div>
          </div>
        </div>
      </nav>

      <main className="max-w-5xl mx-auto px-6 py-8">
        {/* ACTION BAR */}
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-8">
          <div className="flex p-0.5 bg-slate-100 rounded-lg">
            <button onClick={() => setView('runs')} className={`px-4 py-1.5 rounded-md text-[11px] font-bold transition-all ${view === 'runs' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>
              Active Runs
            </button>
            <button onClick={() => setView('waitlist')} className={`px-4 py-1.5 rounded-md text-[11px] font-bold transition-all ${view === 'waitlist' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>
              Waitlist {waitlist.length > 0 && <span className="ml-1 text-indigo-500">{waitlist.length}</span>}
            </button>
          </div>

          <div className="flex gap-2 w-full sm:w-auto">
            <Button onClick={() => setModals({ ...modals, create: true })} className="h-9 px-4 bg-indigo-600 text-white rounded-md text-xs font-semibold">
              <i className="fas fa-plus mr-1.5 text-[10px]"></i> New Run
            </Button>
            <Button onClick={() => setModals({ ...modals, wait: true })} variant="secondary" className="h-9 px-4 rounded-md text-xs font-semibold">
              I'm Hungry
            </Button>
          </div>
        </div>

        {/* CONTENT */}
        <div className="max-w-2xl mx-auto">
          {view === 'runs' ? (
            runs.length === 0 ? (
              <EmptyState icon="fa-inbox" title="No active runs" subtitle="Coordination is better than going alone." />
            ) : (
              <div className="space-y-4">
                {runs.map(run => (
                  <RunCard key={run.id} run={run} userEmail={user.email} onJoin={() => setModals({ ...modals, join: run.id })} onArrive={() => setModals({ ...modals, arrive: run.id })} onDepart={() => updateAndSync(runs.map(r => r.id === run.id ? { ...r, status: 'departed' } : r), waitlist)} waitlist={waitlist} onPromote={(waitId) => promoteFromWaitlist(run.id, waitId)} />
                ))}
              </div>
            )
          ) : (
            waitlist.length === 0 ? (
              <EmptyState icon="fa-clock" title="Waitlist is clear" subtitle="Everyone seems to be busy or full." />
            ) : (
              <div className="grid grid-cols-1 gap-3">
                {waitlist.map(item => (
                  <WaitCard key={item.id} item={item} />
                ))}
              </div>
            )
          )}
        </div>
      </main>

      {/* MODALS */}
      {modals.create && (
        <Modal title="Launch Food Run" onClose={() => setModals({ ...modals, create: false })}>
          <form onSubmit={handleStartRun} className="space-y-4">
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider ml-0.5">Where to?</label>
              <input required autoFocus className="w-full h-10 px-3 bg-slate-50 border border-slate-200 rounded-md text-sm font-semibold outline-none focus:border-indigo-500 uppercase" placeholder="e.g. Vitrina" value={inputs.dest} onChange={e => setInputs({ ...inputs, dest: e.target.value })} />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider ml-0.5">Mins until go</label>
                <input type="number" className="w-full h-10 px-3 bg-slate-50 border border-slate-200 rounded-md text-sm font-semibold outline-none focus:border-indigo-500" value={inputs.time} onChange={e => setInputs({ ...inputs, time: Number(e.target.value) })} />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider ml-0.5">Max slots</label>
                <input type="number" className="w-full h-10 px-3 bg-slate-50 border border-slate-200 rounded-md text-sm font-semibold outline-none focus:border-indigo-500" value={inputs.max} onChange={e => setInputs({ ...inputs, max: Number(e.target.value) })} />
              </div>
            </div>
            <Button type="submit" className="w-full h-10 bg-indigo-600 text-white rounded-md font-bold text-sm shadow-sm mt-2">Broadcast Run</Button>
          </form>
        </Modal>
      )}

      {modals.wait && (
        <Modal title="I'm Hungry" onClose={() => setModals({ ...modals, wait: false })}>
          <form onSubmit={(e) => { e.preventDefault(); const newItem: WaitingOrder = { id: Math.random().toString(36).substr(2, 9), userName: user!.name, userEmail: user!.email, destination: inputs.dest.toUpperCase(), itemDescription: inputs.item, floor: inputs.floor, timestamp: Date.now() }; updateAndSync(runs, [newItem, ...waitlist]); setModals({ ...modals, wait: false }); setInputs({ ...inputs, dest: '', item: '', floor: '' }); setView('waitlist'); }} className="space-y-4">
            <input required className="w-full h-10 px-3 bg-slate-50 border border-slate-200 rounded-md text-sm outline-none" placeholder="Destination (e.g. Salad bar)" value={inputs.dest} onChange={e => setInputs({ ...inputs, dest: e.target.value })} />
            <input required className="w-full h-10 px-3 bg-slate-50 border border-slate-200 rounded-md text-sm outline-none" placeholder="What do you want?" value={inputs.item} onChange={e => setInputs({ ...inputs, item: e.target.value })} />
            <input required className="w-full h-10 px-3 bg-slate-50 border border-slate-200 rounded-md text-sm outline-none" placeholder="Floor / Drop-off point" value={inputs.floor} onChange={e => setInputs({ ...inputs, floor: e.target.value })} />
            <Button type="submit" className="w-full h-10 bg-slate-900 text-white rounded-md font-bold text-sm mt-2">Add to Waitlist</Button>
          </form>
        </Modal>
      )}

      {modals.join && (
        <Modal title="Join Food Run" onClose={() => setModals({ ...modals, join: null })}>
          <form onSubmit={(e) => { e.preventDefault(); handleJoinRun(modals.join); }} className="space-y-4">
            <input required autoFocus className="w-full h-10 px-3 bg-slate-50 border border-slate-200 rounded-md text-sm outline-none" placeholder="Item description" value={inputs.item} onChange={e => setInputs({ ...inputs, item: e.target.value })} />
            <input required className="w-full h-10 px-3 bg-slate-50 border border-slate-200 rounded-md text-sm outline-none" placeholder="Your location / Floor" value={inputs.floor} onChange={e => setInputs({ ...inputs, floor: e.target.value })} />
            <Button type="submit" className="w-full h-10 bg-indigo-600 text-white rounded-md font-bold text-sm mt-2">Join Now</Button>
          </form>
        </Modal>
      )}

      {modals.arrive && (
        <Modal title="Arrival Notification" onClose={() => setModals({ ...modals, arrive: null })}>
          <form onSubmit={(e) => { e.preventDefault(); updateAndSync(runs.filter(r => r.id !== modals.arrive), waitlist); setModals({ ...modals, arrive: null }); }} className="space-y-4">
            <div className="text-center p-4 bg-emerald-50 text-emerald-700 rounded-md mb-4 text-xs font-medium">
              Everyone on the list will be notified of the arrival.
            </div>
            <input required autoFocus className="w-full h-12 px-3 bg-slate-50 border border-slate-200 rounded-md text-center text-lg font-bold outline-none" placeholder="WHERE ARE YOU?" value={inputs.loc} onChange={e => setInputs({ ...inputs, loc: e.target.value })} />
            <Button type="submit" className="w-full h-10 bg-emerald-600 text-white rounded-md font-bold text-sm">Finish Run</Button>
          </form>
        </Modal>
      )}
    </div>
  );
};

const RunCard: React.FC<{ run: FoodRun, userEmail: string, onJoin: () => void, onArrive: () => void, onDepart: () => void, waitlist: WaitingOrder[], onPromote: (id: string) => void }> = ({ run, userEmail, onJoin, onArrive, onDepart, waitlist, onPromote }) => {
  const isOwner = userEmail.toLowerCase() === run.runnerEmail.toLowerCase();
  const hasJoined = run.orders.some(o => o.userEmail.toLowerCase() === userEmail.toLowerCase());
  const spotsLeft = run.maxOrders - run.orders.length;
  const relevantWaiters = waitlist.filter(w => w.destination.toUpperCase() === run.destination.toUpperCase());

  return (
    <div className="bg-white border border-slate-200/80 rounded-lg overflow-hidden transition-all hover:border-slate-300">
      <div className="p-5 sm:p-6">
        <div className="flex flex-col sm:flex-row justify-between items-start gap-4">
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 mb-2">
              <span className={`text-[8px] font-black px-1.5 py-0.5 rounded uppercase tracking-widest ${run.status === 'active' ? 'bg-emerald-50 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}>
                {run.status}
              </span>
              <span className="text-slate-300 text-[10px]">•</span>
              <span className="text-[10px] font-semibold text-slate-400 truncate uppercase">Runner: {run.runnerName}</span>
            </div>

            <h3 className="text-xl font-bold text-slate-900 leading-tight mb-4">{run.destination}</h3>

            {run.orders.length > 0 && (
              <div className="space-y-2 mb-4 bg-slate-50/50 p-3 rounded-md border border-slate-100">
                {run.orders.map(o => (
                  <div key={o.id} className="flex justify-between items-center text-[11px]">
                    <span className="font-semibold text-slate-700 flex-1"><span className="text-slate-400 font-medium">{o.userName}:</span> {o.itemDescription}</span>
                    <span className="text-slate-400 bg-white px-1.5 py-0.5 rounded border border-slate-100 font-bold ml-2">FL {o.floor}</span>
                  </div>
                ))}
              </div>
            )}

            {isOwner && relevantWaiters.length > 0 && spotsLeft > 0 && (
              <div className="bg-amber-50/40 rounded-md p-3 border border-amber-100/50 mt-2">
                <div className="text-[9px] font-bold text-amber-600/70 uppercase tracking-widest mb-2">Waitlist Suggestions:</div>
                <div className="flex flex-wrap gap-1.5">
                  {relevantWaiters.map(w => (
                    <button key={w.id} onClick={() => onPromote(w.id)} className="px-2 py-1 bg-white border border-amber-200 rounded text-[9px] font-bold text-amber-600 hover:bg-amber-500 hover:text-white transition-all">
                      + Add {w.userName}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>

          <div className="w-full sm:w-32 flex flex-col items-center justify-center bg-slate-50/80 rounded-md p-4 sm:p-3 border border-slate-100">
            <div className="text-2xl font-bold text-slate-900">{spotsLeft}</div>
            <div className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">Slots left</div>

            <div className="mt-3 w-full">
              {isOwner ? (
                run.status === 'active' ? (
                  <Button onClick={onDepart} className="w-full h-8 bg-indigo-600 text-white rounded-md text-[10px] font-bold uppercase">Depart</Button>
                ) : (
                  <Button onClick={onArrive} className="w-full h-8 bg-emerald-600 text-white rounded-md text-[10px] font-bold uppercase">Arrived</Button>
                )
              ) : (
                !hasJoined && run.status === 'active' && spotsLeft > 0 ? (
                  <Button onClick={onJoin} className="w-full h-8 bg-slate-900 text-white rounded-md text-[10px] font-bold uppercase">Join</Button>
                ) : (
                  <div className="w-full py-1.5 text-center text-[9px] font-bold text-slate-400 bg-white rounded border border-slate-100 uppercase italic">Locked</div>
                )
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

