import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center gap-1.5 transition-all duration-200 antialiased active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer border-none outline-none";

  const variants = {
    primary: "bg-indigo-600 text-white hover:bg-indigo-700 shadow-sm shadow-indigo-500/10",
    secondary: "bg-white border border-slate-200 text-slate-600 hover:text-slate-900 hover:bg-slate-50 hover:border-slate-300 shadow-sm shadow-slate-200/20",
    danger: "bg-red-600 text-white hover:bg-red-700 shadow-sm",
    ghost: "text-slate-400 hover:text-indigo-600 hover:bg-indigo-50/50"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${className}`} 
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading ? <i className="fas fa-circle-notch fa-spin text-[10px]"></i> : children}
    </button>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { FoodRun, Order, WaitingOrder } from './types';
import { Button } from './components/Button';

const SYNC_ROOT = 'https://keyvalue.xyz/v1/lunchrun_v13_';

const extractDomain = (email: string) => {
  const domain = email.split('@')[1] || 'public';
  return domain.replace(/[^a-zA-Z0-9]/g, '_');
};

const extractName = (email: string) => {
  return email.split('@')[0]
    .split(/[._-]/)
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
};

const App: React.FC = () => {
  const [user, setUser] = useState<{ name: string; email: string } | null>(() => {
    const saved = localStorage.getItem('lr_v13_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [runs, setRuns] = useState<FoodRun[]>([]);
  const [waitlist, setWaitlist] = useState<WaitingOrder[]>([]);
  const [syncStatus, setSyncStatus] = useState<'ONLINE' | 'SYNCING' | 'LOCAL'>('ONLINE');
  const [view, setView] = useState<'runs' | 'waitlist'>('runs');
  const [modals, setModals] = useState<{ [key: string]: any }>({ create: false, join: null, wait: false, arrive: null });
  const [inputs, setInputs] = useState({ dest: '', time: 15, max: 6, item: '', floor: '', loc: '' });

  const lastUpdateRef = useRef<number>(0);
  const syncLock = useRef<boolean>(false);

  useEffect(() => {
    if (user) localStorage.setItem('lr_v13_user', JSON.stringify(user));
  }, [user]);

  const getSyncUrl = () => user ? `${SYNC_ROOT}${extractDomain(user.email)}` : null;

  const sync = async (forcePush: boolean = false, dataToPush?: { runs: FoodRun[], waitlist: WaitingOrder[] }) => {
    const url = getSyncUrl();
    if (!url || syncLock.current) return;
    syncLock.current = true;

    try {
      if (forcePush && dataToPush) {
        setSyncStatus('SYNCING');
        const ts = Date.now();
        const body = JSON.stringify({ runs: dataToPush.runs, waitlist: dataToPush.waitlist, ts });
        await fetch(url, { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body });
        lastUpdateRef.current = ts;
        setSyncStatus('ONLINE');
      } else {
        const res = await fetch(url);
        if (res.ok) {
          const text = await res.text();
          if (text) {
            const data = JSON.parse(text);
            if (data.ts && data.ts > lastUpdateRef.current) {
              setRuns(data.runs || []);
              setWaitlist(data.waitlist || []);
              lastUpdateRef.current = data.ts;
              setSyncStatus('ONLINE');
            }
          }
        }
      }
    } catch (e) {
      setSyncStatus('LOCAL');
    } finally {
      syncLock.current = false;
    }
  };

  useEffect(() => {
    if (!user) return;
    const interval = setInterval(() => sync(), 3000);
    sync();
    return () => clearInterval(interval);
  }, [user?.email]);

  const updateAndSync = (newRuns: FoodRun[], newWait: WaitingOrder[]) => {
    setRuns(newRuns);
    setWaitlist(newWait);
    sync(true, { runs: newRuns, waitlist: newWait });
  };

  const handleStartRun = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    const newRun: FoodRun = {
      id: Math.random().toString(36).substr(2, 9),
      runnerName: user.name,
      runnerEmail: user.email,
      destination: inputs.dest.toUpperCase(),
      departureTime: Date.now() + (inputs.time * 60000),
      minutesUntilDeparture: inputs.time,
      maxOrders: inputs.max,
      status: 'active',
      orders: []
    };
    updateAndSync([newRun, ...runs], waitlist);
    setModals({ ...modals, create: false });
    setInputs({ ...inputs, dest: '' });
  };

  const promoteFromWaitlist = (runId: string, waitId: string) => {
    const waiter = waitlist.find(w => w.id === waitId);
    if (!waiter) return;
    const order: Order = {
      id: waiter.id,
      userName: waiter.userName,
      userEmail: waiter.userEmail,
      itemDescription: waiter.itemDescription,
      floor: waiter.floor,
      cibusCode: '',
      timestamp: Date.now()
    };
    const updatedRuns = runs.map(r => r.id === runId ? { ...r, orders: [...r.orders, order] } : r);
    const updatedWait = waitlist.filter(w => w.id !== waitId);
    updateAndSync(updatedRuns, updatedWait);
  };

  if (!user) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6">
        <div className="w-full max-w-sm bg-white border border-slate-200 p-10 rounded-lg shadow-[0_1px_3px_rgba(0,0,0,0.1)]">
          <div className="w-10 h-10 bg-indigo-600 rounded flex items-center justify-center text-white mb-8 shadow-[0_0_15px_rgba(79,70,229,0.4)]">
            <i className="fas fa-terminal text-sm"></i>
          </div>
          <h1 className="text-xl font-bold text-slate-900 mb-2 tracking-tight">System Access</h1>
          <p className="text-slate-500 mb-8 text-sm leading-relaxed">Identity verification required to coordinate team logistical food operations.</p>
          <form onSubmit={(e) => {
            e.preventDefault();
            const email = (e.currentTarget.elements[0] as HTMLInputElement).value;
            setUser({ name: extractName(email), email: email.toLowerCase() });
          }} className="space-y-4">
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Enterprise Email</label>
              <input required type="email" placeholder="user@company.com" className="w-full h-11 px-4 bg-slate-50 border border-slate-200 rounded-md text-sm font-mono outline-none focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 transition-all" />
            </div>
            <Button type="submit" className="w-full h-11 bg-slate-900 text-white rounded-md font-bold text-xs uppercase tracking-widest hover:bg-black transition-colors">Initialize Session</Button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen pb-20">
      {/* TECH NAV */}
      <nav className="sticky top-0 z-40 glass border-b border-slate-200/60 px-6">
        <div className="max-w-5xl mx-auto h-16 flex items-center justify-between">
          <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setView('runs')}>
            <div className="w-8 h-8 bg-slate-900 rounded flex items-center justify-center text-white text-xs group-hover:bg-indigo-600 transition-colors">
              <i className="fas fa-bolt"></i>
            </div>
            <div>
              <span className="font-extrabold text-sm tracking-tighter uppercase block leading-none">LunchRun</span>
              <span className="text-[9px] font-mono text-slate-400 font-bold tracking-widest">SYSTEM_V1.3</span>
            </div>
          </div>

          <div className="flex items-center gap-6">
            <div className="hidden md:flex items-center gap-2">
              <div className={`w-2 h-2 rounded-full ${syncStatus === 'ONLINE' ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-amber-400'} animate-pulse`}></div>
              <span className="text-[10px] font-mono font-bold text-slate-400 uppercase tracking-widest">{syncStatus}</span>
            </div>
            <div className="h-4 w-px bg-slate-200"></div>
            <div className="flex items-center gap-3">
               <div className="text-right">
                 <span className="text-xs font-bold text-slate-900 block leading-none">{user.name}</span>
                 <span className="text-[9px] font-mono text-slate-400 uppercase">{extractDomain(user.email)}</span>
               </div>
               <div className="w-8 h-8 bg-slate-100 border border-slate-200 rounded-full flex items-center justify-center text-slate-500 text-[10px] font-mono font-bold">
                 {user.name.charAt(0)}
               </div>
            </div>
          </div>
        </div>
      </nav>

      <main className="max-w-5xl mx-auto px-6 py-10">
        {/* SUB-HEADER ACTION AREA */}
        <div className="flex flex-col sm:flex-row justify-between items-end gap-6 mb-12 border-b border-slate-200 pb-8">
          <div>
            <h2 className="text-xs font-mono font-bold text-indigo-600 uppercase tracking-[0.3em] mb-2">// LOGISTICS_CENTRAL</h2>
            <div className="flex gap-1 bg-slate-100 p-0.5 rounded-md">
              <button onClick={() => setView('runs')} className={`px-6 py-2 rounded text-[10px] font-bold uppercase tracking-widest transition-all ${view === 'runs' ? 'bg-white text-slate-900 shadow-sm border border-slate-200' : 'text-slate-400 hover:text-slate-600'}`}>
                Active_Missions
              </button>
              <button onClick={() => setView('waitlist')} className={`px-6 py-2 rounded text-[10px] font-bold uppercase tracking-widest transition-all ${view === 'waitlist' ? 'bg-white text-slate-900 shadow-sm border border-slate-200' : 'text-slate-400 hover:text-slate-600'}`}>
                Waitlist_Queued [{waitlist.length}]
              </button>
            </div>
          </div>

          <div className="flex gap-3">
            <Button onClick={() => setModals({ ...modals, wait: true })} variant="secondary" className="h-10 px-6 rounded-md text-[10px] font-bold uppercase tracking-widest border border-slate-200">
              <i className="fas fa-radar mr-2 text-slate-400"></i> Signal Hunger
            </Button>
            <Button onClick={() => setModals({ ...modals, create: true })} className="h-10 px-8 bg-indigo-600 text-white rounded-md text-[10px] font-bold uppercase tracking-widest shadow-[0_4px_14px_rgba(79,70,229,0.3)] hover:translate-y-[-1px] transition-transform">
              Deploy Run
            </Button>
          </div>
        </div>

        {/* FEED CONTENT AREA */}
        <div className="max-w-3xl">
          {view === 'runs' ? (
            runs.length === 0 ? (
              <EmptyState icon="fa-terminal" title="No broadcasted missions" subtitle="The sector is currently quiet. Initiate a run to begin coordination." />
            ) : (
              <div className="grid grid-cols-1 gap-6">
                {runs.map(run => (
                  <RunCard key={run.id} run={run} userEmail={user.email} onJoin={() => setModals({ ...modals, join: run.id })} onArrive={() => setModals({ ...modals, arrive: run.id })} onDepart={() => updateAndSync(runs.map(r => r.id === run.id ? { ...r, status: 'departed' } : r), waitlist)} waitlist={waitlist} onPromote={(waitId) => promoteFromWaitlist(run.id, waitId)} />
                ))}
              </div>
            )
          ) : (
            waitlist.length === 0 ? (
              <EmptyState icon="fa-microchip" title="Waitlist Buffer Empty" subtitle="No active hunger signals detected in your workspace domain." />
            ) : (
              <div className="grid grid-cols-1 gap-4">
                {waitlist.map(item => (
                  <WaitCard key={item.id} item={item} />
                ))}
              </div>
            )
          )}
        </div>
      </main>

      {/* TECH MODALS */}
      {modals.create && (
        <Modal title="Deploy New Food Run" onClose={() => setModals({ ...modals, create: false })}>
          <form onSubmit={handleStartRun} className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-mono font-bold text-slate-400 uppercase tracking-widest">Target Destination</label>
              <input required autoFocus className="w-full h-12 px-4 bg-slate-900 text-indigo-400 border border-slate-700 rounded-md text-sm font-mono outline-none focus:border-indigo-500 transition-colors uppercase" placeholder="E.G. BURGER_STATION" value={inputs.dest} onChange={e => setInputs({ ...inputs, dest: e.target.value })} />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <label className="text-[10px] font-mono font-bold text-slate-400 uppercase tracking-widest">T-Minus (Mins)</label>
                <input type="number" className="w-full h-12 px-4 bg-slate-50 border border-slate-200 rounded-md text-sm font-mono font-bold outline-none focus:border-indigo-500" value={inputs.time} onChange={e => setInputs({ ...inputs, time: Number(e.target.value) })} />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-mono font-bold text-slate-400 uppercase tracking-widest">Payload Limit</label>
                <input type="number" className="w-full h-12 px-4 bg-slate-50 border border-slate-200 rounded-md text-sm font-mono font-bold outline-none focus:border-indigo-500" value={inputs.max} onChange={e => setInputs({ ...inputs, max: Number(e.target.value) })} />
              </div>
            </div>
            <Button type="submit" className="w-full h-12 bg-indigo-600 text-white rounded-md font-bold text-xs uppercase tracking-widest shadow-lg shadow-indigo-500/20">Execute Broadcast</Button>
          </form>
        </Modal>
      )}

      {modals.wait && (
        <Modal title="Broadcast Hunger Signal" onClose={() => setModals({ ...modals, wait: false })}>
          <form onSubmit={(e) => { e.preventDefault(); const newItem: WaitingOrder = { id: Math.random().toString(36).substr(2, 9), userName: user!.name, userEmail: user!.email, destination: inputs.dest.toUpperCase(), itemDescription: inputs.item, floor: inputs.floor, timestamp: Date.now() }; updateAndSync(runs, [newItem, ...waitlist]); setModals({ ...modals, wait: false }); setInputs({ ...inputs, dest: '', item: '', floor: '' }); setView('waitlist'); }} className="space-y-4">
            <div className="space-y-1">
               <label className="text-[9px] font-mono font-bold text-slate-400 uppercase ml-1">Location_ID</label>
               <input required className="w-full h-11 px-4 bg-slate-50 border border-slate-200 rounded-md text-sm outline-none font-mono" placeholder="WHERE FROM?" value={inputs.dest} onChange={e => setInputs({ ...inputs, dest: e.target.value })} />
            </div>
            <div className="space-y-1">
               <label className="text-[9px] font-mono font-bold text-slate-400 uppercase ml-1">Item_Spec</label>
               <input required className="w-full h-11 px-4 bg-slate-50 border border-slate-200 rounded-md text-sm outline-none font-mono" placeholder="WHAT DO YOU NEED?" value={inputs.item} onChange={e => setInputs({ ...inputs, item: e.target.value })} />
            </div>
            <div className="space-y-1">
               <label className="text-[9px] font-mono font-bold text-slate-400 uppercase ml-1">Drop_Point</label>
               <input required className="w-full h-11 px-4 bg-slate-50 border border-slate-200 rounded-md text-sm outline-none font-mono" placeholder="FLOOR / DESK" value={inputs.floor} onChange={e => setInputs({ ...inputs, floor: e.target.value })} />
            </div>
            <Button type="submit" className="w-full h-12 bg-slate-900 text-white rounded-md font-bold text-xs uppercase tracking-[0.2em] mt-2">Transmit Signal</Button>
          </form>
        </Modal>
      )}

      {modals.join && (
        <Modal title="Join Active Mission" onClose={() => setModals({ ...modals, join: null })}>
          <form onSubmit={(e) => { e.preventDefault(); const order: Order = { id: Math.random().toString(36).substr(2, 9), userName: user!.name, userEmail: user!.email, itemDescription: inputs.item, floor: inputs.floor, cibusCode: '', timestamp: Date.now() }; const updated = runs.map(r => r.id === modals.join ? { ...r, orders: [...r.orders, order] } : r); updateAndSync(updated, waitlist); setModals({ ...modals, join: null }); setInputs({ ...inputs, item: '', floor: '' }); }} className="space-y-4">
            <input required autoFocus className="w-full h-11 px-4 bg-slate-50 border border-slate-200 rounded-md text-sm outline-none font-mono" placeholder="ITEM_SPEC" value={inputs.item} onChange={e => setInputs({ ...inputs, item: e.target.value })} />
            <input required className="w-full h-11 px-4 bg-slate-50 border border-slate-200 rounded-md text-sm outline-none font-mono" placeholder="DROP_POINT" value={inputs.floor} onChange={e => setInputs({ ...inputs, floor: e.target.value })} />
            <Button type="submit" className="w-full h-12 bg-indigo-600 text-white rounded-md font-bold text-xs uppercase">Confirm Enrollment</Button>
          </form>
        </Modal>
      )}

      {modals.arrive && (
        <Modal title="Report Arrival" onClose={() => setModals({ ...modals, arrive: null })}>
          <form onSubmit={(e) => { e.preventDefault(); updateAndSync(runs.filter(r => r.id !== modals.arrive), waitlist); setModals({ ...modals, arrive: null }); }} className="space-y-6 text-center">
            <div className="w-16 h-16 bg-emerald-50 text-emerald-500 rounded-full flex items-center justify-center mx-auto mb-4 border border-emerald-100">
               <i className="fas fa-check text-2xl"></i>
            </div>
            <p className="text-xs font-mono font-bold text-slate-400 uppercase tracking-widest mb-6 px-10">Destination reached. Deploy drop-off coordinates to all members.</p>
            <input required autoFocus className="w-full h-14 px-4 bg-slate-50 border border-slate-200 rounded-md text-center text-xl font-mono font-bold outline-none focus:border-emerald-500" placeholder="COORDINATES" value={inputs.loc} onChange={e => setInputs({ ...inputs, loc: e.target.value })} />
            <Button type="submit" className="w-full h-12 bg-emerald-600 text-white rounded-md font-bold text-xs uppercase tracking-widest mt-4">Close Mission</Button>
          </form>
        </Modal>
      )}
    </div>
  );
};

const RunCard: React.FC<{ run: FoodRun, userEmail: string, onJoin: () => void, onArrive: () => void, onDepart: () => void, waitlist: WaitingOrder[], onPromote: (id: string) => void }> = ({ run, userEmail, onJoin, onArrive, onDepart, waitlist, onPromote }) => {
  const isOwner = userEmail.toLowerCase() === run.runnerEmail.toLowerCase();
  const hasJoined = run.orders.some(o => o.userEmail.toLowerCase() === userEmail.toLowerCase());
  const spotsLeft = run.maxOrders - run.orders.length;
  const relevantWaiters = waitlist.filter(w => w.destination.toUpperCase() === run.destination.toUpperCase());

  return (
    <div className="bg-white border border-slate-200 rounded-lg overflow-hidden group hover:border-indigo-300/60 transition-all duration-300">
      <div className="p-6">
        <div className="flex flex-col md:flex-row justify-between items-start gap-8">
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-3 mb-3">
              <span className={`text-[9px] font-mono font-black px-2 py-0.5 rounded uppercase tracking-[0.2em] border ${run.status === 'active' ? 'bg-emerald-50 text-emerald-600 border-emerald-200/50' : 'bg-indigo-50 text-indigo-600 border-indigo-200/50'}`}>
                {run.status}
              </span>
              <span className="text-[9px] font-mono font-bold text-slate-400 uppercase tracking-widest truncate">RUNNER::{run.runnerName}</span>
            </div>

            <h3 className="text-2xl font-extrabold text-slate-900 tracking-tighter mb-6">{run.destination}</h3>

            {run.orders.length > 0 && (
              <div className="space-y-1 mb-6 border-l-2 border-slate-100 pl-4 py-1">
                <div className="text-[9px] font-mono font-bold text-slate-300 uppercase tracking-widest mb-3 italic">:: PAYLOAD_MANIFEST</div>
                {run.orders.map(o => (
                  <div key={o.id} className="flex justify-between items-center text-[11px] group/item">
                    <span className="font-semibold text-slate-600"><span className="text-slate-400 font-mono font-bold mr-2">[{o.userName}]</span> {o.itemDescription}</span>
                    <span className="text-[10px] font-mono font-bold text-slate-400 opacity-0 group-hover/item:opacity-100 transition-opacity">LEVEL {o.floor}</span>
                  </div>
                ))}
              </div>
            )}

            {isOwner && relevantWaiters.length > 0 && spotsLeft > 0 && (
              <div className="bg-indigo-50/40 rounded border border-indigo-100/50 p-4 mt-2">
                <div className="text-[9px] font-mono font-bold text-indigo-400 uppercase tracking-widest mb-3">WAITLIST_HITS:</div>
                <div className="flex flex-wrap gap-2">
                  {relevantWaiters.map(w => (
                    <button key={w.id} onClick={() => onPromote(w.id)} className="px-3 py-1.5 bg-white border border-indigo-100 rounded text-[10px] font-mono font-bold text-indigo-600 hover:bg-indigo-600 hover:text-white transition-all shadow-sm">
                      + ADD_USER({w.userName})
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>

          <div className="w-full md:w-36 flex flex-col items-center justify-between md:border-l border-slate-100 md:pl-8 pt-6 md:pt-0">
            <div className="text-center mb-6">
              <div className="text-4xl font-mono font-black text-slate-900 tracking-tighter">{spotsLeft}</div>
              <div className="text-[9px] font-mono font-bold text-slate-400 uppercase tracking-[0.2em] mt-1">Free_Slots</div>
            </div>

            <div className="w-full space-y-2">
              {isOwner ? (
                run.status === 'active' ? (
                  <Button onClick={onDepart} className="w-full h-10 bg-indigo-600 text-white rounded text-[10px] font-bold uppercase tracking-widest hover:bg-indigo-700">Depart</Button>
                ) : (
                  <Button onClick={onArrive} className="w-full h-10 bg-emerald-600 text-white rounded text-[10px] font-bold uppercase tracking-widest hover:bg-emerald-700">Arrived</Button>
                )
              ) : (
                !hasJoined && run.status === 'active' && spotsLeft > 0 ? (
                  <Button onClick={onJoin} className="w-full h-10 bg-slate-900 text-white rounded text-[10px] font-bold uppercase tracking-widest hover:bg-black">Enroll</Button>
                ) : (
                  <div className="w-full py-2.5 text-center text-[10px] font-mono font-bold text-slate-300 bg-slate-50 rounded border border-slate-100 uppercase tracking-[0.3em] italic">Locked</div>
                )
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

