);

const Modal: React.FC<{ title: string; onClose: () => void; children: React.ReactNode }> = ({ title, onClose, children }) => (
  <div className="fixed inset-0 bg-slate-900/20 backdrop-blur-sm z-50 flex items-center justify-center p-4">
    <div className="bg-white border border-white rounded-[2.5rem] w-full max-w-md shadow-[0_30px_70px_rgba(0,0,0,0.1)] overflow-hidden animate-in fade-in zoom-in-95 duration-300">
      <div className="px-8 py-6 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
        <h3 className="text-xs font-black text-slate-900 uppercase tracking-[0.2em]">{title}</h3>
        <button onClick={onClose} className="w-8 h-8 flex items-center justify-center text-slate-300 hover:text-slate-600 transition-colors">
          <i className="fas fa-times text-sm"></i>
        </button>
      </div>
      <div className="p-8">
        {children}
      </div>
    </div>
  </div>
);

export default App;

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center gap-2 transition-all duration-300 antialiased active:scale-[0.96] disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer border-none outline-none";

  const variants = {
    primary: "bg-indigo-600 text-white hover:bg-indigo-700 shadow-md",
    secondary: "bg-white border border-slate-200 text-slate-700 hover:bg-slate-50 hover:border-slate-300",
    danger: "bg-rose-500 text-white hover:bg-rose-600",
    ghost: "text-slate-400 hover:text-indigo-600 hover:bg-indigo-50/50"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${className}`} 
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading ? <i className="fas fa-circle-notch fa-spin text-sm"></i> : children}
    </button>
  );
};
